    ["01-2"] = {name="Durotar", nameA="Durotar: {a:367} & {a:362}", shortA="Durotar: {a:367} +", tips={{k="取捨", text="Vale a pena fazer Carregue suas tralhas. Colete Retalho de Lona junto com as outras missões da Bastilha Tiragarde."}, {k="取捨", text="Entregue primeiro Aniquile os invasores para poder aceitar Dos destroços.... Faça e Um espírito solvente na mesma ida."}, {k="取捨", text="Guarde por ora a continuação das masmorras do Antro das Sombras. Se for fazer Cavernas Ígneas, pegue depois a cadeia Inimigos ocultos com Thrall. O distintivo de oficial necessário para a primeira etapa pode ser obtido na região de Lâmina Ardente, ao norte."}, {k="提醒", text="Abaixo do nível 12? Faça as primeiras etapas de Faça o que eu digo..., A Rocha da Caveira ou Ameaça vinda de baixo.", s={{"Abaixo do nível 12?"}, {"Faça as primeiras etapas de Faça o que eu digo..., A Rocha da Caveira ou Ameaça vinda de baixo"}}}}, danger={[1]="As escadas e portas em Bastilha Tiragarde podem puxar os marinheiros do andar de cima. Limpe a parede externa e a entrada primeiro.", [2]="Gigantes marinhos vagam pela área das nagas na costa norte. Limpe os mobs próximos antes de puxar um. Retire-se ao longo da costa se tiver problemas."}, grind={[1]={mob="Fuzileiro de Kul Tiraz", note="Mobs normais densos na Bastilha Tiragarde. Puxe do lado de fora para evitar acréscimos nos corredores. Colete Retalho de Lona para Carregue suas tralhas."}, [2]={mob="Guarda de Batalha Crinavalha", note="Mobs normais se aglomeram a oeste de Monte Navalha. Siga ao longo da borda do acampamento e observe as patrulhas. Emparelhe com Invasão."}, [3]={mob="Bruxa da Tempestade Sopravento", note="Mobs normais agrupados no norte de Durotar, com conjuradores. Use cobertura para puxá-los de perto. Faça Securing the Lines ou farme até o nível 12 antes de entrar em Orgrimmar."}}, supply={[1]={npc="Trayexir"}, [2]={npc="Estalajadeiro Grosk"}, [3]={npc="Wuark"}, [4]={npc="Estalajadeiro Grosk"}, [5]={npc="Ghrawt"}, [6]={npc="Doraso"}}, ste