"}, [150]={hint="Fale com o Necroguarda Baldreno dos viajantes misteriosos da Harmonia Telúrica que passaram pelo Sepulcro recentemente."}, [151]={npc="Necroguarda Baldreno", tgt="Necroguarda Baldreno"}, [152]={npc="Necroguarda Baldreno", tgt="Necroguarda Baldreno", desc="Faça junto com as missões da Ilha de Fenris no Sepulcro."}, [153]={hint="Investigue na Ilha de Fenris, a leste, o que aconteceu com o grupo de viajantes da Harmonia Telúrica.", desc="Faça junto com as missões da Ilha de Fenris no Sepulcro."}, [154]={npc="Restos Calcinados", npcObj=true, desc="Faça junto com as missões da Ilha de Fenris no Sepulcro."}, [155]={npc="Restos Calcinados", npcObj=true}, [156]={hint="Investigue o Castelo Fenris ao norte e tente localizar o membro desaparecido do grupo da Harmonia Telúrica."}, [157]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento"}, [158]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento"}, [159]={hint="Recupere a Chave da Ilha de Fenris dos Gnolls Putricouro e use-a para libertar Lúmina Cantavento."}, [160]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento"}, [161]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento"}, [162]={hint="Acompanhe Lúmina Cantavento e ajude-a a fugir do Castelo Fenris."}, [163]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento"}, [164]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento", desc="Alcance o nível 20 para desbloquear a continuação, Uma lâmina beijada pela lua."}, [165]={hint="Fale com Lúmina Cantavento no Sepulcro.", desc="Alcance o nível 20 para desbloquear a continuação, Uma lâmina beijada pela lua."}, [166]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento", desc="Alcance o nível 20 para desbloquear a continuação, Uma lâmina beijada pela lua."}, [167]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento", tag="Opcional", desc="Entregue A dívida primeiro. No nível 20, procure Lumina para aceitar; fale com Trevan e guarde as anotações da arma na mochila. Depois, volte ao Sepulcro com os três materiais."}, [168]={npc="Júnio Aquino", tgt="Júnio Aquino", tag="Opcional", desc="Faça junto com a rota norte-sul de Pinhaprata; é preciso voltar às Cidade Baixa."}, [169]={hint="Mate Fernão Thatros e leve a cabeça dele para Júnio Aquino no Distrito dos Ladinos da Cidade Baixa.", tag="Opcional", desc="Faça junto com a rota norte-sul de Pinhaprata; é preciso voltar às Cidade Baixa."}, [170]={npc="Júnio Aquino", tgt="Júnio Aquino", tag="Opcional", desc="Faça junto com a rota norte-sul de Pinhaprata; é preciso voltar às Cidade Baixa."}, [171]={npc="Júnio Aquino", tgt="Júnio Aquino", tag="Opcional", desc="Use Furtividade para passar pelo mago de Dalaran antes de entrar na sala."}, [172]={hint="Encontre o Relatório Situacional de Dalaran e devolva-o a Júnio Aquino no Distrito dos Ladinos da Cidade Baixa.", tag="Opcional", desc="Use Furtividade para passar pelo mago de Dalaran antes de entrar na sala."}, [173]={npc="Júnio Aquino", tgt="Júnio Aquino", tag="Opcional", desc="Use Furtividade para passar pelo mago de Dalaran antes de entrar na sala."}, [174]={npc="Júnio Aquino", tgt="Júnio Aquino", desc="Se jogar de morto-vivo, comece na Cidade Baixa. Continue a sequência de arrombamento nos Sertões, na Vila Catraca e no Acampamento Taurajo."}, [175]={hint="Vá até Orgrimmar e fale com Shenthul no Antro das Sombras.", desc="Se jogar de morto-vivo, comece na Cidade Baixa. Continue a sequência de arrombamento nos Sertões, na Vila Catraca e no Acampamento Taurajo."}, [176]={npc="Shenthul", tgt="Shenthul", desc="Se jogar de morto-vivo, comece na Cidade Baixa. Continue a sequência de arrombamento nos Sertões, na Vila Catraca e no Acampamento Taurajo."}, [177]={npc="Caio Cantígnea", tgt="Caio Cantígnea", tag="Opcional", desc="Aceite a missão introdutória só se passar por Montalvo. Se já estiver nas Cidade Baixa, aceite Investigue a Loja de Alquimia direto."}, [178]={hint="Fale com Anastácia Cordato.", tag="Opcional", desc="Aceite a missão introdutória só se passar por Montalvo. Se já estiver nas Cidade Baixa, aceite Investigue a Loja de Alquimia direto."}, [179]={npc="Anastácia Cordato", tgt="Anastácia Cordato", tag="Opcional", desc="Aceite a missão introdutória só se passar por Montalvo. Se já estiver nas Cidade Baixa, aceite Investigue a Loja de Alquimia direto."}, [180]={npc="Anastácia Cordato", tgt="Anastácia Cordato", desc="Revele-o com o feitiço do pergaminho. Lute até a criatura parar de atacar, use a caixa de contenção espiritual e por fim pegue o recipiente do chão."}, [181]={hint="Obtenha um Cantochão da Manifestação e um Baú de Cofres de Contenção atrás de Anastácia Cordato. Traga 3 Cofres de Contenção Cheios, o Baú de Cofres de Contenção e o Cantochão da Manifestação para Anastácia na Cidade Baixa.", desc="Revele-o com o feitiço do pergaminho. Lute até a criatura parar de atacar, use a caixa de contenção espiritual e por fim pegue o recipiente do chão."}, [182]={npc="Anastácia Cordato", tgt="Anastácia Cordato", desc="Revele-o com o feitiço do pergaminho. Lute até a criatura parar de atacar, use a caixa de contenção espiritual e por fim pegue o recipiente do chão."}, [183]={npc="Anastácia Cordato", tgt="Anastácia Cordato"}, [184]={hint="Leve 10 Linhos e 6 Gemas de Mana de Dalaran para Josefo Gregório."}, [185]={npc="Josefo Gregório", tgt="Josefo Gregório"}, [186]={npc="Josefo Gregório", tgt="Josefo Gregório", star={"Vestes de Fogo Místico Inferior", {"MAGE"}}}, [187]={npc="Josefo Gregório", tgt="Josefo Gregório", star={"Vestes de Fogo Místico Inferior", {"MAGE"}}}, [188]={text="Volte à Encruzilhada, nos Sertões, com a Pedra de Regresso que você vinculou antes. Se a Pedra de Regresso não estiver disponível, vá à torre ao sul de Montalvo, procure Zapetta (60.74, 58.87, plataforma oeste) e pegue a linha de Orgrimmar. Se ainda estiver no Sepulcro, voe primeiro para a Cidade Baixa e depois saia da cidade. Se o ponto de voo da Cidade Baixa não estiver desbloqueado, siga pela estrada do nordeste direto até Montalvo."}}},
    ["05-d3"] = {name="Ruínas de Lordaeron", entrance="Cidade Baixa 72.41, 11.37", pickup="Em Montalvo, confirme primeiro com Lina o progresso de Patrulha da retaguarda. Lina tem ainda uma continuação, Patrulha da retaguarda. Antes de ir a Floresta de Pinhaprata, ao desembarcar do zepelim em Montalvo, dá para visitar Lina e Kristof de passagem. No Sepulcro, aceite primeiro Pedido desesperado com Tabitha e conclua as três etapas de Receita mortal. Procure Greave e Mobin na sala de alquimia da Cidade Baixa. Entregue estes seis tipos de missão só na fase da masmorra.", pickupS={{"Em Montalvo, confirme primeiro com Lina o progresso de Patrulha da retaguarda"}, {"Lina tem ainda uma continuação, Patrulha da retaguarda", {race={"Orc", "Scourge"}}}, {"Antes de ir a Floresta de Pinhaprata, ao desembarcar do zepelim em Montalvo, dá para visitar Lina e Kristof de passagem"}, {"No Sepulcro, aceite primeiro Pedido desesperado com Tabitha e conclua as três etapas de Receita mortal"}, {"Procure Greave e Mobin na sala de alquimia da Cidade Baixa"}, {"Entregue estes seis tipos de missão só na fase da masmorra"}}, tips={{k="動線", text="Entrada → Sugapresa em Beco do Rei → elimine os mortos-vivos pelo caminho → mate o Barão e pegue o brasão → Rath'mael no cemitério; pelo caminho, procure Eduardo a oeste. O Renegado do mercado e o Victor na chaminé a sudoeste do cemitério são opcionais."}, {k="取捨", text="A Horda pode priorizar uma corrida nos níveis 16-20. Se você ainda não fez a cadeia de receitas de Pinhaprata, faça antes as missões do Sepulcro e só então forme o grupo, para que Sugapresa conte na cadeia."}, {k="說明", text="A entrada fica nas Ruínas de Lordaeron, na superfície de Tirisfal, acima da Cidade Baixa. Use as coordenadas do mapa da Cidade Baixa. Ao entrar nas ruínas, suba a escada de pedra à esquerda e evite o elevador para baixo.", s={{"A entrada fica nas Ruínas de Lordaeron, na superfície de Tirisfal, acima da Cidade Baixa"}, {"Use as coordenadas do mapa da Cidade Baixa"}, {"Ao entrar nas ruínas, suba a escada de pedra à esquerda e evite o elevador para baixo"}}}}, steps={[1]={npc="Necroguarda Lina", tgt="Necroguarda Lina", desc="Pule se você terminou isso em Montalvo."}, [2]={hint="Mate 8 Horrores Sangrentos e 8 Espíritos Errantes. Depois, apresente seu relatório a Linnea no acampamento.", desc="Pule se você terminou isso em Montalvo."}, [3]={npc="Necroguarda Lina", tgt="Necroguarda Lina", desc="Pule se você terminou isso em Montalvo."}, [4]={npc="Necroguarda Lina", tgt="Necroguarda Lina", preText="Patrulha da retaguarda"}, [5]={hint="Leve o Coração de Talharretalha até a Necroguarda Lina."}, [6]={npc="Necroguarda Lina", tgt="Necroguarda Lina"}, [7]={npc="Necroguarda Kristof", tgt="Necroguarda Kristof", desc="O pré-requisito Patrulha da retaguarda tem restrições de raça. Para outras raças, verifique se Kristof oferece esta missão.", preText="Patrulha da retaguarda"}, [8]={npc="Tábata Tececórdio", tgt="Tábata Tececórdio"}, [9]={npc="Boticário Renferrel", tgt="Boticário Renferrel", desc="Se você já fez esta parte no Sepulcro (Floresta de Pinhaprata), entregue com o progresso atual, sem refazer."}, [10]={hint="Colete 6 Corações de Urso Cinzento e 6 amostras de Sangue de Pateante e leve-os para o Mestre-boticário Faranello na Cidade Baixa.", desc="Se você já fez esta parte no Sepulcro (Floresta de Pinhaprata), entregue com o progresso atual, sem refazer."}, [11]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", desc="Se você já fez esta parte no Sepulcro (Floresta de Pinhaprata), entregue com o progresso atual, sem refazer."}, [12]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", desc="Encontre o diário de Bernard na pousada Vilarejo Lenhardente.", preText="Receita mortal"}, [13]={hint="Recupere o Diário do Boticário Berardo em Vilarejo Lenhardente e leve-o ao Boticário Renferrel no Sepulcro.", desc="Encontre o diário de Bernard na pousada Vilarejo Lenhardente."}, [14]={npc="Boticário Renferrel", tgt="Boticário Renferrel", desc="Encontre o diário de Bernard na pousada Vilarejo Lenhardente."}, [15]={npc="Boticário Renferrel", tgt="Boticário Renferrel", preText="Receita mortal"}, [16]={hint="Leve 6 amostras de Musgo de Rastejante do Lago, 6 amostras de Musgo de Sorrateiro do Lago e um Tumor Endurecido para o Mestre-boticário Faranello na Cidade Baixa."}, [17]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello"}, [18]={npc="Teodoro Chaves", tgt="Teodoro Chaves", preText="Receita mortal"}, [19]={npc="Morbin Ruinaluz", tgt="Morbin Ruinaluz"}, [20]={text="Entrada: Ruínas de Lordaeron"}, [21]={hint="Colete a Cepa Altamente Tóxica do Sugapresa nas Ruínas de Lordaeron para Teodoro Chaves, na Cidade Baixa.", desc="Local: Passe pelos nerubianos e procure Sugapresa patrulhando Beco do Rei.", spot="Passe pelos nerubianos e procure Sugapresa patrulhando Beco do Rei."}, [22]={hint="Colete 25 Membros Intactos nas Ruínas de Lordaeron para Morbin Ruinaluz, na Cidade Baixa.", desc="Local: Saqueie mortos-vivos ao longo da rota principal através de Beco do Rei, o mirante e o cemitério.", spot="Saqueie mortos-vivos ao longo da rota principal através de Beco do Rei, o mirante e o cemitério."}, [23]={npc="Cabeça Abominável", npcObj=true, desc="Pode ser aceita no nível 15. Depois de matar o Barão, saqueie a Cabeça Abominável e clique com o botão direito para aceitar a missão."}, [24]={npc="Escudo de Lordaeron", npcObj=true, desc="O Escudo de Lordaeron tem vários locais possíveis. Ao longo do caminho, verifique os objetos interativos do pátio das aranhas, das torres e das salas trancadas."}, [25]={hint="Mate Rath'mael nas Ruínas de Lordaeron para o Necroguarda Kristof em Montalvo.", desc="Local: Abra espaço ao redor de Rath'mael no cemitério de Lordaeron antes de puxar.", spot="Abra espaço ao redor de Rath'mael no cemitério de Lordaeron antes de puxar."}, [26]={hint="Investigue o desaparecimento de Edward Tececórdio nas Ruínas de Lordaeron.", desc="Local: Edward, perto dos carniçais, no lado oeste do cemitério de Rath'mael. Ordem: primeiro derrote Rath'mael, depois examine o corpo de Edward.", spot="Edward, perto dos carniçais, no lado oeste do cemitério de Rath'mael."}, [27]={npc="Teodoro Chaves", tgt="Teodoro Chaves"}, [28]={npc="Morbin Ruinaluz", tgt="Morbin Ruinaluz"}, [29]={hint="Leve o Escudo de Lordaeron a Urraca Convulserpe na Cidade Baixa.", desc="O Escudo de Lordaeron tem vários locais possíveis. Ao longo do caminho, verifique os objetos interativos do pátio das aranhas, das torres e das salas trancadas."}, [30]={npc="Urraca Convulserpe", tgt="Urraca Convulserpe"}, [31]={hint="Entregue a Cabeça Abominável ao Mestre-boticário Faranello na Cidade Baixa.", desc="Pode ser aceita no nível 15. Depois de matar o Barão, saqueie a Cabeça Abominável e clique com o botão direito para aceitar a missão."}, [32]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello"}, [33]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", preText="Tormento sem fim"}, [34]={hint="Leve a Cabeça do Barão ao corpo de Othmar na Cidade Baixa."}, [35]={npc="Abominação Incompleta", tgt="Abominação Incompleta"}, [36]={npc="Abominação Incompleta", tgt="Abominação Incompleta", preText="Tormento sem fim"}, [37]={hint="Relate suas descobertas ao Mestre-boticário Faranello na Cidade Baixa."}, [38]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello"}, [39]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", desc="Procure Taven Grist no Distrito Comercial para o primeiro reagente. A erva ardente fica ao lado do treinador de herborismo. Compre a essência da agonia do vendedor de venenos do Distrito dos Ladinos.", preText="Tormento sem fim"}, [40]={hint="Obtenha um Morrião Tóxico com Clorinda Grisette no Distrito Comercial, Pustulerva perto do local de Treinamento de Herborismo, e Essência da Agonia com o comerciante de venenos no Distrito dos Ladinos para entregar ao Mestre-boticário Faranello na Cidade Baixa.", desc="Procure Taven Grist no Distrito Comercial para o primeiro reagente. A erva ardente fica ao lado do treinador de herborismo. Compre a essência da agonia do vendedor de venenos do Distrito dos Ladinos."}, [41]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", desc="Procure Taven Grist no Distrito Comercial para o primeiro reagente. A erva ardente fica ao lado do treinador de herborismo. Compre a essência da agonia do vendedor de venenos do Distrito dos Ladinos."}, [42]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", desc="Injete o soro chiante no dispositivo acima de Osma.", preText="Tormento sem fim"}, [43]={hint="Injete Soro Sibilante nos mecanismos sobre o corpo de Othmar para o Mestre-boticário Faranello.", desc="Injete o soro chiante no dispositivo acima de Osma."}, [44]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", desc="Injete o soro chiante no dispositivo acima de Osma."}, [45]={npc="Necroguarda Kristof", tgt="Necroguarda Kristof"}, [46]={npc="Tábata Tececórdio", tgt="Tábata Tececórdio"}}},
    ["02-10"] = {name="Sertões", nameA="Sertões: {a:392} & {a:378}", shortA="Sertões: {a:392} +", tips={{k="交通", text="Depois do circuito norte, use a Pedra de Regresso para voltar à Encruzilhada. Entregue as missões antes de voar a Vila Catraca. Na primeira visita ao Acampamento Taurajo, obtenha o ponto de voo."}, {k="取捨", text="Tribos em guerra, O nome dela era Olgra e Consumido pelo ódio têm os mesmos alvos: faça as três juntas. Consumido pelo ódio pede 60 presas; se não tiver o bastante, guarde-as na mochila, para não precisar farmá-las à parte quando atingir o nível exigido."}, {k="取捨", text="Entregue Uma carta para Jin'Zil e Zé Fízzica na próxima parada, na Cordilheira das Torres de Pedra. Recolha os ovos de Ovos de Aranha de Fundolimo agora e entregue a missão ao voltar à Vila Catraca. Guarde A caçada do Vale Gris e, se fizer, Os relatórios dos Brado Guerreiro para Vale Gris."}, {k="取捨", text="Grupo para a elite de nível 20 em PROCURA-SE: Bruuz, o evento centauro em Contra-ataque! e a missão de fronteira Culpa errônea justamente corrigida. Evite a escolta Fortaleza da Guardanorte se quiser evitar puxões extras."}, {k="取捨", text="A taxa de saque de A fortuna do mineiro é baixa. Se não cair, siga para a parte final da rota. As quatro missões raras só começam se você encontrar e saquear o item."}, {k="提醒", text="Abaixo do nível 23, você pode continuar matando lagartos e espreitadores no ponto de mobs de Trabalho de campo (47.11, 77.38), ou ir para o sul aceitar Reivindicação de Gann. A entrada da Caverna Ululante fica em cerca de 47.70, 35.00, e o ideal é fazê-la entre os níveis 18-23; se for entrar, leve as missões da Caverna Ululante aceitas na Encruzilhada e em Vila Catraca.", s={{"Abaixo do nível 23, você pode continuar matando lagartos e espreitadores no ponto de mobs de Trabalho de campo (47.11, 77.38), ou ir para o sul aceitar Reivindicação de Gann"}, {"A entrada da Caverna Ululante fica em cerca de 47.70, 35.00, e o ideal é fazê-la entre os níveis 18-23; se for entrar, leve as missões da Caverna Ululante aceitas na Encruzilhada e em Vila Catraca"}}}}, danger={[1]="O Pilhador de elite de Trabalho de campo patrulha entre os mobs normais. Mate só os lagartos da borda e evite cruzar o meio do bando.", [2]="Soldados da Aliança ficam em grupos na fronteira com o Pântano Vadeoso. Pule Culpa errônea justamente corrigida se não tiver um grupo."}, grind={[1]={mob="Borrascouro", note="Mobs normais densos na área de Trabalho de campo. Circule pela grama, fique de olho no Pilhador Furioso de elite e evite o meio do bando."}, [2]={mob="Espreitador Presavaia", note="Mobs normais densos, no mesmo campo dos lagartos-trovão. Se outros jogadores estiverem limpando a mesma área, troque de alvo pela borda, sem precisar mudar de acampamento."}}, supply={[1]={npc="Devrak"}, [2]={npc="Bragok"}, [3]={npc="Estalajadeiro Wiley"}, [4]={npc="Xaveco"}, [5]={npc="Estalajadeiro Wiley"}, [6]={npc="Bossanovik"}, [7]={npc="Omusa Chifre Troante"}, [8]={npc="Estalajadeira Byula"}, [9]={npc="Sanuye Runa Totem"}}, steps={[1]={text="Quem já voltou do Sepulcro, na Floresta de Pinhaprata, para a Encruzilhada aceita a missão no acampamento. Se entrou no meio do caminho e ainda está nos Reinos do Leste, use primeiro a Pedra de Regresso para ir à Encruzilhada. Se a Pedra de Regresso não estiver disponível, pegue a linha de Orgrimmar na torre ao sul de Montalvo, entre em Orgrimmar e voe para a Encruzilhada. Se o ponto de voo da Encruzilhada não estiver desbloqueado, vá do portão sul de Orgrimmar pela estrada de Durotar para o sul até Monte Navalha, atravesse a ponte a oeste para os Sertões e siga a estrada principal até a Encruzilhada para desbloqueá-lo. Guarde a Pedra de Regresso da Encruzilhada até terminar a rota do norte."}, [2]={hint="Encontre o Meio-pingente da Agilidade Aquática e o Meio-pingente da Resistência Aquática. Fale com os residentes da Clareira da Lua para obter pistas de onde esse itens podem estar."}, [3]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [4]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [5]={text="Em Refúgio Noturno, encontre Bonthen Vento do Prado (só druidas; 44.28, 45.87) e voe para Penhasco do Trovão. Se a Pedra de Regresso estiver vinculada em um lugar útil e fora do tempo de recarga, você também pode voltar com ela. Não use o ponto de voo comum de Faustron, ao sul de Clareira da Lua; essa rota ainda não está aberta."}, [6]={hint="Volte ao Penhasco do Trovão e mostre a Turak Runa Totem o Pingente do Leão Marinho."}, [7]={npc="Turak Runa Totem", tgt="Turak Runa Totem"}, [8]={text="Voe do Penhasco do Trovão para a Encruzilhada e retome a rota."}, [9]={npc="Mankrik", tgt="Mankrik"}, [10]={npc="Mankrik", tgt="Mankrik"}, [11]={npc="Korran", tgt="Korran"}, [12]={npc="Thork", tgt="Thork"}, [13]={hint="Leve o Pelego de Echeyaki para Sergra Espinhonegro, na Encruzilhada."}, [14]={npc="Sergra Espinhonegro", tgt="Sergra Espinhonegro", desc="Pule se você já a entregou na Encruzilhada."}, [15]={npc="Sergra Espinhonegro", tgt="Sergra Espinhonegro"}, [16]={hint="Obtenha 6 Anéis de Tenente Harpia de Asabruxas Matadoras e leve-os para Darsok Punhálacre na Encruzilhada.", desc="Faça isso somente se você não terminou no A Encruzilhada."}, [17]={npc="Darsok Punhálacre", tgt="Darsok Punhálacre", desc="Pule se você já a entregou na Encruzilhada."}, [18]={npc="Darsok Punhálacre", tgt="Darsok Punhálacre"}, [19]={text="Voe da Encruzilhada para Vila Catraca se os dois pontos de voo já estiverem desbloqueados. Se não tiver o de Vila Catraca, siga a estrada leste até a cidade e obtenha-o com Bragok (63.08, 37.16). Se já pegou A rebimboca na Encruzilhada, pode mantê-la."}, [20]={npc="Cáliper Porcatraca", tgt="Cáliper Porcatraca"}, [21]={npc="Capitão Thalo'thas Solaz", tgt="Capitão Thalo'thas Solaz"}, [22]={npc="Cáliper Porcatraca", tgt="Cáliper Porcatraca"}, [23]={npc="Cobogó", tgt="Cobogó"}, [24]={npc="Mestre Portuário Caruncho", tgt="Mestre Portuário Caruncho", tag="Opcional", desc="Aceite apenas se estiver indo para a mina no norte."}, [25]={npc="PROCURA-SE", npcObj=true, tag="Grupo recomendado, Opcional", desc="Elite de nível 20. Aceite só se for fazer em grupo."}, [26]={npc="Operador de Grua Mafuá", tgt="Operador de Grua Mafuá", tag="Grupo recomendado, Opcional", desc="Aceite só se for fazer a Caverna Ululante em grupo."}, [27]={text="Siga a passagem ao norte de Vila Catraca até o Pântano Lodoso e limpe as planícies ao norte. Se não aceitou A rebimboca na primeira visita, volte antes a Cobogó para pegá-la."}, [28]={hint="Acesse o Painel de Controle no laboratório da Empreendimentos S.A."}, [29]={npc="Painel de Controle", npcObj=true}, [30]={npc="Painel de Controle", npcObj=true}, [31]={hint="Feche a Válvula de Controle de Combustível, a Válvula de Regulagem e a Válvula Principal e, em seguida, use o Painel de Controle."}, [32]={npc="Painel de Controle", npcObj=true}, [33]={npc="Painel de Controle", npcObj=true}, [34]={hint="Pegue a Chave do Painel do Engenhoqueiro Faísca para usar no painel de controle."}, [35]={npc="Painel de Controle", npcObj=true}, [36]={npc="Painel de Controle", npcObj=true}, [37]={hint="Consiga a Esmeralda Olho-de-gato de um dos feitores ou seguranças da Empreendimentos S.A. e leve para o Mestre Portuário Caruncho, em Vila Catraca.", tag="Opcional", desc="A Esmeralda Olho-de-gato tem baixa taxa de saque. Pegue só se passar por perto e não fique farmando por muito tempo."}, [38]={npc="Retalhador do Manivela", tgt="Retalhador do Manivela", desc="Derrote o capataz, pegue a Chave de Ignição e entregue-a a Wizzlecrank."}, [39]={hint="Consiga a Chave de Ignição para Manivela.", desc="Derrote o capataz, pegue a Chave de Ignição e entregue-a a Wizzlecrank."}, [40]={npc="Retalhador do Manivela", tgt="Retalhador do Manivela", desc="Derrote o capataz, pegue a Chave de Ignição e entregue-a a Wizzlecrank."}, [41]={npc="Retalhador do Manivela", tgt="Retalhador do Manivela", desc="Cure e elimine mobs próximos antes de aceitar. A escolta começa imediatamente."}, [42]={hint="Escolte o Manivela e o retalhador goblínico roubado até Cobogó, na Vila Catraca.", desc="Escolte-o para fora do Pântano Lodoso. Espere o diálogo terminar e a missão ser concluída."}, [43]={npc="Kadrak", tgt="Kadrak"}, [44]={npc="Kadrak", tgt="Kadrak", tag="Opcional", desc="Deixe para fazer de passagem pelo Posto Machadada, no Vale Gris. Depois de aceitar, clique com o botão direito na pasta de relatórios para obter os relatórios dos Brado Guerreiro para os três emissários, e guarde a resposta mais recente de cada um."}, [45]={npc="Vrang Sanguebravo", tgt="Vrang Sanguebravo"}, [46]={npc="Vrang Sanguebravo", tgt="Vrang Sanguebravo"}, [47]={hint="Colete 6 Pelegos de Leão da Savana de Matriarcas da Savana e Patriarcas da Savana nos Sertões."}, [48]={hint="Colete 8 Caças Encurraladas achadas em Armadilhas Disparadas nos Sertões."}, [49]={npc="Vrang Sanguebravo", tgt="Vrang Sanguebravo"}, [50]={npc="Vrang Sanguebravo", tgt="Vrang Sanguebravo"}, [51]={npc="Vrang Sanguebravo", tgt="Vrang Sanguebravo"}, [52]={hint="Leve o Pacote de Peles para o eremita no cume com vista para os Montes Áridos, nos Sertões."}, [53]={npc="Téo Tragolongo", tgt="Walton"}, [54]={npc="Téo Tragolongo", tgt="Walton"}, [55]={hint="Vá até a caravana destroçada e descubra por que os kultirenos estão aqui."}, [56]={npc="Téo Tragolongo", tgt="Walton"}, [57]={npc="Téo Tragolongo", tgt="Walton", desc="Quando a escolta for atacada, puxe os marinheiros isolados para longe. Entregue só depois de o evento terminar com a morte de Téo Tragolongo."}, [58]={hint="Ajude Walton a sobreviver ao confronto com Téo Tragolongo e os marinheiros kultirenos.", desc="Quando a escolta for atacada, puxe os marinheiros isolados para longe. Entregue só depois de o evento terminar com a morte de Téo Tragolongo."}, [59]={npc="Téo Tragolongo", tgt="Walton", desc="Quando a escolta for atacada, puxe os marinheiros isolados para longe. Entregue só depois de o evento terminar com a morte de Téo Tragolongo."}, [60]={hint="Mate Serena Plumassangue e leve a cabeça dela para Darsok Punhálacre na Encruzilhada."}, [61]={text="Depois de limpar o lado norte, use a Pedra de Regresso para voltar à Encruzilhada. Se a Pedra de Regresso ainda estiver em recarga, siga para o sul pela estrada principal."}, [62]={npc="Darsok Punhálacre", tgt="Darsok Punhálacre"}, [63]={npc="Darsok Punhálacre", tgt="Darsok Punhálacre", desc="Deixe para o Retiro Rocha do Sol: procure Jin'Zil na caverna da entrada das Torres de Pedra."}, [64]={text="Depois das entregas na Encruzilhada, voe para Vila Catraca para entregar A rebimboca e as missões do norte."}, [65]={npc="Cobogó", tgt="Cobogó"}, [66]={npc="Cobogó", tgt="Cobogó"}, [67]={npc="Mestre Portuário Caruncho", tgt="Mestre Portuário Caruncho", tag="Opcional"}, [68]={hint="Leve a Barbatana Dorsal de Bruuz para o Gasganete na Vila Catraca.", tag="Grupo recomendado, Opcional", desc="Agrupe-se ou puxe para os guardas. Cause dano suficiente para obter crédito de saque."}, [69]={npc="Gasganete", tgt="Gasganete", tag="Grupo recomendado, Opcional"}, [70]={text="Costa sudeste, depois as missões dos quilboars rumo ao Acampamento Taurajo"}, [71]={hint="Recupere o Carregamento de Botas e a Lente Telescópica para Gasganete na Vila Catraca.", desc="Faça isto junto com a Fortaleza da Guardanorte. Primeiro, abra um baú em cada acampamento de Southsea."}, [72]={hint="O Capitão Thalo'thas Solaz de Vila Catraca quer que você obtenha 10 Medalhas de Theramore e mate a Capitão Amazona, o Canhoneiro Ocastro e o Canhoneiro Smythe."}, [73]={npc="Gilthares Galhareda", tgt="Gilthares Galhareda", desc="Termine os canhões e emblemas da torre antes de iniciar a escolta."}, [74]={hint="Escolte Gilthares Galhareda em segurança até o Capitão Solaz, que está na Vila Catraca.", desc="Escolte Gilthares de Fortaleza da Guardanorte a Vila Catraca. Fique até obter crédito."}, [75]={npc="Gasganete", tgt="Gasganete"}, [76]={npc="Capitão Thalo'thas Solaz", tgt="Capitão Thalo'thas Solaz"}, [77]={npc="Capitão Thalo'thas Solaz", tgt="Capitão Thalo'thas Solaz"}, [78]={text="Siga a sudoeste de Vila Catraca pelo Oásis Estagnado e pelos ninhos de raptores e depois continue para o Acampamento Taurajo."}, [79]={hint="Leve a Cabeça do Verog para Regthar Portões-da-morte a oeste da Encruzilhada.", desc="Agrupe-se para limpar mais rápido. Ao ver o grito, vá para a tenda em 53.06, 41.74."}, [80]={hint="Mate raptores Helióscamos e colete as penas. Use as penas em 3 dos ninhos de Garrafoices. Fale novamente com Sergra Espinhonegro na Encruzilhada."}, [81]={hint="Leve a Prata Roubada para Gazrog na Encruzilhada."}, [82]={hint="Encontre a Mulher de Mankrik e depois fale novamente com ele na Encruzilhada."}, [83]={nodeA="{a:378}", node="Camp Taurajo", desc="Ao chegar ao Acampamento Taurajo, se ainda não tiver o ponto de voo, desbloqueie-o com Omusa Chifre Troante. Mantenha a Pedra de Regresso vinculada à Encruzilhada até o Retiro Rocha do Sol, na Cordilheira das Torres de Pedra."}, [84]={npc="Denterroto", tgt="Denterroto"}, [85]={npc="Trapista Forjaço", tgt="Trapista Forjaço", tag="Opcional", desc="Aceite apenas se estiver indo para o sul para matar javatuscos."}, [86]={npc="Bruto Logmar", tgt="Bruto Logmar", tag="Grupo recomendado, Opcional", desc="Cadeia em grupo da versão Forever. Pule se faltar gente para formar o grupo."}, [87]={text="Voe até o A Encruzilhada para receber Garrafoices furiosos, Perdida em combate e outras entregas de missões. Depois de obter a orientação de Jorn, siga para sudoeste em busca de centauros ou voe de volta para Acampamento Taurajo."}, [88]={npc="Sergra Espinhonegro", tgt="Sergra Espinhonegro"}, [89]={npc="Gazrog", tgt="Gazrog"}, [90]={npc="Mankrik", tgt="Mankrik"}, [91]={npc="Mankrik", tgt="Mankrik", desc="Entregue Perdida em combate antes de aceitar."}, [92]={npc="Sergra Espinhonegro", tgt="Sergra Espinhonegro"}, [93]={npc="Regthar Portões-da-morte", tgt="Regthar Portões-da-morte"}, [94]={npc="Regthar Portões-da-morte", tgt="Regthar Portões-da-morte"}, [95]={hint="Leve a Cabeça do Hezrul para Regthar Portões-da-morte a oeste da Encruzilhada."}, [96]={npc="Regthar Portões-da-morte", tgt="Regthar Portões-da-morte"}, [97]={npc="Regthar Portões-da-morte", tgt="Regthar Portões-da-morte", tag="Opcional", desc="Forme um grupo antes de aceitar. Os reforços dos centauros atacam em ondas."}, [98]={hint="Leve um Pedaço do Estandarte de Krom'zar para Regthar Portões-da-morte, a oeste da Encruzilhada.", tag="Opcional", desc="Proteja os aliados, mate o senhor da guerra Krom'zar e saqueie 1 pedaço do estandarte."}, [99]={npc="Regthar Portões-da-morte", tgt="Regthar Portões-da-morte", tag="Opcional"}, [100]={npc="Jorn Vidente do Céu", tgt="Jorn Vidente do Céu"}, [101]={npc="Jorn Vidente do Céu", tgt="Jorn Vidente do Céu"}, [102]={text="Sul de Acampamento Taurajo: javatuscos e lagartos trovão"}, [103]={hint="Mate 6 Rabdomantes Costagulha, 12 Tecespinhos Costagulha e 12 Geomantes Costagulha e fale novamente com Denterroto no Acampamento Taurajo, nos Sertões."}, [104]={hint="Leve 60 Presas de Javatusco Costagulha para Mankrik na Encruzilhada."}, [105]={hint="Mate javatuscos e pegue 4 dos Adornos de Olgra para o memorial de Mankrik."}, [106]={hint="Obtenha 12 Ovos de Silitídeo e devolva a Garra de Escavação para Korran na Encruzilhada."}, [107]={hint="Mate soldados da Aliança que se aproximam dos Sertões na fronteira do Pântano Vadeoso e depois fale novamente com o Bruto Logmar no Acampamento Taurajo.", tag="Grupo recomendado, Opcional", desc="Puxe os soldados separadamente e depois mate o Pilhador Furioso."}, [108]={npc="Casco de Lakota'mani", npcObj=true, tag="Opcional", desc="Faça isso se você encontrar um Lakota'mani raro e saquear seu casco."}, [109]={hint="Leve o Casco de Lakota'mani para Jorn no Acampamento Taurajo.", tag="Opcional", desc="Faça isso se você encontrar um Lakota'mani raro e saquear seu casco."}, [110]={npc="Jorn Vidente do Céu", tgt="Jorn Vidente do Céu", tag="Opcional", desc="Faça isso se você encontrar um Lakota'mani raro e saquear seu casco."}, [111]={npc="Ponta da Cauda de Owatanka", npcObj=true, tag="Opcional", desc="Faça isso se encontrar o raro Owatanka e saquear o espinho da cauda dele."}, [112]={hint="Leve a Ponta da Cauda de Owatanka para Jorn no Acampamento Taurajo.", tag="Opcional", desc="Faça isso se encontrar o raro Owatanka e saquear o espinho da cauda dele."}, [113]={npc="Jorn Vidente do Céu", tgt="Jorn Vidente do Céu", tag="Opcional", desc="Faça isso se encontrar o raro Owatanka e saquear o espinho da cauda dele."}, [114]={npc="Cabeça do Segador", npcObj=true, tag="Opcional", desc="Faça isso se encontrar o raro Ceifador e saquear a cabeça dele."}, [115]={hint="Leve a Cabeça do Ceifador para Jorn Vidente do Céu.", tag="Opcional", desc="Faça isso se encontrar o raro Ceifador e saquear a cabeça dele."}, [116]={npc="Jorn Vidente do Céu", tgt="Jorn Vidente do Céu", tag="Opcional", desc="Faça isso se encontrar o raro Ceifador e saquear a cabeça dele."}, [117]={npc="Pena de Anhan Guera", npcObj=true, tag="Opcional", desc="Faça isso se você encontrar o raro Anhan Guera e saquear sua pena."}, [118]={hint="Leve a Pena de Anhan Guera para Jorn Vidente do Céu, no Acampamento Taurajo.", tag="Opcional", desc="Faça isso se você encontrar o raro Anhan Guera e saquear sua pena."}, [119]={npc="Jorn Vidente do Céu", tgt="Jorn Vidente do Céu", tag="Opcional", desc="Faça isso se você encontrar o raro Anhan Guera e saquear sua pena."}, [120]={npc="Denterroto", tgt="Denterroto"}, [121]={npc="Denterroto", tgt="Denterroto", desc="Entregue um Estilhaço de Sangue se você tiver um. Caso contrário, mate fora do acampamento por outro."}, [122]={hint="Leve um Estilhaço de Sangue para Denterroto no Acampamento Taurajo, que fica nos Sertões.", desc="Entregue um Estilhaço de Sangue se você tiver um. Caso contrário, mate fora do acampamento por outro."}, [123]={npc="Denterroto", tgt="Denterroto", desc="Entregue um Estilhaço de Sangue se você tiver um. Caso contrário, mate fora do acampamento por outro."}, [124]={npc="Denterroto", tgt="Denterroto", tag="Opcional", desc="Aceite apenas se estiver indo para o sul para matar os três chefes."}, [125]={npc="Bruto Logmar", tgt="Bruto Logmar", tag="Grupo recomendado, Opcional"}, [126]={text="Se precisar de EXP, acrescente o extremo sul e feche a rota com as entregas"}, [127]={hint="Leve um Punhal Crinavalha, uma Varinha de Crinavalha Carbonizada e um Escudo de Guerra Crinavalha ao Trapista Forjaço no Acampamento Taurajo, que fica nos Sertões.", tag="Opcional"}, [128]={hint="Mate Nak, Kâz e Lok Mataorc e leve o crânio deles para Denterroto no Acampamento Taurajo, que fica nos Sertões.", tag="Opcional", desc="Os três mobs nomeados estão em assentamentos separados. Siga os pinos."}, [129]={npc="Gann Agulha de Pedra", tgt="Gann Agulha de Pedra", tag="Opcional", desc="Abaixo de 23 e já no sul? Mate os dois tipos de anões e saqueie o diário do capataz."}, [130]={hint="Gann Agulha de Pedra quer que você mate 15 Escavadores de Bael'Dun e 5 Capatazes de Bael'dun.", tag="Opcional", desc="Abaixo de 23 e já no sul? Mate os dois tipos de anões e saqueie o diário do capataz."}, [131]={npc="Gann Agulha de Pedra", tgt="Gann Agulha de Pedra", tag="Opcional", desc="Abaixo de 23 e já no sul? Mate os dois tipos de anões e saqueie o diário do capataz."}, [132]={npc="[UNUSED] Sulhasa", tgt="[UNUSED] Sulhasa", desc="Encontre Sulhasa numa árvore na borda do Pântano Vadeoso."}, [133]={hint="Sulhasa, na parte sul dos Sertões, quer que você elimine 7 Lagartos Borrascouro e 7 Espreitadores Presavaia na área para que ela possa descer da árvore com segurança."}, [134]={npc="[UNUSED] Sulhasa", tgt="[UNUSED] Sulhasa"}, [135]={npc="Denterroto", tgt="Denterroto", tag="Opcional"}, [136]={npc="Denterroto", tgt="Denterroto", tag="Opcional", desc="Entregue quando voltar à Encruzilhada."}, [137]={npc="Trapista Forjaço", tgt="Trapista Forjaço", tag="Opcional"}, [138]={text="Conclua a cadeia de Jorn e as duas introduções para etapas posteriores"}, [139]={text="Na volta, ao norte do Acampamento Taurajo e a oeste de Vila Catraca, procure Zhevras Crinaveloz e Ishamuhale. Depois de pegar uma Carcaça Fresca de Zhevra, use-a primeiro para completar a isca."}, [140]={hint="Leve a Presa de Ishamuhale para Jorn no Acampamento Taurajo.", desc="As carcaças de Zhevra apodrecem após 30 minutos."}, [141]={hint="Obtenha 5 Chifres Intactos de Raptor de Garrafoices Helióscamos e leve-os para Cáliper Porcatraca na Vila Catraca."}, [142]={npc="Cáliper Porcatraca", tgt="Cáliper Porcatraca"}, [143]={hint="Leve 5 Presas de Leão da Savana, 5 Rins de Pinote e 1 Chifre de Lagarto Trovejante para o Cervejeiro Drohn, em Vila Catraca.", tag="Opcional", desc="Pegue presas de leão, rins de pássaro e chifres de lagarto no caminho. Se não juntar tudo, pode pular."}, [144]={npc="Cervejeiro Drohn", tgt="Cervejeiro Drohn", tag="Opcional"}, [145]={npc="Cáliper Porcatraca", tgt="Cáliper Porcatraca", tag="Opcional", desc="Entregue Chifres de raptor primeiro. Aceite só se for fazer a Caverna Ululante."}, [146]={text="Voe da Vila Catraca ao Acampamento Taurajo e volte ao Jorn. Se já estiver no nível 23 e pular a missão de caça de Vale Gris, siga da Encruzilhada para oeste até a Cordilheira das Torres de Pedra."}, [147]={npc="Jorn Vidente do Céu", tgt="Jorn Vidente do Céu"}, [148]={npc="Jorn Vidente do Céu", tgt="Jorn Vidente do Céu", desc="Guarde para entregar no Posto Machadada, no Vale Gris."}, [149]={npc="Jorn Vidente do Céu", tgt="Jorn Vidente do Céu", desc="Faça isso com os lagartos trovão fora do acampamento. Prepare três garrafas."}, [150]={hint="Leve 3 unidades de Sangue de Lagarto Trovejante para Jorn Vidente do Céu, no Acampamento Taurajo.", desc="Faça isso com os lagartos trovão fora do acampamento. Prepare três garrafas."}, [151]={npc="Jorn Vidente do Céu", tgt="Jorn Vidente do Céu", desc="Faça isso com os lagartos trovão fora do acampamento. Prepare três garrafas."}, [152]={npc="Jorn Vidente do Céu", tgt="Jorn Vidente do Céu"}, [153]={hint="Encontre e mate um falcotrom, depois leve as asas dele para Jorn Vidente do Céu, no Acampamento Taurajo."}, [154]={npc="Jorn Vidente do Céu", tgt="Jorn Vidente do Céu"}, [155]={text="Voe de volta à Encruzilhada para entregar as missões restantes."}, [156]={npc="Mankrik", tgt="Mankrik"}, [157]={npc="Mankrik", tgt="Mankrik"}, [158]={npc="Korran", tgt="Korran"}, [159]={npc="Thork", tgt="Thork", tag="Opcional"}, [160]={npc="Sorek", tgt="Sorek", tag="Opcional", desc="Aceite com um treinador em Orgrimmar, no Penhasco do Trovão ou nas Cidade Baixa. Torm Totem da Fúria (57.24, 87.37) e Dalto Flores (47.40, 17.29) também oferecem a missão."}, [161]={hint="Fale com Ruga Totem da Fúria.", tag="Opcional", desc="Aceite com um treinador em Orgrimmar, no Penhasco do Trovão ou nas Cidade Baixa."}, [162]={npc="Ruga Totem da Fúria", tgt="Ruga Totem da Fúria", tag="Opcional", desc="Aceite com um treinador em Orgrimmar, no Penhasco do Trovão ou nas Cidade Baixa."}, [163]={npc="Ruga Totem da Fúria", tgt="Ruga Totem da Fúria", tag="Opcional", desc="Faça junto com as missões ao redor do Acampamento Taurajo."}, [164]={hint="Leve 5 antenas tremelicantes para Ruga Totem da Fúria no Acampamento Taurajo", tag="Opcional", desc="Faça junto com as missões ao redor do Acampamento Taurajo."}, [165]={npc="Ruga Totem da Fúria", tgt="Ruga Totem da Fúria", tag="Opcional", desc="Faça junto com as missões ao redor do Acampamento Taurajo."}, [166]={npc="Ruga Totem da Fúria", tgt="Ruga Totem da Fúria", tag="Opcional"}, [167]={npc="Thun'grim Olhafogo", tgt="Thun'grim Olhafogo", tag="Opcional"}, [168]={npc="Thun'grim Olhafogo", tgt="Thun'grim Olhafogo", tag="Opcional", desc="Barras de Ferro vêm dos goblins da mina das Torres de Pedra, Azurita dos fazendeiros de Eira dos Montes e Flogisto do chefe de Urzal dos Tuscos; as Barras de Ferro também podem ser compradas. Entregue depois de juntar tudo no Posto Machadada, no Vale Gris."}, [169]={npc="Shenthul", tgt="Shenthul", desc="Outras origens podem começar pela introdução Para Orgrimmar! em Monte Navalha ou aceitar direto com Shenthul."}, [170]={hint="Fale com Zando'zan no Antro das Sombras.", desc="Outras origens podem começar pela introdução Para Orgrimmar! em Monte Navalha ou aceitar direto com Shenthul."}, [171]={npc="Zando'zan", tgt="Zando'zan", desc="Outras origens podem começar pela introdução Para Orgrimmar! em Monte Navalha ou aceitar direto com Shenthul."}, [172]={npc="Zando'zan", tgt="Zando'zan"}, [173]={npc="Wrenix, o Ignóbil", tgt="Wrenix, o Ignóbil"}, [174]={npc="Wrenix, o Ignóbil", tgt="Wrenix, o Ignóbil", desc="Use B.E.C.A. primeiro no papagaio. Pratique Arrombamento em baús de bordo."}, [175]={hint="Leve o Tesouro dos Mares do Sul para Wrenix, o Ignóbil, na Vila Catraca. Não se esqueça de pegar um B.E.C.A. e as Ferramentas de Ladrões no Aparato Mercadotrônico do Wrenix. Você precisará desses dois itens para cumprir a missão.", desc="Use B.E.C.A. primeiro no papagaio. Pratique Arrombamento em baús de bordo."}, [176]={npc="Wrenix, o Ignóbil", tgt="Wrenix, o Ignóbil", desc="Use B.E.C.A. primeiro no papagaio. Pratique Arrombamento em baús de bordo."}, [177]={npc="Shenthul", tgt="Shenthul", desc="Espere Shenthul fazer a demonstração, selecione-o e use /salute."}, [178]={hint="Faça a Continência dos Mãos Despedaçada para Shenthul.", desc="Espere Shenthul fazer a demonstração, selecione-o e use /salute."}, [179]={npc="Shenthul", tgt="Shenthul", desc="Espere Shenthul fazer a demonstração, selecione-o e use /salute."}, [180]={npc="Shenthul", tgt="Shenthul", desc="Dispare primeiro dois sinalizadores, depois se aproxime e use /salute. Se errar a ordem, ele ataca."}, [181]={hint="Vá à Torre da Empreendimentos S.A., ao norte do Charco de Lodo, e entre em contato com o agente secreto da Mão Despedaçada, o Capataz Arruela.", desc="Dispare primeiro dois sinalizadores, depois se aproxime e use /salute. Se errar a ordem, ele ataca."}, [182]={npc="Capataz Arruela", tgt="Capataz Arruela", desc="Dispare primeiro dois sinalizadores, depois se aproxime e use /salute. Se errar a ordem, ele ataca."}, [183]={npc="Capataz Arruela", tgt="Capataz Arruela", desc="Roube a chave primeiro (Bater Carteira). A caixa trancada do elixir aprimorado exige Arrombamento; depois do veneno, aceite A ajuda de Hinoto."}, [184]={hint="Roube a Chave da Torre do Capataz Biela e, em seguida, mate 2 Peões Mutantes da Empreendimentos S.A., 2 Patrulheiros da Empreendimentos S.A. e 2 Vigias da Empreendimentos S.A.", desc="Roube a chave primeiro (Bater Carteira). A caixa trancada do elixir aprimorado exige Arrombamento; depois do veneno, aceite A ajuda de Hinoto."}, [185]={npc="Shenthul", tgt="Shenthul", desc="Roube a chave primeiro (Bater Carteira). A caixa trancada do elixir aprimorado exige Arrombamento; depois do veneno, aceite A ajuda de Hinoto."}, [186]={npc="Shenthul", tgt="Shenthul", desc="Entregue em Serraria Tarren."}, [187]={npc="Searn Guardafogo", tgt="Searn Guardafogo", desc="O clamor da água no Penhasco do Trovão, Clamor da Água em Monte Navalha e Clamor da Água na Aldeia Casco Sangrento são introduções opcionais à mesma sequência. Você também pode ir direto à Islen Vidente da Água."}, [188]={hint="Encontre Islen Vidente da Água nos Sertões.", desc="O clamor da água no Penhasco do Trovão, Clamor da Água em Monte Navalha e Clamor da Água na Aldeia Casco Sangrento são introduções opcionais à mesma sequência. Você também pode ir direto à Islen Vidente da Água."}, [189]={npc="Islen Vidente da Água", tgt="Islen Vidente da Água", desc="O clamor da água no Penhasco do Trovão, Clamor da Água em Monte Navalha e Clamor da Água na Aldeia Casco Sangrento são introduções opcionais à mesma sequência. Você também pode ir direto à Islen Vidente da Água."}, [190]={npc="Islen Vidente da Água", tgt="Islen Vidente da Água"}, [191]={hint="Encontre Salma nos Sertões Meridionais."}, [192]={npc="Salma", tgt="Salma"}, [193]={npc="Salma", tgt="Salma"}, [194]={hint="Encha o Odre Marrom Vazio no laguinho abaixo da cabana de Salma e leve para ela nos Sertões."}, [195]={npc="Salma", tgt="Salma"}, [196]={npc="Salma", tgt="Salma", desc="Pegue água na Serraria Tarren. Entregue nos Sertões depois de passar por Aldeia Vento Livre, em Mil Agulhas."}, [197]={npc="Turak Runa Totem", tgt="Turak Runa Totem"}, [198]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [199]={text="Tauren"}, [200]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [201]={npc="Espírito do Grande Felino", tgt="Espírito do Grande Felino"}, [202]={npc="Espírito do Grande Felino", tgt="Espírito do Grande Felino"}, [203]={hint="Recupere a Relíquia da Presa, a Relíquia da Garra e a Relíquia da Sombra Silenciosa do Templo de Tempesfúria e depois leve-as ao Espírito do Grande Felino."}, [204]={npc="Espírito do Grande Felino", tgt="Espírito do Grande Felino"}, [205]={npc="Espírito do Grande Felino", tgt="Espírito do Grande Felino"}, [206]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [207]={text="Skyborne Moldavento"}, [208]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [209]={npc="Avatar de Saeyleenan", tgt="Avatar de Saeyleenan"}, [210]={npc="Avatar de Saeyleenan", tgt="Avatar de Saeyleenan"}, [211]={hint="Recupere a Relíquia da Presa, a Relíquia da Garra e a Relíquia da Sombra Silenciosa do Templo de Tempesfúria e depois leve-as ao Avatar de Saeyleenan."}, [212]={npc="Avatar de Saeyleenan", tgt="Avatar de Saeyleenan"}, [213]={npc="Avatar de Saeyleenan", tgt="Avatar de Saeyleenan"}, [214]={hint="Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua."}, [215]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [216]={text="Termine ambas as rotas raciais aqui"}, [217]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor", desc="Entregue a Turak Runa Totem e aprenda Forma de Felino e suas habilidades iniciais."}, [218]={hint="Volte ao Penhasco do Trovão e fale com Turak Runa Totem no Platô dos Anciãos.", desc="Entregue a Turak Runa Totem e aprenda Forma de Felino e suas habilidades iniciais."}, [219]={npc="Turak Runa Totem", tgt="Turak Runa Totem", desc="Entregue a Turak Runa Totem e aprenda Forma de Felino e suas habilidades iniciais."}, [220]={npc="Gan'rul Olho de Sangue", tgt="Gan'rul Olho de Sangue", desc="Depois de aceitar, escolha Súcubo ou Íncubo com Cazul."}, [221]={hint="Fale com Cazul no Antro das Sombras.", desc="Depois de aceitar, escolha Súcubo ou Íncubo com Cazul."}, [222]={npc="Cazul", tgt="Cazul", desc="Depois de aceitar, escolha Súcubo ou Íncubo com Cazul."}, [223]={text="Rota ocidental: Súcubo"}, [224]={npc="Cazul", tgt="Cazul"}, [225]={npc="Zankaja", tgt="Zankaja"}, [226]={npc="Zankaja", tgt="Zankaja"}, [227]={hint="Fale com Gazrog na Encruzilhada."}, [228]={npc="Gazrog", tgt="Gazrog"}, [229]={npc="Gazrog", tgt="Gazrog"}, [230]={hint="Fale com Ken'zigla em Malaka'jin."}, [231]={npc="Ken'zigla", tgt="Ken'zigla"}, [232]={npc="Ken'zigla", tgt="Ken'zigla"}, [233]={npc="Bruto Logmar", tgt="Bruto Logmar"}, [234]={npc="Bruto Logmar", tgt="Bruto Logmar"}, [235]={npc="Bruto Dogran", tgt="Bruto Dogran"}, [236]={npc="Bruto Dogran", tgt="Bruto Dogran"}, [237]={npc="Gan'rul Olho de Sangue", tgt="Gan'rul Olho de Sangue"}, [238]={npc="Gan'rul Olho de Sangue", tgt="Gan'rul Olho de Sangue", desc="Use Pingente de Dogran no círculo de invocação em Orgrimmar. Derrote a súcubo."}, [239]={hint="Com o Pingente de Dogran, evoque e subjugue uma Súcubo; depois, devolva o Pingente de Dogran a Gan'rul Olho de Sangue, em Orgrimmar.", desc="Use Pingente de Dogran no círculo de invocação em Orgrimmar. Derrote a súcubo."}, [240]={npc="Gan'rul Olho de Sangue", tgt="Gan'rul Olho de Sangue", desc="Use Pingente de Dogran no círculo de invocação em Orgrimmar. Derrote a súcubo."}, [241]={text="Rota ocidental: Íncubo"}, [242]={npc="Cazul", tgt="Cazul", tag="Opcional"}, [243]={npc="Magar", tgt="Magar", tag="Opcional"}, [244]={npc="Magar", tgt="Magar", tag="Opcional", desc="Perto do lago, no Vale Gris, mate bestas do pântano como os Shadethicket Stone Movers e pegue 1 Shriveled Scarf."}, [245]={hint="Investigue o Lago Céu Caído, que fica no Vale Gris, e relate suas descobertas a Gan'rul Olho de Sangue em Orgrimmar.", tag="Opcional", desc="Perto do lago, no Vale Gris, mate bestas do pântano como os Shadethicket Stone Movers e pegue 1 Shriveled Scarf."}, [246]={npc="Gan'rul Olho de Sangue", tgt="Gan'rul Olho de Sangue", tag="Opcional", desc="Perto do lago, no Vale Gris, mate bestas do pântano como os Shadethicket Stone Movers e pegue 1 Shriveled Scarf."}, [247]={npc="Gan'rul Olho de Sangue", tgt="Gan'rul Olho de Sangue", tag="Opcional", desc="Use o cachecol para invocar o Íncubo em Orgrimmar. Derrote-o e procure Gan'rul."}, [248]={hint="Usando o Lenço Fenecido, evoque e subjugue um íncubo. Depois, devolva o Lenço Fenecido para Gan'rul Olho de Sangue em Orgrimmar.", tag="Opcional", desc="Use o cachecol para invocar o Íncubo em Orgrimmar. Derrote-o e procure Gan'rul."}, [249]={npc="Gan'rul Olho de Sangue", tgt="Gan'rul Olho de Sangue", tag="Opcional", desc="Use o cachecol para invocar o Íncubo em Orgrimmar. Derrote-o e procure Gan'rul."}, [250]={text="Rota Leste: início compartilhado"}, [251]={npc="Silvério Hidalgo", tgt="Silvério Hidalgo", tag="Opcional", desc="Na rota leste, procure Godrick nas Cidade Baixa. Se já estiver no nível 20 no Sepulcro, em Pinhaprata, pode aceitar antes."}, [252]={hint="Fale com Godofredo Fasano no Templo dos Malditos.", tag="Opcional", desc="Na rota leste, procure Godrick nas Cidade Baixa. Se já estiver no nível 20 no Sepulcro, em Pinhaprata, pode aceitar antes."}, [253]={npc="Godofredo Fasano", tgt="Godofredo Fasano", tag="Opcional", desc="Na rota leste, procure Godrick nas Cidade Baixa. Se já estiver no nível 20 no Sepulcro, em Pinhaprata, pode aceitar antes."}, [254]={text="Rota Leste: Súcubo"}, [255]={npc="Godofredo Fasano", tgt="Godofredo Fasano", tag="Opcional", desc="Mate Dalin ao sul de Pinhaprata e Comar fora do Porto de Menethil, no Pantanal, e pegue o coração de cada um."}, [256]={hint="Leve os corações de Dalin Forjífice e Corma Vilardo para Silvério Hidalgo no Templo dos Malditos.", tag="Opcional", desc="Mate Dalin ao sul de Pinhaprata e Comar fora do Porto de Menethil, no Pantanal, e pegue o coração de cada um."}, [257]={npc="Silvério Hidalgo", tgt="Silvério Hidalgo", tag="Opcional", desc="Mate Dalin ao sul de Pinhaprata e Comar fora do Porto de Menethil, no Pantanal, e pegue o coração de cada um."}, [258]={npc="Silvério Hidalgo", tgt="Silvério Hidalgo", tag="Opcional", desc="Use o coração no círculo de invocação nas Cidade Baixa e derrote a Súcubo."}, [259]={hint="Usando os Corações Puros, evoque e subjugue uma súcubo. Depois, devolva os Corações Puros para Silvério Hidalgo no Distrito da Magia na Cidade Baixa.", tag="Opcional", desc="Use o coração no círculo de invocação nas Cidade Baixa e derrote a Súcubo."}, [260]={npc="Silvério Hidalgo", tgt="Silvério Hidalgo", tag="Opcional", desc="Use o coração no círculo de invocação nas Cidade Baixa e derrote a Súcubo."}, [261]={text="Rota Leste: Íncubo"}, [262]={npc="Godofredo Fasano", tgt="Godofredo Fasano", tag="Opcional", desc="Mate Avelina em Pinhaprata e Isaac Pessoa nos Sertões; pegue um coração de cada um."}, [263]={hint="Leve os corações de Avelina Lily e Isaac Pessoa para Silvério Hidalgo no Templo dos Malditos.", tag="Opcional", desc="Mate Avelina em Pinhaprata e Isaac Pessoa nos Sertões; pegue um coração de cada um."}, [264]={npc="Silvério Hidalgo", tgt="Silvério Hidalgo", tag="Opcional", desc="Mate Avelina em Pinhaprata e Isaac Pessoa nos Sertões; pegue um coração de cada um."}, [265]={npc="Silvério Hidalgo", tgt="Silvério Hidalgo", tag="Opcional", desc="Use o coração no círculo de invocação nas Cidade Baixa e derrote o Íncubo."}, [266]={hint="Usando os Corações dos Amantes, evoque e subjugue um íncubo. Depois, devolva os Corações dos Amantes para Silvério Hidalgo no Distrito da Magia na Cidade Baixa.", tag="Opcional", desc="Use o coração no círculo de invocação nas Cidade Baixa e derrote o Íncubo."}, [267]={npc="Silvério Hidalgo", tgt="Silvério Hidalgo", tag="Opcional", desc="Use o coração no círculo de invocação nas Cidade Baixa e derrote o Íncubo."}, [268]={text="Equipamento de classe opcional"}, [269]={npc="Doan Karhan", tgt="Doan Karhan", tag="Opcional", desc="Pegue 3 fragmentos pequenos dos acólitos do Crepúsculo nas Profundezas Negras e 1 fragmento grande das Almas Negras da Presa Negra, na Bastilha da Presa Negra.", star={"Orbe de Soran'ruk", {"WARLOCK"}}}, [270]={hint="Encontre 3 Fragmentos de Soran'ruk e 1 Fragmento Grande de Soran'ruk e entregue-os a Doan Karhan nos Sertões.", tag="Opcional", desc="Pegue 3 fragmentos pequenos dos acólitos do Crepúsculo nas Profundezas Negras e 1 fragmento grande dos lobisomens Alma Negra da Presa Negra, na Bastilha da Presa Negra. Os marcadores são, em ordem, as entradas das Profundezas Negras e da Bastilha da Presa Negra. Nas Profundezas Negras, mate acólitos do Crepúsculo; na Bastilha da Presa Negra, mate Almas Negras da Presa Negra."}, [271]={npc="Doan Karhan", tgt="Doan Karhan", tag="Opcional", desc="Pegue 3 fragmentos pequenos dos acólitos do Crepúsculo nas Profundezas Negras e 1 fragmento grande das Almas Negras da Presa Negra, na Bastilha da Presa Negra.", star={"Orbe de Soran'ruk", {"WARLOCK"}}}}},
    ["05-d5"] = {name="Minas Mortas", entrance="Cerro Oeste 38.20, 77.50", pickup="Ao ir para Pinhaprata, primeiro pegue Incidente diplomático com Danitha Morr em Bastilha de Bandarion, Tirisfal, e conclua os pré-requisitos de Pinhaprata e da Ilha de Fenris (só mortos-vivos, só paladinos). No nível 20, pegue Uma lâmina beijada pela lua com Lúmina no Sepulcro e pegue as notas com Trevano (só mortos-vivos, só paladinos). Pegue o barco de Vila Catraca para Angra do Butim, suba para o norte pelo Selva do Espinhaço até a Floresta do Crepúsculo e siga a oeste até Arroio da Lua.", pickupS={{"Ao ir para Pinhaprata, primeiro pegue Incidente diplomático com Danitha Morr em Bastilha de Bandarion, Tirisfal, e conclua os pré-requisitos de Pinhaprata e da Ilha de Fenris (só mortos-vivos, só paladinos)", {race={"Scourge"}, class={"PALADIN"}}}, {"No nível 20, pegue Uma lâmina beijada pela lua com Lúmina no Sepulcro e pegue as notas com Trevano (só mortos-vivos, só paladinos)", {race={"Scourge"}, class={"PALADIN"}}}, {"Pegue o barco de Vila Catraca para Angra do Butim, suba para o norte pelo Selva do Espinhaço até a Floresta do Crepúsculo e siga a oeste até Arroio da Lua"}}, tips={{k="動線", text="Túnel da mina na entrada → Rhahk'Zor → Serraria do Sneed, pegando a madeira → Forja de Gilnid → exploda a porta para as docas → Sr. Castiga → Capitão Peleverde → Edwin VanCleef. Cuca fica no convés inferior do navio. Se só precisar da madeira, saia depois da sala do Sneed."}, {k="取捨", text="Se estiver só subindo de nível, pule esta viagem. Para Uma lâmina beijada pela lua, vá até a sala de Sneed e junte a madeira (só paladinos mortos-vivos). Continue se o grupo quiser o equipamento do chefe final.", s={{"Se estiver só subindo de nível, pule esta viagem"}, {"Para Uma lâmina beijada pela lua, vá até a sala de Sneed e junte a madeira (só paladinos mortos-vivos)", {race={"Scourge"}, class={"PALADIN"}}}, {"Continue se o grupo quiser o equipamento do chefe final"}}}, {k="說明", text="Entre no prédio da mina em Arroio da Lua (42.40, 70.40), desça e siga o túnel até o portal em 38.20, 77.50. As missões Defias da Aliança não contam para a Horda.", s={{"Entre no prédio da mina em Arroio da Lua (42.40, 70.40), desça e siga o túnel até o portal em 38.20, 77.50"}, {"As missões Defias da Aliança não contam para a Horda"}}}}, steps={[1]={npc="Danitha Morr", tgt="Danitha Morr"}, [2]={hint="Vá até o Sepulcro, na Floresta de Pinhaprata, e fale com Trevano Rol dos membros desaparecidos da Harmonia Telúrica."}, [3]={npc="Trevano Rol", tgt="Trevano Rol"}, [4]={npc="Trevano Rol", tgt="Trevano Rol", preText="Incidente diplomático"}, [5]={npc="Necroguarda Baldreno", tgt="Necroguarda Baldreno"}, [6]={npc="Necroguarda Baldreno", tgt="Necroguarda Baldreno", preText="Dupla intrigante"}, [7]={hint="Investigue na Ilha de Fenris, a leste, o que aconteceu com o grupo de viajantes da Harmonia Telúrica."}, [8]={npc="Restos Calcinados", npcObj=true}, [9]={npc="Restos Calcinados", npcObj=true, preText="Destino sórdido"}, [10]={hint="Investigue o Castelo Fenris ao norte e tente localizar o membro desaparecido do grupo da Harmonia Telúrica."}, [11]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento"}, [12]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento", preText="Entrando no Castelo Fenris"}, [13]={hint="Recupere a Chave da Ilha de Fenris dos Gnolls Putricouro e use-a para libertar Lúmina Cantavento."}, [14]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento"}, [15]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento", desc="Siga a seção de classe do Sepulcro (Floresta de Pinhaprata) para os Moldavento.", preText="Lúmina Cantavento"}, [16]={hint="Acompanhe Lúmina Cantavento e ajude-a a fugir do Castelo Fenris.", desc="Siga a seção de classe do Sepulcro (Floresta de Pinhaprata) para os Moldavento."}, [17]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento", desc="Siga a seção de classe do Sepulcro (Floresta de Pinhaprata) para os Moldavento."}, [18]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento", preText="A ira da Moldavento"}, [19]={hint="Fale com Lúmina Cantavento no Sepulcro."}, [20]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento"}, [21]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento", desc="Depois de aceitar, fale com Trevano Rol e pegue 1 conjunto de notas da arma. Mantenha a missão no registro.", preText="A dívida"}, [22]={text="Entrada: Minas Mortas"}, [23]={hint="Fale com Trevano Rol no Sepulcro e leve os materiais de que ele precisa.", desc="Mate Goblins Entalhadores para pegar Carvalho de Pedra Branca. Local: passe por Rhahk'Zor, entre na serraria e mate os carpinteiros ao lado de Sneed.", spot="Passe pelo guarda Rhahk'Zor e entre na serraria. Mate os carpinteiros ao lado de Sneed."}, [24]={npc="Trevano Rol", tgt="Trevano Rol", desc="Só entregue quando tiver as anotações da arma, o White Stone Oak Lumber, a barra de prata encantada da Bastilha da Presa Negra e a gema de Kor purificada da Em busca da Gema Kor."}}},
    ["05-d4"] = {name="Caverna Ululante", entrance="Sertões 46.00, 36.30", pickup="Conclua Os Charcos Esquecidos → O Oásis Estagnado → Seres alterados com Tonga no A Encruzilhada, depois visite Hamuul, Nara e Zama em Penhasco do Trovão. Entregue Chifres de raptor antes de pegar Bebidas inteligentes e Encrencas nas docas em Vila Catraca. Encontre Nalpak e Ebru na saliência acima da entrada da caverna.", pickupS={{"Conclua Os Charcos Esquecidos → O Oásis Estagnado → Seres alterados com Tonga no A Encruzilhada, depois visite Hamuul, Nara e Zama em Penhasco do Trovão"}, {"Entregue Chifres de raptor antes de pegar Bebidas inteligentes e Encrencas nas docas em Vila Catraca"}, {"Encontre Nalpak e Ebru na saliência acima da entrada da caverna"}}, tips={{k="動線", text="Anacondra na parte rasa da entrada → Cobrahn a oeste do rio → de volta ao canal, Pythas, Skum, Serpentis e Verdan a leste → depois que os quatro Senhores das Presas caírem, volte à entrada, escolte o Discípulo e mate Mutanus. Colha Ofídeas, junte Pelegos anormais e Essência Ululante pelo caminho e elimine as criaturas alteradas em ambas as alas."}, {k="取捨", text="Entregue Chifres de raptor para desbloquear Bebidas inteligentes. Se você perder uma missão, não deixe o grupo esperando na porta. Se a cadeia de oásis A Encruzilhada estiver concluída, continue a partir de Hamuul Runa Totem."}, {k="說明", text="Entre na caverna externa em Oásis das Águas Claras (47.70, 35.00) e siga o túnel até o portal. Pegue primeiro as missões de Nalpak e Ebru na alcova acima da entrada externa.", s={{"Entre na caverna externa em Oásis das Águas Claras (47.70, 35.00) e siga o túnel até o portal"}, {"Pegue primeiro as missões de Nalpak e Ebru na alcova acima da entrada externa"}}}}, steps={[1]={npc="Tonga Runa Totem", tgt="Tonga Runa Totem"}, [2]={hint="Informe Tonga Runa Totem sobre as suas descobertas."}, [3]={npc="Tonga Runa Totem", tgt="Tonga Runa Totem"}, [4]={npc="Tonga Runa Totem", tgt="Tonga Runa Totem", preText="Os Charcos Esquecidos"}, [5]={hint="Fale novamente com Tonga na Encruzilhada depois de investigar o Oásis Estagnado."}, [6]={npc="Tonga Runa Totem", tgt="Tonga Runa Totem"}, [7]={npc="Tonga Runa Totem", tgt="Tonga Runa Totem", preText="O Oásis Estagnado"}, [8]={hint="Leve 8 Cascos Alterados de Mordelisca para Tonga Runa Totem, na Encruzilhada.", tag="Alvo: Mordelisca do Oásis / Oasis Snapjaw Hatchling"}, [9]={npc="Tonga Runa Totem", tgt="Tonga Runa Totem"}, [10]={npc="Tonga Runa Totem", tgt="Tonga Runa Totem", preText="Seres alterados"}, [11]={npc="Arquidruida Hamuul Runa Totem", tgt="Arquidruida Hamuul Runa Totem"}, [12]={npc="Arquidruida Hamuul Runa Totem", tgt="Arquidruida Hamuul Runa Totem", preText="Hamuul Runa Totem"}, [13]={npc="Nara Juba Agreste", tgt="Nara Juba Agreste"}, [14]={npc="Nara Juba Agreste", tgt="Nara Juba Agreste", preText="Nara Juba Agreste"}, [15]={npc="Boticário Zaqueu", tgt="Boticário Zaqueu"}, [16]={npc="Cáliper Porcatraca", tgt="Cáliper Porcatraca"}, [17]={hint="Obtenha 5 Chifres Intactos de Raptor de Garrafoices Helióscamos e leve-os para Cáliper Porcatraca na Vila Catraca."}, [18]={npc="Cáliper Porcatraca", tgt="Cáliper Porcatraca"}, [19]={npc="Cáliper Porcatraca", tgt="Cáliper Porcatraca", preText="Chifres de raptor"}, [20]={npc="Operador de Grua Mafuá", tgt="Operador de Grua Mafuá"}, [21]={npc="Nalpak", tgt="Nalpak"}, [22]={npc="Ebru", tgt="Ebru"}, [23]={hint="O Operador de Grua Mafuá, em Vila Catraca, quer que você recupere a garrafa de Xerez de 99 Anos com Maluc Insano, que se refugiou na Caverna Ululante."}, [24]={text="Entrada: Caverna Ululante"}, [25]={hint="A Boticária Zaqueia, no Penhasco do Trovão, quer que você colete 10 Ofídeas.", desc="A Ofídea cresce na caverna externa em frente à entrada da masmorra. Local: Siga o leito raso do rio depois da entrada para encontrar Ofídea e vasculhe as duas margens atrás de plantas colhíveis.", spot="Siga o canal raso depois da porta e colha Ofídeas em ambas as margens."}, [26]={hint="Nalpak na Caverna Ululante quer 20 Pelegos Anormais.", desc="Os Deviate Slayers ficam na caverna externa em frente à entrada da masmorra. Local: Limpe as feras mutantes nas bifurcações rasas e nos dois flancos, coletando couros enquanto avança para os chefes.", spot="Mate as criaturas alteradas na bifurcação rasa e nas duas alas. Pegue os couros enquanto avança pelos chefes."}, [27]={hint="Ebru, na Caverna Ululante, quer que você mate 7 Assoladores Anormais, 7 Víboras Anormais, 7 Trôpegos Anormais e 7 Presáteras Anormais.", desc="Local: Limpe primeiro a bifurcação rasa e complete os quatro tipos de monstros nas alas oeste e leste do canal.", spot="Limpe primeiro a bifurcação rasa e complete os quatro tipos de monstros nas alas oeste e leste do canal."}, [28]={hint="Leve 6 porções de Essência Ululante para Cáliper Porcatraca na Vila Catraca.", desc="As coordenadas apontam para Ectoplasmas Devoradores fora da entrada. Você pode continuar coletando depois de entrar na masmorra. Você pode matar Ectoplasmas Devoradores fora da entrada da masmorra. Local: Dentro da masmorra, procure limos ao longo do canal de água e complete a essência se faltar.", spot="Dentro da masmorra, procure gosmas ao longo do canal se ainda faltar Essência Ululante."}, [29]={hint="Leve as Gemas de Cobrahn, Sucurina, Pítias e Serpentis para Nara Juba Agreste no Penhasco do Trovão.", desc="Local: Encontre Anacondra nas águas rasas, Cobrahn a oeste e os outros dois chefes a leste.", spot="Encontre Anacondra nas águas rasas, Cobrahn a oeste e os outros dois chefes a leste."}, [30]={npc="Estilhaço Chamejante", npcObj=true, desc="Depois dos quatro Druidas, volte à entrada e fale com o Discípulo de Naralex. Conclua a escolta e o ritual, depois mate Mutanus, o Devorador, para pegar o fragmento."}, [31]={npc="Nalpak", tgt="Nalpak"}, [32]={npc="Ebru", tgt="Ebru"}, [33]={npc="Operador de Grua Mafuá", tgt="Operador de Grua Mafuá"}, [34]={npc="Cáliper Porcatraca", tgt="Cáliper Porcatraca"}, [35]={hint="Viaje para a Vila Catraca e procure alguém que possa contar mais alguma coisa sobre a lasca faiscante."}, [36]={npc="Falla Vento Sábio", tgt="Falla Vento Sábio"}, [37]={npc="Falla Vento Sábio", tgt="Falla Vento Sábio", preText="A lasca faiscante"}, [38]={npc="Arquidruida Hamuul Runa Totem", tgt="Arquidruida Hamuul Runa Totem"}, [39]={npc="Nara Juba Agreste", tgt="Nara Juba Agreste"}, [40]={npc="Boticário Zaqueu", tgt="Boticário Zaqueu"}}},
    ["02-11"] = {name="Cordilheira das Torres de Pedra", tips={{k="交通", text="Na primeira visita ao Retiro Rocha do Sol, desbloqueie o ponto de voo e vincule a Pedra de Regresso. Depois do desvio pela passagem sul, volte ao Retiro Rocha do Sol e voe para Vila Catraca."}, {k="取捨", text="Pegue as Sementes de Gaia no Lago Mirkfallon e faça O legado de Cenarius nas Torres de Pedra. Depois de devolver as sementes, faça os quatro objetivos do Vale Carbonizado numa só ida. Em Aldeia Vento Livre, em Mil Agulhas, entregue Chamando as reservas ao passar pelo Grande Elevador."}, {k="取捨", text="Mate Ornanos só ao chegar ao Posto Machadada, no Vale Gris. Novas instruções (1095) e Hanfritz Schaventorck (1096) só valem a pena se você for voltar ao Rochedo Cortavento mais tarde; assim se poupa uma ida e volta a Vila Catraca."}, {k="取捨", text="Pode pular. Besseleth e O terrano se ergue exigem matar elites. A A magia florestal de Jin'Zil pede vários tipos de feras e é entregue no extremo sul: só entregue se já tiver os materiais."}, {k="提醒", text="Abaixo do nível 25? Mate harpias Fúria Sangrenta ou elementais de fogo na borda do Vale Carbonizado (cerca de 32, 64). Puxe um inimigo de cada vez primeiro.", s={{"Abaixo do nível 25?"}, {"Mate harpias Fúria Sangrenta ou elementais de fogo na borda do Vale Carbonizado (cerca de 32, 64)"}, {"Puxe um inimigo de cada vez primeiro"}}}}, danger={[1]="Besseleth é uma aranha de elite próxima a Passagem Tramateia. Limpe as pequenas aranhas primeiro. Pule se você não tiver um grupo.", [2]="A caverna da Ravina da Avalanche é estreita. Antes de abrir o barril para invocar Goggeroc, limpe o caminho da entrada até o barril para ter por onde recuar."}, grind={[1]={mob="Harpia Furissangue", note="Densidade média de mobs normais na entrada leste do Vale Carbonizado. Pegue os isolados pela borda, fique de olho nas patrulhas e farme a partir do nível 23."}, [2]={mob="Arauto do Vento Furissangue", note="Muitos mobs normais conjuradores no leste do Vale Carbonizado. Use a parede da montanha para puxá-los para fora do acampamento e evitar puxar ninhos inteiros. Combine com as missões do Vale Carbonizado."}}, supply={[1]={npc="Tharm"}, [2]={npc="Estalajadeira Jayka"}, [3]={npc="Borand"}, [4]={npc="Estalajadeira Jayka"}, [5]={npc="Grawnal"}, [6]={npc="Jeeda"}}, steps={[1]={text="Siga a estrada noroeste da Encruzilhada rumo à entrada das Torres de Pedra e procure primeiro Seereth Quebra-pedra, nos Sertões (35.26, 27.88)."}, [2]={hint="Fale com Seereth Quebra-pedra na Cordilheira das Torres de Pedra.", tag="Se aceita na Encruzilhada, Opcional"}, [3]={npc="Seereth Quebra-pedra", tgt="Seereth Quebra-pedra", tag="Se aceita na Encruzilhada, Opcional"}, [4]={npc="Seereth Quebra-pedra", tgt="Seereth Quebra-pedra"}, [5]={text="Siga pelo sul das Torres de Pedra até Malaka'jin e depois suba pela área das aranhas até o Rochedo Cortavento."}, [6]={hint="Entregue a carta de Darsok a Jin'Zil em sua caverna em Malaka'jin, nas Torres de Pedra.", tag="Se aceito no trecho Vila Catraca / Acampamento Taurajo"}, [7]={npc="Mandingueiro Jin'Zil", tgt="Mandingueiro Jin'Zil", tag="Se aceito no trecho Vila Catraca / Acampamento Taurajo"}, [8]={npc="Xen'Zilla", tgt="Xen'Zilla"}, [9]={npc="Mandingueiro Jin'Zil", tgt="Mandingueiro Jin'Zil", tag="Opcional"}, [10]={npc="Pôster de Procura-se: Besseleth", npcObj=true, tag="Grupo recomendado, Opcional"}, [11]={npc="Zé Fízzica", tgt="Zé Fízzica", tag="Se aceito no trecho Vila Catraca / Acampamento Taurajo"}, [12]={npc="Zé Fízzica", tgt="Zé Fízzica"}, [13]={hint="Xen'Zilla, em Malaka'Jin, precisa que você mate 10 Rastejadoras de Fundolimo e 7 Cospeçonhas de Fundolimo."}, [14]={hint="Leve 15 Ovos de Fundolimo para Cáliper Porcatraca em Vila Catraca.", tag="Se aceito no trecho Vila Catraca / Acampamento Taurajo"}, [15]={hint="Mate 15 Madeireiros da Empreendimentos S.A. e, então, fale novamente com Seereth Quebra-pedra na fronteira entre as Torres de Pedra e os Sertões."}, [16]={hint="Consiga os Diagramas do Super Ceifador 6000 e entregue-os a Zé Fízzica na Cordilheira das Torres de Pedra.", desc="O projeto cai dos Operadores da Empreendimentos S.A."}, [17]={npc="Piznik", tgt="Piznik", desc="Piznik está dentro da mina no lado leste do Rochedo Cortavento."}, [18]={hint="Pegue o minério misterioso com Piznik depois que ele terminar de minerá-lo."}, [19]={npc="Piznik", tgt="Piznik"}, [20]={npc="Piznik", tgt="Piznik"}, [21]={npc="Zé Fízzica", tgt="Zé Fízzica"}, [22]={npc="Zé Fízzica", tgt="Zé Fízzica"}, [23]={npc="Zé Fízzica", tgt="Zé Fízzica"}, [24]={hint="Mate Besseleth e leve a Presa de Besseleth a Maggran no Retiro Rocha do Sol.", tag="Grupo recomendado, Opcional", desc="Besseleth é elite. Pule se você não consegue vencê-la."}, [25]={nodeA="{a:460}", node="Sun Rock Retreat", desc="Siga a estrada até Retiro Rocha do Sol e obtenha o ponto de voo de Tharm."}, [26]={text="Vincule sua Pedra de Regresso com Estalajadeira Jayka na estalagem de Retiro Rocha do Sol (47.47, 62.13); use-a só depois de concluir as entregas do desfiladeiro sul.", bindA="{a:460}"}, [27]={npc="Maggran Ata Terra", tgt="Maggran Ata Terra", tag="Grupo recomendado, Opcional"}, [28]={npc="Tammra Campo de Vento", tgt="Tammra Campo de Vento"}, [29]={npc="Braelyn Manígnea", tgt="Braelyn Manígnea"}, [30]={npc="Maggran Ata Terra", tgt="Maggran Ata Terra"}, [31]={npc="Tsunomem", tgt="Tsunomem"}, [32]={npc="Maggran Ata Terra", tgt="Maggran Ata Terra"}, [33]={npc="Maggran Ata Terra", tgt="Maggran Ata Terra"}, [34]={npc="Mor'rogal", tgt="Mor'rogal"}, [35]={text="Dê uma volta para o norte em torno de Lago Mirkfallon e Morro das Torres de Pedra. Volte pelo mesmo caminho e entregue as sementes em Retiro Rocha do Sol antes de seguir para oeste."}, [36]={hint="Tammra Campo de Vento, no Retiro Rocha do Sol, quer que você colete 10 Sementes de Gaia."}, [37]={hint="Mate 4 Filhos de Cenarius, 4 Filhas de Cenarius e 4 Botânicos Cenarianos para Braelyn Manígnea, no Retiro Rocha do Sol."}, [38]={hint="O Mandingueiro Jin'Zil, em Malaka'jin, quer 5 porções de Seiva das Torres de Pedra, 5 Bigodes de Felino do Crepúsculo, 30 Olhos de Corcel e uma Escama de Dragão Encantado.", tag="Opcional", desc="Há muitos olhos de cervo-chifrudo: pegue-os de passagem ao fazer O legado de Cenarius e não farme só para isso."}, [39]={npc="Tammra Campo de Vento", tgt="Tammra Campo de Vento"}, [40]={npc="Tammra Campo de Vento", tgt="Tammra Campo de Vento"}, [41]={npc="Braelyn Manígnea", tgt="Braelyn Manígnea"}, [42]={npc="Braelyn Manígnea", tgt="Braelyn Manígnea", tag="Opcional"}, [43]={text="Vá para oeste do Retiro Rocha do Sol até o Vale Carbonizado e combine na mesma volta as harpias, as Pedras do Sol, os elementais do fogo e os montes de terra."}, [44]={hint="Maggran Ata Terra, no Retiro Rocha do Sol, quer que você mate 7 Hapias Furissague, 7 Emboscadoras Furissangue, 7 Matadoras Furissangue e 7 Plumerrantes Furissangue."}, [45]={hint="Leve 15 Pedras Solares Lampejantes para Mor'rogal."}, [46]={hint="Leve 10 Incenderitas a Tsunomem no Retiro Rocha do Sol."}, [47]={hint="Plante 10 Sementes de Gaia em Montículos de Terra de Gaia e, então, devolva as Sementes Encantadas de Gaia restantes a Tammra, no Retiro Rocha do Sol.", desc="Use a semente da missão em um Monturo de Terra de Gaia elevado."}, [48]={text="Depois de uma volta pelo Vale Carbonizado, volte pela estrada leste ao Retiro Rocha do Sol e entregue tudo de uma vez. Guarde a Pedra de Regresso para a volta de Malaka'jin e da passagem."}, [49]={npc="Maggran Ata Terra", tgt="Maggran Ata Terra"}, [50]={npc="Mor'rogal", tgt="Mor'rogal"}, [51]={npc="Tsunomem", tgt="Tsunomem"}, [52]={npc="Tammra Campo de Vento", tgt="Tammra Campo de Vento"}, [53]={npc="Maggran Ata Terra", tgt="Maggran Ata Terra", tag="Elite, Grupo recomendado, Opcional"}, [54]={hint="Maggram, no Retiro Rocha do Sol, quer que você mate a Estripadora Furissangue e traga os restos mortais dela como prova de seu feito.", tag="Elite, Grupo recomendado, Opcional", desc="Estripadora Furissangue é uma elite de nível 26. Traga um grupo."}, [55]={npc="Maggran Ata Terra", tgt="Maggran Ata Terra", tag="Elite, Grupo recomendado, Opcional"}, [56]={text="Depois de entregar as missões do Vale Carbonizado no Retiro Rocha do Sol, desça pela estrada sudeste. Faça as missões opcionais da Ravina da Avalanche ou vá direto a Malaka'jin e à passagem dos Sertões. Mantenha a Pedra de Regresso do Retiro Rocha do Sol para depois de entregar as missões da passagem."}, [57]={hint="Explore as profundezas da caverna na Ravina da Avalanche e colete 10 Cristais de Ressonita para que Mor'rogal, no Retiro Rocha do Sol, os analise."}, [58]={npc="Mor'rogal", tgt="Mor'rogal"}, [59]={npc="Mor'rogal", tgt="Mor'rogal", tag="Grupo recomendado, Opcional"}, [60]={hint="Abra o esquife de ressonita com o Cristal de Ressonita Encantado e, então, mate Goggeroc. Fale novamente com Mor'rogal levando as notícias e o Cristal de Ressonita Encantado.", tag="Grupo recomendado, Opcional", desc="Isso convoca uma elite de nível 20. Pule se você estiver sozinho."}, [61]={npc="Mor'rogal", tgt="Mor'rogal", tag="Grupo recomendado, Opcional"}, [62]={npc="Xen'Zilla", tgt="Xen'Zilla"}, [63]={npc="Mandingueiro Jin'Zil", tgt="Mandingueiro Jin'Zil", tag="Opcional"}, [64]={npc="Seereth Quebra-pedra", tgt="Seereth Quebra-pedra"}, [65]={npc="Seereth Quebra-pedra", tgt="Seereth Quebra-pedra", tag="Pule a viagem de volta se você tiver EXP suficiente, Opcional"}, [66]={hint="Destrua os retalhadores XT:4 e XT:9 e, então, fale novamente com Seereth Quebra-pedra na fronteira entre a Cordilheira das Torres de Pedra e os Sertões.", tag="Pule a viagem de volta se você tiver EXP suficiente, Opcional, Alvo: XT:4/XT:9"}, [67]={npc="Seereth Quebra-pedra", tgt="Seereth Quebra-pedra", tag="Pule a viagem de volta se você tiver EXP suficiente, Opcional"}, [68]={npc="Seereth Quebra-pedra", tgt="Seereth Quebra-pedra", tag="Pré-requisito Penhasco do Trovão, Opcional"}, [69]={text="Depois de entregar as missões de Seereth na passagem, use a Pedra de Regresso para voltar ao Retiro Rocha do Sol e voe com Tharm até Vila Catraca para entregar os ovos e a carta secreta. Se a Pedra de Regresso estiver em recarga, siga da passagem até os Sertões e voe da Encruzilhada para Vila Catraca."}, [70]={npc="Cáliper Porcatraca", tgt="Cáliper Porcatraca", tag="Se aceito no trecho Vila Catraca / Acampamento Taurajo"}, [71]={npc="Cobogó", tgt="Cobogó"}, [72]={npc="Cobogó", tgt="Cobogó", tag="Faça depois, quando passar por lá, Opcional"}, [73]={text="Se for fazer a introdução opcional de Sangue dos Inocentes e tiver A Bruxa Anciã, voe de Vila Catraca para o Penhasco do Trovão para continuar. Se o Penhasco do Trovão não estiver desbloqueado, voe para o Acampamento Taurajo, vá a oeste pela estrada de Mulgore até o Penhasco do Trovão e desbloqueie com Tal (47.00, 49.83). Se não pretende desbloqueá-lo no caminho, pode pular esta missão secundária e voar de Vila Catraca direto para Orgrimmar."}, [74]={npc="Magatha Temível Totem", tgt="Magatha Temível Totem", tag="Pré-requisito Penhasco do Trovão, Opcional"}, [75]={npc="Magatha Temível Totem", tgt="Magatha Temível Totem", tag="Pré-requisito Penhasco do Trovão, Opcional"}, [76]={hint="Fale com a Boticária Zaqueia nos Poços das Visões, que ficam no Penhasco do Trovão.", tag="Pré-requisito Penhasco do Trovão, Opcional"}, [77]={npc="Boticário Zaqueu", tgt="Boticário Zaqueu", tag="Pré-requisito Penhasco do Trovão, Opcional"}, [78]={npc="Boticário Zaqueu", tgt="Boticário Zaqueu", tag="Pré-requisito Penhasco do Trovão, Opcional"}, [79]={npc="Veenix", tgt="Veenix", tag="Opcional", desc="Faça esta preparação primeiro e depois a A Trompa de Xelthos na Floresta de Pinhaprata; é um método opcional para abrir uma porta e infiltrar-se na masmorra."}, [80]={hint="Saque de: Desmatador da Empreendimentos S.A., Operador da Empreendimentos S.A., Madeireiro da Empreendimentos S.A.", tag="Opcional", desc="Faça esta preparação primeiro e depois a A Trompa de Xelthos na Floresta de Pinhaprata; é um método opcional para abrir uma porta e infiltrar-se na masmorra."}, [81]={npc="Veenix", tgt="Veenix", tag="Opcional", desc="Faça esta preparação primeiro e depois a A Trompa de Xelthos na Floresta de Pinhaprata; é um método opcional para abrir uma porta e infiltrar-se na masmorra."}, [82]={npc="Ur'kyo", tgt="Ur'kyo"}, [83]={hint="Complete os objetivos da missão."}, [84]={npc="Ur'kyo", tgt="Ur'kyo"}, [85]={text="Depois das missões opcionais do Penhasco do Trovão, voe primeiro do Penhasco do Trovão a Orgrimmar. Saia de Orgrimmar e confirme a rota de Clareiras de Tirisfal com Frezza, na torre de zepelim de Durotar (50.82, 13.54). Desça na torre ao sul de Montalvo e siga a pé até as Cidade Baixa. Depois continue até a Serraria Tarren, no Contraforte de Eira dos Montes."}}},
    ["02-12"] = {name="Contraforte de Eira dos Montes", tips={{k="交通", text="Na primeira visita, vá a pé do Sepulcro até a Serraria Tarren; desbloqueie o ponto de voo com Clarissa e vincule a Pedra de Regresso com o Estalajadeiro Chê. Ao ir embora, vá a pé da Cidade Baixa até a torre ao sul de Montalvo e pegue o zepelim de Orgrimmar."}, {k="取捨", text="Colete Elixir do sofrimento a oeste na mesma ida, junto com A batalha de Eira dos Montes. Elixir da dor tem drop baixo: junte tudo de passagem e só então entregue. Depois de entregar, aparece Lembrancinhas da morte; a partir daí, colete os crânios ao matar humanos."}, {k="取捨", text="Suporte aos batedores, Elixir da Agonia: faça de passagem as duas missões ao redor de Mazoga. Se aceitou Sangue dos Inocentes, vá também aos arredores do Forte do Desterro. Ao fazer A batalha de Eira dos Montes, pegue os crânios de passagem."}, {k="取捨", text="Se faltarem alvos de Perigo! e for preciso voltar só por isso, pule-a e siga direto para a próxima parada. Dun Garok (A batalha de Eira dos Montes) tem muitos mobs; sozinho, deixe para um nível mais alto. Na crista oeste de Vantagens valiosas há pumas da montanha de nível alto; com pressa, pule a sequência secundária inteira."}, {k="取捨", text="Se já aceitou A jornada para Serraria Tarren no Retiro Rocha do Sol, aproveite a ida ao Forte do Desterro para concluir Sangue dos Inocentes e leve Volte ao Penhasco do Trovão para entregar ao passar pelo Penhasco do Trovão, a caminho da Aldeia Vento Livre, em Mil Agulhas."}, {k="取捨", text="Depois de concluir a primeira parte de Elixir da Agonia, aceite a parte seguinte na Cidade Baixa e volte à costa de Eira dos Montes para fazê-la."}, {k="提醒", text="No nível 27, faça uma visita rápida a Aldeia Vento Livre, em Mil Agulhas, antes de entrar no Vale Gris. Abaixo do 27, mate fazendeiros nas fazendas de Eira dos Montes a oeste (cerca de 33, 42) ou membros comuns da Camarilha ao redor do Forte do Desterro (cerca de 77, 43); com um grupo, também dá para encarar Dun Garok.", s={{"No nível 27, faça uma visita rápida a Aldeia Vento Livre, em Mil Agulhas, antes de entrar no Vale Gris"}, {"Abaixo do 27, mate fazendeiros nas fazendas de Eira dos Montes a oeste (cerca de 33, 42) ou membros comuns da Camarilha ao redor do Forte do Desterro (cerca de 77, 43); com um grupo, também dá para encarar Dun Garok"}}}}, danger={[1]="Os fuzileiros, sacerdotes e guardas de montanha de Dun Garok se ajudam na entrada das escadas. Com o grupo, limpe primeiro o lado de fora e só depois entre para procurar o capitão.", [2]="Siga o caminho acima da caverna do Yeti para colocar o frasco no pico oeste. Se você avistar leões da montanha de níveis mais altos, dê a volta ao longo da encosta em vez de subir direto."}, grind={[1]={mob="Fazendeiro de Eira dos Montes", note="Densidade média de mobs normais no lado leste das fazendas de Eira dos Montes. Evite os grupos na porta das casas e junte de passagem os crânios de humanos."}, [2]={note="Densidade média de mobs normais no meio das fazendas. Procure soldados de patrulha pelas bordas dos campos e evite as casas onde ficam um vereador e um fazendeiro juntos."}, [3]={mob="Urso Cinzento Ancião", note="Floresta aberta ao norte do Forte do Desterro, com poucos mobs normais. Evite os grupos do forte. É bom para matar alguns na volta pela rota leste."}}, supply={[1]={npc="Clarissa"}, [2]={npc="Estalajadeiro Chê"}, [3]={npc="Estalajadeiro Chê"}, [4]={npc="Keila Fuligissacra"}, [5]={npc="Antônio Nunes"}, [6]={npc="Thomas Mordan"}, [7]={npc="Ezequiel Potio"}}, steps={[1]={text="Se você já entrou na Cidade Baixa depois da parada do Retiro Rocha do Sol, na Cordilheira das Torres de Pedra, parta de dentro da cidade. Se o ponto de voo da Serraria Tarren já estiver desbloqueado, voe direto. Na primeira visita, voe primeiro para o Sepulcro, siga pela estrada do sul até a estrada do lado leste de Pinhaprata que leva a Eira dos Montes, atravesse o contraforte e pegue a bifurcação norte até a Serraria Tarren. Se o Sepulcro não estiver desbloqueado, saia da Cidade Baixa por terra. Só vá primeiro pegar o zepelim fora de Orgrimmar se você entrou na rota no meio do caminho e ainda está em Kalimdor."}, [2]={nodeA="{a:272}", node="Tarren Mill", desc="Na primeira visita, desbloqueie o ponto de voo com Clarissa."}, [3]={text="Vincule sua Pedra de Regresso com Estalajadeiro Chê na estalagem de Serraria Tarren (62.78, 19.03).", bindA="{a:272}"}, [4]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo"}, [5]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo", tag="Opcional"}, [6]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo", tag="Conclua antes a missão A jornada para Serraria Tarren, Opcional"}, [7]={text="Pegue em Serraria Tarren → ursos, aranhas, leões e fazendas a oeste"}, [8]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo"}, [9]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo", tag="Opcional", desc="Taxa de drop baixa. Só vale a pena se completar enquanto faz outras missões."}, [10]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia"}, [11]={npc="Perigo!", npcObj=true}, [12]={hint="Boticário Lindolfo, de Serraria Tarren, quer 10 Línguas de Urso Cinzento e um pouco de Pus de Rastejante."}, [13]={hint="Leve 10 Ampolas de Sangue de Leão da Montanha para o Boticário Lindolfo na Serraria Tarren.", tag="Opcional", desc="Taxa de drop baixa. Só vale a pena se completar enquanto faz outras missões."}, [14]={hint="Mate 6 Lavradores de Eira dos Montes, 6 Fazendeiros de Eira dos Montes, o Fazendeiro Raí e o Fazendeiro Pegaz, depois apresente-se novamente a Darthalia na Serraria Tarren."}, [15]={text="Depois da primeira volta a oeste, use a Pedra de Regresso para voltar à Serraria Tarren e entregar. Se estiver em recarga, volte pela estrada principal."}, [16]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia"}, [17]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia"}, [18]={npc="Necroguarda Sandoval", tgt="Necroguarda Sandoval"}, [19]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo"}, [20]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo"}, [21]={npc="Umpi", tgt="Umpi"}, [22]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo", tag="Opcional"}, [23]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo", tag="Opcional"}, [24]={text="Segundo circuito agrícola → Durnholde e Cogumelos Fuçalama → ferraria ocidental"}, [25]={hint="Alimente Fido com o Elixir da Dor.", tag="Opcional"}, [26]={npc="Fido", tgt="Fido", tag="Opcional"}, [27]={hint="Mate 15 Camponeses de Eira dos Montes e apresente-se novamente a Darthalia na Serraria Tarren."}, [28]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia"}, [29]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia"}, [30]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia"}, [31]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo"}, [32]={npc="Krusk", tgt="Krusk"}, [33]={npc="PROCURA-SE", npcObj=true, desc="O cartaz de PROCURA-SE também oferece esta missão (62.57, 20.66)."}, [34]={hint="Krusk, da Serraria Tarren, precisa que você liberte Drull e Tog'thar do Forte do Desterro.", desc="Pegue as duas chaves com os guardas do Forte do Desterro e liberte os dois prisioneiros dos grilhões."}, [35]={hint="Mate 10 Ladinos da Camarilha e 10 Vigias da Camarilha. Fale novamente com a Alta-executora Darthalia na Serraria Tarren para receber sua recompensa."}, [36]={hint="Leve 5 Ampolas de Sangue Inocente para o Boticário Lindolfo na Serraria Tarren.", tag="Opcional"}, [37]={hint="A Alta-executora Darthalia quer que você entregue as ordens atualizadas para o Sicário Masoj, ao sul da Serraria Tarren, nos arredores de Dun Garok."}, [38]={npc="Sicário Masoj", tgt="Sicário Masoj"}, [39]={npc="Sicário Masoj", tgt="Sicário Masoj", tag="Conclua a missão Suporte aos batedores, Opcional"}, [40]={hint="Leve 6 Cogumelos Fuçalama para o Boticário Lindolfo na Serraria Tarren."}, [41]={hint="Mate o Ferreiro Verrintão e 4 Ferreiros Aprendizes de Eira dos Montes."}, [42]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia"}, [43]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia"}, [44]={npc="Krusk", tgt="Krusk"}, [45]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia"}, [46]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo", tag="Opcional"}, [47]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo", tag="Conclua Sangue dos Inocentes primeiro. Entregue em Aldeia Vento Livre., Opcional"}, [48]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo"}, [49]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo"}, [50]={text="Prefeitura → mina → entrega na Serraria Tarren"}, [51]={hint="Mate o Magistrado Ardelado e 5 Conselheiros de Eira dos Montes. Destrua a Proclamação de Eira dos Montes. Roube o Livro de Registro de Eira dos Montes. Depois apresente-se de volta a Darthalia na Serraria Tarren."}, [52]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia"}, [53]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia"}, [54]={hint="Mate o Encarregado Grilhões e 10 Mineradores de Eira dos Montes, depois apresente-se novamente a Darthalia em Serraria Tarren."}, [55]={hint="A Alta-executora Darthalia da Serraria Tarren está oferecendo uma recompensa pelas cabeças de Tabelião Horácio Brancorcel, Cidadão Urbano, Minerador Talhatudo e a Fazendeira Kalaba."}, [56]={hint="O Necroguarda Sandoval da Serraria Tarren quer 30 Crânios Humanos de Eira dos Montes."}, [57]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia"}, [58]={npc="Necroguarda Sandoval", tgt="Necroguarda Sandoval"}, [59]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia"}, [60]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia", tag="Grupo, Grupo recomendado, Opcional"}, [61]={hint="Viaje até Dun Garok é mate 10 Montanhistas, 8 Carabineiros, 4 Sacerdotes e o Capitão Monteferro, depois apresente-se novamente a Darthalia na Serraria Tarren.", tag="Grupo, Grupo recomendado, Opcional"}, [62]={hint="O Sicário Masoj precisa que você deixe as três Ampolas de Boticário nos picos ao redor do Contraforte de Eira dos Montes e depois retorne até ele.", tag="Mob de nível alto, Opcional"}, [63]={npc="Sicário Masoj", tgt="Sicário Masoj", tag="Opcional"}, [64]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia", tag="Grupo, Grupo recomendado, Opcional"}, [65]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia", tag="Conclua antes a missão A batalha de Eira dos Montes, Opcional"}, [66]={text="Voe de Serraria Tarren para Cidade Baixa para entregar Elixir da Agonia e Comenda Lacrada de Darthalia, se você os tiver. Mantenha seu Pedra de Regresso vinculado a Serraria Tarren."}, [67]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello"}, [68]={npc="Varimatras", tgt="Varimatras", tag="Opcional"}, [69]={npc="Serguei Hinoto", tgt="Serguei Hinoto"}, [70]={npc="Serguei Hinoto", tgt="Serguei Hinoto", desc="Continue a cadeia para curar Toque de Zanzil."}, [71]={hint="Espere Serguei Hinoto concluir a cura.", desc="Continue a cadeia para curar Toque de Zanzil."}, [72]={npc="Serguei Hinoto", tgt="Serguei Hinoto", desc="Continue a cadeia para curar Toque de Zanzil."}, [73]={npc="Carta Elegante", npcObj=true, tag="Opcional", desc="Seu treinador inicia Carta Elegante. Use Detectar Armadilhas nas caixas da passagem."}, [74]={hint="Leve o Selo de Corvoforte para Fahrad na Mansão de Corvoforte, que fica oculta nas colinas de Eira dos Montes.", tag="Opcional", desc="Seu treinador inicia Carta Elegante. Use Detectar Armadilhas nas caixas da passagem."}, [75]={npc="Fahrad", tgt="Fahrad", tag="Opcional", desc="Seu treinador inicia Carta Elegante. Use Detectar Armadilhas nas caixas da passagem."}, [76]={npc="Guarda do Corvoforte", tgt="Guarda do Corvoforte", tag="Opcional", desc="Busca de reputação repetível. Pule se você estiver nivelando."}, [77]={hint="Saque de: Assassino da Camarilha, Conjurador da Camarilha, Salteador da Camarilha", tag="Opcional", desc="Busca de reputação repetível. Pule se você estiver nivelando."}, [78]={npc="Guarda do Corvoforte", tgt="Guarda do Corvoforte", tag="Opcional", desc="Busca de reputação repetível. Pule se você estiver nivelando."}, [79]={npc="Mirokos Formassilente", tgt="Mirokos Formassilente", tag="Opcional", desc="Faça junto com a missão do Forte do Desterro."}, [80]={hint="Matar: Lord Tomas", tag="Opcional", desc="Faça junto com a missão do Forte do Desterro."}, [81]={npc="Mirokos Formassilente", tgt="Mirokos Formassilente", tag="Opcional", desc="Faça junto com a missão do Forte do Desterro."}, [82]={npc="Encomenda Escondida", npcObj=true, tag="Opcional", desc="Aceite e entregue a Encomenda Escondida fora da aldeia de Pinhaprata. Nível mínimo para aceitar: 1; recomendado 23+. É preciso entrar sozinho na masmorra; use os explosivos de Veenix para abrir o portão do pátio."}, [83]={hint="Encontre a Trompa de Xelthos dentro da Bastilha da Presa Negra. Depois, leve-a até o esconderijo de C perto do Vilarejo Lenhardente. Você precisa fazer isso sem ajuda.", tag="Opcional", desc="Aceite e entregue a Encomenda Escondida fora da aldeia de Pinhaprata. Nível mínimo para aceitar: 1; recomendado 23+. É preciso entrar sozinho na masmorra; use os explosivos de Veenix para abrir o portão do pátio."}, [84]={npc="Encomenda Escondida", npcObj=true, tag="Opcional", desc="Aceite e entregue a Encomenda Escondida fora da aldeia de Pinhaprata. Nível mínimo para aceitar: 1; recomendado 23+. É preciso entrar sozinho na masmorra; use os explosivos de Veenix para abrir o portão do pátio."}, [85]={hint="Log", tag="Opcional", desc="A continuação chega por correio; confirme que recebeu a carta e volte à Encomenda Escondida."}, [86]={npc="Encomenda Escondida", npcObj=true, tag="Opcional", desc="A continuação chega por correio; confirme que recebeu a carta e volte à Encomenda Escondida."}, [87]={npc="Encomenda Escondida", npcObj=true, tag="Opcional", desc="Nível mínimo 25; recomenda-se aprender Sumir e Distração antes. Volte à Floresta de Pinhaprata depois de receber o convite para a encomenda."}, [88]={hint="Usar/coletar: Padlocked Reliquary", tag="Opcional", desc="Nível mínimo 25; recomenda-se aprender Sumir e Distração antes. Volte à Floresta de Pinhaprata depois de receber o convite para a encomenda."}, [89]={npc="Encomenda Escondida", npcObj=true, tag="Opcional", desc="Nível mínimo 25; recomenda-se aprender Sumir e Distração antes. Volte à Floresta de Pinhaprata depois de receber o convite para a encomenda."}, [90]={hint="Log", tag="Opcional", desc="Devolva somente depois de receber a carta de acompanhamento."}, [91]={npc="Encomenda Escondida", npcObj=true, tag="Opcional", desc="Devolva somente depois de receber a carta de acompanhamento."}, [92]={hint="Encha o Odre Vermelho Vazio no poço da Serraria Tarren e entregue-o para Salma nos Sertões.", desc="Mantenha o odre completo para Aldeia Vento Livre em Mil Agulhas."}, [93]={npc="Aelthalyste", tgt="Aelthalyste"}, [94]={hint="Complete os objetivos da missão."}, [95]={npc="Aelthalyste", tgt="Aelthalyste"}, [96]={npc="Anastácia Cordato", tgt="Anastácia Cordato", tag="Opcional"}, [97]={hint="Fale com Denya.", tag="Opcional"}, [98]={npc="Denya", tgt="Denya", tag="Opcional"}, [99]={text="Saia das Cidade Baixa, vá até a torre de zepelim ao sul de Montalvo e espere o zepelim de Orgrimmar na plataforma oeste, ao lado de Zapetta (60.74, 58.87); pegue esse zepelim para ir a Aldeia Vento Livre, em Mil Agulhas. Se já estiver no nível 29 e tiver concluído Aldeia Vento Livre, ao chegar a Orgrimmar siga direto para o Posto Machadada, no Vale Gris."}}},
    ["05-d7"] = {name="Excavation Site: Wetlands", nameA="{a:16732}", entrance="Pantanal 47.79, 56.16", pickup="Se já estiver no nível 24 na parada do Retiro Rocha do Sol, na Cordilheira das Torres de Pedra, você pode voar das Torres de Pedra para Orgrimmar e aceitar Mudando o cardápio com Borsgan no Bazar. Depois de sair da Serraria Tarren, vá primeiro a Ruína do Martelo, em Arathi, e aceite Boatos dos Presa do Dragão com Zaruk; em seguida atravesse a Ponte Thandol e Dun Modr e siga pela trilha de montanha perto da Rocha de Thelgen até a Agente Sicária; só entre na masmorra depois de aceitar Presa fácil.", pickupS={{"Se já estiver no nível 24 na parada do Retiro Rocha do Sol, na Cordilheira das Torres de Pedra, você pode voar das Torres de Pedra para Orgrimmar e aceitar Mudando o cardápio com Borsgan no Bazar"}, {"Depois de sair da Serraria Tarren, vá primeiro a Ruína do Martelo, em Arathi, e aceite Boatos dos Presa do Dragão com Zaruk; em seguida atravesse a Ponte Thandol e Dun Modr e siga pela trilha de montanha perto da Rocha de Thelgen até a Agente Sicária; só entre na masmorra depois de aceitar Presa fácil"}}, tips={{k="動線", text="Da entrada leste, siga para oeste pelo pântano até Salespino → pegue a trilha entre os arbustos para os raptores do matagal e Caninumbra → limpe os Presa do Dragão no acampamento sudoeste → vá para o sul até o sítio de escavação, ative o painel ao lado do Guardião e, depois de derrotá-lo, pegue a relíquia."}, {k="取捨", text="Uma corrida completa coleta a carne, o despacho dos Presa do Dragão e a relíquia do chefe final. A última parte volta a Kalimdor; entregue-a junto com a próxima viagem a Orgrimmar ou Penhasco do Trovão."}, {k="說明", text="O portal azul fica no alto da encosta a sudeste do Sítio de Escavação de Whelgar. A pedra de encontro, a Agente Sicária e o portal ficam em pontos diferentes.", s={{"O portal azul fica no alto da encosta a sudeste do Sítio de Escavação de Whelgar"}, {"A pedra de encontro, a Agente Sicária e o portal ficam em pontos diferentes"}}}}, steps={[1]={npc="Borsgan", tgt="Borsgan"}, [2]={npc="Zaruk", tgt="Zaruk"}, [3]={hint="Viaje até o Pantanal e encontre a Agente Sicária nas colinas acima do acampamento Presa do Dragão."}, [4]={npc="Agente Sicária", tgt="Agente Sicária"}, [5]={npc="Agente Sicária", tgt="Agente Sicária", preText="Boatos dos Presa do Dragão"}, [6]={text="Entrada: Excavation Site: Wetlands"}, [7]={hint="Entre nos Sítios de Escavação no Pantanal e traga Carne de Raptor do Matagal.", desc="Local: Depois do lago Salespino, siga pela trilha arbustiva antes de Caninumbra e mate os raptores.", spot="Depois do lago Salespino, siga pela trilha arbustiva antes de Caninumbra e mate os raptores."}, [8]={hint="Derrote as forças da Presa do Dragão no Sítio de Escavação e fale novamente com a Agente Sicária do lado de fora com qualquer coisa que recuperar.", desc="Local: Passe Caninumbra e elimine as tropas Presa do Dragão no campo de escavação.", spot="Passe Caninumbra e elimine as tropas Presa do Dragão no campo de escavação."}, [9]={npc="Relíquia Titânica", npcObj=true, desc="Derrote o Guardião da Relíquia, o último chefe, pegue a Relíquia Titânica e aceite a missão pelo item."}, [10]={npc="Agente Sicária", tgt="Agente Sicária"}, [11]={npc="Borsgan", tgt="Borsgan"}, [12]={hint="Leve a Relíquia Titânica até o Platô dos Anciãos, no Penhasco do Trovão e procure por alguém que possa lhe dizer mais a respeito dela.", desc="Derrote o Guardião da Relíquia, o último chefe, pegue a Relíquia Titânica e aceite a missão pelo item."}, [13]={npc="Bashana Runa Totem", tgt="Bashana Runa Totem"}, [14]={npc="Bashana Runa Totem", tgt="Bashana Runa Totem", desc="Depois de entregar Conhecimento ancestral, pegue a próxima missão com Bashana. Veja primeiro se a missão oferece a relíquia de novo. Se o material não for dado, siga o estado atual do jogo.", preText="Conhecimento ancestral"}, [15]={hint="Leve a Relíquia Titânica para Muln Terrafúria no Platô do Vigia dos Céus, no noroeste de Mulgore.", desc="Depois de entregar Conhecimento ancestral, pegue a próxima missão com Bashana. Veja primeiro se a missão oferece a relíquia de novo. Se o material não for dado, siga o estado atual do jogo."}, [16]={npc="Alaana Tempesvaga", tgt="Muln Earthfury", desc="Depois de entregar Conhecimento ancestral, pegue a próxima missão com Bashana. Veja primeiro se a missão oferece a relíquia de novo. Se o material não for dado, siga o estado atual do jogo."}}},
    ["05-d6"] = {name="Bastilha da Presa Negra", entrance="Floresta de Pinhaprata 44.70, 67.80", pickup="Antes de ir a Pinhaprata, ao passar por Cidade Baixa, pegue O Livro de Ur no Distrito Alquímico. No Sepulcro, pegue Sicários na Presa Negra e Arugal tem que morrer com Hadrec e Dalar. Bruxos podem pegar O orbe de Soran'ruk a leste do Acampamento Taurajo, nos Sertões. Paladinos mortos-vivos devem fazer antes a cadeia das Minas Mortas, de Incidente diplomático a Uma lâmina beijada pela lua, e manter Uma lâmina beijada pela lua no registro. No caminho para Eira dos Montes, ao voltar aos Reinos do Leste, voe primeiro para o Sepulcro, em Pinhaprata, e depois siga para o sul.", pickupS={{"Antes de ir a Pinhaprata, ao passar por Cidade Baixa, pegue O Livro de Ur no Distrito Alquímico"}, {"No Sepulcro, pegue Sicários na Presa Negra e Arugal tem que morrer com Hadrec e Dalar"}, {"Bruxos podem pegar O orbe de Soran'ruk a leste do Acampamento Taurajo, nos Sertões"}, {"Paladinos mortos-vivos devem fazer antes a cadeia das Minas Mortas, de Incidente diplomático a Uma lâmina beijada pela lua, e manter Uma lâmina beijada pela lua no registro"}, {"No caminho para Eira dos Montes, ao voltar aos Reinos do Leste, voe primeiro para o Sepulcro, em Pinhaprata, e depois siga para o sul"}}, tips={{k="動線", text="Mate Rethilgore e liberte Adamant → encontre Vincent no lado direito do pátio → salão de banquetes e muralhas → sala de Fenrus para o livro → limpe a torre para Nandos, o Mestre de Lobos → mate Arugal no andar de cima e verifique sua mesa."}, {k="取捨", text="Entregue O Livro de Ur e Arugal tem que morrer fora da masmorra. Entregue Sicários na Presa Negra a Vincent lá dentro. Se o grupo estiver instável antes do nível 22, tente primeiro as Ruínas de Lordaeron ou a Caverna Ululante."}, {k="說明", text="Siga ao sul a partir do Sepulcro e suba pela rampa ao norte de Vilarejo Lenhardente para entrar no castelo. Passe pelo portão externo e procure o portal perto do pátio. Para o chefe oculto de Dalaran, pegue o Tomo Negro na mesa de Arugal. Use o dispositivo de linhas ley no salão de Lenhâmbar para criar o Tomo de Dalaran.", s={{"Siga ao sul a partir do Sepulcro e suba pela rampa ao norte de Vilarejo Lenhardente para entrar no castelo"}, {"Passe pelo portão externo e procure o portal perto do pátio"}, {"Para o chefe oculto de Dalaran, pegue o Tomo Negro na mesa de Arugal"}, {"Use o dispositivo de linhas ley no salão de Lenhâmbar para criar o Tomo de Dalaran"}}}}, steps={[1]={npc="Guardião Bel'dugur", tgt="Guardião Bel'dugur"}, [2]={npc="Alto-executor Hadrec", tgt="Alto-executor Hadrec"}, [3]={npc="Dalar Tessalba", tgt="Dalar Tessalba"}, [4]={npc="Doan Karhan", tgt="Doan Karhan", tag="Opcional", desc="Os outros 3 fragmentos pequenos estão nas Profundezas Negras. Só entregue depois de concluir os dois livros."}, [5]={text="Entrada: Bastilha da Presa Negra"}, [6]={hint="Encontre o Sicário Admeto e o Sicário Vicente.", desc="Local: Depois de Rethilgore, abra a cela e siga o Sicário pela escada do pátio, pela direita.", spot="Depois de Rethilgore, abra a cela e siga o Sicário pela escada do pátio, pela direita."}, [7]={npc="Sicário Vicente", tgt="Sicário Vicente", spot="Pátio, à direita: Sicário Vicente"}, [8]={hint="Leve o Livro de Ur para o Guardião Bel'dugur no Boticarium da Cidade Baixa.", desc="Local: Passe pela muralha e suba a torre. Pegue o livro na prateleira de baixo da estante à esquerda no quarto de Fenrus.", spot="Passe pela muralha e suba a torre. Pegue o livro na prateleira de baixo da estante à esquerda no quarto de Fenrus."}, [9]={hint="Encontre 3 Fragmentos de Soran'ruk e 1 Fragmento Grande de Soran'ruk e entregue-os a Doan Karhan nos Sertões.", tag="Opcional", desc="Local: Mate os Darksouls da Presa Negra ao longo do caminho da torre. Pegue o item só se tiver a missão de bruxo.", spot="Mate os Darksouls da Presa Negra ao longo do caminho da torre. Pegue o item só se tiver a missão de bruxo."}, [10]={hint="Mate Arugal e leve sua cabeça para Dalar Tessalba no Sepulcro.", desc="Local: Depois de Nandos, o Mestre de Lobos, suba as escadas e mate Arugal em seu quarto.", spot="Depois de Nandos, o Mestre de Lobos, suba as escadas e mate Arugal em seu quarto."}, [11]={hint="Fale com Trevano Rol no Sepulcro e leve os materiais de que ele precisa.", tag="Opcional", desc="Local: Procure a barra de prata na mesa do quarto de Arugal. Pegue só se tiver a missão Uma lâmina beijada pela lua.", spot="Procure a barra de prata na mesa do quarto de Arugal. Pegue só se tiver a missão Uma lâmina beijada pela lua."}, [12]={npc="Dalar Tessalba", tgt="Dalar Tessalba"}, [13]={npc="Guardião Bel'dugur", tgt="Guardião Bel'dugur"}, [14]={npc="Doan Karhan", tgt="Doan Karhan", tag="Opcional", desc="Com os três fragmentos pequenos das Profundezas Negras (Vale Gris, Posto Machadada) em mãos, volte aos Sertões para entregar."}}},
    ["02-13"] = {name="Mil Agulhas", tips={{k="交通", text="Entre em Orgrimmar e voe para Taurajo; do extremo sul dos Sertões, desça ao vale pelo Grande Elevador e desbloqueie o ponto de voo da Aldeia Vento Livre na primeira visita. Só faça o desvio pelo Penhasco do Trovão se tiver Fogo sagrado para entregar."}, {k="取捨", text="Entregue a carta do Retiro Rocha do Sol direto ao guarda do Grande Elevador. O baú de suprimentos a oeste de Aldeia Vento Livre, os três tipos de harpias e a provação de Resistência compartilham a mesma área."}, {k="取捨", text="Faça a breve visita a Aldeia Vento Livre antes da linha principal do Vale Gris. Deixe a volta completa da Chapada Cintilante para a parada posterior da Chapada Cintilante."}, {k="取捨", text="Pode pular. A escolta de Lakota, a jaula da pantera e a sequência da patrulha oeste demoram mais; só faça se tiver companhia ou se já estiver passando pelos alvos."}, {k="提醒", text="A entrada de Urzal dos Tuscos fica no extremo sul dos Sertões, antes do Grande Elevador. Se estiver atrás no progresso esperado desta etapa, ganhe EXP nas encostas das harpias estridentes a oeste de Aldeia Vento Livre (cerca de 27, 51).", s={{"A entrada de Urzal dos Tuscos fica no extremo sul dos Sertões, antes do Grande Elevador"}, {"Se estiver atrás no progresso esperado desta etapa, ganhe EXP nas encostas das harpias estridentes a oeste de Aldeia Vento Livre (cerca de 27, 51)"}}}}, danger={[1]="A queda do elevador é fatal. Antes de cruzar a ponte de Aldeia Vento Livre ou usar o elevador do norte, espere a plataforma chegar.", [2]="Antes de abrir a caixa na caverna das harpias, elimine os inimigos próximos e deixe uma rota de fuga. Inimigos aparecem ao abrir a caixa."}, grind={[1]={mob="Hiena Courirrita", note="Densidade moderada de mobs normais no vale a oeste de Aldeia Vento Livre. Puxe um inimigo de cada vez no fundo do vale e pule o desvio do acampamento das harpias."}, [2]={mob="Harpia Guinchadora", note="Densidade moderada de mobs normais nas encostas ocidentais da harpia. Escolha harpias solitárias ao longo da borda enquanto faz a missão da harpia."}}, supply={[1]={npc="Nyse"}, [2]={npc="Estalajadeiro Abeqwa"}, [3]={npc="Starn"}, [4]={npc="Estalajadeiro Abeqwa"}, [5]={npc="Starn"}, [6]={npc="Montarr"}, [7]={npc="Omusa Chifre Troante"}}, steps={[1]={text="Na torre de zepelins ao sul de Montalvo, procure Zapetta (60.74, 58.87, plataforma oeste) para confirmar a rota de Orgrimmar. Ao chegar em Durotar, entre em Orgrimmar e voe para o Acampamento Taurajo; só se ainda estiver em Serraria Tarren, voe primeiro para Cidade Baixa e pegue o zepelim. Se tiver Volte ao Penhasco do Trovão para entregar: se Penhasco do Trovão já estiver aberto, voe até lá, entregue e depois voe para Taurajo; senão, caminhe de Taurajo para o oeste pela estrada de Mulgore até Penhasco do Trovão, suba pelo elevador, obtenha o ponto de voo de Tal e, depois de entregar, volte voando para Taurajo."}, [2]={npc="Boticário Zaqueu", tgt="Boticário Zaqueu", tag="Se aceito em Serraria Tarren, Opcional"}, [3]={text="Siga a estrada sul dos Sertões até o Grande Elevador e fale com o guarda do lado norte."}, [4]={hint="Maggran quer que você entregue uma carta a Grish Pisaléguas no Grande Elevador, que fica nos Sertões.", tag="Se aceito em Retiro Rocha do Sol"}, [5]={npc="Grish Pisa Léguas", tgt="Grish Pisa Léguas", tag="Se aceito em Retiro Rocha do Sol"}, [6]={npc="Valente Chifre da Lua", tgt="Valente Chifre da Lua"}, [7]={nodeA="{a:484}", node="Freewind Post", desc="Desça pelo Grande Elevador até o fundo do vale, siga pela estrada para o leste até a Aldeia Vento Livre, suba ao planalto pelo elevador da aldeia e desbloqueie o ponto de voo com Nyse. Neste trecho, não mude a vinculação da Pedra de Regresso."}, [8]={npc="Vigia do Rochedo Chifre Longo", tgt="Vigia do Rochedo Chifre Longo"}, [9]={npc="Vigia do Rochedo Chifre Longo", tgt="Vigia do Rochedo Chifre Longo"}, [10]={npc="Hagar Casco de Raio", tgt="Hagar Casco de Raio"}, [11]={npc="Jandia", tgt="Jandia"}, [12]={npc="Jandia", tgt="Jandia", desc="Rau Corta Montes também oferece esta missão (46.14, 51.71)."}, [13]={npc="Elu", tgt="Elu"}, [14]={npc="Pôster de Procura-se - Arnak Temível Totem", npcObj=true}, [15]={text="Limpe os acampamentos de centauros ao norte de Aldeia Vento Livre, depois vá para Dorn e os ninhos de serpentes do vento."}, [16]={hint="Mate 12 Batedores Galath, 10 Cavalgantes Galath e 6 Ventilhões Galath, depois fale novamente com o Vigia do Rochedo Chifre Longo na Aldeia Vento Livre."}, [17]={npc="Dorn Espreitaprados", tgt="Dorn Espreitaprados"}, [18]={hint="Se tiver fé, pule lá de cima das tábuas, no topo de Mil Agulhas.", desc="Salte da prancha bem na frente de Dorn. Um salto bem-sucedido teletransporta você de volta."}, [19]={npc="Dorn Espreitaprados", tgt="Dorn Espreitaprados"}, [20]={npc="Dorn Espreitaprados", tgt="Dorn Espreitaprados"}, [21]={hint="Leve o Ovo Alienígena a Hagar Casco de Raio, na Aldeia Vento Livre."}, [22]={npc="Vigia do Rochedo Chifre Longo", tgt="Vigia do Rochedo Chifre Longo"}, [23]={npc="Hagar Casco de Raio", tgt="Hagar Casco de Raio"}, [24]={npc="Vigia do Rochedo Chifre Longo", tgt="Vigia do Rochedo Chifre Longo"}, [25]={npc="Hagar Casco de Raio", tgt="Hagar Casco de Raio"}, [26]={text="Limpe as harpias estridentes e as caixas de suprimentos a oeste. Siga o vale através de Alcândora até Posto Confinalvo."}, [27]={hint="Leve 8 Suprimentos de Vento Livre Roubados para Jandia, na Aldeia Vento Livre.", desc="Vá para oeste de Aldeia Vento Livre, suba a encosta da harpia até a caixa na caverna de Um fim para as guinchadoras."}, [28]={hint="Mate 5 Harpias Guinchadoras, 5 harpias Plumerrantes Guinchadoras e 5 harpias Arautas do Vento Guinchadoras."}, [29]={hint="Leve a Garra da Grenka para Dorn Espreitaprados em Mil Agulhas.", desc="Limpe a caverna primeiro. Quebre a caixa na parte de trás para gerar Grenka Sangrunhidos."}, [30]={hint="Leve 10 Ovos de Mantícora de Alcândora para Elu, na Aldeia Vento Livre."}, [31]={npc="Pae'ka Monte Veloz", tgt="Pae'ka Monte Veloz", tag="Escolta, Opcional"}, [32]={hint="Escolte Pae'ka Monte Veloz para fora de Alcândora, depois converse com Motega Barba de Fogo, no Posto Confinalvo.", tag="Escolta, Opcional", desc="Em Alcândora, saqueie ovos e elimine manticoras perto da saída antes de escoltar Pao'ka."}, [33]={npc="Motega Barba de Fogo", tgt="Motega Barba de Fogo", tag="Escolta, Opcional"}, [34]={npc="Motega Barba de Fogo", tgt="Motega Barba de Fogo"}, [35]={npc="Motega Barba de Fogo", tgt="Motega Barba de Fogo", tag="Aceite se estiver voando para Penhasco do Trovão, Opcional"}, [36]={npc="Vizlo Limpajunta", tgt="Vizlo Limpajunta", tag="Elite, Grupo recomendado, Opcional"}, [37]={hint="Mate a fera e traga de volta o Dispositivo Hipercapacitador e a Chave da Jaula da Pantera para Vizlo Limpajunta.", tag="Elite, Grupo recomendado, Opcional", desc="Agrupe-se. A elite ataca assim que você abre a jaula."}, [38]={npc="Vizlo Limpajunta", tgt="Vizlo Limpajunta", tag="Elite, Grupo recomendado, Opcional"}, [39]={npc="Bilhete de Assassinato", npcObj=true, tag="Início: saque de patrulha, Opcional", desc="O Mensageiro Galath patrulha entre os acampamentos. Saqueie e use o Bilhete de Assassinato."}, [40]={hint="Alerte Kanati Nuvem Cinzenta, no Posto Confinalvo, do plano para assassiná-lo.", tag="Início: saque de patrulha, Opcional", desc="O Mensageiro Galath patrulha entre os acampamentos. Saqueie e use o Bilhete de Assassinato."}, [41]={npc="Kanati Nuvem Cinzenta", tgt="Kanati Nuvem Cinzenta", tag="Início: saque de patrulha, Opcional"}, [42]={npc="Kanati Nuvem Cinzenta", tgt="Kanati Nuvem Cinzenta", tag="Início: saque de patrulha, Opcional"}, [43]={hint="Proteja Kanati Nuvem Cinzenta do ataque dos centauros.", tag="Início: saque de patrulha, Opcional", desc="Cure e beba antes de aceitar. O ataque começa imediatamente."}, [44]={npc="Kanati Nuvem Cinzenta", tgt="Kanati Nuvem Cinzenta", tag="Início: saque de patrulha, Opcional"}, [45]={text="Pegue a rampa oeste até Pináculo da Nuvem Negra para a nota e atravesse as pontes para o norte."}, [46]={hint="Localize e recupere os três Bilhetes Secretos no Pináculo da Nuvem Negra.", desc="Pegue a rampa em 31.5, 36.7 para a ponte. Procure as notas em todos os três campos."}, [47]={hint="Mate Arnak Temível Totem e leve uma prova de seu feito para o Vigia do Rochedo Chifre Longo, na Aldeia Vento Livre."}, [48]={npc="Lakota Cantéolo", tgt="Lakota Cantéolo", tag="Se o tempo permitir"}, [49]={hint="Escolte Lakota Cantéolo para fora do Pináculo da Nuvem Negra e depois fale com Thalia Couro Âmbar, na Aldeia Vento Livre.", tag="Se o tempo permitir", desc="Limpe a área da gaiola e a ponte primeiro, depois acompanhe Lakota montanha abaixo."}, [50]={hint="Reúna 10 punhados de Agave Incendia, depois consulte Magatha Temível Totem no Platô dos Anciãos, que fica no Penhasco do Trovão.", tag="Se o tempo permitir, Opcional"}, [51]={text="Primeiro entregue Teste de resistência a Dorn, a nordeste, e depois volte a Aldeia Vento Livre para entregar tudo de uma vez."}, [52]={npc="Dorn Espreitaprados", tgt="Dorn Espreitaprados"}, [53]={npc="Dorn Espreitaprados", tgt="Dorn Espreitaprados", tag="Se encontrar, Grupo recomendado, Opcional"}, [54]={npc="Vigia do Rochedo Chifre Longo", tgt="Vigia do Rochedo Chifre Longo"}, [55]={npc="Jandia", tgt="Jandia"}, [56]={npc="Jandia", tgt="Jandia"}, [57]={npc="Elu", tgt="Elu"}, [58]={npc="Vigia do Rochedo Chifre Longo", tgt="Vigia do Rochedo Chifre Longo"}, [59]={npc="Thalia Couro Âmbar", tgt="Thalia Couro Âmbar"}, [60]={hint="Leve os Fragmentos de Rok'Alim para Dorn Espreitaprados em Mil Agulhas.", tag="Se encontrar, Grupo recomendado, Opcional", desc="Procure Petra'lim, o Batedor no vale oeste e perto de Alcândora."}, [61]={npc="Dorn Espreitaprados", tgt="Dorn Espreitaprados", tag="Se encontrar, Grupo recomendado, Opcional"}, [62]={text="Se tiver Fogo sagrado para entregar e o ponto de voo do Penhasco do Trovão estiver desbloqueado, voe primeiro da Aldeia Vento Livre para o Penhasco do Trovão. Se não for ao Penhasco do Trovão, pule a próxima entrega e siga direto para os passos de saída desta parada."}, [63]={npc="Magatha Temível Totem", tgt="Magatha Temível Totem", tag="Entregue em Penhasco do Trovão, Opcional"}, [64]={npc="Salma", tgt="Salma"}, [65]={npc="Salma", tgt="Salma", desc="Pegue água no Posto Machadada. Volte aos Sertões para entregar."}, [66]={text="Vá da Aldeia Vento Livre ou do Penhasco do Trovão até o Posto Machadada, no Vale Gris."}}},
    ["02-14"] = {name="Vale Gris", tips={{k="交通", text="Desbloqueie primeiro o Posto Machadada e depois o Assentamento Zoram'gar. Conforme as missões a entregar, voe para o Posto Machadada, o Retiro Rocha do Sol ou a Encruzilhada, ou voe direto de Zoram'gar para Orgrimmar. Mantenha a Pedra de Regresso vinculada à Serraria Tarren."}, {k="取捨", text="Faça uma volta em cada um: os pioneiros ao sul do Posto Machadada, os elementais do lago a sudoeste e os sátiros ao norte. Resolva junto os ursos de Zoram'gar e o talismã da caverna."}, {k="取捨", text="Pode pular. As três feras patrulham; só as mate se cruzar com elas. Se sobrarem páginas soltas, troque mais tarde em vez de farmar repetidamente."}, {k="取捨", text="Depois do nível 29, se já for passar pela Encruzilhada e por Orgrimmar, aceite antes O enxame se adensa: leve primeiro a Orgrimmar, entregue e aceite a continuação, depois leve à Chapada Cintilante e entregue; ainda há mais uma etapa depois. Pule se não estiver no caminho desta etapa."}, {k="提醒", text="Abaixo do nível 30? Priorize sátiros (cerca de 67, 57) ou furbolgs Pelocardo (cerca de 32, 38). Se o grupo estiver pronto, faça as Profundezas Negras na Praia de Zoram. Se os companheiros ainda não estiverem reunidos, continue com esta etapa.", s={{"Abaixo do nível 30?"}, {"Priorize sátiros (cerca de 67, 57) ou furbolgs Pelocardo (cerca de 32, 38)"}, {"Se o grupo estiver pronto, faça as Profundezas Negras na Praia de Zoram"}, {"Se os companheiros ainda não estiverem reunidos, continue com esta etapa"}}}}, danger={[1]="Astranaar é uma cidade da Aliança, com sentinelas de nível 40 na estrada. Contorne-a por fora no caminho para Zoram'gar.", [2]="Os furbolgs dentro do Covil dos Pelocardo podem bloquear as passagens estreitas. Abra caminho até a saída antes de abrir o baú ou de aceitar a escolta de Ruul."}, grind={[1]={mob="Assombrante Malmíscar", note="Densidade moderada de mobs normais fora do acampamento dos sátiros. Limpe ao longo da borda, observe patrulhas e sátiros próximos e colete Chifres de Sátiro."}, [2]={mob="Patalmas Alfa", note="Densidade média de mobs normais na floresta ao norte do Posto Machadada. Puxe um por vez em área aberta, perto do ponto de voo; bom para ganhar EXP sem entrar no acampamento dos sátiros."}, [3]={mob="Ladino Xaviano", note="Densidade média de mobs normais no acampamento de Xavian. Cuidado com inimigos ocultos e patrulhas; limpe primeiro o lado de fora e só depois entre. Bom para o último trecho do nível 29, aproveitando para pegar Chifres de Sátiro."}}, supply={[1]={npc="Vhulgra"}, [2]={npc="Estalajadeira Kailisk"}, [3]={npc="Burkrum"}, [4]={npc="Estalajadeira Kailisk"}, [5]={npc="Burkrum"}, [6]={npc="Andruk"}, [7]={npc="Wik'Tar"}}, steps={[1]={text="Se o ponto de voo do Posto Machadada estiver desbloqueado, voe direto da Aldeia Vento Livre ou do Penhasco do Trovão. Se não, voe primeiro para a Encruzilhada, vá ao norte pelos Sertões passando pela Muralha Mor'shan e siga a estrada do lado leste do Vale Gris até o Posto Machadada.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [2]={nodeA="{a:431}", node="Splintertree Post", desc="Desbloqueie o ponto de voo com Vhulgra. Guarde a Pedra de Regresso da Serraria Tarren para a volta aos Reinos do Leste; se ela estiver vinculada em outro lugar e você quiser usá-la no Vale Gris, procure a Estalajadeira Kailisk."}, [3]={hint="Fale com Senani Coração Trovejante no Posto Machadada, que fica no Vale Gris.", tag="Se aceito no trecho Vila Catraca / Acampamento Taurajo"}, [4]={npc="Senani Coração Trovejante", tgt="Senani Coração Trovejante", tag="Se aceito no trecho Vila Catraca / Acampamento Taurajo"}, [5]={npc="Senani Coração Trovejante", tgt="Senani Coração Trovejante"}, [6]={hint="Complete os objetivos da missão.", desc="Entregue A caçada do Vale Gris e, em seguida, faça A Caçada do Vale Gris antes de iniciar as três missões de caça dos drops."}, [7]={npc="Senani Coração Trovejante", tgt="Senani Coração Trovejante"}, [8]={npc="Mastok Wrilehiss", tgt="Mastok Wrilehiss"}, [9]={npc="Pixel", tgt="Pixel"}, [10]={npc="Koray'bin", tgt="Koray'bin"}, [11]={npc="Gurda Marcafúria", tgt="Gurda Marcafúria", tag="Só se faltarem páginas, Opcional"}, [12]={text="Mate os Vanguardeiros ao sul do Posto Machadada e siga para sudoeste até o lago."}, [13]={npc="Garra de Garraguda", npcObj=true, tag="Aceite se você vir o alvo, Opcional", desc="Mate Garraguda e clique com o botão direito na garra na mochila para iniciar a missão."}, [14]={hint="Leve a Garra de Garraguda para Senani Coração Trovejante no Posto Machadada, Vale Gris.", tag="Aceite se você vir o alvo, Opcional", desc="Mate Garraguda e clique com o botão direito na garra na mochila para iniciar a missão."}, [15]={hint="Mate 9 Vanguardeiros do Vale Gris, depois fale novamente com Koray'bin, no Posto Machadada."}, [16]={npc="Batedor do Brado Guerreiro", tgt="Batedor do Brado Guerreiro", tag="Requer o Relatório dos Brado Guerreiro, Opcional", desc="Se ainda não abriu a pasta, clique com o botão direito nela para obter o Relatório dos Brado Guerreiro e troque-o com o batedor."}, [17]={hint="Complete os objetivos da missão.", tag="Requer o Relatório dos Brado Guerreiro, Opcional"}, [18]={npc="Batedor do Brado Guerreiro", tgt="Batedor do Brado Guerreiro", tag="Requer o Relatório dos Brado Guerreiro, Opcional"}, [19]={npc="Torek", tgt="Torek", tag="Escolta"}, [20]={hint="Acompanhe Torek no ataque ao Posto Avançado Asa de Prata e sua comandante, Duriel Flameluna. Em seguida, apresente-se a Ertog Raivatusco no Posto Machadada.", tag="Escolta", desc="Espere seu grupo perto de Torek. A luta começa assim que você aceita a missão de escolta."}, [21]={hint="Liquide 12 Elementais da Água Contaminados no Lago Mistral, a leste do Túnel Garracava e a sudoeste de Posto Machadada."}, [22]={npc="Globo d'Água Conspurcado", npcObj=true, tag="Faça se cair, Opcional", desc="Encontre Mareante à beira do lago. Clique com o botão direito em Globo d'Água Conspurcado para iniciar."}, [23]={hint="Entregue o Globo d'Água Conspurcado a Mastok Wrilehiss no Posto Machadada, no Vale Gris.", tag="Faça se cair, Opcional", desc="Encontre Mareante à beira do lago. Clique com o botão direito em Globo d'Água Conspurcado para iniciar."}, [24]={npc="Pata de Ursangous", npcObj=true, tag="Faça se cair, Opcional", desc="Mate Ursangous e clique com o botão direito na pata dele na mochila para iniciar a missão."}, [25]={hint="Leve a Pata de Ursangous para Senani Coração Trovejante no Posto Machadada, Vale Gris.", tag="Faça se cair, Opcional", desc="Mate Ursangous e clique com o botão direito na pata dele na mochila para iniciar a missão."}, [26]={npc="Cabeça de Shadumbra", npcObj=true, tag="Faça se cair, Opcional", desc="Mate Shadumbra e clique com o botão direito na cabeça dela na mochila para iniciar a missão."}, [27]={hint="Leve a Cabeça de Shadumbra para Senani Coração Trovejante no Posto Machadada, Vale Gris.", tag="Faça se cair, Opcional", desc="Mate Shadumbra e clique com o botão direito na cabeça dela na mochila para iniciar a missão."}, [28]={text="Siga o lago para nordeste em direção a Posto Machadada. Mate Ornanos e limpe o acampamento dos sátiros no caminho de volta."}, [29]={hint="Leve a Cabeça de Ornanos a Braelyn Manígnea no Retiro Rocha do Sol.", tag="Se aceito em Retiro Rocha do Sol, Opcional"}, [30]={hint="Consiga 16 Chifres de Sátiro para Pixel no Posto Machadada."}, [31]={npc="Pioneira do Brado Guerreiro", tgt="Pioneira do Brado Guerreiro", tag="Requer o Relatório dos Brado Guerreiro, Opcional"}, [32]={hint="Complete os objetivos da missão.", tag="Requer o Relatório dos Brado Guerreiro, Opcional"}, [33]={npc="Pioneira do Brado Guerreiro", tgt="Pioneira do Brado Guerreiro", tag="Requer o Relatório dos Brado Guerreiro, Opcional"}, [34]={npc="Koray'bin", tgt="Koray'bin"}, [35]={npc="Mastok Wrilehiss", tgt="Mastok Wrilehiss"}, [36]={npc="Pixel", tgt="Pixel"}, [37]={npc="Ertog Raivatusco", tgt="Ertog Raivatusco", tag="Entregue após a escolta"}, [38]={npc="Senani Coração Trovejante", tgt="Senani Coração Trovejante", tag="Entregue assim que tiver a captura, Opcional"}, [39]={npc="Senani Coração Trovejante", tgt="Senani Coração Trovejante", tag="Entregue assim que tiver a captura, Opcional"}, [40]={npc="Senani Coração Trovejante", tgt="Senani Coração Trovejante", tag="Entregue assim que tiver a captura, Opcional"}, [41]={npc="Senani Coração Trovejante", tgt="Senani Coração Trovejante", tag="Entregue assim que tiver a captura, Opcional"}, [42]={hint="Complete os objetivos da missão.", tag="Entregue assim que tiver a captura, Opcional"}, [43]={npc="Senani Coração Trovejante", tgt="Senani Coração Trovejante", tag="Entregue assim que tiver a captura, Opcional"}, [44]={npc="Mastok Wrilehiss", tgt="Mastok Wrilehiss", tag="Aceite se pegar o Globo d'Água Conspurcado, Opcional"}, [45]={npc="Mastok Wrilehiss", tgt="Mastok Wrilehiss", tag="Aceite se pegar o Globo d'Água Conspurcado, Opcional"}, [46]={hint="Encontre as 12 páginas que voaram do Manual de Operações do Retalhador e organize-as nos capítulos 1, 2 e 3. Devolva o manual a Gurda Marcafúria, que está perto do Posto Machadada.", tag="Requer todas as páginas, Opcional", desc="Não farme monstros por páginas que faltam. Use as páginas da mochila para montar os capítulos."}, [47]={npc="Gurda Marcafúria", tgt="Gurda Marcafúria", tag="Requer todas as páginas, Opcional"}, [48]={node="Assentamento Zoram'gar", desc="Se já estiver desbloqueado, voe para lá do Posto Machadada. Na primeira visita, siga pela estrada do Vale Gris para o oeste, evite os guardas da Aliança em Astranaar, depois desvie para a costa oeste e desbloqueie o ponto de voo com Andruk."}, [49]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea", tag="Se tiver a cadeia do globo d'água, Opcional"}, [50]={npc="Mensageiro do Brado Guerreiro", tgt="Mensageiro do Brado Guerreiro", tag="Requer o Relatório dos Brado Guerreiro, Opcional"}, [51]={hint="Complete os objetivos da missão.", tag="Requer o Relatório dos Brado Guerreiro, Opcional"}, [52]={npc="Mensageiro do Brado Guerreiro", tgt="Mensageiro do Brado Guerreiro", tag="Requer o Relatório dos Brado Guerreiro, Opcional"}, [53]={npc="Karang Amakkar", tgt="Karang Amakkar"}, [54]={npc="Mitsuwa", tgt="Mitsuwa"}, [55]={npc="Marukai", tgt="Marukai", tag="Mobs de baixo nível para EXP extra, Opcional"}, [56]={hint="Entregue 20 Cabeças de Iracauda a Marukai, na Praia de Zoram.", tag="Mobs de baixo nível para EXP extra, Opcional"}, [57]={npc="Marukai", tgt="Marukai", tag="Mobs de baixo nível para EXP extra, Opcional"}, [58]={text="Siga a estrada leste até Aldeia dos Pelocardo. Mate Furbolgs e saqueie os amuletos na caverna ao norte da vila."}, [59]={hint="Mate 12 Vingadores Pelocardo e 12 Xamãs Pelocardo; a maioria se localiza a leste da Praia de Zoram, na Aldeia dos Pelocardo. Uma vez concluído, fale novamente com Karang Amakkar no Assentamento Zoram'gar, Vale Gris."}, [60]={hint="Entregue 8 Patuás Troll para Mitsuwa, no Assentamento Zoram'gar."}, [61]={npc="Ruul Casco de Neve", tgt="Ruul Casco de Neve", tag="Escolta"}, [62]={hint="Escolte Ruul e, em seguida, fale com Yama Casco de Neve, no Posto Machadada.", tag="Escolta", desc="Mobs podem aparecer na entrada e no interior. Limpe a passagem antes de aceitar."}, [63]={npc="Karang Amakkar", tgt="Karang Amakkar"}, [64]={npc="Mitsuwa", tgt="Mitsuwa"}, [65]={npc="Karang Amakkar", tgt="Karang Amakkar", tag="Retorne ao acampamento oriental, Opcional"}, [66]={hint="Finque o Estandarte de Karang no Montículo Totêmico dos Torpeflora. Não deixe que os pelursos destruam o estandarte. Derrote o Chefe Murgut e leve o Totem de Murgut para Karang Amakkar em Zoram'gar.", tag="Retorne ao acampamento oriental, Opcional", desc="Limpe a área antes de plantar a bandeira. Esteja pronto para controlar as ondas."}, [67]={npc="Karang Amakkar", tgt="Karang Amakkar", tag="Retorne ao acampamento oriental, Opcional"}, [68]={npc="Muglash", tgt="Muglash", tag="Escolta em grupo, Opcional"}, [69]={hint="Escolte Muglash em segurança até o braseiro. Ajude-o a apagar o braseiro, e proteja-o na luta contra as nagas.", tag="Escolta em grupo, Opcional"}, [70]={npc="Mensageiro do Brado Guerreiro", tgt="Mensageiro do Brado Guerreiro", tag="Escolta em grupo, Opcional"}, [71]={text="Se for entregar Liberdade para Ruul! ou ainda tiver missões no Posto Machadada, voe do Assentamento Zoram'gar ao Posto Machadada; se a Pedra de Regresso estiver vinculada ao Posto Machadada e disponível, pode usá-la. Se não fez a escolta e não tem nada para entregar, fique no Assentamento Zoram'gar e voe daqui direto ao próximo destino."}, [72]={npc="Yama Casco de Neve", tgt="Yama Casco de Neve", tag="Se a escolta estiver completa"}, [73]={text="Se concluiu Ornanos ou pretende continuar com Instruções adicionais, voe do Assentamento Zoram'gar ou do Posto Machadada ao Retiro Rocha do Sol (45.12, 59.84). Se não tem pendências nas Torres de Pedra, pule esta viagem."}, [74]={npc="Braelyn Manígnea", tgt="Braelyn Manígnea", tag="Se aceito em Retiro Rocha do Sol, Opcional"}, [75]={npc="Zé Fízzica", tgt="Zé Fízzica", tag="Se aceito e retornando para Rochedo Cortavento, Opcional"}, [76]={npc="Zé Fízzica", tgt="Zé Fízzica", tag="Se aceito e retornando para Rochedo Cortavento, Opcional"}, [77]={hint="Leve o Braço Mecânico do Hanfritz a Zé Fízzica na Cordilheira das Torres de Pedra.", tag="Se aceito e retornando para Rochedo Cortavento, Opcional", desc="Suba pela encosta ao norte do Rochedo Cortavento até o andaime de madeira. Não o procure no fundo do lago. Gerenzo está no andaime elevado."}, [78]={npc="Zé Fízzica", tgt="Zé Fízzica", tag="Se aceito e retornando para Rochedo Cortavento, Opcional"}, [79]={npc="Braelyn Manígnea", tgt="Braelyn Manígnea", tag="Mais tarde ou em grupo, Opcional"}, [80]={hint="Vá ao Retiro da Garra no Morro das Torres de Pedra. Usando a Chave do Guardião do Portal, obtenha os itens escondidos pelos druidas. Use esses itens para abrir o Tesouro do Retiro da Garra.", tag="Mais tarde ou em grupo, Opcional", desc="Os guardiões da porta e os alvos da caverna ficam agrupados; só avance mais fundo se estiver em grupo e for no seu caminho. Os três primeiros pontos são três esconderijos; o último é o depósito da caverna do Morro das Torres de Pedra."}, [81]={npc="Tesouro do Retiro do Gadanho", npcObj=true, tag="Mais tarde ou em grupo, Opcional"}, [82]={text="Com os três Relatórios dos Brado Guerreiro, vá à Encruzilhada e siga pela estrada norte, passando pelo Baluarte de Mor'shan, até Kadrak (48.12, 5.42). Se já desbloqueou o ponto de voo do Vale Gris, também pode descer pela estrada leste direto para o sul."}, [83]={hint="Abra o Monte de Relatórios e entregue os Relatórios dos Brado Guerreiro ao Batedor do Brado Guerreiro, o Mensageiro do Brado Guerreiro e o Pioneiro do Brado Guerreiro. Em seguida, entregue o informe sobre a situação atual que você receberá de cada um deles para Kadrak, na torre de vigia do norte dos Sertões.", tag="Entregue com todos os três relatórios atualizados, Opcional", desc="Entregue aqui os três relatórios atualizados, recebidos em troca dos três emissários. A abertura da pasta e as trocas já devem ter sido feitas na parte anterior."}, [84]={npc="Kadrak", tgt="Kadrak", tag="Entregue com todos os três relatórios atualizados, Opcional"}, [85]={npc="Ulorico Glacivéu", tgt="Ulorico Glacivéu", tag="Opcional", desc="Aceite Uma lâmina beijada pela lua primeiro; esta parte é aceita ao chegar à Praia de Zoram, no Vale Gris."}, [86]={hint="Leve uma Gema Kor para Ulorico Glacivéu no Vale Gris.", tag="Opcional", desc="Aceite Uma lâmina beijada pela lua primeiro; esta parte é aceita ao chegar à Praia de Zoram, no Vale Gris."}, [87]={npc="Ulorico Glacivéu", tgt="Ulorico Glacivéu", tag="Opcional", desc="Aceite Uma lâmina beijada pela lua primeiro; esta parte é aceita ao chegar à Praia de Zoram, no Vale Gris."}, [88]={hint="Fale com Trevano Rol no Sepulcro e leve os materiais de que ele precisa.", tag="Opcional", desc="Entregue só depois de juntar os três materiais. As Minas Mortas ficam em Cerro Oeste; a Horda pode chegar lá pela Selva do Espinhaço e pela Floresta do Crepúsculo. Mate Goblins Entalhadores para pegar Carvalho de Pedra Branca."}, [89]={npc="Trevano Rol", tgt="Trevano Rol", tag="Opcional", desc="Com os três materiais em mãos, volte à Floresta de Pinhaprata: voe do Vale Gris a Orgrimmar, pegue o zepelim até Tirisfal e voe até o Sepulcro."}, [90]={npc="Trevano Rol", tgt="Trevano Rol", tag="Opcional", desc="Se ainda não passou pela Serraria Tarren, faça isso nessa etapa; se já passou, voe até lá a partir do Sepulcro."}, [91]={hint="Fale com Ott e peça que ele forje a sua lâmina.", tag="Opcional", desc="Se ainda não passou pela Serraria Tarren, faça isso nessa etapa; se já passou, voe até lá a partir do Sepulcro."}, [92]={npc="Ott", tgt="Ott", tag="Opcional", desc="Se ainda não passou pela Serraria Tarren, faça isso nessa etapa; se já passou, voe até lá a partir do Sepulcro."}, [93]={npc="Ott", tgt="Ott", tag="Opcional"}, [94]={hint="Observe Ott forjar a sua lâmina.", tag="Opcional"}, [95]={npc="Ott", tgt="Ott", tag="Opcional"}, [96]={npc="Ott", tgt="Ott", tag="Opcional", desc="Ao entregar, você recebe a Lâmina de Prataluna.", star={"Lâmina de Prataluna", {"PALADIN"}}}, [97]={hint="Leve a Obra-prima de Ott a Trevano Rol na Floresta de Pinhaprata.", tag="Opcional", desc="Ao entregar, você recebe a Lâmina de Prataluna."}, [98]={npc="Trevano Rol", tgt="Trevano Rol", tag="Opcional", desc="Ao entregar, você recebe a Lâmina de Prataluna.", star={"Lâmina de Prataluna", {"PALADIN"}}}, [99]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento", tag="Grupo recomendado, Opcional", desc="Elite itinerante de cerca do nível 25; pode ser feita em grupo. É preciso saber usar espadas de duas mãos: se ainda não sabe, aprenda com o mestre de armas Archibald, no Distrito Militar das Cidade Baixa (57.31, 32.77), e treine até conseguir acertar. Ao entregar a missão, você recebe Mata-cão.", star={"Mata-cão", {"PALADIN"}}}, [100]={hint="Use a Lâmina de Prataluna para eliminar o Velho Olho-de-fogo na Floresta de Pinhaprata.", tag="Grupo recomendado, Opcional", desc="Elite itinerante de cerca do nível 25; pode ser feita em grupo. É preciso saber usar espadas de duas mãos: se ainda não sabe, aprenda com o mestre de armas Archibald, no Distrito Militar das Cidade Baixa (57.31, 32.77), e treine até conseguir acertar. Ao entregar a missão, você recebe Mata-cão."}, [101]={npc="Lúmina Cantavento", tgt="Lúmina Cantavento", tag="Grupo recomendado, Opcional", desc="Elite itinerante de cerca do nível 25; pode ser feita em grupo. É preciso saber usar espadas de duas mãos: se ainda não sabe, aprenda com o mestre de armas Archibald, no Distrito Militar das Cidade Baixa (57.31, 32.77), e treine até conseguir acertar. Ao entregar a missão, você recebe Mata-cão.", star={"Mata-cão", {"PALADIN"}}}, [102]={hint="Leve para Thun'grim Olhafogo 15 Lingotes Fumegantes de Ferro, 10 Azuritas Pulverizadas, 10 Barras de Ferro e a Ampola de Flogisto.", tag="Opcional", desc="Pule a missão de equipamento por enquanto se estiver faltando flogisto ou materiais de mineração."}, [103]={npc="Thun'grim Olhafogo", tgt="Thun'grim Olhafogo", tag="Opcional", desc="Pule a missão de equipamento por enquanto se estiver faltando flogisto ou materiais de mineração."}, [104]={npc="Thun'grim Olhafogo", tgt="Thun'grim Olhafogo", tag="Opcional", star={"Cota Brutal", {"WARRIOR"}}}, [105]={npc="Thun'grim Olhafogo", tgt="Thun'grim Olhafogo", tag="Opcional", star={"Cota Brutal", {"WARRIOR"}}}, [106]={npc="Thun'grim Olhafogo", tgt="Thun'grim Olhafogo", tag="Opcional"}, [107]={npc="Ula'elek", tgt="Ula'elek", tag="Opcional"}, [108]={npc="Ula'elek", tgt="Ula'elek", tag="Opcional", desc="Dá para farmar na mesma área dos Chifres de Sátiro, mas conclua Cota brutal antes."}, [109]={hint="Leve 7 Cascos Não-fendidos de Sátiro para Ula'elek na Aldeia Sen'jin em Durotar", tag="Opcional", desc="Dá para farmar na mesma área dos Chifres de Sátiro, mas conclua Cota brutal antes."}, [110]={npc="Ula'elek", tgt="Ula'elek", tag="Opcional", desc="Dá para farmar na mesma área dos Chifres de Sátiro, mas conclua Cota brutal antes."}, [111]={npc="Ula'elek", tgt="Ula'elek", tag="Opcional"}, [112]={npc="Ula'elek", tgt="Ula'elek", tag="Opcional"}, [113]={npc="Thun'grim Olhafogo", tgt="Thun'grim Olhafogo", tag="Opcional"}, [114]={npc="Orm Casco de Pedra", tgt="Orm Casco de Pedra", tag="Opcional"}, [115]={npc="Orm Casco de Pedra", tgt="Orm Casco de Pedra", tag="Opcional", desc="Volte para pegar o equipamento somente se você tiver um grupo ou tiver um nível alto o suficiente."}, [116]={hint="Leve um Chifre Galvanizado para Orm Casco de Pedra no Penhasco do Trovão.", tag="Opcional", desc="Volte para pegar o equipamento somente se você tiver um grupo ou tiver um nível alto o suficiente."}, [117]={npc="Orm Casco de Pedra", tgt="Orm Casco de Pedra", tag="Opcional", desc="Volte para pegar o equipamento somente se você tiver um grupo ou tiver um nível alto o suficiente."}, [118]={npc="Orm Casco de Pedra", tgt="Orm Casco de Pedra", tag="Opcional"}, [119]={npc="Orm Casco de Pedra", tgt="Orm Casco de Pedra", tag="Opcional"}, [120]={npc="Thun'grim Olhafogo", tgt="Thun'grim Olhafogo", tag="Opcional"}, [121]={hint="Fale com Velora Noitile na Cidade Baixa.", tag="Opcional"}, [122]={npc="Velora Noitile", tgt="Velora Noitile", tag="Opcional"}, [123]={npc="Velora Noitile", tgt="Velora Noitile", tag="Opcional", desc="Requer um desvio para Pantanal. Pule se você estiver apenas nivelando."}, [124]={hint="Leve 8 Tíbias Firmes de Presa do Dragão para Velora Noitile na Cidade Baixa.", tag="Opcional", desc="Requer um desvio para Pantanal. Pule se você estiver apenas nivelando."}, [125]={npc="Velora Noitile", tgt="Velora Noitile", tag="Opcional", desc="Requer um desvio para Pantanal. Pule se você estiver apenas nivelando."}, [126]={npc="Velora Noitile", tgt="Velora Noitile", tag="Opcional"}, [127]={npc="Velora Noitile", tgt="Velora Noitile", tag="Opcional"}, [128]={hint="Encha o Odre Azul Vazio nas Ruínas de Poeira Estelar, que fica no Vale Gris, e devolva-o para Salma nos Sertões.", desc="Volte aos Sertões pelo sudoeste do Vale Gris para entregar."}, [129]={npc="Salma", tgt="Salma", desc="Volte aos Sertões pelo sudoeste do Vale Gris para entregar."}, [130]={npc="Salma", tgt="Salma"}, [131]={npc="Islen Vidente da Água", tgt="Islen Vidente da Água"}, [132]={npc="Islen Vidente da Água", tgt="Islen Vidente da Água", desc="Faça a purificação em Pinhaprata, de passagem pela etapa da Serraria Tarren."}, [133]={npc="Denya", tgt="Denya", tag="Opcional", desc="Fique dentro da cachoeira e use o frasco da missão."}, [134]={hint="Leve uma Amostra de Água Xaviana para Denya em Orgrimmar.", tag="Opcional", desc="Fique dentro da cachoeira e use o frasco da missão."}, [135]={npc="Denya", tgt="Denya", tag="Opcional", desc="Fique dentro da cachoeira e use o frasco da missão."}, [136]={npc="Denya", tgt="Denya", tag="Opcional"}, [137]={hint="Leve 12 Cabelos das Irmãs Risonhas para Kil'hala na Encruzilhada.", tag="Opcional"}, [138]={npc="Kil'hala", tgt="Kil'hala", tag="Opcional"}, [139]={npc="Kil'hala", tgt="Kil'hala", tag="Opcional"}, [140]={hint="Complete os objetivos da missão.", tag="Opcional"}, [141]={npc="Kil'hala", tgt="Kil'hala", tag="Opcional"}, [142]={text="Se acabou de entregar os relatórios dos Brado Guerreiro no lado norte, volte à Encruzilhada e voe para Orgrimmar. Nos demais casos, voe para Orgrimmar de onde estiver (Posto Machadada, Assentamento Zoram'gar ou Retiro Rocha do Sol)."}, [143]={npc="Sorek", tgt="Sorek", desc="Comece a sequência de Postura de Berserker antes de sair de Kalimdor para os Reinos do Leste. Qualquer instrutor de guerreiros de capital pode orientar você. Torm Totem da Fúria (57.24, 87.37) e Dalto Flores (47.40, 17.29) também oferecem a missão."}, [144]={text="Voe de Orgrimmar para Vila Catraca e siga pela costa para o sudeste até a Ilha da Peleja."}, [145]={hint="Fale com Klannoc Macleod.", desc="Inicie Postura de Berserker antes de cruzar para Reinos do Leste. Pergunte a um treinador Guerreiro da cidade."}, [146]={npc="Klannoc Macleod", tgt="Klannoc Macleod", desc="Inicie Postura de Berserker antes de cruzar para Reinos do Leste. Pergunte a um treinador Guerreiro da cidade."}, [147]={npc="Klannoc Macleod", tgt="Klannoc Macleod", desc="Reabasteça-se antes de pisar na grade. Ao concluir, você aprende a Postura de Berserker."}, [148]={hint="Mate o Grande Gui. Em seguida, fale com Klannoc Macleod na Ilha da Peleja.", desc="Reabasteça-se antes de pisar na grade. Ao concluir, você aprende a Postura de Berserker."}, [149]={npc="Klannoc Macleod", tgt="Klannoc Macleod", desc="Reabasteça-se antes de pisar na grade. Ao concluir, você aprende a Postura de Berserker."}, [150]={npc="Klannoc Macleod", tgt="Klannoc Macleod", tag="Opcional", desc="Inicie a cadeia de armas Redemoinho separadamente de Postura de Berserker."}, [151]={text="Voe de Vila Catraca para Orgrimmar e volte ao zepelim para as Clareiras de Tirisfal."}, [152]={npc="Gan'rul Olho de Sangue", tgt="Gan'rul Olho de Sangue", tag="Opcional", desc="Missão introdutória de Orgrimmar; você pode aceitar a missão direto em Vila Catraca."}, [153]={hint="Fale com Strahad Farsan na Vila Catraca.", tag="Opcional", desc="Missão introdutória de Orgrimmar; você pode aceitar a missão direto em Vila Catraca."}, [154]={npc="Strahad Farsan", tgt="Strahad Farsan", tag="Opcional", desc="Missão introdutória de Orgrimmar; você pode aceitar a missão direto em Vila Catraca."}, [155]={text="Voe de Orgrimmar para Vila Catraca."}, [156]={npc="Strahad Farsan", tgt="Strahad Farsan"}, [157]={text="Voe de Vila Catraca para Orgrimmar e volte ao zepelim para as Clareiras de Tirisfal."}, [158]={text="Embarque no zepelim das Clareiras de Tirisfal do lado de Frezza (50.82, 13.54), desça em Montalvo e siga para a Cidade Baixa. Só use direto a Pedra de Regresso que você manteve na Serraria Tarren se tiver certeza de que não precisa entrar na Cidade Baixa para entregar ou aceitar missões."}}},
    ["05-d8"] = {name="Profundezas Negras", entrance="Vale Gris 16.50, 11.00", pickup="Pegue Problemas nas Profundezas com Tsunomem no Retiro Rocha do Sol (Cordilheira das Torres de Pedra) e guarde-a para Je'neu Sancrea no Posto de Zoram'gar, no Vale Gris. Bruxos podem pegar O orbe de Soran'ruk em Vila Catraca e no Acampamento Taurajo, nos Sertões. Paladinos mortos-vivos devem manter Uma lâmina beijada pela lua no registro, pegando-a no Sepulcro, em Pinhaprata. Em Praia de Zoram, pegue primeiro A essência de Aku'mai e Nas ruínas. Se encontrar o bilhete na caverna externa, entregue-o no posto antes de entrar. Depois, paladinos mortos-vivos pegam Em busca da Gema Kor.", pickupS={{"Pegue Problemas nas Profundezas com Tsunomem no Retiro Rocha do Sol (Cordilheira das Torres de Pedra) e guarde-a para Je'neu Sancrea no Posto de Zoram'gar, no Vale Gris"}, {"Bruxos podem pegar O orbe de Soran'ruk em Vila Catraca e no Acampamento Taurajo, nos Sertões"}, {"Paladinos mortos-vivos devem manter Uma lâmina beijada pela lua no registro, pegando-a no Sepulcro, em Pinhaprata"}, {"Em Praia de Zoram, pegue primeiro A essência de Aku'mai e Nas ruínas"}, {"Se encontrar o bilhete na caverna externa, entregue-o no posto antes de entrar"}, {"Depois, paladinos mortos-vivos pegam Em busca da Gema Kor"}}, tips={{k="動線", text="Siga a caverna inundada até a piscina das tartarugas de Ghamoo-ra e encontre Thaelrid na caverna lateral subaquática → passe pelas cavernas de Lady Sarevess e Gelihast até Lorgus Jett no acampamento Crepúsculo. Colete os fragmentos no acampamento Crepúsculo pelo caminho (só bruxo). Clique na pedra debaixo da ponte das ruínas do Altar da Lua, mate Aquanis e pegue o globo → volte ao santuário e mate Kelris → com o grupo pronto, acenda os braseiros um a um e entre no covil de Aku'mai."}, {k="取捨", text="Faça A essência de Aku'mai e procure o bilhete na caverna externa na mesma viagem. O bilhete é só uma dica de drop; se não cair, faça as outras missões mesmo assim. Paladinos mortos-vivos com Em busca da Gema Kor aceita podem concluí-la na mesma viagem.", s={{"Faça A essência de Aku'mai e procure o bilhete na caverna externa na mesma viagem"}, {"O bilhete é só uma dica de drop; se não cair, faça as outras missões mesmo assim"}, {"Paladinos mortos-vivos com Em busca da Gema Kor aceita podem concluí-la na mesma viagem", {race={"Scourge"}, class={"PALADIN"}}}}}, {k="說明", text="Nade a partir das ruínas, no extremo noroeste de Praia de Zoram. Siga o canal pela caverna até o portal da masmorra, no fundo. Cada braseiro ao redor de Kelris desencadeia uma onda. Acenda um de cada vez.", s={{"Nade a partir das ruínas, no extremo noroeste de Praia de Zoram"}, {"Siga o canal pela caverna até o portal da masmorra, no fundo"}, {"Cada braseiro ao redor de Kelris desencadeia uma onda"}, {"Acenda um de cada vez"}}}}, steps={[1]={npc="Tsunomem", tgt="Tsunomem"}, [2]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea"}, [3]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea", desc="Retire primeiro em Assentamento Zoram'gar."}, [4]={hint="Entregue 20 Safiras de Aku'Mai a Je'neu Sancrea no Vale Gris.", desc="Retire primeiro em Assentamento Zoram'gar."}, [5]={npc="Bilhete Úmido", npcObj=true, tag="Opcional", desc="Pré-requisito: Problemas nas Profundezas. Mantenha A essência de Aku'mai aceita ao mesmo tempo. Se a nota não cair, o grupo não precisa esperar.", preText="Problemas nas Profundezas"}, [6]={hint="Leve o Bilhete Úmido para Je'neu Sancrea, no Vale Gris.", tag="Opcional", desc="Pré-requisito: Problemas nas Profundezas. Mantenha A essência de Aku'mai aceita ao mesmo tempo. Se a nota não cair, o grupo não precisa esperar."}, [7]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea", tag="Opcional", desc="Pré-requisito: Problemas nas Profundezas. Mantenha A essência de Aku'mai aceita ao mesmo tempo. Se a nota não cair, o grupo não precisa esperar."}, [8]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea", tag="Opcional", desc="Entregue Bilhete Úmido (Lealdade aos Deuses Antigos) e aceite do mesmo NPC.", preText="Lealdade aos Deuses Antigos"}, [9]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea"}, [10]={npc="Ulorico Glacivéu", tgt="Ulorico Glacivéu", tag="Opcional", desc="Aceite primeiro a missão Uma lâmina beijada pela lua e mantenha no registro. Só entregue depois de receber a gema de Kor purificada nesta missão."}, [11]={hint="Leve uma Gema Kor para Ulorico Glacivéu no Vale Gris.", tag="Opcional"}, [12]={npc="Ulorico Glacivéu", tgt="Ulorico Glacivéu", tag="Opcional"}, [13]={text="Entrada: Profundezas Negras"}, [14]={npc="Guarda Argênteo Thaelrid", tgt="Guarda Argênteo Thaelrid", desc="Encontre Thaelrid na passagem subaquática perto do lago das tartarugas e pegue a missão antes de ir ao altar do Crepúsculo."}, [15]={hint="Mate Lorgus Jett nas Profundezas Negras e depois fale novamente com Je'neu Sancrea no Vale Gris.", tag="Opcional", desc="Local: Passando pela caverna inundada de Gelihast, encontre Lorgus Jett no acampamento Crepúsculo.", spot="Passando pela caverna inundada de Gelihast, encontre Lorgus Jett no acampamento Crepúsculo."}, [16]={hint="Encontre 3 Fragmentos de Soran'ruk e 1 Fragmento Grande de Soran'ruk e entregue-os a Doan Karhan nos Sertões.", tag="Opcional", desc="Local: Mate acólitos do acampamento Crepúsculo até o santuário e saqueie três fragmentos.", spot="Mate acólitos do acampamento Crepúsculo até o santuário e saqueie três fragmentos."}, [17]={hint="Leve a cabeça do Senhor do Crepúsculo Kelris para Bashana Runa Totem, no Penhasco do Trovão.", desc="Local: Desembarque no Santuário da Lua e mate Kelris diante do altar do Crepúsculo. Ordem: Se fizer as etapas \"Nas ruínas\"-\"O Barão Aquanis\" na mesma volta, entre primeiro na água e depois no santuário.", spot="Desembarque no santuário da lua. Mate Kelris no altar Crepúsculo."}, [18]={hint="Leve o Núcleo das Profundezas para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris.", desc="Local: Mergulhe sob a ponte das ruínas do Altar da Lua e use a Pedra das Profundezas para pegar o núcleo. Ordem: Reúna primeiro o grupo e depois clique na pedra; ela invoca o Barão Aquanis da etapa \"O Barão Aquanis\".", spot="Mergulhe sob a ponte das ruínas do altar. Clique na Pedra das Profundezas para pegar o núcleo."}, [19]={npc="Globo d'Água Estranho", npcObj=true, desc="Mate Barão Aquanis, saqueie o globo e clique com o botão direito para iniciar a missão."}, [20]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea"}, [21]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea"}, [22]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea", tag="Opcional"}, [23]={npc="Je'neu Sancrea", tgt="Je'neu Sancrea"}, [24]={npc="Bashana Runa Totem", tgt="Bashana Runa Totem"}}},
    ["03-15"] = {name="Contraforte de Eira dos Montes", tips={{k="取捨", text="Abaixo do nível 31? Mate yetis na caverna das colinas para completar a EXP."}, {k="取捨", text="Patrulhas de Dalaran e Braçadeiras da vinculação só são liberadas ao entregar as missões da rodada anterior; faça tudo junto no lado oeste. Chave da cidade pode ser aceita de passagem, e a masmorra de Dalaran pode ser pulada."}, {k="取捨", text="Infiltração só é liberada depois de O resgate; deixe-a para Montanhas de Alterac. Se ainda não fez a primeira parte de O elixir da agonia, pule o ramo costeiro."}, {k="提醒", text="O túmulo de Helcolar fica perto da cidade aliada de Costa Sul; aproxime-se pelo lado de fora da cidade.", s={{"O túmulo de Helcolar fica perto da cidade aliada de Costa Sul; aproxime-se pelo lado de fora da cidade"}}}, {k="提醒", text="A etapa dos níveis 30-32 pode ser combinada com Ruína do Martelo, no Planalto Arathi. Precisa de EXP? Mate yetis comuns no sopé oeste de Eira dos Montes (cerca de 45, 29) ou complete em Ruína do Martelo.", s={{"A etapa dos níveis 30-32 pode ser combinada com Ruína do Martelo, no Planalto Arathi"}, {"Precisa de EXP?"}, {"Mate yetis comuns no sopé oeste de Eira dos Montes (cerca de 45, 29) ou complete em Ruína do Martelo"}}}}, danger={[1]="Guardas da Aliança de nível 55 patrulham Costa Sul. Para Uma vingança para Helcolar, vá ao túmulo por fora da cidade e não atravesse a cidade.", [2]="Os inimigos reaparecem em grande número na entrada da caverna dos yetis. Ao procurar a Varinha de Helcolar, limpe primeiro o lado de fora e deixe uma rota de fuga antes de entrar."}, grind={[1]={mob="Yeti das Cavernas", note="Densos mobs normais na encosta fora da caverna do Yeti Ocidental. Puxe um inimigo de cada vez para longe da entrada. Comece no nível 30."}, [2]={mob="Yeti Feroz", note="Mobs normais densos perto da entrada da caverna dos yetis, misturados com yetis da caverna. Limpe primeiro a borda externa e depois ganhe EXP nos níveis 31-32."}}, supply={[1]={npc="Clarissa"}, [2]={npc="Estalajadeiro Chê"}, [3]={npc="Estalajadeiro Chê"}, [4]={npc="Keila Fuligissacra"}, [5]={npc="Antônio Nunes"}, [6]={npc="Thomas Mordan"}, [7]={npc="Ezequiel Potio"}}, steps={[1]={text="Se voltou direto para a Serraria Tarren com a Pedra de Regresso e não tem missões para entregar ou aceitar na Cidade Baixa, desbloqueie logo o ponto de voo na Serraria Tarren. Se pegou o zepelim depois da parada do Posto Machadada, no Vale Gris, entre na Cidade Baixa pela torre ao sul de Montalvo; só voe para Orgrimmar e então pegue o zepelim se estiver entrando na rota no meio do caminho, vindo de Kalimdor. Se ainda não tiver o ponto de voo da Cidade Baixa, procure Miguel Garreta (63.25, 48.56)."}, [2]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", tag="Com pré-requisito nas Cidade Baixa, Opcional", desc="Poção Forte de Sangue de Troll ×1: dá para comprar na casa de leilões."}, [3]={npc="Jonas Anísio", tgt="Jonas Anísio"}, [4]={npc="Jonas Anísio", tgt="Jonas Anísio", desc="Pegue o livro na costa sudoeste de Eira dos Montes e o manuscrito na caverna dos centauros ao sul de Mil Agulhas."}, [6]={text="Voe da Cidade Baixa para a Serraria Tarren. Se o ponto de voo da Serraria Tarren não estiver desbloqueado, voe para o Sepulcro, siga para o sul pela estrada da Floresta de Pinhaprata até o Contraforte de Eira dos Montes e depois a leste até a Serraria Tarren."}, [7]={nodeA="{a:272}", node="Tarren Mill", desc="Obtenha o ponto de voo de Clarissa."}, [8]={text="Vincule sua Pedra de Regresso com Estalajadeiro Chê na estalagem de Serraria Tarren (62.78, 19.03).", bindA="{a:272}"}, [9]={npc="Noviço Trevando", tgt="Noviço Trevando", tag="Opcional"}, [10]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio"}, [11]={npc="Guardião Bel'varão", tgt="Guardião Bel'varão"}, [12]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio"}, [13]={npc="Sebo", tgt="Sebo"}, [14]={text="Cavernas do sopé → acampamento Dalaran"}, [15]={hint="Recupere o Bastão de Helcolar do Yeti e leve-o de volta para o Noviço Trevando, em Serraria Tarren.", tag="Opcional", desc="Encontre a lápide fora de Costa Sul. Evite os guardas da Aliança."}, [16]={npc="Noviço Trevando", tgt="Noviço Trevando", tag="Opcional"}, [17]={npc="Noviço Trevando", tgt="Noviço Trevando", tag="Opcional"}, [18]={hint="Encontre os traidores e recupere os artefatos, depois volte a falar comigo."}, [19]={hint="Leve 10 Fichas de Pedra Gasta para o Guardião Bel'varão, na Serraria Tarren."}, [20]={hint="Consiga a Chave do Esgoto de Dalaran para Magus Ordínio Olharvazio na Serraria Tarren."}, [21]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio"}, [22]={npc="Guardião Bel'varão", tgt="Guardião Bel'varão"}, [23]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio"}, [24]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio"}, [25]={npc="Guardião Bel'varão", tgt="Guardião Bel'varão"}, [26]={hint="Mate 6 Evocadores de Dalaran e 8 Escravos Elementais, depois fale novamente com o Magus Olharvazio na Serraria Tarren."}, [27]={hint="Leve 4 Braçadeiras do Vínculo à Terra para o Guardião Bel'varão, na Serraria Tarren.", desc="Mate Elementais Escravizados perto de Dalaran para obter as braçadeiras."}, [28]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio"}, [29]={npc="Guardião Bel'varão", tgt="Guardião Bel'varão"}, [30]={text="Mina Veioazul e a costa perto de Costa Sul"}, [31]={hint="Leve a Mistura Fuçalama, um Elixir Forte de Sangue de Troll, 5 Escamas de Espinhadaga e 5 Olhos de Rancapina para o Boticário Lindolfo, na Serraria Tarren.", tag="Opcional"}, [32]={text="Vá à costa sudoeste de Eira dos Montes e pegue o Tomo Mofado (27.78, 72.79)."}, [33]={hint="Carregue o Bastão de Helcolar com os poderes da Chama de Azel, da Chama de Veraz e da Chama de Uzel.", tag="Opcional"}, [34]={npc="Tumba de Helcolar", npcObj=true, tag="Opcional"}, [35]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo", tag="Opcional"}, [36]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo", tag="Opcional"}, [37]={hint="Leve o Barril de Stout do Festeiro para o Boticário Lindolfo na Serraria Tarren.", tag="Opcional"}, [38]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo", tag="Opcional"}, [39]={npc="Boticário Lindolfo", tgt="Boticário Lindolfo", tag="Opcional"}, [40]={hint="Coloque o Barril Estragado no tapete para os fazendeiros capturados.", tag="Opcional"}, [41]={npc="Tapete Empoeirado", npcObj=true, tag="Opcional"}, [42]={hint="Fale com Bath'rah, o Vigia dos Ventos.", tag="Opcional", desc="Inicie a cadeia de armas Redemoinho separadamente de Postura de Berserker."}, [43]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Inicie a cadeia de armas Redemoinho separadamente de Postura de Berserker."}, [44]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Colete as Presas de Bloodscalp na Selva do Espinhaço, em Grom'gol e Angra do Butim, e os amuletos elementais no Planalto Arathi, em Ruína do Martelo. Com tudo em mãos, volte a Bath'rah."}, [45]={hint="Derrote a Manifestação da Água Corrompida e deposite as Braçadeiras da Manifestação Corrompida junto com as Gotas Restantes da Mais Pura Água no Braseiro da Fonteterna, que fica na Floresta de Pinhaprata.", desc="Antes, conclua a entrega de água dos Sertões em Posto Machadada, no Vale Gris. Se o seu pacto espiritual expirar, procure Tiev Borduno para se reabastecer."}, [46]={npc="Braseiro da Fonteterna", npcObj=true, desc="Antes, conclua a entrega de água dos Sertões em Posto Machadada, no Vale Gris. Se o seu pacto espiritual expirar, procure Tiev Borduno para se reabastecer."}, [47]={npc="Braseiro da Fonteterna", npcObj=true}, [48]={hint="Fale com a Manifestação Menor da Água na Floresta de Pinhaprata."}, [49]={npc="Manifestação Menor da Água", tgt="Manifestação Menor da Água"}, [50]={npc="Manifestação Menor da Água", tgt="Manifestação Menor da Água", desc="Entregue em Chapada Cintilante, em Mil Agulhas, quando voltar a Kalimdor."}, [51]={text="Siga a leste da Serraria Tarren, passe pela Muralha de Thoradin e entre no Planalto Arathi."}}},
    ["05-d10"] = {name="Dalaran", entrance="Montanhas de Alterac 8.46, 59.21", pickup="Em Serraria Tarren, pegue O Cavaleiro da Sepultura com Melissara; ao passar por Cidade Baixa, pegue Fonte de poder com o Doutor Martinho Nunes. Em Serraria Tarren, no nível 30, pegue Invasão da prisão e Chave da cidade com Wordeen. Vá para sudeste ao longo de Espelho de Lordaeron até o campo de internamento e pegue na mesma viagem a pedra de sangue e a chave suja. Volte a Serraria Tarren para entregar, pegue Patrulhas de Dalaran e, ao concluir, Blood in the Streets. Siga a margem do lago até a imagem de Modera, pegue Heart of Disruption e mantenha a chave do esgoto com você.", pickupS={{"Em Serraria Tarren, pegue O Cavaleiro da Sepultura com Melissara; ao passar por Cidade Baixa, pegue Fonte de poder com o Doutor Martinho Nunes"}, {"Em Serraria Tarren, no nível 30, pegue Invasão da prisão e Chave da cidade com Wordeen"}, {"Vá para sudeste ao longo de Espelho de Lordaeron até o campo de internamento e pegue na mesma viagem a pedra de sangue e a chave suja"}, {"Volte a Serraria Tarren para entregar, pegue Patrulhas de Dalaran e, ao concluir, Blood in the Streets"}, {"Siga a margem do lago até a imagem de Modera, pegue Heart of Disruption e mantenha a chave do esgoto com você"}}, tips={{k="動線", text="Aceite as missões dos goblins na entrada dos esgotos → derrote Atrexis e, se quiser matar Lyn, entre na Câmara de Runas → suba à rua pela direita, recolha núcleos de construto e procure o livro na estante do andar de cima, à esquerda da cidadela → abra o portal na sala de recepção da Cidadela Violeta e derrote a Sombra do Arquimago. Antes de sair, entregue o livro a Rexxie na entrada dos esgotos."}, {k="取捨", text="Os pré-requisitos da Horda começam no nível 30. Faça primeiro as missões de abertura da porta e só depois recrute o grupo. Se o grupo tiver a chave, confirme quem consegue abrir a porta; ter a própria chave facilita voltar. Para o chefe oculto Lyn the Ignored, traga o Tomo de Dalaran feito a partir da Bastilha da Presa Negra."}, {k="說明", text="A imagem de Modera e o portal da masmorra ficam em pontos diferentes. Vá pelo lado do esgoto do Espelho de Lordaeron. As restrições de facção valem para os portões externos de Dalaran e para falar com os NPCs da cidade.", s={{"A imagem de Modera e o portal da masmorra ficam em pontos diferentes"}, {"Vá pelo lado do esgoto do Espelho de Lordaeron"}, {"As restrições de facção valem para os portões externos de Dalaran e para falar com os NPCs da cidade"}}}}, steps={[1]={npc="Doutor Martinho Nunes", tgt="Doutor Martinho Nunes"}, [2]={npc="Melissara", tgt="Melissara"}, [3]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio"}, [4]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio"}, [5]={hint="Encontre os traidores e recupere os artefatos, depois volte a falar comigo."}, [6]={hint="Consiga a Chave do Esgoto de Dalaran para Magus Ordínio Olharvazio na Serraria Tarren."}, [7]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio"}, [8]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio"}, [9]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio", preText="Invasão da prisão, Chave da cidade"}, [10]={hint="Mate 6 Evocadores de Dalaran e 8 Escravos Elementais, depois fale novamente com o Magus Olharvazio na Serraria Tarren."}, [11]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio"}, [12]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio", preText="Patrulhas de Dalaran, Chave da cidade"}, [13]={hint="Find a way into Dalaran along the Lordamere Lake."}, [14]={npc="Imagem da Arquimaga Modera", tgt="Imagem da Arquimaga Modera"}, [15]={npc="Imagem da Arquimaga Modera", tgt="Imagem da Arquimaga Modera", desc="Ao aceitar a missão, você recebe a Chave do Esgoto de Dalaran. A Chave Imunda é só um pré-requisito.", preText="Blood in the Streets"}, [16]={text="Entrada: Dalaran"}, [17]={npc="Rexxie Copperclutch", desc="Procure o goblin atrás da grade do lado direito do esgoto."}, [18]={hint="Derrote Atrexis, o Cavaleiro da Sepultura, em Dalaran para Melissara na Serraria Tarren.", desc="Local: Siga o túnel de esgoto principal até a área aberta e mate Atrexis.", spot="Siga o túnel de esgoto principal até a área aberta e mate Atrexis."}, [19]={hint="Colete 6 Núcleos de Sentinela Rachados em Dalaran para o Doutor Martinho Nunes, na Cidade Baixa.", desc="Local: Depois do Cavaleiro da Sepultura, suba a rua pela direita. Mate as Sentinelas Despedaçadas ao longo da rua.", spot="Depois do Cavaleiro da Sepultura, suba a rua pela direita. Mate as Sentinelas Despedaçadas ao longo da rua."}, [20]={hint="Collect the Founding of Dalaran from the City of Dalaran for Rexxie Copperclutch near the sewer entrance.", desc="Local: Suba no prédio à esquerda da escada do castelo e procure a estante atrás da estátua.", spot="Suba no prédio à esquerda da escada do castelo e procure a estante atrás da estátua."}, [21]={npc="Rexxie Copperclutch"}, [22]={hint="Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill.", desc="Local: Entre na Cidadela Violeta e abra o portal. Mate a Sombra do Arquimago na sala de recepção.", spot="Entre na Cidadela Violeta e abra o portal. Mate a Sombra do Arquimago na sala de recepção."}, [23]={npc="Melissara", tgt="Melissara"}, [24]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio"}, [25]={npc="Doutor Martinho Nunes", tgt="Doutor Martinho Nunes"}, [26]={npc="Magus Ordínio Olharvazio", tgt="Magus Ordínio Olharvazio", desc="Horda: vire para a imagem à beira do lago lá fora. Siga seu marcador de missão.", preText="Heart of Disruption"}, [27]={hint="Fale com a Imagem da Arquimaga Modera nos arredores de Dalaran.", desc="Horda: vire para a imagem à beira do lago lá fora. Siga seu marcador de missão."}, [28]={npc="Imagem da Arquimaga Modera", tgt="Imagem da Arquimaga Modera", desc="Horda: vire para a imagem à beira do lago lá fora. Siga seu marcador de missão."}}},
    ["05-d9"] = {name="Monastério Escarlate: Cemitério", entrance="Clareiras de Tirisfal 85.20, 32.10", pickup="Ao passar pela Serraria Tarren, em Eira dos Montes, desbloqueie antes o ponto de voo. Da Cidade Baixa, siga pela estrada norte de Clareiras de Tirisfal até o Monastério. Primeiro conclua Matéria orguânica, em Urzal dos Tuscos, e depois vá ao distrito de alquimia da Cidade Baixa falar com Faranell. Se for primeiro a Mil Agulhas, deixe Corações do fanatismo para aceitar quando for às Montanhas de Alterac. Pode fazer antes Vorrel, no Cemitério. Depois de sair do Cemitério, vá à margem do Lago Alterac e à Serraria Tarren.", pickupS={{"Ao passar pela Serraria Tarren, em Eira dos Montes, desbloqueie antes o ponto de voo"}, {"Da Cidade Baixa, siga pela estrada norte de Clareiras de Tirisfal até o Monastério"}, {"Primeiro conclua Matéria orguânica, em Urzal dos Tuscos, e depois vá ao distrito de alquimia da Cidade Baixa falar com Faranell"}, {"Se for primeiro a Mil Agulhas, deixe Corações do fanatismo para aceitar quando for às Montanhas de Alterac"}, {"Pode fazer antes Vorrel, no Cemitério"}, {"Depois de sair do Cemitério, vá à margem do Lago Alterac e à Serraria Tarren"}}, tips={{k="動線", text="Corredor de entrada: limpe os Cruzados e pegue os corações → sala de interrogatório: mate Vishas e encontre Vorrel no cavalete de tortura → atravesse o cemitério a céu aberto e desça a escada das catacumbas até o Mago Sangrento Thalnos."}, {k="取捨", text="O Cemitério é fácil de agrupar desde o início. Faça Vorrel mesmo que você não tenha terminado Matéria orguânica."}, {k="說明", text="Pegue a entrada mais à esquerda. O Cemitério não requer a Chave Escarlate.", s={{"Pegue a entrada mais à esquerda"}, {"O Cemitério não requer a Chave Escarlate"}}}}, steps={[1]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", tag="Opcional", desc="Pegue só se for fazer Urzal dos Tuscos primeiro. Dá para fazer em Chapada Cintilante, em Mil Agulhas."}, [2]={hint="Leve 1 porção de Guano de Morcego para o Mestre-boticário Faranello na Cidade Baixa.", tag="Opcional", desc="Esta etapa está em Urzal dos Tuscos."}, [3]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", tag="Opcional"}, [4]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", tag="Opcional", desc="Veja Urzal dos Tuscos para a rota completa do pré-requisito Matéria orguânica. Os drops acumulam nas quatro alas, então deixe para pegar quando fizer as quatro alas na mesma corrida.", preText="Matéria orguânica"}, [5]={text="Entrada: Monastério Escarlate: Cemitério"}, [6]={npc="Vorrel Sentripaz", tgt="Vorrel Sentripaz", desc="Encontre Vorrel na prateleira da primeira sala de interrogatório."}, [7]={hint="O Mestre-boticário Faranello, da Cidade Baixa, quer 20 Corações do Fanatismo.", tag="Opcional", desc="Local: Limpe primeiro os Cruzados Escarlates vivos, do corredor de entrada até a sala de interrogatório.", spot="Limpe primeiro os Cruzados Escarlates vivos, do corredor de entrada até a sala de interrogatório."}, [8]={hint="Leve a aliança de Vorrel Sentripaz para Mônica Sentripaz na Serraria Tarren.", desc="Outra elite pode estar na sala. Espere ela patrulhar até o cais."}, [9]={npc="Mônica Sentripaz", tgt="Mônica Sentripaz"}, [10]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", tag="Opcional", desc="Colete todos os 20 antes de entregar em Cidade Baixa."}}},
    ["03-16"] = {name="Planalto Arathi", nameA="Planalto Arathi: {a:321}", tips={{k="取捨", text="Elimine os raptores e os membros da Camarilha perto de Ruína do Martelo e os Cascasseca ao sudeste. Se já está no nível 32, deixe as continuações Chamado às armas e A astúcia dos raptores para a visita de retorno a Ruína do Martelo, no Planalto Arathi."}, {k="取捨", text="Reabastecimento da enfermaria e Suturas de seda são conteúdo novo da versão Forever. Entregue para liberar. Se já estiver no nível 32, deixe para a segunda visita."}, {k="提醒", text="Abaixo do nível 32 antes de ir a Mil Agulhas? Saindo de Ruína do Martelo, mate trolls Cascasseca comuns fora da aldeia (cerca de 68, 69) e evite entrar no acampamento lotado.", s={{"Abaixo do nível 32 antes de ir a Mil Agulhas?"}, {"Saindo de Ruína do Martelo, mate trolls Cascasseca comuns fora da aldeia (cerca de 68, 69) e evite entrar no acampamento lotado"}}}}, danger={[1]="Os curandeiros Cascasseca dentro das cabanas se curam, e na frente delas ficam caça-cabeças de nível mais alto. Limpe pela borda dos campos e guarde uma interrupção."}, grind={[1]={mob="Arremessador Cascasseca", note="Mobs normais de longo alcance, densos, nos arredores da Aldeia Cascasseca. Puxe um de cada vez pela encosta, perto da área da missão. Bom para chegar ao nível 32."}, [2]={mob="Mandingueiro Cascasseca", note="Mobs normais conjuradores, densos, a leste da Aldeia Cascasseca. Interrompa as curas e limpe ao redor das casas; cuidado com os Caça-cabeças Cascasseca, de nível mais alto, por perto."}}, supply={[1]={npc="Urda"}, [2]={npc="Estalajadeiro Adegra"}, [3]={npc="Mu'uta"}, [4]={npc="Estalajadeiro Adegra"}, [5]={npc="Graud"}}, steps={[1]={hint="Mate 8 Ogros Punho de Pedra e 10 Impositores Punho de Pedra. Depois apresente-se a Drum Fel no posto avançado Ruína do Martelo, no Planalto Arathi."}, [2]={nodeA="{a:321}", node="Hammerfall", desc="Desbloqueie o ponto de voo com Urda."}, [3]={npc="Drum Fel", tgt="Drum Fel"}, [4]={npc="Gor'mul", tgt="Gor'mul"}, [5]={npc="Tor'gan", tgt="Tor'gan"}, [6]={npc="Tor'gan", tgt="Tor'gan"}, [7]={npc="Tor'gan", tgt="Tor'gan"}, [8]={npc="Drum Fel", tgt="Drum Fel"}, [9]={npc="Doutor Victor Zerbini", tgt="Doutor Victor Zerbini"}, [10]={hint="Consiga 10 Olhos de Raptores do Planalto matando os Andarilhos do Planalto ou os Espancadores do Planalto e entregue a Tor'gan em Ruína do Martelo."}, [11]={hint="Obtenha 10 Amuletos de Pedra-sangrenta e entregue-os a Tor'gan em Ruína do Martelo."}, [12]={npc="Tor'gan", tgt="Tor'gan"}, [13]={npc="Tor'gan", tgt="Tor'gan"}, [14]={npc="Tor'gan", tgt="Tor'gan"}, [15]={npc="Gor'mul", tgt="Gor'mul"}, [16]={npc="Gor'mul", tgt="Gor'mul"}, [17]={npc="Tor'gan", tgt="Tor'gan"}, [18]={hint="Mate 10 Arremessadores Cascasseca, 10 Caçadores de Cabeças Cascasseca e 8 Mandingueiros Cascasseca. Depois, fale novamente com Drum Fel no posto avançado Ruína do Martelo."}, [19]={hint="Devolva 12 Sedaracnas Cirúrgicas ao Doutor Victor Zerbini na Ruína do Martelo, no Planalto Arathi."}, [20]={npc="Drum Fel", tgt="Drum Fel"}, [21]={npc="Doutor Victor Zerbini", tgt="Doutor Victor Zerbini"}, [22]={npc="Doutor Victor Zerbini", tgt="Doutor Victor Zerbini", desc="Entregue Suturas de seda ao mesmo médico para desbloquear a missão de suprimentos."}, [23]={hint="Pegue uma bolsa de Tônicos Embalados no laboratório de Jorel, na Fazenda Go'Shek, e fale novamente com o Doutor Victor Zerbini na Ruína do Martelo."}, [24]={npc="Doutor Victor Zerbini", tgt="Doutor Victor Zerbini"}, [25]={text="Voe para a Cidade Baixa para organizar as bolsas e saia da cidade rumo à torre de zepelins ao sul de Montalvo."}}},
    ["05-d13"] = {name="Monastério Escarlate: Catedral", entrance="Clareiras de Tirisfal 85.20, 32.10", pickup="Voe de Ruína do Martelo para Cidade Baixa; com nível 35, dá para fazer a Catedral na mesma viagem da Biblioteca e do Arsenal. No caminho para Eira dos Montes, ao passar por Cidade Baixa, veja Varimatras no Distrito Real; Adentrando o Monastério Escarlate só é aceita no nível 33. Se ainda não tiver nível 35, faça na volta aos Reinos do Leste, a caminho das Montanhas de Alterac. Leve a Chave Escarlate e o progresso de mortes da Biblioteca e do Arsenal.", pickupS={{"Voe de Ruína do Martelo para Cidade Baixa; com nível 35, dá para fazer a Catedral na mesma viagem da Biblioteca e do Arsenal"}, {"No caminho para Eira dos Montes, ao passar por Cidade Baixa, veja Varimatras no Distrito Real"}, {"Adentrando o Monastério Escarlate só é aceita no nível 33"}, {"Se ainda não tiver nível 35, faça na volta aos Reinos do Leste, a caminho das Montanhas de Alterac"}, {"Leve a Chave Escarlate e o progresso de mortes da Biblioteca e do Arsenal"}}, tips={{k="動線", text="Atravesse o pátio da fonte e suba as escadas → mate Mograine na Catedral → espere que Juba Branca o ressuscite → mate os dois."}, {k="取捨", text="Ainda falta Loksey ou Herod? Volte primeiro à ala correspondente e só depois retorne à cidade."}, {k="說明", text="Traga a Chave Escarlate ou peça a um ladino do grupo com Ora (direis) ouvir estrelas! de Arrombamento para abrir a porta.", s={{"Traga a Chave Escarlate ou peça a um ladino do grupo com Ora (direis) ouvir estrelas! de Arrombamento para abrir a porta"}}}}, steps={[1]={text="Pré-requisito: Adentrando o Monastério Escarlate"}, [2]={text="Entrada: Monastério Escarlate: Catedral"}, [3]={hint="Mate a Alta-inquisidora Cristalba, o Comandante Escarlate Mograine, Herodes, o Campeão Escarlate e o Mestre de Matilha Lobato, depois volte a falar com Varimatras na Cidade Baixa.", desc="Limpe primeiro os arredores da sala na Catedral. Cristalba vai ressuscitar Mograine. Local: Atravesse o pátio da fonte, suba as escadas e enfrente os dois chefes no salão principal. Ordem: Mograine → Cristalba o ressuscita → os dois chefes.", spot="Atravesse o pátio da fonte e suba as escadas. Mate os dois chefes da Catedral."}, [4]={npc="Varimatras", tgt="Varimatras", desc="Entregue no Distrito Real de Cidade Baixa depois que todos os quatro chefes contarem."}}},
    ["05-d12"] = {name="Monastério Escarlate: Arsenal", entrance="Clareiras de Tirisfal 85.20, 32.10", pickup="Voe de Ruína do Martelo, em Arathi, para Cidade Baixa; dá para fazer na mesma viagem da Biblioteca. Pegue Adentrando o Monastério Escarlate com Varimatras no Distrito Real de Cidade Baixa; exige nível 33. Se já a pegou na Biblioteca, mantenha a missão e leve a Chave Escarlate. De Cidade Baixa, siga pela estrada norte de Tirisfal até o monastério.", pickupS={{"Voe de Ruína do Martelo, em Arathi, para Cidade Baixa; dá para fazer na mesma viagem da Biblioteca"}, {"Pegue Adentrando o Monastério Escarlate com Varimatras no Distrito Real de Cidade Baixa; exige nível 33"}, {"Se já a pegou na Biblioteca, mantenha a missão e leve a Chave Escarlate"}, {"De Cidade Baixa, siga pela estrada norte de Tirisfal até o monastério"}}, tips={{k="動線", text="Abra a porta do Arsenal → atravesse o quartel e o corredor até o fim → mate Herod no salão → elimine os recrutas Escarlates que entrarem depois."}, {k="取捨", text="Se alguém tiver a Chave Escarlate, vá direto para o Arsenal."}, {k="說明", text="Traga a Chave Escarlate ou peça a um ladino do grupo com Ora (direis) ouvir estrelas! de Arrombamento para abrir a porta.", s={{"Traga a Chave Escarlate ou peça a um ladino do grupo com Ora (direis) ouvir estrelas! de Arrombamento para abrir a porta"}}}}, steps={[1]={text="Pré-requisito: Adentrando o Monastério Escarlate"}, [2]={text="Entrada: Monastério Escarlate: Arsenal"}, [3]={text="Mate o Campeão Herod para registrar em Adentrando o Monastério Escarlate. Corpo a corpo: afastem-se durante o Redemoinho."}, [4]={text="Deixe Adentrando o Monastério Escarlate no registro e vá em seguida à Catedral. Só entregue em Cidade Baixa depois de concluir os quatro chefes.", desc="Continue a missão depois do Arsenal e continue até a Catedral."}}},
    ["05-d11"] = {name="Monastério Escarlate: Biblioteca", entrance="Clareiras de Tirisfal 85.20, 32.10", pickup="Voe de Ruína do Martelo, em Arathi, para Cidade Baixa e vá à Biblioteca. Em Mil Agulhas, faça primeiro a cadeia Teste da Fé → Teste de resistência → Teste de força com Dorn em Aldeia Vento Livre. Se você já passou pelo Retiro Rocha do Sol, pegue o túnel pelo sul do Vale Gris até Braug e depois procure Parqual em Cidade Baixa. Ao passar por Penhasco do Trovão, pegue O Compêndio dos Caídos de passagem (só orcs, taurens e trolls). Em Chapada Cintilante e Aldeia Muralha Verde, faça os pré-requisitos de Tabetha e Tirth; o livro pode ser pego depois, ao voltar aos Reinos do Leste (só magos).", pickupS={{"Voe de Ruína do Martelo, em Arathi, para Cidade Baixa e vá à Biblioteca"}, {"Em Mil Agulhas, faça primeiro a cadeia Teste da Fé → Teste de resistência → Teste de força com Dorn em Aldeia Vento Livre"}, {"Se você já passou pelo Retiro Rocha do Sol, pegue o túnel pelo sul do Vale Gris até Braug e depois procure Parqual em Cidade Baixa"}, {"Ao passar por Penhasco do Trovão, pegue O Compêndio dos Caídos de passagem (só orcs, taurens e trolls)", {race={"Orc", "Tauren", "Troll"}}}, {"Em Chapada Cintilante e Aldeia Muralha Verde, faça os pré-requisitos de Tabetha e Tirth; o livro pode ser pego depois, ao voltar aos Reinos do Leste (só magos)", {class={"MAGE"}}}}, tips={{k="動線", text="Pegue o livro da pequena sala à esquerda depois da galeria → mate o Mestre de Matilha Loksey no pátio → pegue os livros no fim do corredor longo e na estante antes de Doan → mate o Arcanista Doan e saqueie a Chave Escarlate do cofre atrás dele."}, {k="取捨", text="Pegue primeiro a Chave Escarlate; com ela dá para abrir o Arsenal e a Catedral em seguida. As missões de livros podem ser feitas na mesma corrida."}, {k="說明", text="A missão Adentrando o Monastério Escarlate abrange três alas; o roteiro completo para fazer e entregar está na Catedral.", s={{"A missão Adentrando o Monastério Escarlate abrange três alas; o roteiro completo para fazer e entregar está na Catedral"}}}}, steps={[1]={npc="Dorn Espreitaprados", tgt="Dorn Espreitaprados", tag="Opcional", desc="Pule se você fez isso em Aldeia Vento Livre."}, [2]={hint="Se tiver fé, pule lá de cima das tábuas, no topo de Mil Agulhas.", tag="Opcional", desc="Pule se você fez isso em Aldeia Vento Livre."}, [3]={npc="Dorn Espreitaprados", tgt="Dorn Espreitaprados", tag="Opcional", desc="Pule se você fez isso em Aldeia Vento Livre."}, [4]={npc="Dorn Espreitaprados", tgt="Dorn Espreitaprados", tag="Opcional", preText="Teste da Fé"}, [5]={hint="Leve a Garra da Grenka para Dorn Espreitaprados em Mil Agulhas.", tag="Opcional"}, [6]={npc="Dorn Espreitaprados", tgt="Dorn Espreitaprados", tag="Opcional"}, [7]={npc="Dorn Espreitaprados", tgt="Dorn Espreitaprados", tag="Opcional", preText="Teste de resistência"}, [8]={hint="Leve os Fragmentos de Rok'Alim para Dorn Espreitaprados em Mil Agulhas.", tag="Opcional"}, [9]={npc="Dorn Espreitaprados", tgt="Dorn Espreitaprados", tag="Opcional"}, [10]={npc="Dorn Espreitaprados", tgt="Dorn Espreitaprados", tag="Opcional", preText="Teste de força"}, [11]={hint="Encontre Braug Espírito Turvo perto da entrada do Túnel Garracava, na Cordilheira das Torres de Pedra.", tag="Opcional"}, [12]={npc="Braug Espírito Turvo", tgt="Braug Espírito Turvo", tag="Opcional"}, [13]={npc="Braug Espírito Turvo", tgt="Braug Espírito Turvo", tag="Opcional", desc="Encontre o livro na caverna e volte para Braug.", preText="Teste de saber"}, [14]={hint="Encontre o Legado dos Aspectos e leve-o para Braug Espírito Turvo perto da entrada do Túnel Garracava, na Cordilheira das Torres de Pedra.", tag="Opcional", desc="Encontre o livro na caverna e volte para Braug."}, [15]={npc="Braug Espírito Turvo", tgt="Braug Espírito Turvo", tag="Opcional", desc="Encontre o livro na caverna e volte para Braug."}, [16]={npc="Braug Espírito Turvo", tgt="Braug Espírito Turvo", tag="Opcional", preText="Teste de saber"}, [17]={hint="Responda à pergunta de Braug Espírito Turvo corretamente, depois fale com ele novamente. Quando você estiver pronto, ele estará na Cordilheira das Torres de Pedra.", tag="Opcional"}, [18]={npc="Braug Espírito Turvo", tgt="Braug Espírito Turvo", tag="Opcional"}, [19]={npc="Braug Espírito Turvo", tgt="Braug Espírito Turvo", tag="Opcional", preText="Teste de saber"}, [20]={hint="Encontre Pasqual Fintallas na Cidade Baixa.", tag="Opcional"}, [21]={npc="Pasqual Fintallas", tgt="Pasqual Fintallas", tag="Opcional"}, [22]={npc="Pasqual Fintallas", tgt="Pasqual Fintallas", tag="Opcional", preText="Teste de saber"}, [23]={npc="Sábio Devoto da Verdade", tgt="Sábio Devoto da Verdade"}, [24]={npc="Auld Agulha de Pedra", tgt="Auld Agulha de Pedra"}, [25]={npc="Varimatras", tgt="Varimatras", desc="Nível 33 ou superior. Se não atingir o nível desta vez, pegue-a depois e volte para matar Loksey."}, [26]={npc="Denya", tgt="Denya", tag="Opcional", desc="A mesma missão também pode ser pega com Ursyn Karnissa (25.70, 14.19) ou com Anastácia Cordato (85.14, 10.03)."}, [27]={npc="Tabetha", tgt="Tabetha", tag="Opcional"}, [28]={npc="Tabetha", tgt="Tabetha", tag="Opcional", preText="Jornada ao pântano"}, [29]={hint="Fale com Tirth, o Mago, no Salar Cintilante.", tag="Opcional"}, [30]={npc="Tirth, o Mago", tgt="Tirth, o Mago", tag="Opcional"}, [31]={npc="Tirth, o Mago", tgt="Tirth, o Mago", tag="Opcional", preText="Segredos ocultos"}, [32]={hint="Encontre a frase que abre o cofre de Tirth e fale novamente com ele.", tag="Opcional"}, [33]={npc="Tirth, o Mago", tgt="Tirth, o Mago", tag="Opcional"}, [34]={npc="Tirth, o Mago", tgt="Tirth, o Mago", tag="Opcional", preText="Tente a sorte"}, [35]={text="Entrada: Monastério Escarlate: Biblioteca"}, [36]={hint="Encontre o Início da Ameaça dos Mortos-vivos e leve para Pasqual Fintallas na Cidade Baixa.", tag="Opcional", desc="Local: Pegue o livro na mesa da pequena sala à esquerda, perto do início da galeria de entrada.", spot="Pegue o livro na mesa da pequena sala à esquerda, perto do início da galeria de entrada."}, [37]={hint="Recupere o Compêndio dos Caídos no Monastério nas Clareiras de Tirisfal e volte a falar com o Sábio Devoto da Verdade no Penhasco do Trovão.", desc="Local: Passe por Loksey até a última curva e procure a estante no início do corredor de Doan.", spot="Passe por Loksey até a última curva e procure a estante no início do corredor de Doan."}, [38]={hint="Leve o livro Rituais do Poder para Tabetha no Pântano Vadeoso.", tag="Opcional", desc="Local: Verifique o livro saindo da prateleira esquerda no início do corredor final.", spot="Verifique o livro saindo da prateleira esquerda no início do corredor final."}, [39]={text="Mate o Mestre de Matilha Loksey para registrar em Adentrando o Monastério Escarlate."}, [40]={text="Mate o Arcanista Doan, abra o cofre atrás dele e pegue a Chave Escarlate."}, [41]={npc="Pasqual Fintallas", tgt="Pasqual Fintallas", tag="Opcional"}, [42]={npc="Sábio Devoto da Verdade", tgt="Sábio Devoto da Verdade"}, [43]={npc="Tabetha", tgt="Tabetha", tag="Opcional"}}},
    ["03-17"] = {name="Mil Agulhas", nameA="Mil Agulhas: {a:484} & {a:439}", shortA="Mil Agulhas: {a:484} +", tips={{k="取捨", text="Os seis pontos de missão na Chapada Cintilante ficam próximos: aceite todas e faça uma única volta. A entrega do piloto exige antes uma viagem a Vila Catraca; depois pegue as peças de Kravel (Peças para Kravel) com Mestre Portuário Caruncho, leve-as a Kravel Barbakarvão na Chapada Cintilante, conclua Entrega para os gnomos e aceite o boato do piloto (O boateiro), que fica guardado para entregar em Selva do Espinhaço Angra do Butim."}, {k="取捨", text="Guarde Martek, o Exilado para Karrath, nos Ermos; Irmão (Árvore genealógica) para a Aldeia Pescassombra, em Desolação; e Nesingwary (Rosarães Guima) para Grom'gol e a Angra do Butim, na Selva do Espinhaço."}, {k="提醒", text="Esta etapa dos níveis 32-34 pode ser combinada com a Aldeia Pescassombra, em Desolação. Abaixo do nível 33? Na Chapada Cintilante, mate tartarugas, abutres e escorpiões ao sul da pista (cerca de 76, 85) e depois siga para Desolação.", s={{"Esta etapa dos níveis 32-34 pode ser combinada com a Aldeia Pescassombra, em Desolação"}, {"Abaixo do nível 33?"}, {"Na Chapada Cintilante, mate tartarugas, abutres e escorpiões ao sul da pista (cerca de 76, 85) e depois siga para Desolação"}}}}, grind={[1]={mob="Cristalderme Sal-gema", note="Mobs normais densos ao sul da pista da Chapada Cintilante. O terreno é aberto: escolha os isolados pelas salinas; bom para ganhar EXP no nível 32."}, [2]={mob="Perfurador Quelobrilho", note="Densidade moderada de mobs normais mais a leste nas salinas. Alterne com lagartos e colete cascas de tartaruga endurecidas."}, [3]={mob="Terror Escorpídeo", note="Densidade moderada de mobs normais a sudeste da pista. Circule acima do solo e observe outras feras. Colete Peçonha Salgada de Escorpídeo se necessário."}}, supply={[1]={npc="Nyse"}, [2]={npc="Estalajadeiro Abeqwa"}, [3]={npc="Starn"}, [4]={npc="Estalajadeiro Abeqwa"}, [5]={npc="Starn"}, [6]={npc="Montarr"}, [7]={npc="Synge"}, [8]={npc="Riznek"}, [9]={npc="Synge"}}, steps={[1]={text="Encontre Zapetta na torre de zepelins ao sul de Montalvo (60.74, 58.87, plataforma oeste) e pegue a linha de Orgrimmar. Em Orgrimmar, voe direto para Aldeia Vento Livre se já a tiver aberto. Se não, voe para Acampamento Taurajo, siga a estrada sul até o Grande Elevador e desça ao fundo do vale, vá para o leste e suba pelo elevador de Aldeia Vento Livre; lá, aprenda o ponto de voo de Nyse (45.14, 49.11)."}, [2]={npc="Vigia do Rochedo Chifre Longo", tgt="Vigia do Rochedo Chifre Longo"}, [3]={hint="Recupere o Tomo Mofado e o Manuscrito Rasgado para Jonas Anísio na Cidade Baixa.", desc="Pegue o livro na costa sudoeste de Eira dos Montes e o manuscrito na caverna dos centauros ao sul de Mil Agulhas."}, [5]={text="Depois de pegar Árvore genealógica, desça o platô a partir de Aldeia Vento Livre e siga a estrada do fundo do vale para o sudeste, rumo a Chapada Cintilante."}, [6]={npc="Xabu Latafuso", tgt="Xabu Latafuso"}, [7]={npc="Capu Latafuso", tgt="Capu Latafuso"}, [8]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [9]={npc="Mestre de Pistas Zheran", tgt="Mestre de Pistas Zheran"}, [10]={npc="Relé", tgt="Relé"}, [11]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [12]={hint="Leve 6 Peçonhas Salgadas de Escorpídeo para Xabu Latafuso no Salar Cintilante."}, [13]={hint="Leve 9 Cascos Endurecidos de Tartaruga para Capu Latafuso no Salar Cintilante."}, [14]={hint="Leve 30 Peças de Carro-foguete para Kravel Barbakarvão no Salar Cintilante."}, [15]={hint="Mate 10 Basiliscos Sal-gema, 10 Cristaldermes Sal-gema e 6 Observadores Sal-gema para o Mestre de Pistas Zheran no Salar Cintilante."}, [16]={hint="Obtenha 10 Ossos Ocos de Abutre para Relé no Salar Cintilante."}, [17]={npc="Xabu Latafuso", tgt="Xabu Latafuso"}, [18]={npc="Capu Latafuso", tgt="Capu Latafuso"}, [19]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [20]={npc="Mestre de Pistas Zheran", tgt="Mestre de Pistas Zheran"}, [21]={npc="Relé", tgt="Relé"}, [22]={npc="Xabu Latafuso", tgt="Xabu Latafuso"}, [23]={npc="Relé", tgt="Relé", tag="Se estiver passando por Vila Catraca, Opcional"}, [24]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão", tag="Se estiver passando por Vila Catraca, Opcional"}, [25]={text="Só se aceitou a entrega do mensageiro (Mestre Portuário Caruncho): volte à Aldeia Vento Livre, voe para Vila Catraca, entregue e voe de volta.", tag="Se estiver passando por Vila Catraca, Opcional"}, [26]={npc="Gasganete", tgt="Gasganete", tag="Se estiver passando por Vila Catraca, Opcional"}, [27]={npc="Mestre Portuário Caruncho", tgt="Mestre Portuário Caruncho", tag="Se estiver passando por Vila Catraca, Opcional"}, [28]={npc="Gasganete", tgt="Gasganete", tag="Opcional"}, [29]={npc="Mestre Portuário Caruncho", tgt="Mestre Portuário Caruncho", tag="Se estiver passando por Vila Catraca, Opcional"}, [30]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão", tag="Opcional"}, [31]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão", tag="Opcional"}, [32]={npc="Xabu Latafuso", tgt="Xabu Latafuso", tag="Opcional"}, [33]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão", tag="Opcional", desc="Entregue a Krazek em Selva do Espinhaço Angra do Butim."}, [34]={hint="Leve o Estilhaço de Água para Islen Vidente da Água nos Sertões.", desc="Termine a missão para obter seu Totem da Água."}, [35]={npc="Islen Vidente da Água", tgt="Islen Vidente da Água", desc="Termine a missão para obter seu Totem da Água."}, [36]={npc="Searn Guardafogo", tgt="Searn Guardafogo", desc="O treinador de Orgrimmar oferece Clamor do ar; em Penhasco do Trovão, a missão equivalente Clamor do ar serve de introdução."}, [37]={hint="Encontre Pradosa Fita Nuvens em Mil Agulhas.", desc="O treinador de Orgrimmar oferece Clamor do ar; em Penhasco do Trovão, a missão equivalente Clamor do ar serve de introdução."}, [38]={npc="Pradosa Fita Nuvens", tgt="Pradosa Fita Nuvens", desc="O treinador de Orgrimmar oferece Clamor do ar; em Penhasco do Trovão, a missão equivalente Clamor do ar serve de introdução."}, [39]={npc="Pradosa Fita Nuvens", tgt="Pradosa Fita Nuvens", tag="Opcional", desc="O chefe final de Urzal dos Tuscos dropa uma nota; guarde-a para entregar nas Montanhas de Alterac. Rau Corta Montes também oferece a missão (46.14, 51.71)."}, [40]={hint="Derrote Charlga Talhaflanco no Urzal dos Tuscos e colete informações sobre os planos dos javatuscos.", tag="Opcional", desc="Fique com a nota do chefe final de Urzal dos Tuscos para a entrega de Alterac."}, [41]={text="Depois de terminar as missões na Chapada Cintilante, volte pelo fundo do vale até a Aldeia Vento Livre e suba no elevador até o ponto de voo."}}},
    ["05-d14"] = {name="Urzal dos Tuscos", entrance="Sertões (1413), perto do portal da masmorra no túnel de espinhos, por volta de 42.30, 89.90.", pickup="Dá para fazer Urzal dos Tuscos no caminho para Mil Agulhas. Em Vila Catraca, pegue Tubérculos Folhazul e as ferramentas da toupeira. No caminho para Eira dos Montes, ao passar por Cidade Baixa, pegue Matéria orguânica com Faranell. Se passar por Penhasco do Trovão antes da instância, pegue Um destino vingativo com Auld. Saindo de Aldeia Vento Livre, volte aos Sertões pelo Grande Elevador e siga a estrada de espinhos a oeste até o portal.", pickupS={{"Dá para fazer Urzal dos Tuscos no caminho para Mil Agulhas"}, {"Em Vila Catraca, pegue Tubérculos Folhazul e as ferramentas da toupeira"}, {"No caminho para Eira dos Montes, ao passar por Cidade Baixa, pegue Matéria orguânica com Faranell"}, {"Se passar por Penhasco do Trovão antes da instância, pegue Um destino vingativo com Auld"}, {"Saindo de Aldeia Vento Livre, volte aos Sertões pelo Grande Elevador e siga a estrada de espinhos a oeste até o portal"}}, tips={{k="動線", text="Entrada, pelo caminho de espinhos: use a toupeira para achar Tubérculos Folhazul → pelo caminho lateral, mate Rugug → Jargba → Ramtusk → na caverna dos morcegos, junte a matéria orgânica → na cabana de Charlga, mate a chefe e pegue o coração e os itens de missão → com o caminho limpo, volte à tenda ao lado do último chefe e escolte Willix até a entrada."}, {k="取捨", text="Para pegar Corações do fanatismo e a sequência de Urzal dos Mortos, mate o chefe final e os morcegos do corredor da frente. Se tiver pouco tempo, faça antes só as toupeiras do caminho ou a escolta."}, {k="說明", text="Urzal dos Tuscos fica a oeste do Grande Elevador; Urzal dos Mortos fica a leste. 42.30, 89.90 é a marca da entrada no cliente Forever. Pela estrada principal, siga o túnel de espinhos a oeste até o portal.", s={{"Urzal dos Tuscos fica a oeste do Grande Elevador"}, {"Urzal dos Mortos fica a leste"}, {"42.30, 89.90 é a marca da entrada no cliente Forever"}, {"Pela estrada principal, siga o túnel de espinhos a oeste até o portal"}}}}, steps={[1]={npc="Cáliper Porcatraca", tgt="Cáliper Porcatraca", desc="Pegue a caixa, o bastão de comando e o manual com o mesmo NPC de Vila Catraca antes de entrar."}, [2]={npc="Auld Agulha de Pedra", tgt="Auld Agulha de Pedra"}, [3]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", desc="Entregue para desbloquear a missão Monastério Escarlate Corações do fanatismo."}, [4]={npc="Ruga Totem da Fúria", tgt="Ruga Totem da Fúria", tag="Opcional"}, [5]={hint="Leve 5 antenas tremelicantes para Ruga Totem da Fúria no Acampamento Taurajo", tag="Opcional"}, [6]={npc="Ruga Totem da Fúria", tgt="Ruga Totem da Fúria", tag="Opcional"}, [7]={npc="Ruga Totem da Fúria", tgt="Ruga Totem da Fúria", tag="Opcional", preText="Provação no Campo dos Gigantes"}, [8]={hint="Fale com Thun'grim Olhafogo nos Sertões.", tag="Opcional"}, [9]={npc="Thun'grim Olhafogo", tgt="Thun'grim Olhafogo", tag="Opcional"}, [10]={npc="Thun'grim Olhafogo", tgt="Thun'grim Olhafogo", tag="Opcional", desc="Prepare antes 15 Lingotes de Ferro Fumegante, 10 Azurita Pulverizada e 10 Barras de Ferro. O último material você pega em Urzal dos Tuscos.", preText="Provação no Campo dos Gigantes, Fale com Thun'grim"}, [11]={npc="Searn Guardafogo", tgt="Searn Guardafogo", tag="Pré-requisito de masmorra"}, [12]={npc="Pradosa Fita Nuvens", tgt="Pradosa Fita Nuvens", tag="Pré-requisito de masmorra"}, [13]={npc="Pradosa Fita Nuvens", tgt="Pradosa Fita Nuvens", tag="Opcional", desc="Missão de totem do nível 30. Em Mil Agulhas, procure o NPC que oferece a missão para o seu personagem. Rau Corta Montes (46.14, 51.71) também oferece a mesma missão."}, [14]={text="Entrada: Urzal dos Tuscos"}, [15]={hint="Pegue um Caixote com Furos.", desc="Local: Cave tubérculos ao longo do caminho de espinhos; também dá para cavar na volta com Willix.", spot="Cave tubérculos ao longo do caminho de espinhos; também dá para cavar na volta com Willix."}, [16]={hint="Leve para Thun'grim Olhafogo 15 Lingotes Fumegantes de Ferro, 10 Azuritas Pulverizadas, 10 Barras de Ferro e a Ampola de Flogisto.", tag="Opcional", desc="Local: Pegue o caminho lateral no início da instância até Rugug. Limpe primeiro os monstros ao lado dele.", spot="Pegue o caminho lateral no início da instância até Rugug. Limpe primeiro os monstros ao lado dele."}, [17]={hint="Leve 1 porção de Guano de Morcego para o Mestre-boticário Faranello na Cidade Baixa.", desc="Local: Mate os morcegos na caverna antes do chefe final.", spot="Mate os morcegos na caverna antes do chefe final."}, [18]={hint="Leve o Coração da Talhaflanco para Auld Agulha de Pedra no Penhasco do Trovão.", desc="Local: Saia da caverna dos morcegos, suba na plataforma e mate Charlga na última cabana.", spot="Saia da caverna dos morcegos, suba na plataforma e mate Charlga na última cabana."}, [19]={hint="Derrote Charlga Talhaflanco no Urzal dos Tuscos e colete informações sobre os planos dos javatuscos.", tag="Opcional", desc="Local: Charlga, na cabana do fim. Ordem: ao matar Charlga, pegue também o coração e a nota esfarrapada.", spot="Charlga, na cabana do fim."}, [20]={npc="Pergaminho Pequeno", npcObj=true, tag="Opcional", desc="Charlga Talhaflanco solta um pergaminho pequeno. Clique com o botão direito para aceitar a missão e guarde-a para Cidade Baixa."}, [21]={npc="Importador Willix", tgt="Importador Willix", desc="A escolta começa na tenda ao lado do chefe final. Limpe primeiro o caminho de volta à entrada e só então aceite."}, [22]={hint="Escolte o Importador Willix para fora do Urzal dos Tuscos.", desc="Limpe primeiro o caminho de volta à entrada e depois aceite a escolta de Willix. Proteja-o até a entrada. Local: parta da tenda ao lado do chefe final e volte à entrada com Willix.", spot="Encontre Willix em uma tenda perto do último chefe e acompanhe-o de volta à entrada."}, [23]={npc="Importador Willix", tgt="Importador Willix", desc="Comece a escolta do NPC dentro da masmorra.", spot="Na entrada da masmorra, onde a escolta termina"}, [24]={npc="Cáliper Porcatraca", tgt="Cáliper Porcatraca"}, [25]={npc="Auld Agulha de Pedra", tgt="Auld Agulha de Pedra"}, [26]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", desc="Entregue em Cidade Baixa e aceite Corações do fanatismo."}, [27]={npc="Varimatras", tgt="Varimatras", tag="Opcional"}, [28]={npc="Thun'grim Olhafogo", tgt="Thun'grim Olhafogo", tag="Opcional"}, [29]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Entregue ao chegar em Alterac, nas Montanhas de Alterac. Se o registro mostrar Aldeia Vento Livre, entregue a Rau Corta Montes (46.14, 51.71) conforme indicado."}}},
    ["03-18"] = {name="Desolação", nameA="Desolação: {a:2408}", tips={{k="取捨", text="Em Roubo na estrada, clique na fogueira pelo caminho e depois vá à cabana de Bibbly. As duas partes são de nível 40 e exigem nível 30. Deixe a entrega de Em fuga para Angra do Butim. Pegue Ossos do ofício na cabana; deixe Totens de Centauro Entalhados e os ossos de kodo para a segunda visita à Aldeia Pescassombra, no nível 37."}, {k="取捨", text="Faça as missões de Gelkis Aliança com os Gelkis e Assalto à dispensa pela estrada sul. Se escolheu Magram ou a reputação for a oposta, pule essas duas etapas e as continuações de Gelkis na Aldeia Pescassombra."}, {k="取捨", text="Ao ir de Aldeia Pescassombra para a costa oeste, faça junto as duas missões aquáticas e o livro antigo. Na Fortaleza Machado do Trovão, mate primeiro o Cajado da Luz Sagrada e a Mão de Iruxos; se o progresso não bastar, complete na segunda ida."}, {k="取捨", text="O Livro dos Anciãos : a missão e o alvo são de nível 38, aproximadamente, 4-6 níveis acima desta parada; se não der conta, pule: isso não afeta as outras missões da costa oeste."}, {k="取捨", text="Se a caravana não estiver lá, siga em frente: não espere pela escolta. Guarde Caçada na Selva do Espinhaço para a próxima parada."}, {k="提醒", text="Abaixo do nível 34? Mate centauros normais ao redor do Cemitério dos Kodos (cerca de 56, 60-68) ou naga Slitherblade na costa oeste (35.91, 28.84) antes de partir para Selva do Espinhaço.", s={{"Abaixo do nível 34?"}, {"Mate centauros normais ao redor do Cemitério dos Kodos (cerca de 56, 60-68) ou naga Slitherblade na costa oeste (35.91, 28.84) antes de partir para Selva do Espinhaço"}}}}, danger={[1]="As nagas da costa oeste ficam perto dos makrura submersos. Puxe os conjuradores para a praia para evitar que dois grupos ataquem ao mesmo tempo debaixo d'água."}, grind={[1]={note="Mobs normais esparsos a leste do Cemitério dos Kodos. Cuidado com outras aves carniceiras. Pegue um pequeno EXP no ciclo de missões do cemitério."}, [2]={mob="Naga Sibilâmina", note="Densas multidões normais na costa oeste. Escolha solteiros e observe as feiticeiras próximas. Combine com outras missões costeiras."}, [3]={mob="Feiticeira Sibilâmina", note="Densidade média de mobs normais conjuradores no extremo sul da área das nagas da costa oeste. Puxe-os para a margem para evitar que os makrura da água entrem na luta."}}, supply={[1]={npc="Gharra"}, [2]={npc="Estalajadeira Sikewa"}, [3]={npc="Hae'Wilani"}, [4]={npc="Estalajadeira Sikewa"}, [5]={npc="Tukkão"}}, steps={[1]={text="Da Aldeia Vento Livre, voe para o Retiro Rocha do Sol, na Cordilheira das Torres de Pedra (com baldeação pela Encruzilhada ou por outros pontos já desbloqueados), e siga para sudoeste pelo Vale Carbonizado até entrar em Desolação. Se o Retiro Rocha do Sol não estiver desbloqueado, voe primeiro para a Encruzilhada, siga para o oeste pela entrada das Torres de Pedra e acompanhe a estrada da montanha até o Retiro Rocha do Sol para desbloqueá-lo."}, [2]={npc="Felgur Doiscortes", tgt="Felgur Doiscortes"}, [3]={npc="Gurda Juba Agreste", tgt="Gurda Juba Agreste"}, [4]={npc="Nataoka Chifre Longo", tgt="Nataoka Chifre Longo"}, [5]={npc="Nataoka Chifre Longo", tgt="Nataoka Chifre Longo"}, [6]={npc="Smid Rabiscafuso", tgt="Smid Rabiscafuso"}, [7]={hint="Leve cinco Kodos Domados e o Kodoagrupandador para Smid Rabiscafuso no Acampamento do Rabiscafuso.", desc="Leve apenas um kodo idoso por vez: domestique-o com o atrativo de kodo, leve-o até Smid Rabiscafuso, espere ele falar e clique no kodo para a contagem aumentar."}, [8]={npc="Smid Rabiscafuso", tgt="Smid Rabiscafuso"}, [9]={nodeA="{a:2408}", node="Shadowprey Village", desc="Siga a estrada sul, passe pela aldeia de Gil até Aldeia Pescassombra e obtenha o ponto de voo de Gharra."}, [10]={text="Vincule sua Pedra de Regresso com Estalajadeira Sikewa na estalagem de Aldeia Pescassombra (24.09, 68.21).", bindA="{a:2408}"}, [11]={npc="Roon Juba Agreste", tgt="Roon Juba Agreste"}, [12]={npc="Taiga Crina Sábia", tgt="Taiga Crina Sábia"}, [13]={npc="Mai'Lahii", tgt="Mai'Lahii", tag="Opcional"}, [14]={npc="Druzelger Ganchomagriço", tgt="Druzelger Ganchomagriço"}, [15]={npc="Aka'rai", tgt="Aka'rai"}, [16]={hint="Converse com Jinar'Zillen, na Aldeia Pescassombra, e depois leve 2 peixes pança-sangrenta para Nataoka Chifre Longo.", desc="Assim que chegar à Aldeia Pescassombra, pegue dois peixes com Jinar'Zillen."}, [17]={text="Costa → Fortaleza Machado do Trovão → sátiros ao leste"}, [18]={npc="Diário de Rodovalho", npcObj=true}, [19]={npc="Azore Albamorte", tgt="Azore Albamorte"}, [20]={npc="Pele de Demônio Esfolada", npcObj=true, tag="Faça se cair, Opcional", desc="Clique com o botão direito em Pele de Demônio Esfolada para iniciar a cadeia. Siga em frente se não cair."}, [21]={npc="Maurin Rachaosso", tgt="Maurin Rachaosso", tag="Faça se cair, Opcional"}, [22]={hint="Pegue o Cetro de Luz e devolva-o para Azore Albamorte na torre de Ethel Rethor."}, [23]={npc="Azore Albamorte", tgt="Azore Albamorte"}, [24]={npc="Azore Albamorte", tgt="Azore Albamorte", tag="Opcional"}, [25]={npc="Maurin Rachaosso", tgt="Maurin Rachaosso", tag="Opcional"}, [26]={hint="Derrote uma variedade de sátiros Furiódios em Sargeron, em Desolação, e depois fale novamente com Ara'kai na Aldeia Pescassombra."}, [27]={hint="Leve um Escalpo de Assombrante para Maurin Rachaosso na Desolação.", tag="Opcional"}, [28]={npc="Maurin Rachaosso", tgt="Maurin Rachaosso", tag="Opcional"}, [29]={npc="Maurin Rachaosso", tgt="Maurin Rachaosso", tag="Opcional"}, [30]={hint="Leve a Cabeça de Khan Dez'hepah para Felgur Doiscortes na Desolação."}, [31]={npc="Felgur Doiscortes", tgt="Felgur Doiscortes"}, [32]={npc="Felgur Doiscortes", tgt="Felgur Doiscortes"}, [33]={hint="Ganhe a reputação de Respeitado pelos Gelkis e depois fale com Uthek, a Sábia."}, [34]={npc="Uthek, a Sábia", tgt="Uthek, a Sábia"}, [35]={npc="Uthek, a Sábia", tgt="Uthek, a Sábia"}, [36]={hint="Entregue 15 Orelhas de Centauro para Felgur Doiscortes em Desolação."}, [37]={hint="Entregue 6 sacos de Carne Mal Desidratada para Uthek, a Sábia, na Aldeia Gelkis."}, [38]={npc="Uthek, a Sábia", tgt="Uthek, a Sábia"}, [39]={npc="Fogueira de Acampamento Extinta", npcObj=true, desc="Clique em Fogueira de Acampamento Extinta a noroeste de Cemitério dos Kodos. Requer nível 30."}, [40]={npc="Felgur Doiscortes", tgt="Felgur Doiscortes"}, [41]={npc="Nataoka Chifre Longo", tgt="Nataoka Chifre Longo"}, [42]={npc="Bibbly Ferrafivela", tgt="Bibbly Ferrafivela"}, [43]={npc="Bibbly Ferrafivela", tgt="Bibbly Ferrafivela", desc="Aceite aqui depois de Roubo na estrada. Entregue na pousada de Angra do Butim, na Selva do Espinhaço."}, [44]={npc="Bibbly Ferrafivela", tgt="Bibbly Ferrafivela", desc="Nesta viagem, apenas aceite; os Ossos de Kodo ficam para a sua segunda visita a Desolação."}, [45]={text="Nagas e ilhas da costa oeste, depois retorne para Aldeia Pescassombra"}, [46]={hint="Encontre 10 nacos de Carne de Marisco de Casca Mole e entregue-os para Mai'Lahii na Aldeia Pescassombra.", tag="Opcional"}, [47]={hint="Mate 7 Mirmidões Sibilâmina, 7 Nagas Sibilâmina e 5 Feiticeiras Sibilâmina. Em seguida, fale com Drulzeger, na Aldeia Pescassombra, em Desolação."}, [48]={hint="Leve um Cristal de Oráculo para Maurin Rachaosso em Desolação.", tag="Opcional"}, [49]={hint="Encontre a Chave Prateada de Rodovalho e a Chave Dourada de Rodovalho. Encontre e abra o Baú de Rodovalho.", desc="A chave de prata cai dos makrura e a de ouro, das nagas; com as duas, nade até o baú na ilhota."}, [50]={hint="Pegue o Livro dos Anciãos e entregue-o para Azore Albamorte na torre de Ethel Rethor.", tag="Opcional"}, [51]={npc="Baú de Rodovalho", npcObj=true}, [52]={npc="Azore Albamorte", tgt="Azore Albamorte", tag="Opcional"}, [53]={npc="Maurin Rachaosso", tgt="Maurin Rachaosso", tag="Opcional"}, [54]={npc="Maurin Rachaosso", tgt="Maurin Rachaosso", tag="Opcional"}, [55]={npc="Takta Laminaço", tgt="Takta Laminaço", tag="Opcional"}, [56]={text="Use a Pedra de Regresso para voltar à Aldeia Pescassombra."}, [57]={npc="Mai'Lahii", tgt="Mai'Lahii", tag="Opcional"}, [58]={npc="Druzelger Ganchomagriço", tgt="Druzelger Ganchomagriço"}, [59]={npc="Aka'rai", tgt="Aka'rai"}, [60]={to="Orgrimmar"}, [61]={npc="Nogg", tgt="Nogg", tag="Grupo recomendado, Opcional"}, [62]={npc="Sovik", tgt="Sovik", tag="Grupo recomendado, Opcional"}, [63]={npc="Zevrost", tgt="Zevrost", tag="Opcional", desc="Missão introdutória de Orgrimmar; escolha esta ou a O conhecimento do Orbe de Orahil; sem a missão introdutória, os fragmentos do orbe podem não aparecer."}, [64]={hint="Fale com Menara Nihila nos Sertões.", tag="Opcional", desc="Missão introdutória de Orgrimmar; escolha esta ou a O conhecimento do Orbe de Orahil; sem a missão introdutória, os fragmentos do orbe podem não aparecer."}, [65]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="Missão introdutória de Orgrimmar; escolha esta ou a O conhecimento do Orbe de Orahil; sem a missão introdutória, os fragmentos do orbe podem não aparecer."}, [66]={npc="Kaal Ceifalma", tgt="Kaal Ceifalma", tag="Opcional", desc="Missão introdutória da Cidade Baixa; escolha esta ou a O conhecimento do Orbe de Orahil; sem a missão introdutória, os fragmentos do orbe podem não aparecer."}, [67]={hint="Fale com Menara Nihila nos Sertões.", tag="Opcional", desc="Missão introdutória da Cidade Baixa; escolha esta ou a O conhecimento do Orbe de Orahil; sem a missão introdutória, os fragmentos do orbe podem não aparecer."}, [68]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="Missão introdutória da Cidade Baixa; escolha esta ou a O conhecimento do Orbe de Orahil; sem a missão introdutória, os fragmentos do orbe podem não aparecer."}, [69]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="Após aceitar, escolha um dos dois atendentes da torre para o seu caminho de recompensa."}, [70]={npc="Acólita Wytula", tgt="Acólita Wytula", tag="Opcional", desc="Escolha um dos dois ramos. Com o rubi, capture a alma de um Manávoro ou de um Caça-magos e entregue a Menara."}, [71]={hint="Pegue o Rubi de Felhas e use-o em um dos Canisvis encontrados em Desolação. Depois de conseguir, leve o Rubi de Felhas e o Espírito de Canisvil Aprisionado de volta a Menara Nihila, nos Sertões.", tag="Opcional", desc="Escolha um dos dois ramos. Com o rubi, capture a alma de um Manávoro ou de um Caça-magos e entregue a Menara."}, [72]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="Escolha um dos dois ramos. Com o rubi, capture a alma de um Manávoro ou de um Caça-magos e entregue a Menara."}, [73]={npc="Acólita Magaz", tgt="Acólita Magaz", tag="Opcional", desc="Escolha um dos dois ramos. Com a esmeralda, capture a alma de um Infernal Menor e entregue a Menara."}, [74]={hint="Pegue a Esmeralda Infusa e use-a em um dos Infernais encontrados em Desolação. Depois de conseguir, leve a Esmeralda Infusa e o Espírito de Infernal Aprisionado de volta a Menara Nihila, nos Sertões.", tag="Opcional", desc="Escolha um dos dois ramos. Com a esmeralda, capture a alma de um Infernal Menor e entregue a Menara."}, [75]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="Escolha um dos dois ramos. Com a esmeralda, capture a alma de um Infernal Menor e entregue a Menara."}, [76]={hint="Fale com os acólitos de Menara dentro da torre acima da Vila Catraca e escolha um caminho a seguir.", tag="Opcional"}, [77]={npc="Tabetha", tgt="Tabetha", tag="Opcional"}, [78]={npc="Tabetha", tgt="Tabetha", tag="Grupo recomendado, Opcional", desc="O Demônio do Orbe é um elite de nível 40; procure um grupo antes de fazer."}, [79]={hint="Mate o Demônio do Orbe, depois fale com Tabetha.", tag="Grupo recomendado, Opcional"}, [80]={npc="Tabetha", tgt="Tabetha", tag="Grupo recomendado, Opcional"}, [81]={npc="Tabetha", tgt="Tabetha", tag="Opcional"}, [82]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional"}, [83]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="Faça só a última etapa do ramo que realmente aparecer. Se o addon não mostrar Orbe de Dar'Orathil concluído ou O Orbe de Nor'Orahil concluído, consulte Menara depois de entregar Devolução do orbe purificado."}, [84]={hint="Espere Menara Nihila completar o Orbe de Dar'Orathil e fale com ela novamente.", tag="Opcional", desc="Faça só a última etapa do ramo que realmente aparecer. Se o addon não mostrar Orbe de Dar'Orathil concluído ou O Orbe de Nor'Orahil concluído, consulte Menara depois de entregar Devolução do orbe purificado."}, [85]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="Faça só a última etapa do ramo que realmente aparecer. Se o addon não mostrar Orbe de Dar'Orathil concluído ou O Orbe de Nor'Orahil concluído, consulte Menara depois de entregar Devolução do orbe purificado."}, [86]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="Faça só a última etapa do ramo que realmente aparecer. Se o addon não mostrar Orbe de Dar'Orathil concluído ou O Orbe de Nor'Orahil concluído, consulte Menara depois de entregar Devolução do orbe purificado."}, [87]={hint="Espere Menara Nihila completar o Orbe de Nor'Orahil e fale com ela novamente.", tag="Opcional", desc="Faça só a última etapa do ramo que realmente aparecer. Se o addon não mostrar Orbe de Dar'Orathil concluído ou O Orbe de Nor'Orahil concluído, consulte Menara depois de entregar Devolução do orbe purificado."}, [88]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="Faça só a última etapa do ramo que realmente aparecer. Se o addon não mostrar Orbe de Dar'Orathil concluído ou O Orbe de Nor'Orahil concluído, consulte Menara depois de entregar Devolução do orbe purificado."}, [89]={text="Saia da cidade rumo à torre de zepelins de Durotar."}}},
    ["03-19"] = {name="Selva do Espinhaço", tips={{k="取捨", text="Na primeira visita a Angra do Butim, entregue Em fuga e compre o grogue para concluir \"Cherry for Your Thoughts?\". Mais tarde você irá à ilha ao largo da costa sudeste do Planalto Arathi e então aceitará a continuação, No Honor Among Thieves."}, {k="取捨", text="Só faça a chave e a escolta se encontrar Gimix em Zul'Kunda; a chave e a carga roubada ficam na mesma área. Se alguém já estiver fazendo a escolta, pode seguir direto com a linha principal."}, {k="取捨", text="Na visita 1 à Angra do Butim, libere o voo e aceite as missões. Por volta do nível 35, entregue só Orelhas de Sanguescalpo, Investigue o acampamento, Oferta e demanda, Estilhaços azuis cantantes, Abordagem hostil e, se já terminou, Algo de valor e A grande fuga de Zimmix. Entregue Oferta e demanda e Estilhaços azuis cantantes para liberar Algumas partes faltando e Mineração da Empreendimentos S.A.."}, {k="取捨", text="Salve Mineração da Empreendimentos S.A. e Excelsior para o retorno Angra do Butim após o loop sul. Entregue Algumas partes faltando primeiro nessa visita para desbloquear."}, {k="取捨", text="Deixe para a visita de volta, no nível 42, toda a cadeia dos piratas Vela Sangrenta, Os olhos dos piratas / rapé, O segredo de Zanzil e Fazendo o Sacode tremer → reportar a Macrey → Voodoo devido. Não aceite ainda Febre da Selva do Espinhaço, Mensagem na garrafa, O baú do capitão, o vinho de Aldo Isque e a sua OOX; deixe para a parada de Angra do Butim depois do nível 45."}, {k="取捨", text="Faça a missão de caçadores de dragões até a etapa de matar os raptores Cauda-de-chicote e depois mate-os junto com A defesa de Grom'gol. Para Estilhaços azuis cantantes, mate primeiro os basiliscos Crista de Cristal ao norte; na primeira ida não precisa ir ao vale do sul."}, {k="取捨", text="Começando do zero no nível 34? Faça as duas primeiras rodadas das três cadeias de caça, além das missões de Grom'gol e dos Bloodscalp. As Panteras Goela-sombria contam para Maestria em panteras e O encantamento de Mok'thardin. Mate Sin'Dall para Maestria em tigres na mesma volta. Guarde os três troféus de Falando com Nezzliok e o Colar de Osso Partido para a Angra do Butim. Entregue As Colinas Verdes da Selva do Espinhaço (Grande Espinhaço: Veredas-Capítulo IV) se já tiver as páginas soltas."}, {k="提醒", text="Faça Cidade Afogada no nível 35 com um grupo (recomendado 35-40). Confira primeiro as missões relacionadas. A entrada é submarina, a oeste de Grom'gol.", s={{"Faça Cidade Afogada no nível 35 com um grupo (recomendado 35-40)"}, {"Confira primeiro as missões relacionadas"}, {"A entrada é submarina, a oeste de Grom'gol"}}}, {k="提醒", text="Por volta dos níveis 34-35, mate trolls Bloodscalp no vale do norte da Selva do Espinhaço (29.76, 21.62). A partir do 36, vá ao acampamento de ogros a sudeste de Grom'gol (35.55, 30.92) e complete até o 37 o que faltar antes de pegar o zepelim. Entregue antes as missões já concluídas no acampamento.", s={{"Por volta dos níveis 34-35, mate trolls Bloodscalp no vale do norte da Selva do Espinhaço (29.76, 21.62)"}, {"A partir do 36, vá ao acampamento de ogros a sudeste de Grom'gol (35.55, 30.92) e complete até o 37 o que faltar antes de pegar o zepelim"}, {"Entregue antes as missões já concluídas no acampamento"}}}}, danger={[1]="As ruínas de O Arrecife Torpe têm murlocs Saltscale de elite. Mergulhe da superfície, siga a parede externa até a tábua de pedra e reserve fôlego suficiente para a volta.", [2]="A escolta de Gimix pelas ruínas de Zul'Kunda cruza uma rota de patrulha. Limpe a parte externa do acampamento antes de aceitá-la."}, grind={[1]={mob="Guerreiro Sanguescalpo", note="Densidade média de mobs normais nas ruínas dos Bloodscalp, no vale do norte. Puxe um por vez pelas muralhas externas e cuidado com os xamãs por perto; bom para ganhar EXP no nível 34. Guerreiros podem pegar nesta volta as Presas Bloodscalp para Arma do redemoinho."}, [2]={mob="Raptor Batecauda", note="Densos mobs normais na floresta ao norte de Grom'gol. Escolha os solteiros ao longo da estrada e evite os mobs de elite Saltscale na água. Combine com a caça de raptores."}, [3]={mob="Brutamontes Mosh'Ogg", note="Densidade média de mobs normais ao redor do acampamento de ogros a sudeste de Grom'gol. Evite os curandeiros e o raro Roloch; a partir do nível 36, dá para ganhar EXP aqui até o 37."}}, supply={[1]={npc="Thysta"}, [2]={npc="Estalajadeiro Thulbek"}, [3]={npc="Krakk"}, [4]={npc="Nargatt"}, [5]={npc="Uthok"}, [6]={npc="Gringer"}, [7]={npc="Estalajadeiro Skindle"}, [8]={npc="Jutak"}, [9]={npc="Nixxrax Enchecopo"}, [10]={npc="Haren Kanmae"}}, steps={[1]={text="Na torre de zepelins fora de Orgrimmar, procure Odete Cobrafrete (50.69, 12.89) e pegue o zepelim de Grom'gol. Se já estiver na Selva do Espinhaço, vá direto ao acampamento."}, [2]={node="Grom'gol", desc="Desbloqueie o ponto de voo com Thysta."}, [3]={npc="Comandante Aggro'gosh", tgt="Comandante Aggro'gosh"}, [4]={npc="Nimboya", tgt="Nimboya", tag="Muitos inimigos"}, [5]={npc="Kin'weelay", tgt="Kin'weelay", tag="Muitos inimigos"}, [6]={npc="Clarividente Mok'thardin", tgt="Clarividente Mok'thardin"}, [7]={npc="Nimboya", tgt="Nimboya"}, [8]={npc="Kin'weelay", tgt="Kin'weelay"}, [9]={npc="Erva Carnívora", tgt="Gemmil", desc="Cranque Mirrabolha também oferece esta missão (27.12, 77.21)."}, [10]={hint="Leve um Estilhaço de Tabuleta para Kin'weelay, no Acampamento Grom'gol.", desc="A tábua de pedra fica na parede externa das ruínas submersas: nade por fora para evitar os murlocs de elite que patrulham."}, [11]={npc="Kin'weelay", tgt="Kin'weelay"}, [12]={npc="Kin'weelay", tgt="Kin'weelay", desc="Entregue esta missão antes para poder aceitar Enemies in the Water."}, [13]={nodeA="{a:35}", node="Booty Bay", desc="Se já estiver desbloqueado, voe para lá de Grom'gol. Na primeira visita, siga pela estrada da Selva do Espinhaço para o sul até Angra do Butim e desbloqueie o ponto de voo com Gringer. Depois de aceitar a primeira leva de missões, voe de volta para Grom'gol."}, [14]={npc="Kebok", tgt="Kebok", tag="Muitos inimigos"}, [15]={npc="Krazek", tgt="Krazek", tag="Opcional"}, [16]={npc="Krazek", tgt="Krazek"}, [17]={npc="Krazek", tgt="Krazek", tag="Grupo recomendado, Opcional"}, [18]={npc="Krazek", tgt="Krazek", tag="Grupo recomendado, Opcional"}, [19]={npc="Drizzlik", tgt="Drizzlik"}, [20]={npc="Cranque Mirrabolha", tgt="Cranque Mirrabolha"}, [21]={hint="Encontre um dos bandidos de Desolação."}, [22]={npc="Tokal", tgt="Tokal"}, [23]={npc="Tokal", tgt="Tokal"}, [24]={hint="Bring a Cherry Grog to Tokal, in Booty Bay, to hear the rest of her story.", desc="Compre e entregue. Não beba."}, [25]={npc="Tokal", tgt="Tokal", desc="Depois de entregar, aceite No Honor Among Thieves; só vale a pena se for passar pela costa sudeste do Planalto Arathi."}, [26]={npc="Kebok", tgt="Kebok"}, [27]={npc="Mestre Portuário Lozgil", tgt="Mestre Portuário Lozgil", tag="Opcional"}, [28]={npc="Mestre Portuário Lozgil", tgt="Mestre Portuário Lozgil", tag="Opcional"}, [29]={npc="Barão Rezingada", tgt="Barão Rezingada", tag="Opcional"}, [30]={npc="Barão Rezingada", tgt="Barão Rezingada", tag="Opcional"}, [31]={text="Expedição ao Norte → rio, ruínas de trolls e vida selvagem"}, [32]={hint="Leve o Caixote de Kravel para Rosarães Guima na Selva do Espinhaço."}, [33]={hint="Leve o Chifre de Kodo de Roon para Rosarães Guima na Selva do Espinhaço."}, [34]={npc="Rosarães Guima", tgt="Rosarães Guima"}, [35]={npc="Rosarães Guima", tgt="Rosarães Guima"}, [36]={npc="Eucunha de Clides", tgt="Eucunha de Clides"}, [37]={npc="Rosarães Guima", tgt="Rosarães Guima"}, [38]={npc="Eucunha de Clides", tgt="Eucunha de Clides", tag="Opcional", desc="As páginas caem aleatoriamente dos monstros da Selva do Espinhaço. Compre as que faltarem na casa de leilões e entregue quando tiver os quatro capítulos."}, [39]={npc="Eucunha de Clides", tgt="Eucunha de Clides", tag="Opcional"}, [40]={npc="Eucunha de Clides", tgt="Eucunha de Clides", tag="Opcional"}, [41]={npc="Eucunha de Clides", tgt="Eucunha de Clides", tag="Opcional"}, [42]={npc="Eucunha de Clides", tgt="Eucunha de Clides", tag="Opcional"}, [43]={npc="Merília Ceireles", tgt="Merília Ceireles"}, [44]={npc="Raciliano Gramos", tgt="Raciliano Gramos"}, [45]={npc="Rosarães Guima", tgt="Rosarães Guima"}, [46]={hint="Leve 2 Peles de Crocolisco Grande do Rio para o Drizzlik na Angra do Butim."}, [47]={hint="Merília Ceireles da Expedição do Rosarães quer que você mate 10 Tigres-do-espinhaço Jovens."}, [48]={hint="Raciliano Gramos da Expedição do Rosarães quer que você mate 10 Panteras Jovens."}, [49]={npc="Merília Ceireles", tgt="Merília Ceireles"}, [50]={npc="Raciliano Gramos", tgt="Raciliano Gramos"}, [51]={npc="Merília Ceireles", tgt="Merília Ceireles"}, [52]={npc="Raciliano Gramos", tgt="Raciliano Gramos"}, [53]={hint="Encontre o acampamento de caçadores e relate a localização para Krazek na Angra do Butim."}, [54]={hint="Merília Ceireles da Expedição do Rosarães quer que você mate 10 Tigres-do-Espinhaço."}, [55]={hint="Raciliano Gramos, da Expedição do Rosarães, quer que você mate 10 Panteras."}, [56]={hint="Rosarães Guima quer que você mate 10 Raptores-do-Espinhaço."}, [57]={npc="Merília Ceireles", tgt="Merília Ceireles"}, [58]={npc="Raciliano Gramos", tgt="Raciliano Gramos"}, [59]={npc="Rosarães Guima", tgt="Rosarães Guima"}, [60]={npc="Merília Ceireles", tgt="Merília Ceireles"}, [61]={npc="Raciliano Gramos", tgt="Raciliano Gramos"}, [62]={npc="Rosarães Guima", tgt="Rosarães Guima"}, [63]={npc="Suprimentos Completamente Saqueados", npcObj=true, tag="Muitos inimigos"}, [64]={text="Limpe Zul'Kunda e os trolls Bloodscalp antes de voltar a Grom'gol"}, [65]={hint="Consiga 15 Orelhas de Sanguescalpo e entregue-as a Kebok na Angra do Butim.", tag="Muitos inimigos"}, [66]={hint="Leve 9 Presas de Sanguescalpo para Nimboya no Acampamento Grom'gol.", tag="Muitos inimigos"}, [67]={hint="Leve 25 Colares de Osso Ensanguentado para Kin'weelay no Acampamento Grom'gol.", tag="Muitos inimigos"}, [68]={npc="Nimboya", tgt="Nimboya", tag="Muitos inimigos"}, [69]={npc="Kin'weelay", tgt="Kin'weelay", tag="Muitos inimigos"}, [70]={npc="Nimboya", tgt="Nimboya", tag="Muitos inimigos"}, [71]={hint="Leve 10 Estilhaços de Cristal Cantante para Cranque Mirrabolha."}, [72]={hint="Recupere 8 Cristais Rolados e entregue-os a Kebok na Angra do Butim."}, [73]={hint="Leve os Esquemas do Regulador de Combustível para o Barão Rezingada na Angra do Butim.", tag="Faça junto com Abordagem hostil, Opcional"}, [74]={npc="Zimmix Cospefaísca", tgt="Zimmix Cospefaísca", desc="Aceite quando ele estiver na jaula a oeste de Zul'Kunda. Se o addon não mostrar a etapa, confira diretamente se o NPC tem a missão."}, [75]={hint="Recupere 8 Carregamentos Roubados nas Ruínas de Zul'Kanda, na Selva do Espinhaço, e entregue a carga recuperada a alguém na Angra do Butim.", tag="Muitos inimigos"}, [76]={hint="Use pelego e carvão para criar um decalque da tabuleta da Terceira Lenda Troll."}, [77]={hint="Obtenha a Chave Primitiva com os trolls das Ruínas de Zul'Kanda, na Selva do Espinhaço, e leve-a a Zimmix Cospefaísca."}, [78]={npc="Zimmix Cospefaísca", tgt="Zimmix Cospefaísca"}, [79]={npc="Zimmix Cospefaísca", tgt="Zimmix Cospefaísca", tag="Faça se você ver, Opcional", desc="Gimix fica a oeste das ruínas. Se a escolta já estiver em andamento, espere a próxima rodada ou pule."}, [80]={hint="Escolte Zimmix Cospefaísca para longe das Ruínas de Zul'Kanda. Depois, fale com o Mestre Portuário Lozgil, na Angra do Butim, sobre o resgate bem-sucedido.", tag="Faça se você ver, Opcional"}, [81]={hint="Leve 20 Cabeças Encolhidas para Nimboya, no Acampamento Grom'gol.", tag="Muitos inimigos"}, [82]={npc="Nimboya", tgt="Nimboya", tag="Muitos inimigos"}, [83]={hint="Rosarães Guima quer que você mate 10 Raptores Batecauda."}, [84]={hint="O Comandante Aggro'gosh do Acampamento Grom'gol quer que você mate 15 Raptores Batecauda."}, [85]={npc="Comandante Aggro'gosh", tgt="Comandante Aggro'gosh"}, [86]={npc="Comandante Aggro'gosh", tgt="Comandante Aggro'gosh"}, [87]={npc="Nimboya", tgt="Nimboya", tag="Muitos inimigos, Opcional"}, [88]={npc="Kin'weelay", tgt="Kin'weelay"}, [89]={npc="Kin'weelay", tgt="Kin'weelay"}, [90]={npc="Comandante Aggro'gosh", tgt="Comandante Aggro'gosh"}, [91]={hint="Saque de: Escaramuçador Escamoura", tag="Alvo: Escaramuçador Escamoura"}, [92]={hint="Explore the Vile Reef and find the cavern entrance."}, [93]={npc="Kin'weelay", tgt="Kin'weelay"}, [94]={npc="Comandante Aggro'gosh", tgt="Comandante Aggro'gosh"}, [95]={npc="Kin'weelay", tgt="Kin'weelay", tag="Grupo recomendado, Opcional"}, [96]={npc="Comandante Aggro'gosh", tgt="Comandante Aggro'gosh", tag="Grupo recomendado, Opcional"}, [97]={hint="Mate 6 Ervas Carnívoras ao sul de Grom'gol e depois informe a mãe de Gemmil."}, [98]={npc="Nerrist", tgt="Nerrist"}, [99]={text="Por volta do nível 35, voe para Angra do Butim assim que tiver um lote de entregas de missões de baixo nível."}, [100]={npc="Kebok", tgt="Kebok", tag="Muitos inimigos"}, [101]={npc="Krazek", tgt="Krazek"}, [102]={npc="Drizzlik", tgt="Drizzlik"}, [103]={npc="Cranque Mirrabolha", tgt="Cranque Mirrabolha"}, [104]={npc="Kebok", tgt="Kebok"}, [105]={npc="Mestre Portuário Lozgil", tgt="Mestre Portuário Lozgil", tag="Muitos inimigos"}, [106]={npc="Mestre Portuário Lozgil", tgt="Mestre Portuário Lozgil", tag="Opcional"}, [107]={npc="Barão Rezingada", tgt="Barão Rezingada", tag="Opcional"}, [108]={npc="Drizzlik", tgt="Drizzlik"}, [109]={npc="Cranque Mirrabolha", tgt="Cranque Mirrabolha"}, [110]={text="Após a primeira rodada de entregas de missões, voe de volta para Grom'gol."}, [111]={text="Costa central → trolls, ogros e caçadas pelo caminho"}, [112]={hint="Leve a Cabeça de Gan'zulah e a Cabeça de Nezzliok para o caldeirão borbulhante no Acampamento Grom'gol.", tag="Muitos inimigos, Opcional"}, [113]={hint="O Comandante Aggro'gosh do Acampamento Grom'gol quer que você mate 10 Brutamontes Ogros e 5 Mandingueiros Ogros."}, [114]={npc="Caldeirão Borbulhante", npcObj=true, tag="Muitos inimigos, Opcional"}, [115]={npc="Comandante Aggro'gosh", tgt="Comandante Aggro'gosh"}, [116]={hint="Raciliano Gramos, da Expedição do Rosarães, quer que você mate 10 Panteras Umbragorja."}, [117]={hint="O Clarividente Mok'thardin do Acampamento Grom'gol quer 8 Garras de Umbragorja e uma Presa Imaculada de Tigresa."}, [118]={npc="Clarividente Mok'thardin", tgt="Clarividente Mok'thardin"}, [119]={npc="Clarividente Mok'thardin", tgt="Clarividente Mok'thardin"}, [120]={hint="Merília Ceireles da Expedição do Rosarães quer que você mate 10 Tigres-do-espinhaço Anciãos."}, [121]={npc="Merília Ceireles", tgt="Merília Ceireles"}, [122]={npc="Raciliano Gramos", tgt="Raciliano Gramos"}, [123]={npc="Rosarães Guima", tgt="Rosarães Guima"}, [124]={npc="Merília Ceireles", tgt="Merília Ceireles"}, [125]={npc="Raciliano Gramos", tgt="Raciliano Gramos", tag="Grupo recomendado, Opcional"}, [126]={npc="Eucunha de Clides", tgt="Eucunha de Clides", tag="Opcional"}, [127]={npc="Eucunha de Clides", tgt="Eucunha de Clides", tag="Opcional"}, [128]={npc="Eucunha de Clides", tgt="Eucunha de Clides", tag="Opcional"}, [129]={npc="Eucunha de Clides", tgt="Eucunha de Clides", tag="Opcional"}, [130]={npc="Eucunha de Clides", tgt="Eucunha de Clides", tag="Opcional"}, [131]={hint="Merília Ceireles da Expedição do Rosarães quer que você mate Sin'Dall e lhe traga a pata dela."}, [132]={hint="Raciliano Gramos, da Expedição do Rosarães, quer que você traga para ele a Presa de Bhag'thera.", tag="Grupo recomendado, Opcional"}, [133]={npc="Merília Ceireles", tgt="Merília Ceireles"}, [134]={npc="Raciliano Gramos", tgt="Raciliano Gramos", tag="Grupo recomendado, Opcional"}, [135]={hint="Leve 5 Peles de Crocolisco Arapuca para Drizzlik na Angra do Butim."}, [136]={npc="Comandante Aggro'gosh", tgt="Comandante Aggro'gosh"}, [137]={hint="Leve os itens listados no Pergaminho de Bath'rah para Bath'rah, o Vigia dos Ventos, em Alterac.", tag="Opcional", desc="Os mobs são os mesmos das missões comuns da Selva do Espinhaço. O que falta, Essência dos exilados, colete no Planalto Arathi, perto de Ruína do Martelo."}, [138]={text="Volte a Grom'gol (32.54, 29.35).", tag="Opcional"}, [139]={text="Pegue o zepelim de Grom'gol de volta a Orgrimmar."}, [140]={text="Temperos Reconfortantes", npc="Xen'to"}, [141]={npc="Zevrost", tgt="Zevrost", tag="Opcional", desc="Missão introdutória de Orgrimmar; você pode aceitar a missão direto em Vila Catraca."}, [142]={hint="Fale com Menara Nihila nos Sertões.", tag="Opcional", desc="Missão introdutória de Orgrimmar; você pode aceitar a missão direto em Vila Catraca."}, [143]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="Missão introdutória de Orgrimmar; você pode aceitar a missão direto em Vila Catraca."}, [144]={text="Voe de Orgrimmar para Vila Catraca.", tag="Opcional"}, [145]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional"}, [146]={hint="Leve Vestes de Arcana para Menara Nihila nos Sertões.", tag="Opcional"}, [147]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional"}, [148]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="Traga uma Barra de Ouro para Xizk Pontobom em Angra do Butim."}, [149]={text="No cais de Vila Catraca, pegue o barco para Angra do Butim.", tag="Opcional"}, [150]={hint="Leve uma Barra de Ouro para Xizk Pontobom, na Selva do Espinhaço.", tag="Opcional", desc="Traga uma Barra de Ouro para Xizk Pontobom em Angra do Butim."}, [151]={npc="Xizk Pontobom", tgt="Xizk Pontobom", tag="Opcional", desc="Traga uma Barra de Ouro para Xizk Pontobom em Angra do Butim."}, [152]={npc="Xizk Pontobom", tgt="Xizk Pontobom", tag="Opcional"}, [153]={text="No cais de Angra do Butim, pegue o barco de volta para Vila Catraca.", tag="Opcional"}, [154]={hint="Fale com Menara Nihila, nos Sertões.", tag="Opcional"}, [155]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional"}, [156]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="No norte de Desolação, pegue 10 Sangues de sátiro Hatefury; no sul, mate Infernais Menores para obter 1 Pedra Infernal Menor."}, [157]={text="Voe de Vila Catraca para Orgrimmar e retome a rota.", tag="Opcional"}}},
    ["05-d16"] = {name="The Drowned City", entrance="Selva do Espinhaço 21.50, 27.70", pickup="A primeira visita à Selva do Espinhaço já está na rota principal: aceite em Grom'gol, faça primeiro O Arrecife Torpe e aceite As lendas antigas dos Gurubashi depois de entregar. Aceite Divinassais escusos e O capitão dos Divinassais com Krazek na Angra do Butim. Faça o decalque de Zul'Kunda para As lendas antigas dos Gurubashi. Volte a Grom'gol para Locating the Lost City e Enemies in the Water e conclua as duas juntas na costa oeste; depois de entregar, aceite The Drowned City e The Only Good Brinescale.... Se o ponto de voo do Penhasco do Trovão já estiver desbloqueado, antes de entrar na masmorra pegue o zepelim de Grom'gol de volta a Orgrimmar, voe para o Penhasco do Trovão e siga a estrada de Mulgore até o Platô do Vigia dos Céus para encontrar Mazu'kon. Com tudo reunido, volte a Grom'gol e nade da costa oeste até o portal submarino.", pickupS={{"A primeira visita à Selva do Espinhaço já está na rota principal: aceite em Grom'gol, faça primeiro O Arrecife Torpe e aceite As lendas antigas dos Gurubashi depois de entregar"}, {"Aceite Divinassais escusos e O capitão dos Divinassais com Krazek na Angra do Butim"}, {"Faça o decalque de Zul'Kunda para As lendas antigas dos Gurubashi"}, {"Volte a Grom'gol para Locating the Lost City e Enemies in the Water e conclua as duas juntas na costa oeste; depois de entregar, aceite The Drowned City e The Only Good Brinescale..."}, {"Se o ponto de voo do Penhasco do Trovão já estiver desbloqueado, antes de entrar na masmorra pegue o zepelim de Grom'gol de volta a Orgrimmar, voe para o Penhasco do Trovão e siga a estrada de Mulgore até o Platô do Vigia dos Céus para encontrar Mazu'kon"}, {"Com tudo reunido, volte a Grom'gol e nade da costa oeste até o portal submarino"}}, tips={{k="動線", text="Zul'Alai → Var'Taka → Capitão Pavoral → Medula Imortal → Min'loth, a Serpente Sagrada. Faça o decalque das tábuas de pedra à esquerda da piscina da entrada, à esquerda de Var'Taka, na boca do crânio na área dos navios e atrás de Min'loth. Na área dos navios, elimine os piratas e pegue os artefatos. Elemental Primevo e Gill são opcionais."}, {k="取捨", text="Conclua os dois pré-requisitos do Grom'gol antes de nadar, para que você possa fazer mais do que a seção do navio. Pule a entrega única do Mulgore se estiver fora do caminho."}, {k="說明", text="A entrada da masmorra fica numa caverna submersa a oeste de Grom'gol. Leve poções de respiração aquática ou peça a um colega com a habilidade que a lance.", s={{"A entrada da masmorra fica numa caverna submersa a oeste de Grom'gol"}, {"Leve poções de respiração aquática ou peça a um colega com a habilidade que a lance"}}}}, steps={[1]={npc="Kin'weelay", tgt="Kin'weelay", desc="Pule se já fez isso no trecho de Grom'gol e Angra do Butim."}, [2]={hint="Leve um Estilhaço de Tabuleta para Kin'weelay, no Acampamento Grom'gol.", desc="Pule se já fez isso no trecho de Grom'gol e Angra do Butim."}, [3]={npc="Kin'weelay", tgt="Kin'weelay", desc="Pule se já fez isso no trecho de Grom'gol e Angra do Butim."}, [4]={npc="Kin'weelay", tgt="Kin'weelay", preText="O Arrecife Torpe"}, [5]={hint="Use pelego e carvão para criar um decalque da tabuleta da Terceira Lenda Troll."}, [6]={npc="Kin'weelay", tgt="Kin'weelay"}, [7]={npc="Kin'weelay", tgt="Kin'weelay", preText="As lendas antigas dos Gurubashi"}, [8]={hint="Explore the Vile Reef and find the cavern entrance."}, [9]={npc="Kin'weelay", tgt="Kin'weelay"}, [10]={npc="Comandante Aggro'gosh", tgt="Comandante Aggro'gosh", desc="Esta etapa já aparece em Grom'gol e Angra do Butim, em Selva do Espinhaço. Depois de entregar O Arrecife Torpe, confirme com o comandante. Se a missão já aparecer, faça-a de passagem na ida e volta a Kin'weelay.", preText="O Arrecife Torpe, As lendas antigas dos Gurubashi"}, [11]={hint="Saque de: Escaramuçador Escamoura", tag="Alvo: Escaramuçador Escamoura", desc="Esta etapa já aparece em Grom'gol e Angra do Butim, em Selva do Espinhaço. Depois de entregar O Arrecife Torpe, confirme com o comandante. Se a missão já aparecer, faça-a de passagem na ida e volta a Kin'weelay."}, [12]={npc="Comandante Aggro'gosh", tgt="Comandante Aggro'gosh", desc="Esta etapa já aparece em Grom'gol e Angra do Butim, em Selva do Espinhaço. Depois de entregar O Arrecife Torpe, confirme com o comandante. Se a missão já aparecer, faça-a de passagem na ida e volta a Kin'weelay."}, [13]={npc="Kin'weelay", tgt="Kin'weelay", preText="Locating the Lost City"}, [14]={npc="Comandante Aggro'gosh", tgt="Comandante Aggro'gosh", preText="Enemies in the Water, Locating the Lost City"}, [15]={npc="Krazek", tgt="Krazek"}, [16]={npc="Krazek", tgt="Krazek"}, [17]={npc="Mazu'kon", tgt="Mazu'kon", tag="Opcional", desc="Mazu'kon fica no Platô do Vigia dos Céus, em Mulgore. Faça o desvio para aceitar quando já tiver o ponto de voo do Penhasco do Trovão e estiver de passagem por Mulgore."}, [18]={npc="Sutara Espreitaprados", tgt="Sutara Espreitaprados", tag="Opcional", desc="Esta é uma missão do Urzal dos Mortos; só aceite de passagem se for mesmo a Mulgore aceitar Ídolo Gurubashi ancestral."}, [19]={text="Entrada: The Drowned City"}, [20]={hint="Use the hide and charcoal to create rubbings of the tablets found in the Drowned City.", desc="Local: Esquerda da poça → esquerda de Var'Taka → boca da caveira ao lado do capitão → atrás do último chefe. Ordem: Faça o decalque em cada um dos quatro marcos pelo caminho.", spot="À esquerda da piscina → à esquerda de Var'Taka → boca da caveira ao lado do capitão → atrás do chefe final."}, [21]={hint="Slay Var'Taka in the Drowned City.", desc="Cuide primeiro do sacerdote ao seu lado e fique atento à respiração debaixo d'água. Local: Passe por Zul'Alai, entre nos arquivos submersos e procure o chefe ao lado de dois sacerdotes.", spot="Depois de Zul'Alai, encontre o chefe próximo a duas sacerdotisas no arquivo inundado."}, [22]={hint="Colete 10 Artefatos Infusos em Vodu de piratas Divinassais na Cidade Afogada.", desc="Se não conseguir juntar tudo, continue limpando piratas na área dos navios. Local: entre na área do navio pirata de Saltseer e saqueie artefatos dos piratas pelo caminho. Ordem: limpe na mesma área do Capitão Saltseer.", spot="Elimine os piratas Saltseer perto dos navios e saqueie os artefatos."}, [23]={hint="Mate 3 Legistas Divinassais e o Capitão Pavoral na Cidade Afogada.", desc="Local: Vá à área dos navios e limpe os legistas nas passagens perto do capitão. Ordem: Interaja com a pérola brilhante depois de matar o capitão.", spot="Limpe os legistas ao longo das passagens próximas ao capitão na área do navio."}, [24]={hint="Recupere um Ídolo Gurubashi Ancestral na Cidade Afogada.", tag="Opcional", desc="Local: Passe pelo capitão e pela barreira de pérolas e mate a Medula Imortal na parte final.", spot="Passe pelo capitão e pela barreira de pérolas e mate a Medula Imortal na parte final."}, [25]={npc="Kin'weelay", tgt="Kin'weelay"}, [26]={npc="Comandante Aggro'gosh", tgt="Comandante Aggro'gosh"}, [27]={npc="Kin'weelay", tgt="Kin'weelay", tag="Opcional", desc="Pegue no mesmo lugar depois de entregar Cidade Afogada. Entregue junto com Ídolo Gurubashi ancestral quando chegar a Kalimdor.", preText="The Drowned City"}, [28]={npc="Krazek", tgt="Krazek"}, [29]={npc="Krazek", tgt="Krazek"}, [30]={hint="Take the tablet etchings to Master Gadrin in Sen'jin Village in Durotar.", tag="Opcional", desc="Entregue se você já estiver voando para Orgrimmar. Isso pode esperar até depois da execução."}, [31]={npc="Mestre Gadrin", tgt="Mestre Gadrin", tag="Opcional", desc="Entregue se você já estiver voando para Orgrimmar. Isso pode esperar até depois da execução."}, [32]={npc="Mazu'kon", tgt="Mazu'kon", tag="Opcional"}}},
    ["05-d15"] = {name="Gnomeregan", entrance="Selva do Espinhaço 27.60, 77.48", pickup="Depois das primeiras entregas em Aldeia Pescassombra, em Desolação, voe para Orgrimmar (com escalas em Retiro Rocha do Sol e na Encruzilhada). Antes de sair da cidade para o zepelim de Grom'gol, encontre Sovik e Nogg no Vale da Honra de Orgrimmar e pegue Guerra dos robôs e Engenheiro-chefe Scooty. Pegue o barco de Vila Catraca para Angra do Butim, ou voe de Grom'gol para Angra do Butim. Quando Scooty concluir Engenheiro-chefe Scooty→E lá vamos nós!, guarde o Transponder Goblínico e entre.", pickupS={{"Depois das primeiras entregas em Aldeia Pescassombra, em Desolação, voe para Orgrimmar (com escalas em Retiro Rocha do Sol e na Encruzilhada)"}, {"Antes de sair da cidade para o zepelim de Grom'gol, encontre Sovik e Nogg no Vale da Honra de Orgrimmar e pegue Guerra dos robôs e Engenheiro-chefe Scooty"}, {"Pegue o barco de Vila Catraca para Angra do Butim, ou voe de Grom'gol para Angra do Butim"}, {"Quando Scooty concluir Engenheiro-chefe Scooty→E lá vamos nós!, guarde o Transponder Goblínico e entre"}}, tips={{k="動線", text="Entre e vire à esquerda, descendo até a Zona Limpa → nos alojamentos à direita, escolte Kernobill → Eletrocutor 6000 → Espanca-gente 9-60 → Termaplugue; pegue a senha e abra o cofre. Se pegar o Anel Encardido, volte à Zona Limpa e use o Sparklematic."}, {k="取捨", text="Faça apenas se o equipamento ou a XP das missões compensar. Entregar junto com as missões de Angra do Butim economiza viagens."}, {k="說明", text="Depois de se teletransportar para a instalação em Dun Morogh, siga pelo corredor subterrâneo até o portal da masmorra; não é preciso passar por Altaforja. Se ainda não liberou Scooty, conclua primeiro a cadeia do teletransportador.", s={{"Depois de se teletransportar para a instalação em Dun Morogh, siga pelo corredor subterrâneo até o portal da masmorra; não é preciso passar por Altaforja"}, {"Se ainda não liberou Scooty, conclua primeiro a cadeia do teletransportador"}}}}, steps={[1]={npc="Nogg", tgt="Nogg"}, [2]={npc="Sovik", tgt="Sovik", preText="Guerra dos robôs"}, [3]={npc="Scooty", tgt="Scooty"}, [4]={npc="Scooty", tgt="Scooty", preText="Engenheiro-chefe Scooty"}, [5]={hint="Esperar até Scooty calibrar o Transponder Goblínico."}, [6]={npc="Scooty", tgt="Scooty"}, [7]={text="Entrada: Gnomeregan"}, [8]={npc="Kernobill", tgt="Kernobill", desc="Encontre Kernobill perto da Zona Limpa. Limpe primeiro a rota de escolta."}, [9]={hint="Escolte Kernobill até a saída do Corredor dos Mecanismos, depois apresente-se a Scooty na Angra do Butim.", desc="Local: Encontre Kernobill na Zona Limpa; limpe primeiro o caminho e depois escolte-o de volta à entrada.", spot="Encontre Kernobill na Zona Limpa; limpe primeiro o caminho e depois escolte-o de volta à entrada."}, [10]={hint="Pegue a Combinação do Cofre do Termaplugue e o Projeto de Mecatraje e leve-os para Nogg em Orgrimmar.", desc="Durante a luta, alguém aperta o botão ao lado do abrigo para controlar as bombas. Local: Siga a passagem no fundo da oficina até a rotunda do último chefe e abra o baú depois de matá-lo.", spot="Siga o túnel da oficina até a sala redonda. Mate o último chefe e abra o cofre."}, [11]={npc="Anel Encardido", npcObj=true, tag="Opcional", desc="Leve 3 moedas de prata e siga o diálogo da máquina."}, [12]={hint="Descubra uma maneira de remover a crosta de sujeira do Anel Encardido.", tag="Opcional", desc="Leve 3 de prata e siga os diálogos da máquina. Local: Vire à esquerda depois da entrada e desça a ladeira; procure a Brastematic 5200 na parede da área de limpeza. Ordem: Pegue primeiro o anel com o Agente Ferro Negro.", spot="Vire à esquerda e desça até a Zona Limpa. Encontre o Sparklematic perto da parede."}, [13]={npc="A Brastematic 5200", npcObj=true, tag="Opcional", desc="Leve 3 moedas de prata e siga o diálogo da máquina.", spot="À esquerda da entrada, descendo a rampa: limpador na parede da área de limpeza"}, [14]={npc="A Brastematic 5200", npcObj=true, tag="Opcional", preText="Anel Encardido"}, [15]={npc="Scooty", tgt="Scooty"}, [16]={npc="Nogg", tgt="Nogg"}, [17]={npc="Nogg", tgt="Nogg", tag="Opcional"}}},
    ["03-20"] = {name="Pântano Vadeoso", nameA="Pântano Vadeoso: {a:496}", tips={{k="取捨", text="Pegue O escudo negro, Pegadas em forma de casco e Tenente Paval Reethe na mesma pousada queimada antes de entrar na vila."}, {k="取捨", text="Leve 3 Temperos Reconfortantes antes de sair da cidade. Entregue a Espada Larga de Lunaço se já tiver; comprar ou forjar uma só para isso aumenta o vaivém. Guarde A fuga do Cascão para quando passar por Vila Catraca a caminho da Garganta Abrasadora."}, {k="提醒", text="Aldeia Muralha Verde e a volta à Aldeia Pescassombra, em Desolação, dividem a faixa de EXP 37→38. Se já entregou as missões de Desolação, mate aranhas e raptores comuns nos pontos de missão do pântano ao norte de Brackenwall, no Pântano Vadeoso, até o nível 38.", s={{"Aldeia Muralha Verde e a volta à Aldeia Pescassombra, em Desolação, dividem a faixa de EXP 37→38"}, {"Se já entregou as missões de Desolação, mate aranhas e raptores comuns nos pontos de missão do pântano ao norte de Brackenwall, no Pântano Vadeoso, até o nível 38"}}}}, danger={[1]="Aranhas venenosas e patrulhas de raptores se sobrepõem no pântano do norte. Puxe um inimigo de cada vez da borda e evite os locais onde as patrulhas se encontram no mato."}, grind={[1]={mob="Fera do Pântano Murchavinha", note="Área dos Murchavinha no pântano do norte: muitos mobs normais. Eles ficam misturados com outros mobs Murchavinha; limpe um por vez pela terra firme até chegar perto do nível exigido para sair desta parada."}, [2]={mob="Cospeçonha Presanegra", note="Há uma quantidade moderada de inimigos normais na parte leste do pântano ao norte. Cuidado com o veneno e as patrulhas de raptores. Venha para cá se houver outros jogadores caçando os Murchavinha."}, [3]={mob="Gritador Dinossangue", note="Orla da mata no pântano do norte: muitos mobs normais. Há crocoliscos e outros raptores por perto; pegue um por vez ao longo da margem e vá embora ao chegar ao nível 38."}}, supply={[1]={npc="Shardi"}, [2]={npc="Krak"}, [3]={npc="Ogg'marr"}, [4]={npc="Zanara"}, [5]={npc="Balai Lok'Wein"}}, steps={[1]={text="Voe de Orgrimmar para o Acampamento Taurajo."}, [2]={text="Siga de Acampamento Taurajo para o leste, rumo ao Pântano Vadeoso. Pare primeiro na pousada incendiada à beira da estrada (29.70, 48.20)."}, [3]={npc="Escudo Negro", npcObj=true}, [4]={npc="Pegadas de casco", npcObj=true}, [5]={npc="Insígnia da Guarda de Theramore", npcObj=true}, [6]={nodeA="{a:496}", node="Brackenwall Village", desc="Obtenha o ponto de voo com Shardi."}, [7]={text="Mantenha a Pedra de Regresso vinculada à Aldeia Pescassombra, em Desolação, para a volta na próxima parada."}, [8]={hint="Informe Krog, na Aldeia Muralha Verde, sobre as pegadas suspeitas na Estalagem Pouso do Umbral."}, [9]={npc="Krog", tgt="Krog"}, [10]={npc="Krog", tgt="Krog"}, [11]={npc="Krog", tgt="Krog"}, [12]={npc="Krog", tgt="Krog"}, [13]={npc="Do'gol", tgt="Do'gol"}, [14]={npc="Do'gol", tgt="Do'gol"}, [15]={npc="Nazir Piquessangue", tgt="Nazir Piquessangue"}, [16]={npc="Esmagabarro Pé-sujo", tgt="Esmagabarro Pé-sujo"}, [17]={npc="Ogron", tgt="Ogron"}, [18]={hint="Vá com Ogron falar com Reethe, e então fale novamente com Krog na Aldeia Muralha Verde."}, [19]={npc="Krog", tgt="Krog"}, [20]={hint="Mate 9 Infiltradores de Theramore e, em seguida, fale com Nazir Piquessangue, na Aldeia Muralha Verde."}, [21]={npc="Nazir Piquessangue", tgt="Nazir Piquessangue"}, [22]={npc="Nazir Piquessangue", tgt="Nazir Piquessangue", tag="Opcional"}, [23]={text="Escolta pela estrada norte → Casarão do Pantanal Iluminado → costa"}, [24]={npc="Inácio Cascão", tgt="Inácio Cascão", tag="Entregue ao passar por Vila Catraca, Opcional"}, [25]={hint="Escolte Inácio \"Cascão\" e, em seguida, fale com Cáliper Porcatraca na Vila Catraca.", tag="Opcional"}, [26]={npc="Zé Olho de Lama", tgt="Zé Olho de Lama"}, [27]={hint="Leve 3 Temperos Reconfortantes para o Zé \"Olho de Lama\" no Pântano Vadeoso."}, [28]={npc="Zé Olho de Lama", tgt="Zé Olho de Lama"}, [29]={npc="Zé Olho de Lama", tgt="Zé Olho de Lama"}, [30]={npc="Terra Solta", npcObj=true}, [31]={hint="Leve 40 Olhos Névoa Negra Inteiros para Zé \"Olho de Lama\" no Casarão do Pantanal Iluminado."}, [32]={hint="Leve o Relatório do Espião para Nazir Piquessangue na Aldeia Muralha Verde."}, [33]={hint="Obtenha 6 Vesículas de Peçonha Ácida para Do'gol na Aldeia Muralha Verde."}, [34]={hint="Leve os Documentos do Capitão a Nazir Piquessangue na Aldeia Muralha Verde.", tag="Opcional"}, [35]={hint="Esmagabarro Pé-sujo, na parte norte do Pântano Vadeoso, quer 12 Cabeças de Lamapina."}, [36]={npc="Zé Olho de Lama", tgt="Zé Olho de Lama"}, [37]={npc="Nazir Piquessangue", tgt="Nazir Piquessangue"}, [38]={npc="Do'gol", tgt="Do'gol"}, [39]={npc="Nazir Piquessangue", tgt="Nazir Piquessangue", tag="Opcional"}, [40]={npc="Esmagabarro Pé-sujo", tgt="Esmagabarro Pé-sujo"}, [41]={npc="Do'gol", tgt="Do'gol"}, [42]={npc="Krog", tgt="Krog"}, [43]={text="Viagem de volta opcional e missões entre zonas"}, [44]={npc="Zé Olho de Lama", tgt="Zé Olho de Lama", tag="Já tendo a Espada Larga de Lunaço, Opcional"}, [45]={hint="Leve uma Espada Larga de Lunaço para o Zé no Pântano Vadeoso.", tag="Já tendo a Espada Larga de Lunaço, Opcional", desc="Traga uma Espada Larga de Lunaço pronta para entregar."}, [46]={npc="Zé Olho de Lama", tgt="Zé Olho de Lama", tag="Já tendo a Espada Larga de Lunaço, Opcional"}, [47]={npc="Terra Solta", npcObj=true}, [48]={hint="Leve a Cabeça de Orc Desafiante para Nazir Piquessangue na Aldeia Muralha Verde."}, [49]={npc="Nazir Piquessangue", tgt="Nazir Piquessangue"}, [50]={npc="Nazir Piquessangue", tgt="Nazir Piquessangue"}, [51]={npc="Denya", tgt="Denya", tag="Opcional, Você já pode comprar na casa de leilões (ou pedir para um alt enviar) 1 × Jade (para Itens do poder, mais tarde no Pântano Vadeoso).", desc="Esta rota passa por Orgrimmar. Em Penhasco do Trovão, procure Ursyn Karnissa (25.70, 14.19); na Cidade Baixa, Anastácia Cordato (85.14, 10.03)."}, [52]={hint="Fale com Tabetha.", tag="Opcional"}, [53]={npc="Tabetha", tgt="Tabetha", tag="Opcional"}, [54]={npc="Tabetha", tgt="Tabetha", tag="Opcional", desc="Guarde 10 feixes de totens e combine-os no Círculo de União Externo."}, [55]={hint="Traga 1 Jade e a Morácea Carregada por Raio para Tabetha no Pântano Vadeoso.", tag="Opcional", desc="Guarde 10 feixes de totens e combine-os no Círculo de União Externo."}, [56]={npc="Tabetha", tgt="Tabetha", tag="Opcional", desc="Guarde 10 feixes de totens e combine-os no Círculo de União Externo."}, [57]={npc="Tabetha", tgt="Tabetha", tag="Opcional"}, [58]={hint="Fale com Tirth, o Mago, no Salar Cintilante.", tag="Opcional"}, [59]={npc="Tirth, o Mago", tgt="Tirth, o Mago", tag="Opcional"}, [60]={npc="Tirth, o Mago", tgt="Tirth, o Mago", tag="Opcional", desc="Selecione o frango e digite /beckon. Fale com ele depois que se transformar em humano."}, [61]={hint="Encontre a frase que abre o cofre de Tirth e fale novamente com ele.", tag="Opcional", desc="Selecione o frango e digite /beckon. Fale com ele depois que se transformar em humano."}, [62]={npc="Tirth, o Mago", tgt="Tirth, o Mago", tag="Opcional", desc="Selecione o frango e digite /beckon. Fale com ele depois que se transformar em humano."}, [63]={npc="Tirth, o Mago", tgt="Tirth, o Mago", tag="Opcional", desc="Entre em grupo na Biblioteca e procure o livro nas estantes."}, [64]={hint="Leve o livro Rituais do Poder para Tabetha no Pântano Vadeoso.", tag="Opcional", desc="Entre em grupo na biblioteca e procure o livro nas estantes. Depois de entrar no Monastério Escarlate, vá para a área da biblioteca."}, [65]={npc="Tabetha", tgt="Tabetha", tag="Opcional", desc="Entre em grupo na Biblioteca e procure o livro nas estantes."}, [66]={npc="Tabetha", tgt="Tabetha", tag="Opcional", desc="Conclua ambas as cadeias de material da varinha antes de reportar.", star={"Varinha da Fúria Glacial / Varinha da Força Etérea / Varinha Iraflama"}}, [67]={hint="Fale com Tabetha depois do ritual.", tag="Opcional", desc="Conclua ambas as cadeias de material da varinha antes de reportar."}, [68]={npc="Tabetha", tgt="Tabetha", tag="Opcional", desc="Conclua ambas as cadeias de material da varinha antes de reportar.", star={"Varinha da Fúria Glacial / Varinha da Força Etérea / Varinha Iraflama"}}, [69]={text="Volte à Aldeia Muralha Verde. Guarde a Pedra de Regresso para a volta da Mannoroc, perto da Aldeia Pescassombra, em Desolação."}}},
    ["03-21"] = {name="Desolação", nameA="Desolação: {a:2408}", tips={{k="取捨", text="Se faltar EXP no nível 37, faça os centauros ao sudeste e os portais da Legião Ardente próximos. Só é possível aceitar Portais para a Legião depois de entregar a Mão de Iruxos em Aldeia Pescassombra. Para o Plasma Espectral, use o baú para atrair os monstros e trate um por vez."}, {k="取捨", text="Na primeira visita, só pegue Mão da Iruxos. Na segunda, no nível 37, pegue a Caixa do Demônio na Fortaleza Machado do Trovão (missão de nível 38). Só depois de entregar dá para pegar Portais para a Legião."}, {k="取捨", text="Totens de Centauro Entalhados e Ossos do ofício, missões de nível 39-40, ficam para esta viagem: os totens saem dos centauros Magram a sudeste das Ruínas de Mannoroc, que você mata de passagem; Ossos do ofício você já aceitou na primeira visita a Desolação: nesta viagem, colete os Ossos de Kodo e entregue na cabana de Bibbly."}, {k="提醒", text="Abaixo do nível 38? Mate demônios normais ao redor de Ruínas de Mannoroc (em torno de 50.40, 70.40). Se as mortes forem lentas, mude para os centauros a sudeste de Cemitério dos Kodos.", s={{"Abaixo do nível 38?"}, {"Mate demônios normais ao redor de Ruínas de Mannoroc (em torno de 50.40, 70.40)"}, {"Se as mortes forem lentas, mude para os centauros a sudeste de Cemitério dos Kodos"}}}}, danger={[1]="Há lordes de elite ao sul de Ruínas de Mannoroc. Se só precisa de EXP ou materiais, fique com os Caçadores de Magos do lado leste."}, grind={[1]={mob="Infernal Menor", note="Mobs normais densos ao norte de Ruínas de Mannoroc. Cuidado com os outros demônios por perto. Bruxos podem pegar uma Pedra Infernal Menor para Componentes para um robessangre dourado encantado (só bruxos)."}, [2]={note="Densidade média de mobs normais conjuradores na mesma borda externa de Ruínas de Mannoroc. Use o terreno para separá-los dos grupos. Alterne com os Infernais Menores."}, [3]={mob="Caça-magos", note="Densidade moderada de mobs normais a leste de Ruínas de Mannoroc. Escolha os solteiros ao redor da borda e evite o senhor de elite ao sul. Use este local se o loop externo estiver lotado."}}, supply={[1]={npc="Gharra"}, [2]={npc="Estalajadeira Sikewa"}, [3]={npc="Hae'Wilani"}, [4]={npc="Estalajadeira Sikewa"}, [5]={npc="Tukkão"}}, steps={[1]={text="Na Aldeia Muralha Verde, escolha Aldeia Pescassombra no mapa de voo e faça baldeação por pontos desbloqueados como a Encruzilhada e o Retiro Rocha do Sol. Se Aldeia Pescassombra não aparecer no mapa e sua Pedra de Regresso estiver vinculada lá e disponível, volte com ela; para a volta de Mannoroc, retorne a pé à Aldeia Pescassombra pela estrada."}, [2]={text="Da Aldeia Pescassombra, vá para o leste passando pelo Entreposto do Espírito que Anda e pelo Cemitério dos Kodos, depois para o norte até a Fortaleza Machado do Trovão para pegar a Caixa do Demônio."}, [3]={npc="Guido Zumbidorla", tgt="Guido Zumbidorla"}, [4]={npc="Gurda Juba Agreste", tgt="Gurda Juba Agreste"}, [5]={hint="Entregue 10 Ossos de Kodo do Cemitério dos Kodos para Bibbly Ferrafivela no Barraco do Kormek."}, [6]={hint="Recolha a Caixa Demoníaca na Fortaleza Machado do Trovão e leve-a, junto com a Picareta do Diabo, para Taiga Crina Sábia na Aldeia Pescassombra.", desc="Use a Enxada do Demônio no cristal vermelho na Fortaleza Machado do Trovão. Mate o espírito demoníaco que aparecer para pegar a Caixa do Demônio."}, [7]={text="Vá ao acampamento dos sátiros Furiódio, a nordeste da Fortaleza Machado do Trovão, e colete 10 Ampolas de Sangue de Furiódio (73.10, 11.04).", tag="Opcional"}, [8]={npc="Bibbly Ferrafivela", tgt="Bibbly Ferrafivela"}, [9]={text="Da cabana de Bibbly, volte à Aldeia Pescassombra para entregar Mão da Iruxos e pegar Portais para a Legião, depois vá para o sul até Ruínas de Mannoroc."}, [10]={npc="Taiga Crina Sábia", tgt="Taiga Crina Sábia"}, [11]={npc="Taiga Crina Sábia", tgt="Taiga Crina Sábia"}, [12]={hint="Feche 6 portais nas Ruínas de Mannoroc e fale com Taiga Crina Sábia na Aldeia Pescassombra.", desc="Use a Mão da Iruxos, dada por Taiga, no portal do covil para banir seis demônios."}, [13]={hint="Obtenha 5 Totens de Centauro Entalhados matando centauros de qualquer clã em Desolação e depois leve-os para Gurda Juba Agreste no Entreposto do Espírito que Anda."}, [14]={hint="Leve 10 Ampolas de Sangue de Furiódio e 1 Pedra Infernal Menor para Menara Nihila, nos Sertões.", tag="Opcional", desc="No sul, mate Infernais Menores para obter 1 Pedra Infernal Menor; o sangue de Furiódio você já juntou todo no norte."}, [16]={hint="Leve 8 Fantasmoplasmas e o Caixote de Ímãs Fantasmais para Guido Zumbidorla na Desolação.", desc="Coloque a caixa no Vale dos Ossos. Dê um passo para trás e puxe os fantasmas um por um."}, [17]={npc="Gurda Juba Agreste", tgt="Gurda Juba Agreste"}, [18]={npc="Guido Zumbidorla", tgt="Guido Zumbidorla"}, [19]={text="Se a Pedra de Regresso ainda estiver vinculada em Aldeia Pescassombra e fora do tempo de recarga, volte à aldeia com ela. Se estiver em recarga ou vinculada em outro lugar, volte a pé pela estrada."}, [20]={npc="Taiga Crina Sábia", tgt="Taiga Crina Sábia"}, [21]={text="Depois de entregar, voe de Gharra (21.60, 74.13) para Orgrimmar."}, [22]={npc="Dran Droffers", tgt="Dran Droffers", tag="Grupo recomendado, Opcional"}, [23]={text="Voe de Orgrimmar para Vila Catraca.", tag="Opcional"}, [24]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="No norte de Desolação, pegue 10 Sangues de sátiro Hatefury; no sul, mate Infernais Menores para obter 1 Pedra Infernal Menor."}, [25]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="Separe Fio de ouro de qualidade, 2 carvões fumegantes e 1 fragmento de alma e volte a Menara."}, [26]={npc="Denya", tgt="Denya", tag="Opcional", desc="Esta rota passa por Orgrimmar. Em Penhasco do Trovão, procure Ursyn Karnissa (25.70, 14.19); na Cidade Baixa, Anastácia Cordato (85.14, 10.03)."}, [27]={hint="Fale com Tabetha.", tag="Opcional"}, [28]={npc="Tabetha", tgt="Tabetha", tag="Opcional"}, [29]={npc="Tabetha", tgt="Tabetha", tag="Opcional"}, [30]={hint="Leve um Orbe Infernal para Tabetha no Pântano Vadeoso.", tag="Opcional"}, [31]={npc="Tabetha", tgt="Tabetha", tag="Opcional"}, [32]={npc="Tabetha", tgt="Tabetha", tag="Opcional", desc="Recarregue saúde e mana e peça a Tabetha para iniciar o exorcismo."}, [33]={hint="Mate o Demônio do Orbe, depois fale com Tabetha.", tag="Opcional", desc="Recarregue saúde e mana e peça a Tabetha para iniciar o exorcismo."}, [34]={npc="Tabetha", tgt="Tabetha", tag="Opcional", desc="Recarregue saúde e mana e peça a Tabetha para iniciar o exorcismo."}, [35]={npc="Tabetha", tgt="Tabetha", tag="Opcional", desc="Confirme se seu grupo está usando a entrada que leva a Sentinela de Obsidiana."}, [36]={hint="Recupere uma Fonte de Energia de Obsidiana e leve-a para Tabetha no Pântano Vadeoso.", tag="Opcional", desc="Confirme primeiro com o grupo que vocês vão pela entrada com a Sentinela de Obsidiana. Entre em Uldaman pela porta dos fundos e procure a Sentinela de Obsidiana."}, [37]={npc="Tabetha", tgt="Tabetha", tag="Opcional", desc="Confirme se seu grupo está usando a entrada que leva a Sentinela de Obsidiana."}, [38]={npc="Tabetha", tgt="Tabetha", tag="Opcional", desc="Recarregue sua mana antes de aceitar. O cronômetro começa quando você aceita."}, [39]={hint="Mate 12 Surtos de Mana no tempo limite permitido.", tag="Opcional", desc="Recarregue sua mana antes de aceitar. O cronômetro começa quando você aceita."}, [40]={npc="Tabetha", tgt="Tabetha", tag="Opcional", desc="Recarregue sua mana antes de aceitar. O cronômetro começa quando você aceita."}, [41]={npc="Tabetha", tgt="Tabetha", tag="Opcional"}, [42]={npc="Tabetha", tgt="Tabetha", tag="Opcional"}, [43]={text="Voe de Vila Catraca para Orgrimmar e volte a pegar o zepelim para as Clareiras de Tirisfal.", tag="Opcional"}}},
    ["03-22"] = {name="Montanhas de Alterac", tips={{k="取捨", text="O resgate/PROCURA-SE: integrantes da Camarilha já foram feitas na sua última passagem pelo Contraforte de Eira dos Montes. Nas montanhas, entregue Infiltração antes de pegar. Procure juntos os objetivos de Gol'dir e Vardus nos acampamentos da Camarilha."}, {k="提醒", text="Esta etapa e Ruína do Martelo juntas levam ao nível 40; confira a EXP que falta ao chegar a Ruína do Martelo. Se faltar pouca EXP, mate membros comuns da Camarilha (58.44, 70.00) antes de ir a Ruína do Martelo.", s={{"Esta etapa e Ruína do Martelo juntas levam ao nível 40; confira a EXP que falta ao chegar a Ruína do Martelo"}, {"Se faltar pouca EXP, mate membros comuns da Camarilha (58.44, 70.00) antes de ir a Ruína do Martelo"}}}}, danger={[1]="Há ogros de elite dentro das Ruínas de Alterac. Mate os brutamontes normais na trilha de fora e espere o grupo antes de entrar."}, grind={[1]={mob="Espião da Camarilha", note="Mobs normais densos ao redor do acampamento da Camarilha. Cuidado com os ocultos e os magos; escolha os isolados pela borda do acampamento, só para ganhar um pouco de EXP antes de Ruína do Martelo."}, [2]={note="Mobs normais densos pela estrada da montanha fora das Ruínas de Alterac. Dentro da cidade há elites; ficar do lado de fora evita desvios e é bom para quem está sozinho."}}, supply={[1]={npc="Clarissa"}, [2]={npc="Estalajadeiro Chê"}, [3]={npc="Estalajadeiro Chê"}, [4]={npc="Keila Fuligissacra"}, [5]={npc="Antônio Nunes"}, [6]={npc="Thomas Mordan"}, [7]={npc="Ezequiel Potio"}}, steps={[1]={text="Na torre de zepelins fora de Orgrimmar, pegue o zepelim das Clareiras de Tirisfal. Depois de descer na torre ao sul de Montalvo, vá à Cidade Baixa e voe para a Serraria Tarren."}, [2]={npc="Jonas Anísio", tgt="Jonas Anísio", desc="Pegue o livro na costa sudoeste de Eira dos Montes e o manuscrito na caverna dos centauros ao sul de Mil Agulhas."}, [3]={npc="Jonas Anísio", tgt="Jonas Anísio", desc="No Pantanal, mate Dragonmaw Bonewarders ou Shadowwarders e pegue 3 varas condutoras. Leve o livro e as varas a Vila Catraca."}, [5]={text="Vincule a Pedra de Regresso na estalagem da Serraria Tarren (62.78, 19.03).", bindA="{a:272}"}, [6]={npc="Melissara", tgt="Melissara", tag="Grupo recomendado, Opcional"}, [7]={npc="Krusk", tgt="Krusk"}, [8]={npc="PROCURA-SE", npcObj=true, tag="Opcional", desc="O cartaz de PROCURA-SE também oferece esta missão (62.57, 20.66)."}, [9]={hint="Obtenha informações sobre o paradeiro de Gol'dir para Krusk na Serraria Tarren."}, [10]={hint="Mate 14 Espancadores Massacristas para Melissara na Serraria Tarren.", tag="Grupo recomendado, Opcional", desc="Forme um grupo antes de enfrentar os Crushridge Maulers de elite e de entrar nas Ruínas de Alterac."}, [11]={npc="Krusk", tgt="Krusk"}, [12]={npc="Melissara", tgt="Melissara", tag="Grupo recomendado, Opcional"}, [13]={npc="Melissara", tgt="Melissara", tag="Grupo recomendado, Opcional"}, [14]={npc="Krusk", tgt="Krusk"}, [15]={hint="Liberte Gol'dir e fale novamente com Krusk na Serraria Tarren."}, [16]={hint="Mate o Barão Vardus e entregue a cabeça dele para a Alta-executora Darthalia na Serraria Tarren.", tag="Opcional", desc="Vardus pode aparecer em acampamentos diferentes da Camarilha: procure primeiro perto de Gol'dir e depois nos acampamentos mais ao norte."}, [17]={npc="Gol'dir", tgt="Gol'dir"}, [18]={npc="Gol'dir", tgt="Gol'dir"}, [19]={hint="Leve as informações reunidas por Gol'dir para Krusk na Serraria Tarren."}, [20]={npc="Krusk", tgt="Krusk"}, [21]={npc="Alta-executora Darthalia", tgt="Alta-executora Darthalia", tag="Opcional"}, [22]={hint="Mate Targ, Revirestrume e Glommus e leve a cabeça deles para Melissara na Serraria Tarren.", tag="Grupo recomendado, Opcional"}, [23]={npc="Melissara", tgt="Melissara", tag="Grupo recomendado, Opcional"}, [24]={npc="Melissara", tgt="Melissara", tag="Grupo recomendado, Opcional"}, [25]={hint="Mate Mug'Thol, e leve a cabeça dele com a Coroa da Vontade para Melissara na Serraria Tarren.", tag="Grupo recomendado, Opcional"}, [26]={npc="Melissara", tgt="Melissara", tag="Grupo recomendado, Opcional"}, [27]={npc="Melissara", tgt="Melissara", tag="Opcional"}, [28]={npc="Sharlindra", tgt="Sharlindra", tag="Opcional"}, [29]={npc="Mirokos Formassilente", tgt="Mirokos Formassilente", tag="Opcional", desc="Pode ser aceita a partir do nível 24; nível da missão 36. Aproveite esta viagem a Alterac."}, [30]={hint="Furte o Relatório de Patrulha de Bartolo. Depois, leve o relatório a Mirokos Formassilente na Mansão de Corvoforte.", tag="Opcional, Alvo: Barton", desc="Pode ser aceita a partir do nível 24; nível da missão 36. Aproveite esta viagem a Alterac."}, [31]={npc="Mirokos Formassilente", tgt="Mirokos Formassilente", tag="Opcional", desc="Pode ser aceita a partir do nível 24; nível da missão 36. Aproveite esta viagem a Alterac."}, [32]={npc="Mirokos Formassilente", tgt="Mirokos Formassilente", tag="Opcional", desc="Saqueie o uniforme do baú. Fique disfarçado em Stromgarde para o acompanhamento."}, [33]={hint="Steal a Syndicate uniform from Northfold Manor to infiltrate Stromgarde Keep.", tag="Opcional", desc="Saqueie o uniforme do baú. Fique disfarçado em Stromgarde para o acompanhamento."}, [34]={npc="Syndicate Footlocker", npcObj=true, tag="Opcional", desc="Saqueie o uniforme do baú. Fique disfarçado em Stromgarde para o acompanhamento."}, [35]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Leve a nota de Urzal dos Tuscos. Só entregue a Rau Corta Montes (46.14, 51.71) se o diário ainda apontar para Aldeia Vento Livre."}, [36]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Depois de Auxílio elemental, consulte Bath'rah. Se entregou a etapa anterior em Aldeia Vento Livre, pode pegar esta direto com Rau."}, [37]={hint="Encontre Pradosa Fita Nuvens em Mil Agulhas.", tag="Opcional", desc="Aceite após Auxílio elemental."}, [38]={npc="Pradosa Fita Nuvens", tgt="Pradosa Fita Nuvens", tag="Opcional", desc="Aceite após Auxílio elemental."}, [39]={npc="Pradosa Fita Nuvens", tgt="Pradosa Fita Nuvens", tag="Opcional", desc="Se Bath'rah já oferecer esta missão, aceite. O fogo dá para pegar de passagem em Ermos e a terra no Pântano das Mágoas; os totens de Desolação e do Pântano Vadeoso exigem voltar depois."}, [40]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Só aceite se Bath'rah oferecer esta missão secundária; dá para fazer separado do nivelamento principal."}, [41]={hint="Return to Rau Cliffrunner in Thousand Needles at Freewind Post.", tag="Opcional", desc="Só aceite se Bath'rah oferecer esta missão secundária; dá para fazer separado do nivelamento principal."}, [42]={npc="Rau Corta Montes", tgt="Rau Corta Montes", tag="Opcional", desc="Só aceite se Bath'rah oferecer esta missão secundária; dá para fazer separado do nivelamento principal."}, [43]={text="Depois do acampamento da Camarilha, vá ao Planalto Arathi."}}},
    ["03-23"] = {name="Planalto Arathi", nameA="Planalto Arathi: {a:321}", tips={{k="取捨", text="Faça juntas, na visita de retorno, as missões avançadas dos Boulderfist, dos raptores e da Camarilha. Se nunca fez a versão de nível baixo, pule as continuações de mesmo nome. Passe pelas pedras de Pedras de união na volta pelo circuito e deixe Fozruk (Quebrando a pedra-chave) para quando tiver grupo."}, {k="取捨", text="Na Enseada de Faldir, aceite de uma vez Salvamento, Tesouro Submerso e A Vingança do Capitão. Depois de concluir os pré-requisitos na enseada e pegar os óculos de caçador de tesouros, mergulhe para o salvamento e faça de passagem Resgate no mar profundo/Afogando as mágoas debaixo d'água. Guarde para entregar quando voltar ao porto a continuação que leva a Angra do Butim."}, {k="取捨", text="Faça Stromgarde se sobrar fôlego. Para poupar deslocamentos, faça primeiro os cristais e os arredores da Ruína do Martelo; as últimas etapas de Stromgarde, Signo de Arathor-Trol'kalar, podem ser puladas."}, {k="提醒", text="Abaixo do nível 40? Mate kobolds comuns na Garganta Seca, a leste de Ruína do Martelo (cerca de 84, 31). Quando ficarem cinzas, passe para os trolls Cascasseca comuns nos arredores da aldeia (cerca de 68, 69).", s={{"Abaixo do nível 40?"}, {"Mate kobolds comuns na Garganta Seca, a leste de Ruína do Martelo (cerca de 84, 31)"}, {"Quando ficarem cinzas, passe para os trolls Cascasseca comuns nos arredores da aldeia (cerca de 68, 69)"}}}}, danger={[1]="Os guardas de Stromgarde se reúnem nos portões. Puxe-os separadamente antes de entregar a corrente do sigilo e não ataque dois grupos de dentro de uma casa.", [2]="Há criaturas subaquáticas nos destroços da Enseada de Faldir. Equipe os óculos de caça-tesouros e fique de olho no fôlego antes de entrar."}, grind={[1]={mob="Topógrafo Bigodesseco", note="Densidade moderada de mobs normais nas profundezas de Garganta Seca, a leste de Ruína do Martelo. Limpe a caverna estreita em etapas. Fique atento ao raro Geomante Adaga-de-sílex."}, [2]={mob="Escavador Bigodesseco", note="Mobs normais densos nos túneis da Garganta Seca, misturados com garimpeiros. Dá para combinar com a missão do cristal; cuidado com os reaparecimentos ao voltar pela caverna."}, [3]={mob="Exilado Vagalhante", note="Elementais da água comuns e densos a noroeste de Ruína do Martelo. São de nível um pouco acima dos kobolds e servem até o nível 40. Dá para coletar os amuletos elementais da missão Arma do redemoinho na mesma passada (apenas guerreiros)."}}, supply={[1]={npc="Urda"}, [2]={npc="Estalajadeiro Adegra"}, [3]={npc="Mu'uta"}, [4]={npc="Estalajadeiro Adegra"}, [5]={npc="Graud"}}, steps={[1]={text="Se começar pelo acampamento da Camarilha, siga a leste pela Muralha de Thoradin e continue a leste pela estrada principal. Primeiro vá a 62.50, 33.73 para aceitar A Princesa Aprisionada e depois entre na Ruína do Martelo. Se já voltou à Serraria Tarren ou à Cidade Baixa e desbloqueou a Ruína do Martelo, voe direto para a Ruína do Martelo e depois volte para A Princesa Aprisionada."}, [2]={npc="Estilhaços de Myzrael", npcObj=true}, [3]={npc="Tor'gan", tgt="Tor'gan"}, [4]={npc="Drum Fel", tgt="Drum Fel"}, [5]={npc="Tor'gan", tgt="Tor'gan", tag="Grupo recomendado, Opcional"}, [6]={hint="Viaje até Ruína do Martelo, no Planalto Arathi, e fale com Zengu."}, [7]={npc="Zengu", tgt="Zengu"}, [8]={npc="Zengu", tgt="Zengu", tag="Grupo recomendado, Opcional"}, [9]={hint="Colete 12 Grânulos of Myzrael, depois leve-os até os Fragmentos Iridescentes, em Garganta Seca.", desc="Os kobolds Bigodesseco na encosta fora da caverna e dentro dela soltam o item. A chance é baixa e eles fogem; conte com cerca de 30 mortes. Os magos de gelo batem forte. Lute com os últimos no fundo da caverna e entregue assim que tiver tudo. Local: A trilha da montanha fica escondida atrás das pedras grandes e árvores por volta de 80, 40, a leste da Ruína do Martelo. Siga a leste e depois vire ao norte; a entrada da caverna fica em 82.3, 36.7."}, [10]={npc="Fragmentos Iridescentes", npcObj=true, desc="Local: Na caverna, siga pelo caminho da esquerda e contorne até a plataforma no fundo; o cristal rosa é o ponto de entrega."}, [11]={npc="Fragmentos Iridescentes", npcObj=true, tag="Opcional"}, [12]={hint="Consiga 12 Corações de Raptores dos Fareja-carne do Planalto para Tor'gan."}, [13]={hint="Mate 10 Brutamontes Punho de Pedra e 4 Magi Punho de Pedra. Depois, fale novamente com Drum Fel no posto avançado Ruína do Martelo."}, [14]={hint="Obtenha a Pedra-sangrenta de Marez Capucho e entregue-a a Tor'gan na Ruína do Martelo.", tag="Grupo recomendado, Opcional"}, [15]={npc="Tor'gan", tgt="Tor'gan"}, [16]={npc="Drum Fel", tgt="Drum Fel"}, [17]={npc="Tor'gan", tgt="Tor'gan", tag="Grupo recomendado, Opcional"}, [18]={npc="Tor'gan", tgt="Tor'gan"}, [19]={npc="Gor'mul", tgt="Gor'mul"}, [20]={npc="Gor'mul", tgt="Gor'mul"}, [21]={npc="Tor'gan", tgt="Tor'gan"}, [22]={npc="Drum Fel", tgt="Drum Fel", tag="Grupo recomendado, Opcional", desc="Os alvos são ogros Punho de Pedra elite de nível 38-40; procure um grupo antes de fazer."}, [23]={npc="Korin Fel", tgt="Korin Fel", tag="Grupo recomendado, Opcional"}, [24]={hint="Mate 15 Xamãs Punho de Pedra e 10 Senhores dos Punho de Pedra e fale novamente com Drum Fel no posto avançado Ruína do Martelo.", tag="Grupo recomendado, Opcional"}, [25]={hint="Mate Or'Kalar e leve a cabeça dele para Korin Fel no posto avançado Ruína do Martelo.", tag="Grupo recomendado, Opcional"}, [26]={npc="Drum Fel", tgt="Drum Fel", tag="Grupo recomendado, Opcional"}, [27]={npc="Korin Fel", tgt="Korin Fel", tag="Grupo recomendado, Opcional"}, [28]={hint="Obtenha o Signo de Strom para Zengu, em Ruína do Martelo.", tag="Grupo recomendado, Opcional"}, [29]={npc="Zengu", tgt="Zengu", tag="Grupo recomendado, Opcional"}, [30]={npc="Zengu", tgt="Zengu", tag="Grupo recomendado, Opcional"}, [31]={hint="Recupere os 11 Fragmentos de Signo dos defensores de Stromgarde e leve para Tor'gan, em Ruína do Martelo.", tag="Grupo recomendado, Opcional"}, [32]={npc="Tor'gan", tgt="Tor'gan", tag="Grupo recomendado, Opcional"}, [33]={npc="Tor'gan", tgt="Tor'gan"}, [34]={npc="Zengu", tgt="Zengu"}, [35]={hint="Consiga a Chave Ardente, a Chave Troante e a Chave Trovejante nas Pedras da União Ocidental, da União Oriental e de União Exterior.", tag="Opcional"}, [36]={text="Nos arredores do Círculo de União Ocidental, no oeste do Planalto Arathi, mate Exilados em Chamas e colete 2 Carvões Fumegantes (25.61, 30.40).", tag="Opcional"}, [37]={npc="Pedra de Vínculo Interior", npcObj=true, tag="Opcional"}, [38]={npc="Pedra de Vínculo Interior", npcObj=true, tag="Grupo recomendado, Opcional"}, [39]={hint="Encontre e mate Fozruk. Leve o Bastão de Ordem para a Pedra-chave, no Planalto Arathi.", tag="Grupo recomendado, Opcional"}, [40]={npc="Pedra-chave", npcObj=true, tag="Grupo recomendado, Opcional"}, [41]={npc="Pedra-chave", npcObj=true, tag="Opcional"}, [42]={npc="Zaruk", tgt="Zaruk", tag="Opcional"}, [43]={npc="Zaruk", tgt="Zaruk", tag="Opcional", desc="Depois de entregar Aliados de Myzrael em Ruína do Martelo, a Horda aceita a continuação com Zaruk; guarde-a para os Ermos."}, [44]={text="Enseada de Faldir"}, [45]={npc="Lolo, o Olheiro", tgt="Lolo, o Olheiro"}, [46]={npc="Juanka Nabrava", tgt="Juanka Nabrava"}, [47]={npc="Professor Bruzundanga", tgt="Professor Bruzundanga"}, [48]={hint="Escolte o Professor Bruzundanga até a caverna e retorne com ele.", desc="Limpe ao redor do professor. Acompanhe-o até a caverna e depois volte para a Enseada de Faldir."}, [49]={npc="Doutor Medeixo", tgt="Doutor Medeixo"}, [50]={npc="Primeiro Oficial Nadaliso", tgt="Primeiro Oficial Nadaliso"}, [51]={npc="Capitão Tripaço", tgt="Capitão Tripaço"}, [52]={npc="Doutor Medeixo", tgt="Doutor Medeixo"}, [53]={hint="O Primeiro Oficial Nadaliso quer que você recupere as Cartas Náuticas e Diários de Bordo do Extravagância da Donzela e do Espírito de Pinhaprata."}, [54]={hint="O Capitão Tripaço, na Enseada de Faldir, quer que você mate 10 Saqueadores Espinhadaga e 3 Feiticeiras Espinhadaga."}, [55]={hint="O Doutor Medeixo na Enseada de Faldir quer que você consiga 10 Gemas Élficas e devolva os Óculos para Caçar Gemas quando tiver terminado.", desc="Aceite Tesouro submerso para pegar os óculos de caçador de tesouros e use-os para achar as joias submersas. Faça Resgate no mar profundo e Afogando as mágoas na mesma volta."}, [56]={npc="Primeiro Oficial Nadaliso", tgt="Primeiro Oficial Nadaliso"}, [57]={npc="Capitão Tripaço", tgt="Capitão Tripaço"}, [58]={npc="Doutor Medeixo", tgt="Doutor Medeixo"}, [59]={npc="Doutor Medeixo", tgt="Doutor Medeixo"}, [60]={npc="Juanka Nabrava", tgt="Juanka Nabrava"}, [61]={text="Do extremo sul do Planalto Arathi, atravesse a Ponte Thandol para entrar no Pantanal e siga para o leste até as montanhas onde circulam os Guarda-ossos Presa do Dragão."}, [62]={hint="Leve o Tomo Reformado e 3 Bastões de Canalização para Strahad Farsan na Vila Catraca.", desc="No Pantanal, mate Dragonmaw Bonewarders ou Shadowwarders e pegue 3 varas condutoras. Leve o livro e as varas a Vila Catraca."}, [63]={text="Volte do Pantanal para Ruína do Martelo."}, [64]={npc="Juanka Nabrava", tgt="Juanka Nabrava"}, [65]={npc="Tor'gan", tgt="Tor'gan"}, [66]={npc="Caldeirão de Bath'rah", npcObj=true, tag="Opcional", desc="Dá para comprar os amuletos na casa de leilões. O caldeirão é o mesmo ponto para aceitar e entregar a missão."}, [67]={hint="Saque de: Kobold Bigodesseco, Topógrafo Bigodesseco, Escavador Bigodesseco", tag="Opcional", desc="Dá para comprar os amuletos na casa de leilões. O caldeirão é o mesmo ponto para aceitar e entregar a missão."}, [68]={npc="Caldeirão de Bath'rah", npcObj=true, tag="Opcional", desc="Dá para comprar os amuletos na casa de leilões. O caldeirão é o mesmo ponto para aceitar e entregar a missão."}, [69]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional"}, [70]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Missão de elite de nível 40. Agrupe-se antes de acioná-lo."}, [71]={hint="Leve o Coração Rodopiante para Bath'rah, o Vigia dos Ventos.", tag="Opcional", desc="Missão de elite de nível 40. Agrupe-se antes de acioná-lo."}, [72]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Missão de elite de nível 40. Agrupe-se antes de acioná-lo."}, [73]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", star={"Machado Redemoinho / Espada Redemoinho / Martelo de Guerra Redemoinho"}}, [74]={hint="Complete os objetivos da missão.", tag="Opcional"}, [75]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", star={"Machado Redemoinho / Espada Redemoinho / Martelo de Guerra Redemoinho"}}, [76]={npc="Syndicate Footlocker", npcObj=true, tag="Opcional", desc="Vista o uniforme antes de entrar. Evite o combate para manter seu disfarce."}, [77]={hint="Enquanto estiver com o disfarce de membro da Camarilha, encontre alguém na Bastilha de Stromgarde que saiba sobre o acordo secreto.", tag="Opcional", desc="Vista o uniforme antes de entrar. Evite o combate para manter seu disfarce."}, [78]={npc="Anastasia Miller", tgt="Anastasia Miller", tag="Opcional", desc="Vista o uniforme antes de entrar. Evite o combate para manter seu disfarce."}, [79]={npc="Anastasia Miller", tgt="Anastasia Miller", tag="Opcional"}, [80]={hint="Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal.", tag="Opcional", desc="Procure o Anastasia's Stash no segundo andar de uma casa ao lado de Stromgarde."}, [81]={npc="Anastasia Miller", tgt="Anastasia Miller", tag="Opcional"}, [82]={npc="Anastasia Miller", tgt="Anastasia Miller", tag="Opcional", desc="Dois guardas vigiam a carga."}, [83]={hint="Break up the secret deal, and take the object being traded to the Syndicate. Then, return to Myrokos Silentform at Ravenholdt Manor.", tag="Opcional", desc="Dois guardas vigiam a carga."}, [84]={npc="Mirokos Formassilente", tgt="Mirokos Formassilente", tag="Opcional", desc="Dois guardas vigiam a carga."}}},
    ["05-d17"] = {name="Urzal dos Mortos", entrance="Sertões (1413), por volta de 49.10, 93.40 (portal no fundo do túnel de espinhos)", pickup="Ao sair da Ruína do Martelo, no Planalto Arathi, voe primeiro para a Cidade Baixa. Ao chegar à Chapada Cintilante, em Mil Agulhas, dá para fazer antes Urzal dos Tuscos e pegar Uma aliança profana. Se estiver na etapa das Montanhas de Alterac até o Planalto Arathi e passar pela Cidade Baixa, entregue primeiro a Varimatras e depois procure André Rosado na mesma cidade para aceitar Arauto do fim. Pegue o zepelim de Tirisfal de volta a Orgrimmar e voe para o Penhasco do Trovão. Se não estiver desbloqueado, voe para o Acampamento Taurajo e siga a estrada de Mulgore. Vá ao noroeste de Mulgore, procure Sutara Espreitaprados e aceite O Olho do Frigífero. Voe para o Acampamento Taurajo e vá ao sul; procure Mírian Lunacanto fora do portão. Os membros do grupo que já estiverem em Sendas do Rio pegam o barco do Porto Detonapavio para o Porto de Bondebico e seguem ao norte. Depois da masmorra, se estiver em Kalimdor, voe para Geringontzan e pegue o barco do Porto de Bondebico para Sendas do Rio. Se Geringontzan não estiver desbloqueada, siga o primeiro passo da primeira visita a Rog'mar, em Sendas do Rio: voe para Aldeia Vento Livre e siga pela encosta sul da Chapada Cintilante. Se precisar voltar antes à Cidade Baixa para entregar Arauto do fim e Uma aliança profana, siga o mesmo primeiro passo a partir da Cidade Baixa.", pickupS={{"Ao sair da Ruína do Martelo, no Planalto Arathi, voe primeiro para a Cidade Baixa"}, {"Ao chegar à Chapada Cintilante, em Mil Agulhas, dá para fazer antes Urzal dos Tuscos e pegar Uma aliança profana"}, {"Se estiver na etapa das Montanhas de Alterac até o Planalto Arathi e passar pela Cidade Baixa, entregue primeiro a Varimatras e depois procure André Rosado na mesma cidade para aceitar Arauto do fim"}, {"Pegue o zepelim de Tirisfal de volta a Orgrimmar e voe para o Penhasco do Trovão"}, {"Se não estiver desbloqueado, voe para o Acampamento Taurajo e siga a estrada de Mulgore"}, {"Vá ao noroeste de Mulgore, procure Sutara Espreitaprados e aceite O Olho do Frigífero"}, {"Voe para o Acampamento Taurajo e vá ao sul; procure Mírian Lunacanto fora do portão"}, {"Os membros do grupo que já estiverem em Sendas do Rio pegam o barco do Porto Detonapavio para o Porto de Bondebico e seguem ao norte"}, {"Depois da masmorra, se estiver em Kalimdor, voe para Geringontzan e pegue o barco do Porto de Bondebico para Sendas do Rio"}, {"Se Geringontzan não estiver desbloqueada, siga o primeiro passo da primeira visita a Rog'mar, em Sendas do Rio: voe para Aldeia Vento Livre e siga pela encosta sul da Chapada Cintilante"}, {"Se precisar voltar antes à Cidade Baixa para entregar Arauto do fim e Uma aliança profana, siga o mesmo primeiro passo a partir da Cidade Baixa"}}, tips={{k="動線", text="Limpe a entrada até a cela de Belnistrasz, perto de Mordresh Olho-de-Fogo → troque o juramento com Belnistrasz e escolte-o até o ídolo, podendo encontrar Pragorja, o Podre, no caminho → suba a rampa em espiral até Amnennar e procure o Olho do Frigífero na mesma área."}, {k="取捨", text="Execute a masmorra completa com um grupo de nível 40+. Mate o chefe final de O Olho do Frigífero e Arauto do fim. Aos 34, pegue a missão do globo ocular e faça A hoste do mal do lado de fora se estiver passando."}, {k="說明", text="Masmorra para cinco jogadores. Não precisa de chave. A entrada fica pela estrada leste, ao norte do Grande Elevador, diferente de Urzal dos Tuscos, a oeste. Se já estiver em Sendas do Rio, pegue o barco de Porto Detonapavio para Porto de Bondebico e siga para o norte.", s={{"Masmorra para cinco jogadores"}, {"Não precisa de chave"}, {"A entrada fica pela estrada leste, ao norte do Grande Elevador, diferente de Urzal dos Tuscos, a oeste"}, {"Se já estiver em Sendas do Rio, pegue o barco de Porto Detonapavio para Porto de Bondebico e siga para o norte"}}}, {k="提醒", text="Masmorra para cinco jogadores. Não precisa de chave. A entrada fica pela estrada leste, ao norte do Grande Elevador, diferente de Urzal dos Tuscos, a oeste. Se já estiver em Sendas do Rio, pegue o barco de Porto Detonapavio para Porto de Bondebico e siga para o norte.", s={{"Masmorra para cinco jogadores"}, {"Não precisa de chave"}, {"A entrada fica pela estrada leste, ao norte do Grande Elevador, diferente de Urzal dos Tuscos, a oeste"}, {"Se já estiver em Sendas do Rio, pegue o barco de Porto Detonapavio para Porto de Bondebico e siga para o norte"}}}}, steps={[1]={npc="Pergaminho Pequeno", npcObj=true, desc="Pule se você já saqueou o Pergaminho Pequeno de Charlga em Urzal dos Tuscos."}, [2]={npc="Varimatras", tgt="Varimatras"}, [3]={npc="Varimatras", tgt="Varimatras", desc="Depois de entregar Uma aliança profana, pegue esta com o mesmo NPC. Os alvos ficam no túnel de espinhos fora da entrada de Urzal dos Mortos.", preText="Uma aliança profana"}, [4]={npc="André Rosado", tgt="André Rosado", desc="Aceite no nível 37 no Distrito da Magia de Cidade Baixa."}, [5]={npc="Sutara Espreitaprados", tgt="Sutara Espreitaprados", desc="Missão nova no Forever."}, [6]={npc="Mírian Lunacanto", tgt="Mírian Lunacanto", desc="Myriam fica fora do portal, no extremo sul dos Sertões (49.01, 94.94). Pegue a missão e limpe os arredores antes de entrar."}, [7]={hint="Leve a cabeça do Embaixador Malcin para Varimatras, na Cidade Baixa."}, [8]={hint="Mate 8 Guerreiros do Urzal, 8 Tecespinhos do Urzal e 8 Sectários da Cabeça da Morte, depois fale novamente com Mírian Lunacanto perto da entrada do Urzal dos Mortos."}, [9]={npc="Mírian Lunacanto", tgt="Mírian Lunacanto"}, [10]={text="Entrada: Urzal dos Mortos"}, [11]={npc="Belnistrasz", tgt="Belnistrasz", desc="Encontre Belnistrasz nas celas. Todos devem concluir o diálogo do juramento antes de iniciar a escolta."}, [12]={hint="Se você concordar em ajudar Belnistrasz, fale novamente com ele e devolva a pedra de juramento que ele lhe deu.", desc="Local: Vá até a cela perto de Mordresh Olho de Fogo e procure Belnistrasz. Ordem: O grupo todo entrega primeiro na Pedra do Juramento e depois pega a escolta.", spot="Encontre Belnistrasz nas células próximas a Mordresh Olho-de-Fogo."}, [13]={npc="Belnistrasz", tgt="Belnistrasz", spot="Cela perto de Mordresh Olho de Fogo: Belnistrasz"}, [14]={npc="Belnistrasz", tgt="Belnistrasz", desc="Espere por todo o grupo antes de começar e fique perto do NPC.", preText="O Flagelo do Urzal"}, [15]={hint="Escolte Belnistrasz até o ídolo dos javatuscos no Urzal dos Mortos.", desc="Local: Escolte Belnistrasz de sua cela até o ídolo e proteja-o.", spot="Escolte Belnistrasz de sua cela até o ídolo e proteja-o."}, [16]={npc="Braseiro de Belnistrasz", npcObj=true, spot="Ao lado da estátua, o braseiro de Benistrasz."}, [17]={hint="André Rosado quer que você mate Amnennar, o Frigífero, e volte com a cabeça dele.", desc="Local: Saia das celas e pegue a rampa em espiral até Amnennar.", spot="Saia das celas e pegue a rampa em espiral até Amnennar."}, [18]={hint="Recover The Coldbringer's Eye from Razorfen Downs.", desc="Local: Entre no covil de Amnennar e procure o Olho do Frigífero. Ordem: Mesma área da etapa \"Arauto do fim\".", spot="Entre no covil de Amnennar e encontre o Olho do Frigífero."}, [19]={npc="Sutara Espreitaprados", tgt="Sutara Espreitaprados"}, [20]={npc="André Rosado", tgt="André Rosado"}, [21]={npc="Varimatras", tgt="Varimatras"}}},
    ["03-24"] = {tips={{k="取捨", text="Na primeira visita, limpe a fazenda, os gnolls, a margem do rio e as feras ao redor de Rog'mar e termine com a rota norte até Bolder'ok. Chogg'Zac é de elite: mate-o com grupo. A entrega da cabeça e as missões seguintes de Clugfist só abrem depois disso. Deixe Mortalha do Crepúsculo e a costa para a segunda visita."}, {k="取捨", text="Desbloqueie nesta parada o ponto de voo de Rog'mar; isso poupa caminhada de ida e volta a Karrath ou Pedregal. Você pode reabastecer com o estalajadeiro Toka."}, {k="提醒", text="Se ainda não estiver no nível 41 depois de entregar as missões desta parada, mate javalis normais ao sul da fazenda de Na'zok (70.62, 33.08) ou continue nas feras ao sul de Rog'mar (cerca de 61, 50). As missões avançadas do Crepúsculo de Bolder'ok ficam para a sua segunda visita a Sendas do Rio.", s={{"Se ainda não estiver no nível 41 depois de entregar as missões desta parada, mate javalis normais ao sul da fazenda de Na'zok (70.62, 33.08) ou continue nas feras ao sul de Rog'mar (cerca de 61, 50)"}, {"As missões avançadas do Crepúsculo de Bolder'ok ficam para a sua segunda visita a Sendas do Rio"}}}}, danger={[1]="Batedores e sacerdotes de Farholde vagam ao sul de Rog'mar. Chame batedores solitários para evitar trazer sacerdotes.", [2]="A caverna ritual do Crepúsculo em Solclaro é estreita. Limpe a entrada antes de interromper os círculos rituais. Cuidado com magos sombrios renascendo atrás de você.", [3]="O Chefe Escoteiro Vargas é elite. Espere pelo seu grupo antes de se aproximar e retire as patrulhas próximas separadamente."}, grind={[1]={mob="Urubu das Baixas Planícies", note="Gramado ao sul de Rog'mar, com muitos monstros normais. Há feras elite de nível 41-42 por perto; escolha uma de cada vez pelo caminho. Dá para pegar de passagem as penas de Feathers for Fletching."}, [2]={mob="Batedor de Ermoforte", note="Acampamento Farholde, na margem sul do rio: mobs normais em alta densidade. Cuidado para os sacerdotes não entrarem na luta junto com os outros batedores; limpe pela borda externa do rio e faça Show Them How It's Done de passagem."}, [3]={mob="Farholde Priest", note="Densidade média de lançadores de feitiços comuns na parte oeste da margem sul. Interrompa as curas e não puxe os batedores junto. Se já fez a parte oeste de Show Them How It's Done, aproveite para farmar aqui."}}, supply={[1]={npc="Grakna"}, [2]={npc="Estalajadeira Toka"}, [3]={npc="Gur'dok"}, [4]={npc="Naluk"}, [5]={npc="Maka"}, [6]={npc="Khebra"}, [7]={npc="Thultazor"}}, steps={[1]={text="Voe de Ruína do Martelo para a Cidade Baixa."}, [2]={npc="Gareno Largo", tgt="Gareno Largo", desc="Aceite a missão ao voltar à Cidade Baixa no nível 40 e vá à Bastilha de Bandarion. Alodor, o Esperançoso (25.42, 14.71) também oferece a missão."}, [3]={hint="Speak with Danitha Morr at Bandarion Keep.", desc="Aceite em Cidade Baixa no nível 40 e depois vá para Bastilha de Bandarion."}, [4]={npc="Danitha Morr", tgt="Danitha Morr", desc="Aceite em Cidade Baixa no nível 40 e depois vá para Bastilha de Bandarion."}, [5]={npc="Danitha Morr", tgt="Danitha Morr", desc="Pegue depois de Report to Danitha. Termine esta corrente antes de comprar uma montaria se quiser o Warhorse."}, [6]={hint="Speak with Danitha Morr to learn to summon your Warhorse.", desc="Pegue depois de Report to Danitha. Termine esta corrente antes de comprar uma montaria se quiser o Warhorse."}, [7]={npc="Danitha Morr", tgt="Danitha Morr", desc="Pegue depois de Report to Danitha. Termine esta corrente antes de comprar uma montaria se quiser o Warhorse."}, [8]={text="Da Bastilha de Bandarion, volte à torre de zepelins ao sul de Montalvo e pegue o zepelim para Orgrimmar."}, [9]={text="Voe de Ruína do Martelo para a Cidade Baixa, vá à torre de zepelins ao sul de Montalvo e pegue o zepelim para Orgrimmar."}, [10]={npc="Kaal Ceifalma", tgt="Kaal Ceifalma", tag="Opcional", desc="Missão introdutória da Cidade Baixa; se aceitar esta, não precisa aceitar a de Orgrimmar."}, [11]={hint="Fale com Strahad Farsan na Vila Catraca.", tag="Opcional", desc="Missão introdutória da Cidade Baixa; se aceitar esta, não precisa aceitar a de Orgrimmar."}, [12]={npc="Strahad Farsan", tgt="Strahad Farsan", tag="Opcional", desc="Missão introdutória da Cidade Baixa; se aceitar esta, não precisa aceitar a de Orgrimmar."}, [13]={npc="Zevrost", tgt="Zevrost", desc="Missão introdutória de Orgrimmar; se já entregou a da Cidade Baixa, pule."}, [14]={hint="Fale com Strahad Farsan nos Sertões.", desc="Missão introdutória de Orgrimmar; se já entregou a da Cidade Baixa, pule."}, [15]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Missão introdutória de Orgrimmar; se já entregou a da Cidade Baixa, pule."}, [16]={text="Voe de Orgrimmar para Vila Catraca."}, [17]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="No Pantanal, mate Dragonmaw Bonewarders ou Shadowwarders e pegue 3 varas condutoras. Leve o livro e as varas a Vila Catraca."}, [18]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Use Tomo do Conluio no círculo perto da torre de Vila Catraca. Mate o caçador vil."}, [19]={hint="Usando the Tomo do Conluio, evoque e subjugue um caçador vil, depois devolva o Tomo do Conluio a Strahad Farsan na Vila Catraca.", desc="Use Tomo do Conluio no círculo perto da torre de Vila Catraca. Mate o caçador vil."}, [20]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Use Tomo do Conluio no círculo perto da torre de Vila Catraca. Mate o caçador vil."}, [21]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Entregue a missão introdutória local e depois aceite a próxima com Strahad."}, [22]={hint="Fale com Strahad Farsan, na Vila Catraca, para aprender a habilidade de evocar um Corcel Vil.", desc="Entregue a missão introdutória local e depois aceite a próxima com Strahad."}, [23]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Entregue a missão introdutória local e depois aceite a próxima com Strahad."}, [24]={text="Voe de Vila Catraca para Geringontzan; se Geringontzan não estiver desbloqueado, voe para a Aldeia Vento Livre, desça pela encosta sul da Chapada Cintilante até Tanaris e retome a rota no barco para Sendas do Rio."}, [25]={text="Se já tiver Rog'mar desbloqueado, voe direto de Ruína do Martelo. Se não, vá de barco, como faz a maioria dos jogadores: voe de Ruína do Martelo para a Cidade Baixa, vá à torre de zepelins ao sul de Montalvo e pegue o zepelim para Orgrimmar; de Orgrimmar, voe para a Aldeia Vento Livre, desça pela encosta sul da Chapada Cintilante até Tanaris e desbloqueie primeiro o ponto de voo de Geringontzan (se já tiver Geringontzan, voe direto). Se já estiver em Kalimdor, vá direto para Tanaris. Se chegou a Rog'mar voando direto, pule os passos do barco em Geringontzan e em Porto Detonapavio.", tag="Antes de ir para Sendas do Rio, você pode comprar na casa de leilões (ou pedir para um alt enviar) 10 × Naco de Carne de Javali (para Paletusk Harvesting) e 10 × Contrapeso Pesado (para Step Two: More Rock)."}, [26]={npc="Estalajadeiro Gabor Bulho", tgt="Estalajadeiro Gabor Bulho", tag="Opcional", desc="Só se for de barco: pegue na estalagem de Geringontzan e entregue em Porto Detonapavio."}, [27]={text="Se ainda não abriu Rog'mar e for pela rota de barco de Porto de Bondebico: embarque em Porto de Bondebico, a leste de Geringontzan (68.60, 23.00), e desembarque no cais de Porto Detonapavio, em Sendas do Rio (80.60, 54.60). O mestre de voo de Porto Detonapavio não tem rotas."}, [28]={npc="Friz Faiscansa", tgt="Friz Faiscansa", tag="Opcional"}, [29]={npc="Friz Faiscansa", tgt="Friz Faiscansa", tag="Opcional", desc="Só pegue se chegou de barco; entregue a Krom'rosh em Rog'mar."}, [30]={text="Se chegou de barco, caminhe para oeste de Porto Detonapavio até Rog'mar.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [31]={nodeA="{a:16743}", node="Rog'mar", desc="Desbloqueie o ponto de voo com Grakna."}, [32]={text="Vincule sua Pedra de Regresso com Innkeeper Toka na estalagem de Rog'mar (57.58, 45.47).", bindA="{a:16743}"}, [33]={npc="Krom'rosh", tgt="Krom'rosh"}, [34]={npc="Tan'jani", tgt="Tan'jani"}, [35]={npc="Krom'rosh", tgt="Krom'rosh", tag="Opcional"}, [36]={npc="Krom'rosh", tgt="Krom'rosh"}, [37]={npc="Krom'rosh", tgt="Krom'rosh"}, [38]={npc="Gur'dok", tgt="Kreza Darkthorn"}, [39]={npc="Tan'jani", tgt="Tan'jani"}, [40]={npc="Neza Rinossangue", tgt="Neza Rinossangue", desc="Sem pré-requisito. Pegue primeiro e faça no mesmo trajeto de Um banquete para os abutres."}, [41]={text="Feras ao sul de Rog'mar (entrega em três viagens)"}, [42]={npc="Carcaça Recolhida", tgt="Carcaça Recolhida", desc="Clique no cadáver roído no chão entre as feras ao sul."}, [43]={hint="Bring the Gnawed Skull to Neza Bloodsnout at Rog'mar."}, [44]={hint="Saque de: Urubu das Baixas Planícies", tag="Alvo: Urubu das Baixas Planícies", desc="Lute no mesmo trajeto de Um banquete para os abutres."}, [45]={npc="Neza Rinossangue", tgt="Neza Rinossangue"}, [46]={npc="Neza Rinossangue", tgt="Neza Rinossangue"}, [47]={npc="Neza Rinossangue", tgt="Neza Rinossangue"}, [48]={npc="Neza Rinossangue", tgt="Neza Rinossangue"}, [49]={hint="Saque de: Moa Errante", tag="Alvo: Moa Errante", desc="Lute no mesmo trajeto de Poison Tips."}, [50]={hint="Saque de: Víbora da Clareira", tag="Alvo: Víbora da Clareira"}, [51]={npc="Neza Rinossangue", tgt="Neza Rinossangue"}, [52]={npc="Neza Rinossangue", tgt="Neza Rinossangue"}, [53]={npc="Neza Rinossangue", tgt="Neza Rinossangue"}, [54]={npc="Neza Rinossangue", tgt="Neza Rinossangue", tag="Opcional, Grupo recomendado"}, [55]={hint="Saque de: Patriarca Campobravo, Caçadora Campobravo", tag="Alvo: Patriarca Campobravo/Caçadora Campobravo"}, [56]={hint="Saque de: Ombassa", tag="Opcional, Alvo: Ombassa, Grupo recomendado", desc="Agrupe-se e use o item de missão para convocar Ombassa, uma elite de nível 41."}, [57]={npc="Neza Rinossangue", tgt="Neza Rinossangue"}, [58]={npc="Neza Rinossangue", tgt="Neza Rinossangue", tag="Opcional, Grupo recomendado"}, [59]={npc="Neza Rinossangue", tgt="Neza Rinossangue"}, [60]={npc="Gur'dok", tgt="Kreza Darkthorn"}, [61]={npc="Neza Rinossangue", tgt="Neza Rinossangue", tag="Grupo recomendado, Opcional", desc="Snargl é uma elite de nível 40 numa caverna; se for instável sozinho, não aceite.", star={"Golpeador Rinossangue", {"WARRIOR", "PALADIN"}}}, [62]={text="Circuito sudoeste: Serraria dos Turner → gnolls de Colinas Cerdosas → Fazenda Arroio dos Prados"}, [63]={hint="Saque de: Lenhador da Serraria dos Turner", tag="Alvo: Lenhador da Serraria dos Turner"}, [64]={hint="Collect Wood Bundles from Peasant Woodpiles in Turner's Logging Camp then fletch them into 20 Makeshift Stickin' Spears."}, [65]={hint="Matar: Místico de Cristarrubra, Coureador de Cristarrubra, Brutamontes de Cristarrubra", tag="Alvo: Místico de Cristarrubra / Caçador Redridge / Brutamontes de Cristarrubra"}, [66]={hint="Saque de: Brutamontes de Cristarrubra, Místico de Cristarrubra, Coureador de Cristarrubra", tag="Alvo: Brutamontes de Cristarrubra / Místico de Cristarrubra / Caçador Redridge"}, [67]={hint="Saque de: Snargl", tag="Grupo recomendado, Opcional, Alvo: Snargl"}, [68]={hint="Matar: Lavrador de Arroio dos Prados", tag="Alvo: Arroio dos Prados Agricultor", desc="Depois dos gnolls, vá para o sudeste até a Fazenda Arroio dos Prados e volte a Rog'mar uma única vez para entregar tudo."}, [69]={hint="Steal 6 Feed Satchels from the Alliance farm in Meadowsbrook then return to Krom'rosh."}, [70]={npc="Krom'rosh", tgt="Krom'rosh"}, [71]={npc="Krom'rosh", tgt="Krom'rosh"}, [72]={npc="Gur'dok", tgt="Kreza Darkthorn"}, [73]={npc="Gur'dok", tgt="Kreza Darkthorn", desc="Aceite depois de entregar Borrowed Blades. Guarde a espada para entregar a Friz em Porto Detonapavio, em Sendas do Rio."}, [74]={npc="Tan'jani", tgt="Tan'jani"}, [75]={npc="Tan'jani", tgt="Tan'jani"}, [76]={npc="Neza Rinossangue", tgt="Neza Rinossangue"}, [77]={npc="Gur'dok", tgt="Kreza Darkthorn"}, [78]={npc="Neza Rinossangue", tgt="Neza Rinossangue", tag="Grupo recomendado, Opcional", star={"Golpeador Rinossangue", {"WARRIOR", "PALADIN"}}}, [79]={npc="Krom'rosh", tgt="Krom'rosh"}, [80]={npc="Gorg", tgt="Gorg"}, [81]={npc="Gorg", tgt="Gorg"}, [82]={hint="Matar: Aprendiz de Rog'mar", tag="Alvo: Estagiário Rog'mar"}, [83]={npc="Gorg", tgt="Gorg"}, [84]={npc="Krom'rosh", tgt="Krom'rosh"}, [85]={text="Acampamento Farholde; mate crocoliscos na volta"}, [86]={hint="Matar: Farholde Priest, Batedor de Ermoforte", tag="Alvo: Farholde Sacerdote / Escoteiro Farholde"}, [87]={hint="Matar: Crocolisco de Água Doce", tag="Alvo: Crocolisco de Água Doce", desc="Lute no caminho de volta pelo rio, do Acampamento Farholde até Rog'mar."}, [88]={npc="Krom'rosh", tgt="Krom'rosh"}, [89]={npc="Tan'jani", tgt="Tan'jani"}, [90]={npc="Tran'gul", tgt="Tran'gul"}, [91]={npc="Tran'gul", tgt="Tran'gul"}, [92]={text="Solclaro"}, [93]={npc="Lanocinho", tgt="Lanocinho"}, [94]={hint="Matar: Saqueador do Crepúsculo, Sombramante do Crepúsculo, Neófito do Crepúsculo", tag="Alvo: Saqueador do Crepúsculo/Sombramante do Crepúsculo/Neófito do Crepúsculo"}, [95]={hint="Saque de: Sombramante do Crepúsculo", tag="Alvo: Sombramante do Crepúsculo"}, [96]={hint="Leve 20 Ossos de Dedo do Crepúsculo para Lanocinho."}, [97]={npc="Lanocinho", tgt="Lanocinho"}, [98]={npc="Lanocinho", tgt="Lanocinho", desc="Siga Lanocinho enquanto ele foge; no final ele se volta contra você com 2 gnolls; derrote-os e depois abra o tesouro."}, [99]={npc="Tesouro de Ziguim", npcObj=true, desc="O Tesouro de Ziguim fica a cerca de 6 quadrados a oeste de Solclaro."}, [100]={npc="Tran'gul", tgt="Tran'gul"}, [101]={npc="Tran'gul", tgt="Tran'gul"}, [102]={npc="Tran'gul", tgt="Tran'gul"}, [103]={hint="Convince a Twilight's Hammer miner in Sunnyglade to divulge their secrets."}, [104]={npc="Porreto", tgt="Porreto"}, [105]={npc="Porreto", tgt="Porreto"}, [106]={hint="Find missing ogres in the caves beneath Sunnyglade for Clubtoe."}, [107]={npc="Brutamontes Potencializado", tgt="Brutamontes do Crepúsculo"}, [108]={npc="Brutamontes Potencializado", tgt="Brutamontes do Crepúsculo"}, [109]={npc="Porreto", tgt="Porreto"}, [110]={hint="Matar: Brutamontes Potencializado, Ritualista do Crepúsculo", tag="Alvo: Brutamontes Potencializado/Ritualista do Crepúsculo"}, [111]={hint="Destroy 5 Twilight Ritual Circles found throughout the caves underneath Sunnyglade."}, [112]={npc="Porreto", tgt="Porreto"}, [113]={npc="Porreto", tgt="Porreto"}, [114]={npc="Porreto", tgt="Porreto", tag="Grupo recomendado, Opcional", desc="É preciso matar antes Chogg'Zac (Twilight No More!), elite de nível 41, para poder pegar a continuação."}, [115]={hint="Saque de: Chogg'Zac", tag="Grupo recomendado, Opcional, Alvo: Chogg'Zac", desc="Chogg'Zac fica numa caverna de Solclaro e é um elite de nível 41."}, [116]={npc="Porreto", tgt="Porreto", tag="Grupo recomendado, Opcional"}, [117]={npc="Porreto", tgt="Porreto"}, [118]={hint="Deliver the head of Chogg to Tran'gul in Rog'mar."}, [119]={npc="Tran'gul", tgt="Tran'gul"}, [120]={npc="Tran'gul", tgt="Tran'gul", desc="Leve a cabeça para Bolder'ok, ao norte. Entregue durante a rota norte."}, [121]={npc="Procura-se", npcObj=true, tag="Grupo recomendado, Opcional", desc="Elite; patrulha a área dos javalis da rota norte (cerca de 69-76, 34-38). Só pegue com grupo."}, [122]={text="Rota norte: Sleebo → Fazenda de Na'zok → Bolder'ok"}, [123]={npc="Sleebo Cospetardo", tgt="Sleebo Cospetardo", desc="De Rog'mar vá para leste, passe primeiro por Sli'bo e depois suba ao norte até a fazenda de Na'zok."}, [124]={hint="Colete 5 Ampolas de Gás do Pântano para Sleebo Cospetardo.", desc="Colete o gás nos respiradouros do pântano perto de Sli'bo."}, [125]={npc="Sleebo Cospetardo", tgt="Sleebo Cospetardo"}, [126]={npc="Sleebo Cospetardo", tgt="Sleebo Cospetardo"}, [127]={hint="Ajude Sleebo a testar sua criação."}, [128]={npc="Sleebo Cospetardo", tgt="Sleebo Cospetardo"}, [129]={npc="Na'zok", tgt="Na'zok", desc="Naco de Carne de Javali pode ser comprado na casa de leilões. Com 10, não precisa farmar."}, [130]={npc="Na'zok", tgt="Na'zok"}, [131]={hint="Saque de: Scoutmaster Vargas", tag="Grupo recomendado, Opcional, Alvo: Chefe Escoteiro Vargas / Escoteiro Reynolds", desc="O Chefe Escoteiro Vargas é elite: forme um grupo primeiro. Depois traga as provas de volta a Rog'mar."}, [132]={hint="Saque de: Javali Pedratusco, Fuçalonga, Goretusco"}, [133]={hint="Matar: Palitusco Jovem", tag="Alvo: Palitusco Jovem", desc="Use o item de missão em javalis jovens para conduzi-los de volta à fazenda."}, [134]={npc="Na'zok", tgt="Na'zok"}, [135]={npc="Na'zok", tgt="Na'zok"}, [136]={hint="Deliver Chogg's head to the ogre city to the north."}, [137]={npc="Clugfist", tgt="Clugfist"}, [138]={npc="Clugfist", tgt="Clugfist"}, [139]={npc="Clugfist", tgt="Clugfist"}, [140]={hint="Matar: Espancador do Crepúsculo, Arauto das Chamas do Crepúsculo", tag="Alvo: Espancador do Crepúsculo/Arauto das Chamas do Crepúsculo"}, [141]={hint="Saque de: Klunk", tag="Alvo: Klunk"}, [142]={npc="Jom-jom", tgt="Jom-jom", desc="Sem pré-requisito, a cerca de 4 quadrados de Na'zok. Escolte até Bolder'ok e encontre Clugfist."}, [143]={hint="Escort Jom-jom to Clugfist at Bolder'ok."}, [144]={npc="Clugfist", tgt="Clugfist"}, [145]={npc="Clugfist", tgt="Clugfist"}, [146]={npc="Clugfist", tgt="Clugfist"}, [147]={npc="Clugfist", tgt="Clugfist"}, [148]={npc="Hamur", tgt="Hamur", desc="Hamur só oferece esta missão depois que você entregar as duas missões acima."}, [149]={hint="Usar/coletar: Rock Pile"}, [150]={npc="Hamur", tgt="Hamur"}, [151]={npc="Hamur", tgt="Hamur", tag="Opcional", desc="Contrapeso Pesado pode ser comprado na casa de leilões. Com 10, você entrega na hora."}, [152]={hint="Deliver 10 Heavy Weightstones to Hamur in Bolder'ok.", tag="Opcional", desc="Leve os materiais a Hamur. O Contrapeso Pesado é feito por ferreiros e também pode ser obtido por troca."}, [153]={npc="Hamur", tgt="Hamur", tag="Opcional"}, [154]={npc="Krom'rosh", tgt="Krom'rosh"}, [155]={npc="Neza Rinossangue", tgt="Neza Rinossangue", tag="Grupo recomendado, Opcional"}}},
    ["03-25"] = {name="Ermos", nameA="Ermos: {a:340}", tips={{k="取捨", text="Os elementais da rocha se sobrepõem a Busca pelos reagentes dos Ermos. Pegue as duas missões antes de lutar. Saqueie 30 mandíbulas de coiote conforme avança e siga em frente quando atingir o nível alvo."}, {k="取捨", text="Faça Cuca fresca - Pedra líquida apenas se você tiver Óleo Gélido, um Giroscronatom e a poção. Salve Alianças rompidas para um nível superior ou um grupo."}, {k="提醒", text="Se já estiver no nível 40 e tiver ouro, aprenda montaria ao passar pelo instrutor da sua raça.", s={{"Se já estiver no nível 40 e tiver ouro, aprenda montaria ao passar pelo instrutor da sua raça"}}}, {k="提醒", text="Abaixo do nível 42? Mate Elementais da Rocha Maior normais no sudoeste de Ermos (por volta de 6.65, 73.85). Se esse local estiver lotado, mude para coiotes e abutres na cordilheira a sudeste de Karrath.", s={{"Abaixo do nível 42?"}, {"Mate Elementais da Rocha Maior normais no sudoeste de Ermos (por volta de 6.65, 73.85)"}, {"Se esse local estiver lotado, mude para coiotes e abutres na cordilheira a sudeste de Karrath"}}}}, danger={[1]="Há Videntes e Golpeadores de Stonevault de elite, níveis 39-40, no leste de Ermos. Mantenha distância ao contornar Uldaman."}, grind={[1]={mob="Elemental Maior da Rocha", note="Mobs comuns e densos ao longo do penhasco ao sul de Karrath. Há ogros Firegut por perto: limpe pela borda externa, junto às rochas. Se estiver difícil antes do nível 42, mude para a cordilheira."}, [2]={note="Densidade média de mobs comuns na cordilheira a sudeste de Karrath. Evite as patrulhas de elite e raras. Bom para farmar sozinho no nível 41 ou para mudar de local quando a área dos elementais estiver lotada."}, [3]={mob="Urubu Gigante", note="Densidade média de mobs comuns na encosta a sudeste de Karrath. Alterne com os patrulheiros da cordilheira. Se tiver missão de asas de urubu ou moelas, colete junto."}}, supply={[1]={npc="Gorrik"}, [2]={npc="Estalajadeiro Shul'kar"}, [3]={npc="Sranda"}, [4]={npc="Estalajadeiro Shul'kar"}, [5]={npc="Rosnado"}}, steps={[1]={to="Kargath", toA="{a:340}", tag="Antes de ir para as Terras Áridas, você pode comprar na casa de leilões (ou pedir para um alt enviar) 1 × de cada: Óleo Gélido, Giroscronatom, Poção de Cura e Poção Inferior de Invisibilidade (para as três missões de entrega das Terras Áridas)."}, [2]={text="Primeira ida a Karrath: entre nos Ermos pelo desfiladeiro do oeste, ao norte do Acampamento do Crepúsculo (aprox. 26.50, 28.00), e siga para noroeste até Karrath para desbloquear o ponto de voo (3.99, 44.78). Mantenha a Pedra de Regresso vinculada a Rog'mar para as próximas visitas.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé, Antes de ir para as Terras Áridas, você pode comprar na casa de leilões (ou pedir para um alt enviar) 1 × de cada: Óleo Gélido, Giroscronatom, Poção de Cura e Poção Inferior de Invisibilidade (para as três missões de entrega das Terras Áridas)."}, [3]={nodeA="{a:340}", node="Kargath", desc="Desbloquear o ponto de voo com Gorrik."}, [4]={npc="Jarkal Limuno", tgt="Jarkal Limuno"}, [5]={npc="Nika Cicatriz-de-sangue", tgt="Nika Cicatriz-de-sangue"}, [6]={npc="Nika Cicatriz-de-sangue", tgt="Nika Cicatriz-de-sangue"}, [7]={npc="Gorn", tgt="Gorn"}, [8]={text="Elementais da rocha e circuito dos monstros do centro"}, [9]={npc="Lotwil Viriato", tgt="Lotwil Viriato"}, [10]={npc="Lotwil Viriato", tgt="Lotwil Viriato", tag="Requer materiais, Opcional"}, [11]={hint="Encontre Óleo Gélido e leve para Lotwil Viriato, nos Ermos.", tag="Requer materiais, Opcional", desc="Consiga primeiro Óleo Gélido e depois entregue a Lotwil. Entregue os materiais aqui. Alquimistas podem fabricar Óleo Gélido."}, [12]={npc="Lotwil Viriato", tgt="Lotwil Viriato", tag="Requer materiais, Opcional"}, [13]={npc="Lotwil Viriato", tgt="Lotwil Viriato", tag="Requer materiais, Opcional"}, [14]={hint="Leve um Giroscronatom para Lotwil Viriato, nos Ermos.", tag="Requer materiais, Opcional", desc="Obtenha um Giroscronatom primeiro. Os engenheiros podem criá-lo."}, [15]={npc="Lotwil Viriato", tgt="Lotwil Viriato", tag="Requer materiais, Opcional"}, [16]={npc="Lucien Tacachave", tgt="Lucien Tacachave", tag="Requer materiais, Opcional"}, [17]={hint="Leve uma Poção de Cura e uma Poção Inferior de Invisibilidade para Lucien Tacachave, nos Ermos.", tag="Requer materiais, Opcional"}, [18]={npc="Lucien Tacachave", tgt="Lucien Tacachave", tag="Requer materiais, Opcional"}, [19]={hint="Encontre 10 Estilhaços Pequenos de Pedra e leve-os para Lotwil Viriato, nos Ermos."}, [20]={npc="Lotwil Viriato", tgt="Lotwil Viriato"}, [21]={npc="Lotwil Viriato", tgt="Lotwil Viriato"}, [22]={npc="Martek, o Exilado", tgt="Martek, o Exilado"}, [23]={npc="Martek, o Exilado", tgt="Martek, o Exilado"}, [24]={npc="Bertolezo", tgt="Bertolezo"}, [25]={hint="Encontre Theldurin, o Perdido.", tag="Opcional"}, [26]={npc="Theldurin, o Perdido", tgt="Theldurin, o Perdido", tag="Opcional"}, [27]={npc="Theldurin, o Perdido", tgt="Theldurin, o Perdido", tag="Opcional"}, [28]={hint="Leve 3 Lajes Grandes para Lotwil Viriato, nos Ermos."}, [29]={npc="Lotwil Viriato", tgt="Lotwil Viriato"}, [30]={npc="Lotwil Viriato", tgt="Lotwil Viriato"}, [31]={hint="Leve 5 Braçadeiras de Liga de Pedra para Lotwil Viriato, nos Ermos.", desc="Os Elementais da Rocha Maior são mobs comuns; farme as Braçadeiras Stonebound neles, no sudoeste."}, [32]={hint="Leve 10 Lâminas de Indúrio para Martek, o Exilado, nos Ermos."}, [33]={hint="Leve 4 Asas de Urubu para Bertolezo."}, [34]={hint="Leve o Fragmento de Pergaminho Rasgado, o Fragmento de Pergaminho Amassado e o Fragmento de Pergaminho Chamuscado para Theldurin, o Perdido.", tag="Opcional"}, [35]={npc="Lotwil Viriato", tgt="Lotwil Viriato"}, [36]={npc="Martek, o Exilado", tgt="Martek, o Exilado"}, [37]={npc="Bertolezo", tgt="Bertolezo"}, [38]={npc="Theldurin, o Perdido", tgt="Theldurin, o Perdido", tag="Opcional"}, [39]={hint="Leve 5 Moelas de Urubu, 10 Presas de Coiote do Rochedo e 5 Estilhaços de Elemental da Rocha para Jarkal Limuno em Karrath, Ermos."}, [40]={hint="Leve 30 Mandíbulas de Coiote para Nika Cicatriz-de-sangue em Karrath."}, [41]={hint="Mate o Chefe Tho'grun e leve o Signo da Terra para Gorn, em Karrath."}, [42]={npc="Jarkal Limuno", tgt="Jarkal Limuno"}, [43]={npc="Nika Cicatriz-de-sangue", tgt="Nika Cicatriz-de-sangue"}, [44]={npc="Gorn", tgt="Gorn"}, [45]={npc="Jarkal Limuno", tgt="Jarkal Limuno", tag="Só aceite se for fazer Uldaman, Opcional"}, [46]={text="Se já aprendeu Montaria, saia de Karrath para a Selva do Espinhaço. Se não, vá ao instrutor de montaria da sua raça: mortos-vivos voam de Karrath para a Cidade Baixa e caminham até Montalvo. Orcs e trolls voam para Grom'gol e pegam o zepelim de volta a Orgrimmar (os trolls seguem depois até Sen'jin) Taurens e Altos-nascidos da Horda também vão assim a Orgrimmar e depois voam para o Penhasco do Trovão. Os taurens descem até Casco Sangrento; os Altos-nascidos da Horda caminham até o cais do Platô do Vigia dos Céus e pegam o Skycutter."}}},
    ["05-d18"] = {name="Uldaman", entrance="Ermos 1418 cerca de 42.60, 10.80 (entrada principal; desça pela escavação até o subsolo)", pickup="Entre em Uldaman por Karrath. Ao passar por Montanhas de Alterac e Ruína do Martelo até Cidade Baixa, pegue antes Tesouros recuperados com Patrick. De Ruína do Martelo ou Grom'gol, voe para Karrath, nos Ermos, e faça Busca pelos reagentes dos Ermos de Jarkal → Busca pelos reagentes de Uldaman; depois procure Bertolezo e Theldurin. Com nível 35, magos podem fazer antes o pré-requisito de Tabetha no Pântano Vadeoso. Para a cadeia do colar, pegue o Colar Partido na primeira corrida, entregue a Dran numa visita a Orgrimmar e depois volte por Karrath para entrar na masmorra.", pickupS={{"Entre em Uldaman por Karrath"}, {"Ao passar por Montanhas de Alterac e Ruína do Martelo até Cidade Baixa, pegue antes Tesouros recuperados com Patrick"}, {"De Ruína do Martelo ou Grom'gol, voe para Karrath, nos Ermos, e faça Busca pelos reagentes dos Ermos de Jarkal → Busca pelos reagentes de Uldaman; depois procure Bertolezo e Theldurin"}, {"Com nível 35, magos podem fazer antes o pré-requisito de Tabetha no Pântano Vadeoso", {class={"MAGE"}}}, {"Para a cadeia do colar, pegue o Colar Partido na primeira corrida, entregue a Dran numa visita a Orgrimmar e depois volte por Karrath para entrar na masmorra"}}, tips={{k="動線", text="Entrada principal → Revelosh → pegue o diário nos restos mortais. Volte a Karrath para a tradução antes de entrar de novo. Os magos podem ir direto ao Sentinela de Obsidiana pela porta dos fundos. Segundo local de escavação → Galgann → Grimlok → Arkhaedas → Discos de Norgannon."}, {k="取捨", text="Priorize Busca pelos reagentes de Uldaman, Tesouros recuperados e Pedras de energia. No nível 40, pegue os discos e a bolsa. O colar leva pelo menos duas viagens, então pule-o se estiver nivelando rapidamente."}, {k="說明", text="Masmorra para cinco jogadores. No nível 34, pegue Tesouros recuperados em Cidade Baixa e faça a caverna externa ao passar pelos Ermos. Para derrotar o chefe final, o recomendado é o nível 42. A porta da frente serve para a limpeza completa e para o colar; a dos fundos serve para fazer só a segunda metade. Para a missão de mago, entre pela porta dos fundos (só magos). Se o seu mapa marcar só a entrada da caverna na superfície, siga o túnel principal dentro da caverna até o portal.", s={{"Masmorra para cinco jogadores"}, {"No nível 34, pegue Tesouros recuperados em Cidade Baixa e faça a caverna externa ao passar pelos Ermos"}, {"Para derrotar o chefe final, o recomendado é o nível 42"}, {"A porta da frente serve para a limpeza completa e para o colar; a dos fundos serve para fazer só a segunda metade"}, {"Para a missão de mago, entre pela porta dos fundos (só magos)", {class={"MAGE"}}}, {"Se o seu mapa marcar só a entrada da caverna na superfície, siga o túnel principal dentro da caverna até o portal"}}}, {k="提醒", text="Masmorra para cinco jogadores. No nível 34, pegue Tesouros recuperados em Cidade Baixa e faça a caverna externa ao passar pelos Ermos. Para derrotar o chefe final, o recomendado é o nível 42. A porta da frente serve para a limpeza completa e para o colar; a dos fundos serve para fazer só a segunda metade. Para a missão de mago, entre pela porta dos fundos (só magos). Se o seu mapa marcar só a entrada da caverna na superfície, siga o túnel principal dentro da caverna até o portal.", s={{"Masmorra para cinco jogadores"}, {"No nível 34, pegue Tesouros recuperados em Cidade Baixa e faça a caverna externa ao passar pelos Ermos"}, {"Para derrotar o chefe final, o recomendado é o nível 42"}, {"A porta da frente serve para a limpeza completa e para o colar; a dos fundos serve para fazer só a segunda metade"}, {"Para a missão de mago, entre pela porta dos fundos (só magos)", {class={"MAGE"}}}, {"Se o seu mapa marcar só a entrada da caverna na superfície, siga o túnel principal dentro da caverna até o portal"}}}}, steps={[1]={npc="Patrício Garreta", tgt="Patrício Garreta", desc="Pegue com antecedência no anel central de Cidade Baixa a partir do nível 33. O baú fica fora do portal."}, [2]={npc="Bertolezo", tgt="Bertolezo", desc="Saqueie Pedras de energia dos anões de Shadowforge do lado de fora na mesma viagem."}, [3]={npc="Theldurin, o Perdido", tgt="Theldurin, o Perdido", desc="Theldurin fica no sul de Ermos. Aceite se estiver de passagem."}, [4]={npc="Jarkal Limuno", tgt="Jarkal Limuno", desc="Se você entregou esta missão em Karrath, pegue Busca pelos reagentes de Uldaman diretamente."}, [5]={hint="Leve 5 Moelas de Urubu, 10 Presas de Coiote do Rochedo e 5 Estilhaços de Elemental da Rocha para Jarkal Limuno em Karrath, Ermos."}, [6]={npc="Jarkal Limuno", tgt="Jarkal Limuno"}, [7]={npc="Jarkal Limuno", tgt="Jarkal Limuno", desc="Jarkal fica em Karrath. Pegue logo depois de entregar Busca pelos reagentes dos Ermos.", preText="Busca pelos reagentes dos Ermos"}, [8]={npc="Denya", tgt="Denya", desc="Dá para fazer antes, a partir do nível 35, entre o Pântano Vadeoso e Desolação; se já entregou, pule."}, [9]={hint="Fale com Tabetha."}, [10]={npc="Tabetha", tgt="Tabetha"}, [11]={npc="Tabetha", tgt="Tabetha"}, [12]={hint="Leve um Orbe Infernal para Tabetha no Pântano Vadeoso."}, [13]={npc="Tabetha", tgt="Tabetha"}, [14]={npc="Tabetha", tgt="Tabetha", preText="O Orbe Infernal"}, [15]={hint="Mate o Demônio do Orbe, depois fale com Tabetha."}, [16]={npc="Tabetha", tgt="Tabetha"}, [17]={npc="Tabetha", tgt="Tabetha", desc="Pegue depois do exorcismo de Tabetha. Avise antes ao grupo que vai limpar o Sentinela de Obsidiana do lado da entrada dos fundos.", preText="O Exorcismo"}, [18]={hint="Pegue o tesouro de Patrício Garreta no baú de sua família, que está no Saguão Sul de Uldaman, e entregue a ele na Cidade Baixa."}, [19]={hint="Leve 8 Pedras de Energia de Dêntrio e 8 Pedras de Energia de An'Alleum para Bertolezo nos Ermos."}, [20]={hint="Leve a Tabuleta de Ryun'eh para Theldurin, o Perdido."}, [21]={npc="Dran Droffers", tgt="Dran Droffers", desc="A missão do colar é opcional. Anões Forjassombra na escavação ou na masmorra soltam o colar partido. Ao pegar, confirme que é a versão da Horda, O resgate do colar."}, [22]={hint="Procure um colar valioso na escavação de Uldaman e leve-o para Dran Droffers em Orgrimmar. O colar pode estar danificado."}, [23]={npc="Dran Droffers", tgt="Dran Droffers"}, [24]={npc="Dran Droffers", tgt="Dran Droffers", desc="Se for fazer Uldaman só uma vez, pode abandonar esta cadeia de várias corridas. Depois de entregar O resgate do colar, pegue a próxima com Dran.", preText="O resgate do colar"}, [25]={text="Entrada: Uldaman"}, [26]={hint="Leve 12 Campânulas de Fungo Magenta para Jarkal Limuno em Karrath.", desc="Os cogumelos roxos crescem fora da entrada da masmorra. Local: Colha primeiro os cogumelos roxos na caverna da entrada principal e complete dentro pelas passagens de escavação.", spot="Colete cogumelos do lado de fora da porta principal e termine ao longo dos túneis de escavação."}, [27]={hint="Recupere uma Fonte de Energia de Obsidiana e leve-a para Tabetha no Pântano Vadeoso.", desc="Local: Pegue a entrada dos fundos. O Sentinela de Obsidiana fica próximo.", spot="Pegue a entrada dos fundos. O Sentinela de Obsidiana fica próximo."}, [28]={hint="Encontre uma pista do paradeiro das gemas nas profundezas de Uldaman.", desc="Local: Da entrada principal, lute até Revelosh e examine os restos na sala atrás dele. Ordem: depois de achar os restos, aceite o diário e saia da masmorra para voltar a Karrath e liberar a próxima ida.", spot="Entre pela porta principal e derrote Revelosh. Depois examine o corpo na sala atrás dele."}, [29]={npc="Restos Mortais de um Paladino", tgt="Restos Mortais de um Paladino", spot="Restos do paladino na sala atrás de Revelosh"}, [30]={npc="Restos Mortais de um Paladino", tgt="Restos Mortais de um Paladino", desc="Pegue o diário no cadáver e volte para Karrath para desbloquear a próxima viagem.", preText="O resgate do colar 2 - A missão"}, [31]={hint="Encontre alguém que consiga traduzir o diário do paladino. O local mais próximo que pode ter alguém que o faça é Karrath, nos Ermos."}, [32]={npc="Jarkal Limuno", tgt="Jarkal Limuno"}, [33]={npc="Jarkal Limuno", tgt="Jarkal Limuno", preText="Traduzindo o diário"}, [34]={hint="Empreste o colar a Jarkal. Em troca, ele vai traduzir o diário para você."}, [35]={npc="Jarkal Limuno", tgt="Jarkal Limuno"}, [36]={npc="Jarkal Limuno", tgt="Jarkal Limuno", desc="Aceite depois de pegar a tradução em Karrath. Limpe a masmorra toda na segunda corrida.", preText="Traduzindo o diário"}, [37]={hint="Recupere todas as três gemas e uma fonte de energia para o colar de Uldaman e leve-as para Jarkal Limuno, em Karrath. Jarkal acredita que uma fonte de energia pode ser encontrada no constructo mais forte presente em Uldaman.", desc="Local: Urna da segunda escavação → sala de Galgann → Grimlok → último chefe. Ordem: Pegue primeiro a gema amarela, depois a vermelha e a azul, e por último a fonte de energia.", spot="Urna da escavação 2 → sala de Galgann → Grimlok → chefe final."}, [38]={npc="Os Discos de Norgannon", npcObj=true, desc="No nível 40+, mate Arkhaedas e clique nos Discos de Norgannon na sala final."}, [39]={hint="Fale com o vigia de pedra e descubra quais são os segredos da história antiga que ele guarda. Após aprender os segredos históricos, ative os Discos de Norgannon.", desc="Local: Derrote Arkhaedas e entre na câmara atrás dele para clicar nos Discos de Norgannon. Ordem: Ouça primeiro o guardião de pedra e depois clique nos discos.", spot="Mate Arkhaedas e use os Discos de Norgannon no cofre atrás dele."}, [40]={npc="Os Discos de Norgannon", npcObj=true, spot="Discos de Norgannon no cofre atrás de Archaedas"}, [41]={npc="Os Discos de Norgannon", npcObj=true, desc="Aceite a entrega da Horda nos mesmos discos e volte ao Penhasco do Trovão.", preText="Os discos de platina"}, [42]={npc="Jarkal Limuno", tgt="Jarkal Limuno"}, [43]={npc="Bertolezo", tgt="Bertolezo"}, [44]={npc="Theldurin, o Perdido", tgt="Theldurin, o Perdido"}, [45]={npc="Patrício Garreta", tgt="Patrício Garreta"}, [46]={npc="Tabetha", tgt="Tabetha"}, [47]={npc="Sábio Devoto da Verdade", tgt="Sábio Devoto da Verdade"}, [48]={npc="Jarkal Limuno", tgt="Jarkal Limuno"}, [49]={npc="Jarkal Limuno", tgt="Jarkal Limuno", preText="Encontre as Gemas e a Fonte de Energia"}, [50]={hint="Entregue o Colar e Gema Recuperados para Dran Droffers em Orgrimmar."}, [51]={npc="Dran Droffers", tgt="Dran Droffers"}, [52]={npc="Dran Droffers", tgt="Dran Droffers", preText="Entregue as gemas"}, [53]={hint="Visite Jarkal Limuno em Karrath para ver se ele obteve sucesso."}, [54]={npc="Jarkal Limuno", tgt="Jarkal Limuno"}}},
    ["03-26"] = {name="Selva do Espinhaço", tips={{k="取捨", text="Na segunda ida a Angra do Butim, entregue primeiro as missões já concluídas, como Tesouro submerso/Mineração da Empreendimentos S.A./Excelsior. Nas três primeiras etapas dos piratas Vela Sangrenta, faça o trecho curto perto da costa; ao aceitar a quarta, faça Fique de olho/Levaram o rapé junto. Só aceite a última etapa depois de entregar a quarta; mate os líderes dos três navios. Antes de Vodu devido, entregue Fazendo o Sacode tremer→Fale novamente com MacKinley. Entregue cada etapa no porto para liberar a seguinte."}, {k="取捨", text="Pegue Charada do Cortello nos navios Bloodsail e faça a primeira parte do percurso ao passar por Pedregal. Conclua Excelsior e Mineração da Empreendimentos S.A. ao longo do caminho, se necessário, para evitar outro voo. Faça Vodu devido em terra antes de embarcar."}, {k="提醒", text="Da parada de Angra do Butim, na Selva do Espinhaço, até a de Rog'mar e Porto Detonapavio, em Sendas do Rio, você chega ao nível 45 no total. Se quiser ganhar um pouco de EXP já nesta parada, depois de terminar os três navios da Vela Sangrenta mate os piratas normais da Vela Sangrenta na praia (cerca de 32, 79).", s={{"Da parada de Angra do Butim, na Selva do Espinhaço, até a de Rog'mar e Porto Detonapavio, em Sendas do Rio, você chega ao nível 45 no total"}, {"Se quiser ganhar um pouco de EXP já nesta parada, depois de terminar os três navios da Vela Sangrenta mate os piratas normais da Vela Sangrenta na praia (cerca de 32, 79)"}}}}, danger={[1]="Os montes de Mosh'Ogg têm vários tipos de ogro, inclusive elites. Em The Offense of Grom'gol, puxe do pé da colina e não entre de uma vez no acampamento.", [2]="Os navios Bloodsail possuem escadas estreitas e poucas saídas. Limpe a costa antes de embarcar e, em seguida, limpe cada convés antes de sair."}, grind={[1]={mob="Espadachim da Vela Sangrenta", note="Mobs comuns e densos nas praias fora de Angra do Butim. Limpe primeiro a costa e fique atento a outros jogadores fazendo as missões da Vela Sangrenta. Depois de terminar os navios, dá para ganhar EXP por aqui."}, [2]={mob="Bruxo da Vela Sangrenta", note="Lançadores de feitiços comuns e densos na costa sul da Vela Sangrenta. Limpe primeiro os mobs corpo a corpo do grupo e depois puxe os bruxos. Fazer a volta em terra economiza o tempo de embarque."}}, supply={[1]={npc="Gringer"}, [2]={npc="Estalajadeiro Skindle"}, [3]={npc="Jutak"}, [4]={npc="Nixxrax Enchecopo"}, [5]={npc="Haren Kanmae"}, [6]={npc="Thysta"}, [7]={npc="Estalajadeiro Thulbek"}, [8]={npc="Krakk"}, [9]={npc="Nargatt"}}, steps={[1]={text="Se estiver em Karrath, voe direto para Angra do Butim e comece o próximo lote de missões.", desc="Ao voltar do instrutor de montaria, se estiver em Kalimdor, voe primeiro para Orgrimmar e procure Odete Cobrafrete na torre de zepelins fora da cidade. Se estiver na Cidade Baixa, vá à torre de zepelins ao sul de Montalvo e procure Hin Denburg. Pegue a linha de Grom'gol e, de lá, voe para Angra do Butim."}, [2]={npc="Xizk Pontobom", tgt="Xizk Pontobom", tag="Opcional"}, [3]={hint="Complete os objetivos da missão.", tag="Opcional"}, [4]={npc="Xizk Pontobom", tgt="Xizk Pontobom", tag="Opcional"}, [5]={npc="Mestre de Frota Chifre do Mar", tgt="Mestre de Frota Chifre do Mar"}, [6]={npc="Imediato Crazz", tgt="Imediato Crazz"}, [7]={npc="MacKinley Lobo do Mar", tgt="MacKinley Lobo do Mar"}, [8]={npc="Corsário Bloads", tgt="Corsário Bloads"}, [9]={npc="Cranque Mirrabolha", tgt="Cranque Mirrabolha"}, [10]={npc="Kebok", tgt="Kebok"}, [11]={npc="Drizzlik", tgt="Drizzlik"}, [12]={npc="Drizzlik", tgt="Drizzlik"}, [13]={npc="Mestre Portuário Lozgil", tgt="Mestre Portuário Lozgil", tag="Requer a escolta Zul'Kunda, Opcional"}, [14]={npc="Krazek", tgt="Krazek", tag="Faça depois em Pedregal, no Pântano das Mágoas, Opcional", desc="A cadeia prévia começa em Vila Catraca com Peças para Kravel (peças para Kravel), passa por Chapada Cintilante com Entrega para os gnomos (carga do gnomo) e termina em Angra do Butim com O boateiro (rumores do piloto)."}, [15]={npc="Aldo Isque", tgt="Aldo Isque", desc="Pegue o grogue na costa das Terras Agrestes e entregue quando voltar a Angra do Butim."}, [16]={text="Explore a praia ao norte e volte ao porto para liberar as missões da Vela Sangrenta"}, [17]={hint="O Imediato Crazz quer que você cheque a enseada ao norte da Angra do Butim."}, [18]={npc="Correspondência dos Vela Sangrenta", npcObj=true}, [19]={npc="Correspondência dos Vela Sangrenta", npcObj=true}, [20]={hint="Relate suas descobertas ao Imediato Crazz na Angra do Butim."}, [21]={npc="Imediato Crazz", tgt="Imediato Crazz"}, [22]={npc="Imediato Crazz", tgt="Imediato Crazz"}, [23]={hint="Relate ao Mestre de Frota Chifre do Mar o ataque planejado pelos Vela Sangrenta."}, [24]={npc="Mestre de Frota Chifre do Mar", tgt="Mestre de Frota Chifre do Mar"}, [25]={npc="Mestre de Frota Chifre do Mar", tgt="Mestre de Frota Chifre do Mar"}, [26]={npc="Dizzy Caolho", tgt="Dizzy Caolho"}, [27]={npc="Dígui", tgt="Dígui"}, [28]={text="Para as missões extras do acampamento, voe de Angra do Butim para Grom'gol e siga para o sul em direção ao porto."}, [29]={npc="Kin'weelay", tgt="Kin'weelay"}, [30]={npc="Kin'weelay", tgt="Kin'weelay", tag="Requer Colares de osso ensanguentado e O Arrecife Torpe"}, [31]={npc="Caldeirão Borbulhante", npcObj=true, tag="Opcional"}, [32]={npc="Rosarães Guima", tgt="Rosarães Guima"}, [33]={npc="Comandante Aggro'gosh", tgt="Comandante Aggro'gosh", tag="Grupo recomendado, Opcional"}, [34]={hint="Rosarães Guima quer que você mate 10 Espreitadores da Selva."}, [35]={hint="Leve 10 Penas de Espreitador da Selva para o Clarividente Mok'thardin no Acampamento Grom'gol.", tag="Faça junto com Maestria em raptores"}, [36]={hint="Traga uma Pele de Crocolisco Ancião para Drizzlik, na Angra do Butim."}, [37]={npc="Rosarães Guima", tgt="Rosarães Guima"}, [38]={npc="Clarividente Mok'thardin", tgt="Clarividente Mok'thardin", tag="Faça junto com Maestria em raptores"}, [39]={npc="Rosarães Guima", tgt="Rosarães Guima", tag="Grupo ou sozinho, se possível, Grupo recomendado, Opcional"}, [40]={hint="Rosarães Guima quer que você mate Tethis, um raptor perigoso e esquivo, na Selva do Espinhaço.", tag="Grupo ou sozinho, se possível, Grupo recomendado, Opcional"}, [41]={npc="Rosarães Guima", tgt="Rosarães Guima", tag="Grupo ou sozinho, se possível, Grupo recomendado, Opcional"}, [42]={npc="Rosarães Guima", tgt="Rosarães Guima", tag="Grupo ou sozinho, se possível, Grupo recomendado, Opcional", star={"Arco do Mestre Caçador / Rifle do Mestre Caçador"}}, [43]={hint="Rosarães Guima quer que você lhe traga a cabeça do Rei Bangalash, o grande tigre branco.", tag="Grupo ou sozinho, se possível, Grupo recomendado, Opcional"}, [44]={npc="Rosarães Guima", tgt="Rosarães Guima", tag="Grupo ou sozinho, se possível, Grupo recomendado, Opcional", star={"Arco do Mestre Caçador / Rifle do Mestre Caçador"}}, [45]={hint="Matar: Feitífice Mosh'Ogg, Fomentador de Guerra Mosh'Ogg, Espancador Mosh'Ogg, Xamã Mosh'Ogg", tag="Grupo recomendado, Opcional", desc="Reúna um grupo para limpar os quatro alvos de elite na Gruta de Mosh'Ogg."}, [46]={hint="Leve 25 Colares de Osso Partido para Kin'weelay no Acampamento Grom'gol."}, [47]={hint="Leve um Troféu de Balia'mah, um Troféu de Ziata'jai e um Troféu Zul'Mamwe para o Caldeirão Borbulhante no Acampamento Grom'gol.", tag="Opcional"}, [48]={npc="Comandante Aggro'gosh", tgt="Comandante Aggro'gosh", tag="Grupo recomendado, Opcional"}, [49]={npc="Kin'weelay", tgt="Kin'weelay"}, [50]={npc="Caldeirão Borbulhante", npcObj=true, tag="Opcional"}, [51]={npc="Caldeirão Borbulhante", npcObj=true, tag="Opcional", desc="Missão de nível 46; os trolls Rachacrânio que você tem de matar são os mesmos das presas; para entregar é preciso voltar mais uma vez a Grom'gol; se o seu nível não for suficiente, pule."}, [52]={text="Coletas no centro e no sul da Selva do Espinhaço → Complexo da Vela Sangrenta"}, [53]={hint="Consiga 18 Presas Rachacrânio e traga-as de volta para Kebok."}, [54]={hint="Mate 8 Caçadores Rachacrânio, 6 Caçadores de Cabeças Rachacrânio e 4 Berserkers Rachacrânio.", tag="Opcional", desc="Faça junto com as presas."}, [55]={hint="Leve 10 Cristais Azuis Canoros para Cranque Mirrabolha na Angra do Butim."}, [56]={npc="Caldeirão Borbulhante", npcObj=true, tag="Opcional", desc="Volte a Grom'gol para entregar e depois siga para o sul."}, [57]={npc="Caldeirão Borbulhante", npcObj=true, tag="Opcional"}, [58]={npc="Kin'weelay", tgt="Kin'weelay", tag="Opcional"}, [59]={hint="Leve 10 Feixes de Junco de Akiris para o Corsário Bloads na Angra do Butim.", tag="Alvo: Explorador Naga / Escaramuçador Escamoura"}, [60]={hint="Leve 12 amostras do Preparado de Zanzil para Cranque Mirrabolha na Angra do Butim."}, [61]={hint="Leve 5 Miúdos de Gorila do Vale da Névoa para \"Phillipe \"Sacode\" na Angra do Butim."}, [62]={hint="O Mestre de Frota Chifre do Mar na Angra do Butim quer que você mate 10 Espadachins da Vela Sangrenta e traga de volta as Cartas de Navegação da Vela Sangrenta e as Ordens da Vela Sangrenta."}, [63]={hint="Dizzy Caolho da Angra do Butim quer que você recupere seu olho com os Bucaneiros da Vela Sangrenta."}, [64]={hint="O Dígui, na Angra do Butim, quer que você leve para ele 15 trouxinhas de Rapé."}, [65]={npc="Kebok", tgt="Kebok"}, [66]={npc="Cranque Mirrabolha", tgt="Cranque Mirrabolha"}, [67]={npc="Drizzlik", tgt="Drizzlik"}, [68]={npc="Corsário Bloads", tgt="Corsário Bloads"}, [69]={npc="Cranque Mirrabolha", tgt="Cranque Mirrabolha"}, [70]={npc="Phillipe Sacode", tgt="Phillipe Sacode"}, [71]={npc="Phillipe Sacode", tgt="Phillipe Sacode"}, [72]={npc="MacKinley Lobo do Mar", tgt="MacKinley Lobo do Mar"}, [73]={npc="MacKinley Lobo do Mar", tgt="MacKinley Lobo do Mar"}, [74]={npc="Mestre de Frota Chifre do Mar", tgt="Mestre de Frota Chifre do Mar"}, [75]={npc="Dizzy Caolho", tgt="Dizzy Caolho"}, [76]={npc="Dígui", tgt="Dígui"}, [77]={npc="Mestre de Frota Chifre do Mar", tgt="Mestre de Frota Chifre do Mar", tag="Grupo recomendado"}, [78]={text="Última volta: abordar os navios e cobrar as dívidas"}, [79]={hint="Leve o Pé-de-clava do Maury, a Luneta Dourada de Janjão e o Anel Enorme do Chucky para MacKinley \"Lobo do Mar\" na Angra do Butim."}, [80]={hint="O Mestre de Frota Chifre do Mar em Angra do Butim quer que você mate o Capitão Tranquiláguas, o Capitão Querena e o Mestre de Frota Firalião.", tag="Grupo recomendado"}, [81]={npc="Charada do Cortello", npcObj=true, desc="Pegue o item enigmático nos navios da Vela Sangrenta para aceitar a missão. O local de entrega fica embaixo da ponte no Pântano das Mágoas, na próxima parada."}, [82]={npc="Mestre de Frota Chifre do Mar", tgt="Mestre de Frota Chifre do Mar", tag="Grupo recomendado"}, [83]={npc="MacKinley Lobo do Mar", tgt="MacKinley Lobo do Mar"}, [84]={npc="MacKinley Lobo do Mar", tgt="MacKinley Lobo do Mar", tag="Grupo recomendado, Opcional"}, [85]={hint="Leve a Chave de Maury para MacKinley \"Lobo do Mar\" na Angra do Butim.", tag="Grupo recomendado, Opcional"}, [86]={npc="MacKinley Lobo do Mar", tgt="MacKinley Lobo do Mar", tag="Grupo recomendado, Opcional"}, [87]={text="Depois de entregar Vela Sangrenta e Cobrança de Dívidas, vá para Pedregal, no Pântano das Mágoas."}}},
    ["03-27"] = {name="Pântano das Mágoas", nameA="Pântano das Mágoas: {a:75}", tips={{k="取捨", text="A fuga de Galen é uma escolta: limpe os monstros do caminho e só então abra a jaula. A entrega é no cofre, não precisa voltar à jaula."}, {k="取捨", text="Mate Crocoliscos Saltjaw a sudoeste do Poço de Lágrimas e entregue as duas missões Falta de suprimentos para liberar a cadeia dos murlocs. Colete as patas de caranguejo para Carne fresca a caminho da costa sudeste e entregue em Pedregal. Os Oráculos murlocs de Ameaça contínua são de nível 44-45; abaixo do nível 44, pule."}, {k="提醒", text="Depois de levar o pergaminho de Cortello no oeste, vá ao Refúgio e entregue as duas missões de Os Perdidos junto com as missões dos cristais. Para um pouco mais de EXP, mate monstros normais do pântano na borda do Poço de Lágrimas (cerca de 60, 55) ou caranguejos gigantes ao norte da Costa da Lestada.", s={{"Depois de levar o pergaminho de Cortello no oeste, vá ao Refúgio e entregue as duas missões de Os Perdidos junto com as missões dos cristais"}, {"Para um pouco mais de EXP, mate monstros normais do pântano na borda do Poço de Lágrimas (cerca de 60, 55) ou caranguejos gigantes ao norte da Costa da Lestada"}}}}, danger={[1]="Antes de falar com Galen, limpe os mobs ao lado da gaiola e na saída do acampamento. Puxar mais mobs depois de abrir a gaiola dificulta cuidar da escolta e da sua própria vida.", [2]="Os murlocs da Costa da Lestada ficam lado a lado, e os Inkspitters e Oráculos puxam outros por trás. Puxe um de cada vez da margem e não os persiga na água."}, grind={[1]={note="Densidade média de mobs comuns na borda norte do Poço de Lágrimas. Puxe pelo lado da terra firme para evitar os dracônicos verdes da área. Fica perto da rota original e serve para ganhar um pouco de EXP."}, [2]={mob="Jogatinta do Pântano", note="Densidade média de murlocs comuns a sudeste de Pedregal. Pegue primeiro os murlocs isolados fora do acampamento e não os persiga para dentro do grupo. Bom para os níveis 42-43."}, [3]={mob="Comecarne do Pântano", note="Densidade moderada de mobs normais na borda sul do mesmo acampamento murloc. Fique atento aos Oráculos de nível superior e alterne com os Inkspitters antes dos 44."}}, supply={[1]={npc="Khebra"}, [2]={npc="Estalajadeiro Karakal"}, [3]={npc="Gharash"}, [4]={npc="Thultash"}, [5]={npc="Thultazor"}}, steps={[1]={text="Se Pedregal já estiver desbloqueado, voe direto de Angra do Butim ou de Grom'gol. Se não estiver e a Pedra de Regresso estiver vinculada a Rog'mar e disponível, use-a para voltar a Rog'mar; caso contrário, voe de Angra do Butim para Rog'mar (com baldeação em Karrath) e depois desça pela estrada do sul, passando pelo Mirante de Terral, até entrar no Pântano das Mágoas; ou voe para Grom'gol, suba pela estrada da Selva do Espinhaço até a Floresta do Crepúsculo, contorne os guardas de Vila Sombria e entre no Pântano das Mágoas pelo lado leste, pela Trilha do Vento Morto.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [2]={nodeA="{a:75}", node="Stonard", desc="Desbloqueie o ponto de voo com Khebra."}, [3]={npc="Helgrum, o Ligeiro", tgt="Helgrum, o Ligeiro"}, [4]={npc="Vil'zerul", tgt="Vil'zerul"}, [5]={npc="Dar", tgt="Dar"}, [6]={npc="Dar", tgt="Dar"}, [7]={text="Sob a ponte oeste e no Refúgio"}, [8]={hint="Resolva a charada."}, [9]={npc="Pergaminho Encharcado", npcObj=true}, [10]={npc="Pergaminho Encharcado", npcObj=true, tag="Faça depois, quando passar por lá, Opcional"}, [11]={npc="Magtoor", tgt="Magtoor"}, [12]={npc="Karana", tgt="Karana"}, [13]={npc="Pelluk", tgt="Pelluk"}, [14]={hint="Leve 10 Partículas de Pó Onírico para Krazek na Angra do Butim. O Pó Onírico é coletado dos dragonetes no Pântano das Mágoas.", tag="Opcional"}, [15]={hint="Slay 10 Lost Ones in the Fallow Sanctuary."}, [16]={hint="Ache o Pescador dos Perdidos que roubou a isca de Pelluk e pegue-a de volta."}, [17]={hint="Leve 6 Cristais de Draenetista para Magtoor no Pântano das Mágoas."}, [18]={npc="Clava de Noboru", npcObj=true, tag="Faça se cair, Opcional", desc="Mate Noboru, que patrulha a região, e clique no porrete que ele deixar cair para aceitar a missão."}, [19]={hint="Leve a Clava de Noboru ao líder do Refúgio no Pântano das Mágoas.", tag="Faça se cair, Opcional"}, [20]={npc="Magtoor", tgt="Magtoor", tag="Faça se cair, Opcional"}, [21]={text="Escolta a nordeste e Poço de Lágrimas"}, [22]={npc="Galen Boaguarda", tgt="Galen Boaguarda"}, [23]={hint="Escolte Galen até a segurança para, então, encontrar seu acampamento no Pântano das Mágoas e abrir seu cofre.", desc="Limpe os mobs ao redor da gaiola e da saída. Depois de abrir a gaiola, acompanhe Galen; a entrega é no cofre, no fim do trajeto."}, [24]={npc="Cofre do Galen", npcObj=true}, [25]={npc="Magtoor", tgt="Magtoor"}, [26]={npc="Karana", tgt="Karana"}, [27]={npc="Pelluk", tgt="Pelluk"}, [28]={hint="Vil'zerul, no Pedregal, quer que você colete 10 Artefatos Atal'ai."}, [29]={text="Pedregal para a costa sudeste"}, [30]={hint="Leve 8 Ancas Não Tratadas de Dentesserra para Tok'Kar no Pântano das Mágoas.", desc="Mate Crocoliscos Saltjaw no pântano a sudoeste do Poço de Lágrimas. Se não bastar, procure ao longo da costa."}, [31]={hint="Leve 10 Pernas de Rastejante Monstruoso para Dar no Pântano das Mágoas.", desc="Mate Caranguejos-do-mar Gigantes ao norte da Costa da Lestada. Colete dez pernas antes de seguir para o sul."}, [32]={npc="Tok'Kar", tgt="Tok'Kar"}, [33]={npc="Tok'Kar", tgt="Tok'Kar"}, [34]={hint="Leve 6 Garras de Tartalisca Dentesserra para Tok'Kar, no Pântano das Mágoas."}, [35]={npc="Tok'Kar", tgt="Tok'Kar"}, [36]={npc="Tok'Kar", tgt="Tok'Kar"}, [37]={npc="Katar", tgt="Katar"}, [38]={npc="Katar", tgt="Katar", desc="Mate dez de cada um dos três tipos de murlocs na praia sudeste. Retorne para Katar."}, [39]={hint="Mate 10 Murlocs do Pântano, 10 Jogatintas do Pântano e 10 Comecarnes do Pântano. Depois, fale novamente com Katar, no Pântano das Mágoas.", desc="Mate dez de cada um dos três tipos de murlocs na praia sudeste. Retorne para Katar."}, [40]={npc="Katar", tgt="Katar", desc="Mate dez de cada um dos três tipos de murlocs na praia sudeste. Retorne para Katar."}, [41]={npc="Katar", tgt="Katar"}, [42]={npc="Tok'Kar", tgt="Tok'Kar"}, [43]={npc="Katar", tgt="Katar", desc="Depois de entregar a etapa anterior, volte a Katar para a continuação. Siga pela costa para o norte e complete os sábios murlocs; antes de entregar, confirme os dez de cada um dos três tipos."}, [44]={hint="Mate 10 Jogatintas do Pântano, 10 Comecarnes do Pântano e 10 Oráculos do Pântano. Depois, fale novamente com Katar, no Pântano das Mágoas.", desc="Depois de entregar a etapa anterior, volte a Katar para a continuação. Siga pela costa para o norte e complete os sábios murlocs; antes de entregar, confirme os dez de cada um dos três tipos."}, [45]={npc="Katar", tgt="Katar", desc="Depois de entregar a etapa anterior, volte a Katar para a continuação. Siga pela costa para o norte e complete os sábios murlocs; antes de entregar, confirme os dez de cada um dos três tipos."}, [46]={text="Volte pelo mesmo caminho, para oeste, até Pedregal e entregue as patas de caranguejo a Dar."}, [47]={npc="Dar", tgt="Dar"}, [48]={npc="Vil'zerul", tgt="Vil'zerul"}, [49]={npc="Vil'zerul", tgt="Vil'zerul", tag="Faça depois, junto com o Templo Submerso, Opcional"}, [50]={npc="Adélio Tadeu", tgt="Adélio Tadeu", tag="Opcional", desc="Volte à Biblioteca quando tiver todos os materiais de fora e da masmorra."}, [51]={hint="Saque de: Feruja Feroz, Feruja Primitiva, Feruja Selvagem", tag="Opcional", desc="Volte à Biblioteca quando tiver todos os materiais de fora e da masmorra."}, [52]={npc="Adélio Tadeu", tgt="Adélio Tadeu", tag="Opcional", desc="Volte à Biblioteca quando tiver todos os materiais de fora e da masmorra."}, [53]={text="Vá a Rog'mar, em Sendas do Rio."}}},
    ["03-28"] = {tips={{k="取捨", text="Vá primeiro para o oeste, a Mortalha do Crepúsculo (só abre depois de entregar Clugfist's Decree), e depois para o leste, até Porto Detonapavio. O Suserano Kilgar é de elite: mate-o com grupo. Faça a linha do monstro marinho na mesma viagem de Windrest Keep."}, {k="提醒", text="Abaixo do nível 45? Mate bucaneiros e mosqueteiros de Eastsea ao longo da Costa da Lestada (cerca de 84, 35-43); dá para reabastecer perto do porto. Do nível 40 ao 45, com grupo, dá para fazer Fortaleza de Krol'Dok; antes, pegue Eye of Mugg e Tome of Twilight em Rog'mar.", s={{"Abaixo do nível 45?"}, {"Mate bucaneiros e mosqueteiros de Eastsea ao longo da Costa da Lestada (cerca de 84, 35-43); dá para reabastecer perto do porto"}, {"Do nível 40 ao 45, com grupo, dá para fazer Fortaleza de Krol'Dok; antes, pegue Eye of Mugg e Tome of Twilight em Rog'mar"}}}, {k="交通", text="No nível 45, pegue o barco neutro no cais de Porto Detonapavio (80.60, 54.60) até Porto de Bondebico, em Tanaris (68.60, 23.00), e depois siga para Geringontzan. Para ficar nos Reinos do Leste, volte pelo caminho até o ponto de voo de Rog'mar. Personagens da Horda que chegarem de Tanaris também precisam ir por terra até Rog'mar para desbloquear o ponto de voo."}}, danger={[1]="Os mosqueteiros de Eastsea podem entrar na luta de longe. Puxe os piratas pela praia e limpe o caminho de embarque antes de sabotar os navios."}, grind={[1]={mob="Eastsea Buccaneer", note="Costa da Lestada, ao norte de Porto Detonapavio, com muitos monstros normais, misturados com mosqueteiros; puxe um de cada vez pela praia. Dá para completar Concorrência nada amigável junto."}, [2]={mob="Mosqueteira dos Mares do Leste", note="Meio da Costa da Lestada, com muitos monstros normais de ataque à distância, misturados com piratas; os de combate corpo a corpo podem ser puxados para o lado da praia aproveitando o terreno. Bom para chegar ao nível 45."}}, supply={[1]={npc="Grakna"}, [2]={npc="Estalajadeira Zizplink"}, [3]={npc="Mika Darby"}, [4]={npc="Estalajadeira Zizplink"}, [5]={npc="Grizzek"}, [6]={npc="Furadaga"}}, steps={[1]={text="Se a Pedra de Regresso estiver vinculada a Rog'mar e fora de recarga, use-a para voltar a Rog'mar; se estiver em recarga, voe direto de Pedregal. Se o ponto de voo de Rog'mar não estiver desbloqueado, siga de Pedregal para o norte até Sendas do Rio e continue para o norte, passando pelo Mirante de Terral, até Rog'mar para desbloqueá-lo."}, [2]={npc="Tan'jani", tgt="Tan'jani", desc="Entregue ao Mandingueiro Uzer'i em Aldeia Mojache, em Feralas; entregue quando chegar à Aldeia Mojache."}, [3]={text="Se você pulou Chogg'Zac na {s:03-24} e agora tem grupo: primeiro complete Twilight No More! em Solclaro, da {s:03-24}, e a rota norte, até entregar Clugfist's Decree; depois pegue The Wayward Warrior e vá para o oeste, até Mortalha do Crepúsculo. Se não, vá direto para o leste a partir de Rog'mar até Porto Detonapavio.", tag="Grupo recomendado, Opcional"}, [4]={text="Mortalha do Crepúsculo, a oeste de Rog'mar"}, [5]={npc="Krom'rosh", tgt="Krom'rosh"}, [6]={npc="Da'grosh", tgt="Da'grosh"}, [7]={npc="Da'grosh", tgt="Da'grosh"}, [8]={npc="Da'grosh", tgt="Da'grosh"}, [9]={npc="Da'grosh", tgt="Da'grosh"}, [10]={npc="Minerador Ogro", tgt="Crag'rog"}, [11]={npc="Minerador Ogro", tgt="Crag'rog"}, [12]={hint="Matar: Fanático do Crepúsculo, Corruptor do Crepúsculo, Campeão do Crepúsculo", tag="Alvo: Fanático do Crepúsculo/Corruptor do Crepúsculo/Campeão do Crepúsculo"}, [13]={hint="Matar: Rog'mar Scout", tag="Alvo: Rog'mar Scout", desc="Pegue cinco chaves dos cultistas do Crepúsculo e abra as cinco jaulas dos batedores de Rog'mar."}, [14]={hint="Recruit 5 Ogre Miners."}, [15]={npc="Minerador Ogro", tgt="Crag'rog"}, [16]={npc="Da'grosh", tgt="Da'grosh"}, [17]={npc="Da'grosh", tgt="Da'grosh"}, [18]={npc="Da'grosh", tgt="Da'grosh", tag="Faça se aguentar mobs de nível mais alto, Grupo recomendado, Opcional"}, [19]={hint="Saque de: Suserano Kilgar", tag="Faça se aguentar mobs de nível mais alto, Grupo recomendado, Opcional, Alvo: Senhor Supremo Kilgar"}, [20]={npc="Da'grosh", tgt="Da'grosh", tag="Faça se aguentar mobs de nível mais alto, Grupo recomendado, Opcional"}, [21]={npc="Da'grosh", tgt="Da'grosh"}, [22]={npc="Krom'rosh", tgt="Krom'rosh"}, [23]={npc="Krom'rosh", tgt="Krom'rosh", tag="Grupo recomendado, Opcional", desc="É preciso entregar antes It Is Time, Brother... para poder pegar."}, [24]={npc="Tran'gul", tgt="Tran'gul", tag="Grupo recomendado, Opcional", desc="É preciso entregar antes It Is Time, Brother... para poder pegar."}, [25]={text="Sul de Porto Detonapavio → pegar tudo no porto → Costa da Lestada"}, [26]={npc="Pelego Pintado", npcObj=true}, [27]={npc="Garradilha", tgt="Argo Salmouro"}, [28]={npc="Garradilha", tgt="Argo Salmouro"}, [29]={npc="Mestre Portuário Carrapeto", tgt="Mestre Portuário Carrapeto", tag="Opcional"}, [30]={npc="Friz Faiscansa", tgt="Friz Faiscansa"}, [31]={npc="Friz Faiscansa", tgt="Friz Faiscansa", desc="Horda: siga a cadeia de entrega de espada de Rog'mar. Se Friz não oferecer essa etapa, comece pelas missões das docas."}, [32]={npc="Mestre Portuário Carrapeto", tgt="Mestre Portuário Carrapeto"}, [33]={npc="Mestre Portuário Carrapeto", tgt="Mestre Portuário Carrapeto"}, [34]={npc="Fimbo Graxamix", tgt="Fimbo Graxamix"}, [35]={npc="PROCURA-SE!", npcObj=true}, [36]={npc="PROCURA-SE!", npcObj=true, tag="Grupo recomendado, Opcional", desc="Podreira Velha é um murloc de elite de nível 42 que ronda as ilhas dos murlocs ao sul do Porto Detonapavio."}, [37]={hint="Mate 8 Oráculos Murloc e 8 Guerreiros Murlocs ao longo da Costa da Lestada.", tag="Alvo: Murloc Guerreiro / Oráculo Murloc"}, [38]={hint="Colete 12 Olhos de Murloc e 6 peças de Carne de Aretisco para Fimbo Graxamix.", tag="Alvo: Oráculo Murloc / Murloc Skimmer / Murloc Saqueador / Aretisco / Orlatisco"}, [39]={hint="Leve uma prova da morte de Podreira Velha ao Mestre Portuário Carrapeto.", tag="Grupo recomendado, Opcional, Alvo: Podreira Velha"}, [40]={hint="Leve a Pinça de Garradilha a Fimbo Graxamix.", tag="Alvo: Garra de armadilha"}, [41]={hint="Mate 10 Bucaneiros dos Mares do Leste e 10 Mosqueteiros dos Mares do Leste ao longo da Costa da Lestada, ao norte do Porto Detonapavio.", tag="Alvo: Bucaneiro de Eastsea / Mosqueteiro de Eastsea"}, [42]={hint="Colete 8 Produtos Contrabandeados para Friz Faiscansa no Porto Detonapavio."}, [43]={npc="Mestre Portuário Carrapeto", tgt="Mestre Portuário Carrapeto"}, [44]={npc="Fimbo Graxamix", tgt="Fimbo Graxamix"}, [45]={npc="Fimbo Graxamix", tgt="Fimbo Graxamix"}, [46]={npc="Mestre Portuário Carrapeto", tgt="Mestre Portuário Carrapeto"}, [47]={npc="Mestre Portuário Carrapeto", tgt="Mestre Portuário Carrapeto", tag="Grupo recomendado, Opcional"}, [48]={npc="Friz Faiscansa", tgt="Friz Faiscansa"}, [49]={npc="Friz Faiscansa", tgt="Friz Faiscansa"}, [50]={npc="Mestre Portuário Carrapeto", tgt="Mestre Portuário Carrapeto"}, [51]={npc="Mestre Portuário Carrapeto", tgt="Mestre Portuário Carrapeto"}, [52]={hint="Roube 5 Barris de Pólvora dos Mares do Leste para o Mestre Portuário Carrapeto."}, [53]={hint="Mate 8 Saqueadores dos Mares do Leste e 8 Bombardeiros dos Mares do Leste para o Mestre Portuário Carrapeto."}, [54]={hint="Colete 15 Entranhas de Fera e 8 Cogumelos Carne-podre para Argo Salmouro.", desc="Primeiro pino: javalis adultos. Segundo: entrada da caverna. Ogros dentro."}, [55]={npc="Garradilha", tgt="Argo Salmouro"}, [56]={npc="Mestre Portuário Carrapeto", tgt="Mestre Portuário Carrapeto"}, [57]={npc="Mestre Portuário Carrapeto", tgt="Mestre Portuário Carrapeto"}, [58]={npc="Mestre Portuário Carrapeto", tgt="Mestre Portuário Carrapeto", desc="Entregue de uma vez o barril de pólvora e Expansão desenfreada; só depois aceite a missão de explodir o navio."}, [59]={npc="Mestre Portuário Carrapeto", tgt="Mestre Portuário Carrapeto", desc="Faça no mesmo trajeto ao canto nordeste da explosão dos navios e da entrega do contrabandista."}, [60]={hint="Arme uma carga explosiva remota em cada um dos três navios dos Mares do Leste.", desc="Leve os explosivos dados pela missão aos três navios piratas e coloque um em cada navio. Os piratas do Mar do Leste estão na margem. Depois de embarcar, procure a pilha de balas de canhão ao lado do canhão do segundo convés."}, [61]={hint="Entregue o Especial de Friz ao Capitão Viracobres na Costa da Lestada.", desc="Depois de explodir os navios, leve-a pela costa para o nordeste para entregar."}, [62]={npc="Capitão Rás", tgt="Capitão Viracobres"}, [63]={npc="Capitão Rás", tgt="Capitão Rás", desc="Fica bem ao lado do Capitão Rás."}, [64]={hint="Mate o Almirante Lamora, encontre o estoque de saque dele e devolva-o para o Mestre Portuário Carrapeto.", tag="Alvo: Almirante Lamora"}, [65]={npc="Mestre Portuário Carrapeto", tgt="Mestre Portuário Carrapeto"}, [66]={npc="Mestre Portuário Carrapeto", tgt="Mestre Portuário Carrapeto"}, [67]={npc="Friz Faiscansa", tgt="Friz Faiscansa"}, [68]={npc="Friz Faiscansa", tgt="Friz Faiscansa", desc="Entregue no cais de Porto de Bondebico assim que desembarcar. Não pegue a outra, que vai para Angra do Butim."}, [69]={npc="Garradilha", tgt="Argo Salmouro"}, [70]={hint="Use a Bolona de Isca para atrair o monstro marinho. Depois, leve a cabeça dele para Argo Salmouro.", tag="Alvo: Manguadonte Monstruoso", desc="Use a isca grande perto dos destroços submersos na ilha dos murlocs para invocar o monstro marinho. Mate-o e depois pegue a cabeça."}, [71]={npc="Garradilha", tgt="Argo Salmouro"}, [72]={text="Masmorra opcional: Fortaleza de Krol'Dok"}, [73]={hint="Infiltrate Krol'dok Stronghold and return to Krom'rosh with proof of their leader's demise.", tag="Grupo recomendado, Opcional"}, [74]={hint="Recover the Tome of Twilight from Krol'dok Stronghold.", tag="Grupo recomendado, Opcional", desc="O livro cai do chefe da masmorra, Nar'gurk."}, [75]={npc="Krom'rosh", tgt="Krom'rosh", tag="Grupo recomendado, Opcional"}, [76]={npc="Tran'gul", tgt="Tran'gul", tag="Grupo recomendado, Opcional"}, [77]={npc="Fahrad", tgt="Fahrad", tag="Opcional", desc="Cadeia de masmorras solo de nível 45. Pegue-o se estiver passando pela mansão."}, [78]={hint="Speak to Fahrad when you're ready to hear his plan.", tag="Opcional", desc="Cadeia de masmorras solo de nível 45. Pegue-o se estiver passando pela mansão."}, [79]={npc="Fahrad", tgt="Fahrad", tag="Opcional", desc="Cadeia de masmorras solo de nível 45. Pegue-o se estiver passando pela mansão."}, [80]={npc="Fahrad", tgt="Fahrad", tag="Opcional", desc="Requer 45; nível de missão 50. Execute a masmorra após atingir Tanaris."}, [81]={hint="Usar/coletar: Spellbound War Chest", tag="Opcional", desc="Requer 45; nível de missão 50. Execute a masmorra após atingir Tanaris."}, [82]={npc="Fahrad", tgt="Fahrad", tag="Opcional", desc="Requer 45; nível de missão 50. Execute a masmorra após atingir Tanaris."}, [83]={hint="Colete 5 Totens do Fogo Deturpados, 5 Totens da Terra Deturpados, 5 Totens do Ar Deturpados e 5 Totens da Água Deturpados para Pradosa Fita Nuvens em Mil Agulhas.", tag="Opcional", desc="Fogo em Ermos, terra no Pântano das Mágoas, ar em Desolação, água no Pântano Vadeoso. Depois de juntar tudo, volte a Mil Agulhas para entregar."}, [84]={npc="Pradosa Fita Nuvens", tgt="Pradosa Fita Nuvens", tag="Opcional", desc="Fogo em Ermos, terra no Pântano das Mágoas, ar em Desolação, água no Pântano Vadeoso. Colete nesta etapa e volte depois a Mil Agulhas. Se aceitou com Bath'rah, siga o diário e entregue em Alterac."}, [85]={npc="Rau Corta Montes", tgt="Rau Corta Montes", tag="Opcional", desc="Conclua todos os quatro totens torcidos. Fique atento aos javatuscos depois de acionar as piscinas de vapor."}, [86]={hint="Saque de: Ravaging Tempest", tag="Opcional, Alvo: Ravaging Tempest", desc="Conclua todos os quatro totens torcidos. Fique atento aos javatuscos depois de acionar as piscinas de vapor."}, [87]={npc="Rau Corta Montes", tgt="Rau Corta Montes", tag="Opcional", desc="Conclua todos os quatro totens torcidos. Fique atento aos javatuscos depois de acionar as piscinas de vapor."}, [88]={npc="Rau Corta Montes", tgt="Rau Corta Montes", tag="Opcional", desc="Conclua Heed My Call em Aldeia Vento Livre primeiro.", star={"Ira da Tempestade / Garra do Relâmpago / Garra do Arauto das Marés"}}, [89]={hint="Deliver the Eye of the Tempest to Bath'rah the Windwatcher in Alterac Mountains.", tag="Opcional", desc="Conclua Heed My Call em Aldeia Vento Livre primeiro."}, [90]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Conclua Heed My Call em Aldeia Vento Livre primeiro.", star={"Ira da Tempestade / Garra do Relâmpago / Garra do Arauto das Marés"}}}},
    ["05-d19"] = {name="Krol'dok Stronghold", nameA="{a:17780}", entrance="Sendas do Rio 48.60, 26.30", pickup="Na parada de Rog'mar, em Sendas do Rio, faça primeiro as cadeias de Solclaro e de Clubtoe, de Tran'gul, e os pré-requisitos de Clugfist em Bolder'ok; depois vá de Rog'mar para o oeste, entre no Acampamento do Crepúsculo e procure Da'grosh e Crag'rog; volte a Rog'mar para entregar as cartas e aceitar as missões do olho e do tomo. Voe para Rog'mar ou entre a pé em Sendas do Rio a partir de Karrath e procure o portão no terreno elevado bem ao norte de Solclaro. Você pode deixar prontos 4 Couros Grossos e 12 Barras de Ferro para a continuação do molde.", pickupS={{"Na parada de Rog'mar, em Sendas do Rio, faça primeiro as cadeias de Solclaro e de Clubtoe, de Tran'gul, e os pré-requisitos de Clugfist em Bolder'ok; depois vá de Rog'mar para o oeste, entre no Acampamento do Crepúsculo e procure Da'grosh e Crag'rog; volte a Rog'mar para entregar as cartas e aceitar as missões do olho e do tomo"}, {"Voe para Rog'mar ou entre a pé em Sendas do Rio a partir de Karrath e procure o portão no terreno elevado bem ao norte de Solclaro"}, {"Você pode deixar prontos 4 Couros Grossos e 12 Barras de Ferro para a continuação do molde"}}, tips={{k="動線", text="Mina: Grox Esmaga-escravos → Comandante do Crepúsculo Zarmok → molde na ferraria ao lado de Ashka → Nar'gurk para o Tomo do Crepúsculo → Bossman Toof na ponte → Overlord Mugg para o Olho de Mugg. Colete as orelhas dos cultistas do Crepúsculo pelo caminho."}, {k="取捨", text="Conclua os pré-requisitos das paradas de Rog'mar e de Rog'mar e Porto Detonapavio, em Sendas do Rio, antes de formar grupo, para completar as três de uma só vez. Os materiais do molde podem ser preparados antes; entregue-os se o molde cair."}, {k="說明", text="A entrada fica bem ao norte de Solclaro; ao lado do portão há outro portal da fortaleza.", s={{"A entrada fica bem ao norte de Solclaro; ao lado do portão há outro portal da fortaleza"}}}}, steps={[1]={npc="Krom'rosh", tgt="Krom'rosh", tag="Pré-requisito de masmorra"}, [2]={hint="Matar: Lavrador de Arroio dos Prados", tag="Pré-requisito de masmorra"}, [3]={npc="Krom'rosh", tgt="Krom'rosh", tag="Pré-requisito de masmorra"}, [4]={npc="Krom'rosh", tgt="Krom'rosh", tag="Pré-requisito de masmorra"}, [5]={hint="Steal 6 Feed Satchels from the Alliance farm in Meadowsbrook then return to Krom'rosh.", tag="Pré-requisito de masmorra"}, [6]={npc="Krom'rosh", tgt="Krom'rosh", tag="Pré-requisito de masmorra"}, [7]={npc="Krom'rosh", tgt="Krom'rosh", tag="Pré-requisito de masmorra"}, [8]={hint="Matar: Farholde Priest, Batedor de Ermoforte", tag="Pré-requisito de masmorra"}, [9]={npc="Krom'rosh", tgt="Krom'rosh", tag="Pré-requisito de masmorra"}, [10]={npc="Tran'gul", tgt="Tran'gul"}, [11]={npc="Tran'gul", tgt="Tran'gul"}, [12]={hint="Matar: Saqueador do Crepúsculo, Sombramante do Crepúsculo, Neófito do Crepúsculo", tag="Alvo: Saqueador do Crepúsculo/Sombramante do Crepúsculo/Neófito do Crepúsculo"}, [13]={hint="Saque de: Sombramante do Crepúsculo", tag="Alvo: Sombramante do Crepúsculo"}, [14]={npc="Tran'gul", tgt="Tran'gul"}, [15]={npc="Tran'gul", tgt="Tran'gul"}, [16]={npc="Tran'gul", tgt="Tran'gul", preText="Encroaching Twilight, Twilight Missives"}, [17]={hint="Convince a Twilight's Hammer miner in Sunnyglade to divulge their secrets."}, [18]={npc="Porreto", tgt="Porreto"}, [19]={npc="Porreto", tgt="Porreto", preText="Digging for Answers"}, [20]={hint="Find missing ogres in the caves beneath Sunnyglade for Clubtoe."}, [21]={npc="Brutamontes Potencializado", tgt="Brutamontes do Crepúsculo"}, [22]={npc="Brutamontes Potencializado", tgt="Brutamontes do Crepúsculo", preText="The Purple Ones"}, [23]={npc="Porreto", tgt="Porreto", preText="The Purple Ones"}, [24]={hint="Matar: Brutamontes Potencializado, Ritualista do Crepúsculo", tag="Alvo: Brutamontes Potencializado/Ritualista do Crepúsculo"}, [25]={hint="Destroy 5 Twilight Ritual Circles found throughout the caves underneath Sunnyglade.", desc="Procure ao longo da caverna."}, [26]={npc="Porreto", tgt="Porreto"}, [27]={npc="Porreto", tgt="Porreto"}, [28]={npc="Porreto", tgt="Porreto", desc="Elite. Chame o grupo para ajudar.", preText="The Purple Ones, Sickening Lights"}, [29]={hint="Saque de: Chogg'Zac", tag="Alvo: Chogg'Zac", desc="Elite. Chame o grupo para ajudar."}, [30]={npc="Porreto", tgt="Porreto", desc="Elite. Chame o grupo para ajudar."}, [31]={npc="Porreto", tgt="Porreto", preText="Twilight No More!"}, [32]={npc="Tran'gul", tgt="Tran'gul"}, [33]={npc="Tran'gul", tgt="Tran'gul", preText="Spread the Word"}, [34]={hint="Deliver Chogg's head to the ogre city to the north."}, [35]={npc="Clugfist", tgt="Clugfist"}, [36]={npc="Clugfist", tgt="Clugfist", preText="Land of Giants"}, [37]={hint="Matar: Espancador do Crepúsculo, Arauto das Chamas do Crepúsculo", tag="Alvo: Espancador do Crepúsculo/Arauto das Chamas do Crepúsculo"}, [38]={npc="Clugfist", tgt="Clugfist"}, [39]={npc="Clugfist", tgt="Clugfist", preText="Land of Giants"}, [40]={hint="Saque de: Klunk", tag="Alvo: Klunk"}, [41]={npc="Clugfist", tgt="Clugfist"}, [42]={npc="Clugfist", tgt="Clugfist", preText="Unworthy Champion"}, [43]={npc="Krom'rosh", tgt="Krom'rosh"}, [44]={npc="Krom'rosh", tgt="Krom'rosh", preText="Clugfist's Decree"}, [45]={hint="Find Da'grosh in the hills west of Rog'mar."}, [46]={npc="Da'grosh", tgt="Da'grosh"}, [47]={npc="Da'grosh", tgt="Da'grosh", preText="The Wayward Warrior"}, [48]={npc="Da'grosh", tgt="Da'grosh", preText="The Wayward Warrior"}, [49]={npc="Da'grosh", tgt="Da'grosh", tag="Opcional", preText="The Wayward Warrior"}, [50]={npc="Minerador Ogro", tgt="Crag'rog", tag="Opcional"}, [51]={npc="Minerador Ogro", tgt="Crag'rog", tag="Opcional", desc="Aceite de Crag'rog, dentro da Mortalha do Crepúsculo.", preText="Rumblings of Discontent"}, [52]={hint="Matar: Fanático do Crepúsculo, Corruptor do Crepúsculo, Campeão do Crepúsculo", tag="Alvo: Fanático do Crepúsculo/Corruptor do Crepúsculo/Campeão do Crepúsculo"}, [53]={hint="Matar: Rog'mar Scout", tag="Alvo: Rog'mar Scout"}, [54]={hint="Recruit 5 Ogre Miners.", tag="Opcional", desc="Procure primeiro os três mineiros marcados no mapa; os demais ficam por perto."}, [55]={npc="Minerador Ogro", tgt="Crag'rog", tag="Opcional"}, [56]={npc="Da'grosh", tgt="Da'grosh"}, [57]={npc="Da'grosh", tgt="Da'grosh"}, [58]={npc="Da'grosh", tgt="Da'grosh", desc="Se ainda não aparecer depois de Abrindo caminho e Break Their Chains, faça de passagem a missão paralela de recrutamento de Klarg e confira de novo.", preText="Carving a Path, Break Their Chains"}, [59]={hint="Saque de: Suserano Kilgar", tag="Alvo: Senhor Supremo Kilgar"}, [60]={npc="Da'grosh", tgt="Da'grosh"}, [61]={npc="Da'grosh", tgt="Da'grosh", desc="Da'grosh dá esta missão depois que você entrega a cabeça do Overlord Kilgar.", preText="Bring Me His Head"}, [62]={npc="Da'grosh", tgt="Da'grosh", preText="Bring Me His Head"}, [63]={hint="Deliver the missive to Krom'rosh at Rog'mar."}, [64]={npc="Krom'rosh", tgt="Krom'rosh"}, [65]={npc="Krom'rosh", tgt="Krom'rosh", preText="It Is Time, Brother..."}, [66]={npc="Tran'gul", tgt="Tran'gul", preText="It Is Time, Brother..."}, [67]={text="Entrada: Krol'dok Stronghold"}, [68]={hint="Collect 15 Cultist Ears from the Twilight's Hammer in Krol'dok Stronghold.", desc="Limpe primeiro os cultistas ao redor de Zarmok (ele também deixa cair uma orelha) e depois veja quantas ainda faltam. Local: depois do túnel da mina, limpe ao redor de Zarmok e complete as orelhas pelas passagens da fortaleza.", spot="Depois da mina, limpe ao redor de Zarmok e complete as orelhas pelas passagens da fortaleza."}, [69]={npc="Krol'dok Moulding", npcObj=true, tag="Opcional", desc="Tunk solta o molde. Clique com o botão direito para iniciar a missão. Tunk fica na ferraria ao lado do administrador de guerra Ashka. Clique com o botão direito no molde depois de saqueá-lo."}, [70]={hint="Recover the Tome of Twilight from Krol'dok Stronghold.", desc="Local: Passe por Ashka e limpe a área dos bruxos do Crepúsculo até achar Nar'gurk.", spot="Passe por Ashka e limpe a área dos bruxos do Crepúsculo até achar Nar'gurk."}, [71]={hint="Infiltrate Krol'dok Stronghold and return to Krom'rosh with proof of their leader's demise.", desc="Local: Atravesse a ponte de Bossman Toof. Mate Overlord Mugg na última sala.", spot="Atravesse a ponte de Bossman Toof. Mate Overlord Mugg na última sala."}, [72]={npc="Krom'rosh", tgt="Krom'rosh"}, [73]={npc="Tran'gul", tgt="Tran'gul"}, [74]={npc="Gur'dok", tgt="Kreza Darkthorn", tag="Opcional"}, [75]={npc="Gur'dok", tgt="Kreza Darkthorn", tag="Opcional", desc="Compre os materiais com antecedência na Casa de Leilões.", preText="Krol'dok Moulding"}, [76]={hint="Bring 4 Thick Leather and 12 Iron Bar to Kreza Darkthorn.", tag="Opcional", desc="Compre os materiais com antecedência na Casa de Leilões."}, [77]={npc="Gur'dok", tgt="Kreza Darkthorn", tag="Opcional", desc="Compre os materiais com antecedência na Casa de Leilões."}, [78]={npc="Da'grosh", tgt="Da'grosh", desc="De Rog'mar, siga para oeste de volta para Da'grosh."}}},
    ["04-29"] = {name="Tanaris", nameA="Tanaris: {a:977} & {a:976}", shortA="Tanaris: {a:977} +", tips={{k="取捨", text="Na primeira ida a Porto de Bondebico, limpe juntos o chapéu de pirata, as missões de abate, as de procurado e os caixotes. Ao ir de barco de Porto Detonapavio a Porto de Bondebico, dá para limpar a costa antes."}, {k="取捨", text="Faça Espíritos guinchadores na Aldeia Mojache, em Feralas, e Deveres dos Dunamalho no Complexo Dunamalho. Deixe Entrega para MacKinley para a volta a Angra do Butim."}, {k="提醒", text="Sem o EXP para a próxima parada? Mate mobs comuns no acampamento Wastewander (59.40, 24.71) ou na entrada da Enseada do Armador Perdido (70.90, 42.48), em ciclo. Com grupo para Zul'Farrak, leve Couraças de escaravelho, Bastão divinomático e Têmpera de troll e entregue em Geringontzan e no Complexo Dunamalho, em Tanaris.", s={{"Sem o EXP para a próxima parada?"}, {"Mate mobs comuns no acampamento Wastewander (59.40, 24.71) ou na entrada da Enseada do Armador Perdido (70.90, 42.48), em ciclo"}, {"Com grupo para Zul'Farrak, leve Couraças de escaravelho, Bastão divinomático e Têmpera de troll e entregue em Geringontzan e no Complexo Dunamalho, em Tanaris"}}}}, danger={[1]="O califa patrulha e pode ter guardas. Elimine os Bandidos Wastewander próximos e puxe-o quando ele chegar a terreno aberto."}, grind={[1]={mob="Pirata dos Mares do Sul", note="Mobs comuns e densos na entrada da Enseada do Armador Perdido; outros jogadores fazendo as missões piratas podem disputar os mobs. Vá limpando pela borda em direção à praia e colete os itens das missões de pirata."}, [2]={mob="Espadachim dos Mares do Sul", note="Mobs normais fora das docas. Mude aqui se a entrada pirata estiver ocupada. Puxe pela borda para evitar os protetores de doca."}}, supply={[1]={npc="Bulkrek Iracarpos"}, [2]={npc="Estalajadeiro Gabor Bulho"}, [3]={npc="Dobrov A. Massoaço"}, [4]={npc="Estalajadeiro Gabor Bulho"}, [5]={npc="Blizricco Sciumbigno"}, [6]={npc="Gikkix"}}, steps={[1]={text="Em Porto Detonapavio, em Sendas do Rio (80.60, 54.60), pegue o barco para Porto de Bondebico e desça em Tanaris (68.60, 23.00). Saindo de Orgrimmar com o ponto de voo de Geringontzan já desbloqueado, você pode ir voando; na primeira visita, dá para ir a pé da Aldeia Vento Livre até Geringontzan, descendo pela encosta sul da Chapada Cintilante."}, [2]={npc="Mestre Portuário Vaporeto", tgt="Mestre Portuário Vaporeto", desc="Só está disponível depois de pegar em Porto Detonapavio."}, [3]={npc="Mestre Portuário Vaporeto", tgt="Mestre Portuário Vaporeto"}, [4]={npc="Tazzik", tgt="Tazzik"}, [5]={text="Pegue as missões no porto e depois entre na cidade para se preparar"}, [6]={npc="Sissi Ashando", tgt="Sissi Ashando"}, [7]={npc="Chefe de Segurança Silvadágua", tgt="Chefe de Segurança Silvadágua"}, [8]={npc="Pôster de Procura-se", npcObj=true}, [9]={npc="Pôster de Procura-se", npcObj=true}, [10]={npc="Esmirno", tgt="Esmirno"}, [11]={npc="Yeh'kinya", tgt="Yeh'kinya", desc="Faça em Feralas e entregue em Porto de Bondebico."}, [12]={npc="Chefe de Segurança Silvadágua", tgt="Chefe de Segurança Silvadágua", desc="Faça em Complexo Dunamalho. Entregue em Porto de Bondebico."}, [13]={nodeA="{a:976}", node="Gadgetzan", desc="De Porto de Bondebico siga a estrada para o oeste até Geringontzan e procure o mestre de voo da Horda, Bulkrek Iracarpos, para obter o ponto de voo."}, [14]={text="Voe de Geringontzan para Vila Catraca.", tag="Opcional"}, [15]={hint="Leve Fio de Ouro de Qualidade, 2 Carvões Fumegantes e um Estilhaço de Alma para Menara Nihila, nos Sertões.", tag="Opcional", desc="Separe Fio de ouro de qualidade, 2 carvões fumegantes e 1 fragmento de alma e volte a Menara."}, [16]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", desc="Separe Fio de ouro de qualidade, 2 carvões fumegantes e 1 fragmento de alma e volte a Menara."}, [17]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", star={"Robessangre Dourado Encantado", {"WARLOCK"}}}, [18]={hint="Espere até Menara Nihila concluir a sua veste e depois fale novamente com ela.", tag="Opcional"}, [19]={npc="Menara Nihila", tgt="Menara Nihila", tag="Opcional", star={"Robessangre Dourado Encantado", {"WARLOCK"}}}, [20]={text="Voe de Vila Catraca de volta para Geringontzan.", tag="Opcional"}, [21]={text="Vincule temporariamente a Pedra de Regresso com o estalajadeiro Gabor Bulho na estalagem de Geringontzan (52.51, 27.91). Troque depois, na Aldeia Mojache, em Feralas.", bindA="{a:976}"}, [22]={npc="Engenheiro-chefe Silvadágua", tgt="Engenheiro-chefe Silvadágua"}, [23]={npc="Operador de Torneira Rastamala", tgt="Operador de Torneira Rastamala"}, [24]={npc="Tran'rek", tgt="Tran'rek", tag="Opcional", desc="Pegue apenas se estiver executando Zul'Farrak."}, [25]={npc="Engenheiro-chefe Silvadágua", tgt="Engenheiro-chefe Silvadágua", tag="Grupo recomendado, Opcional", desc="Saqueie isto durante o evento de escada em Zul'Farrak.", star={"Anel da Confraria Maçom", {"ROGUE", "HUNTER", "DRUID"}}}, [26]={npc="Trenton Lumartelo", tgt="Trenton Lumartelo", tag="Opcional", desc="Pegue apenas se estiver executando Zul'Farrak."}, [27]={text="Acampamentos Wastewander e Enseada do Armador Perdido"}, [28]={hint="Elimine 10 Bandidos e Ladrões Errantes a leste de Geringontzan, depois fale novamente com o Engenheiro-chefe Silvadágua."}, [29]={hint="Leve 5 Bolsas de Água do Errante para o Operador de Torneira Rastamala em Geringontzan."}, [30]={npc="Engenheiro-chefe Silvadágua", tgt="Engenheiro-chefe Silvadágua"}, [31]={npc="Operador de Torneira Rastamala", tgt="Operador de Torneira Rastamala"}, [32]={npc="Engenheiro-chefe Silvadágua", tgt="Engenheiro-chefe Silvadágua"}, [33]={hint="Elimine 10 Magos das Sombras Errantes, 8 Ladinos Errantes e 6 Assassinos Errantes para o Engenheiro-chefe Silvadágua em Geringontzan.", desc="Entre no acampamento Wastewander a sudeste de Geringontzan."}, [34]={hint="Leve a cabeça de Califa Escorpicada ao Engenheiro-chefe Silvadágua em Geringontzan.", desc="Ele pode ter uma escolta. Espere até que ele chegue ao limite do acampamento antes de puxar."}, [35]={hint="O Chefe de Segurança Silvadágua do Porto de Bondebico, em Tanaris, quer que você mate 10 Piratas dos Mares do Sul, 10 Flibusteiros dos Mares do Sul, 10 Estivadores dos Mares do Sul e 10 Espadachins dos Mares do Sul."}, [36]={hint="Sissi Ashando quer que você colete 20 Chapéus de Pirata dos Mares do Sul e leve-os para ela no Porto de Bondebico, em Tanaris.", desc="Saqueie todos os inimigos abatidos enquanto faz a missão Recadinho dos Mares do Sul."}, [37]={hint="Leve a Cabeça do André ao Chefe de Segurança Silvadágua no Porto de Bondebico."}, [38]={hint="Leve o Carregamento do Esmirno para Esmirno no Porto de Bondebico."}, [39]={npc="Horário do Navio", npcObj=true, tag="Opcional", desc="Mate os Flibusteiros dos Mares do Sul, abra a maleta que eles dropam para pegar a programação e clique com o botão direito na programação, na mochila, para aceitar a missão."}, [40]={text="Siga a costa para o norte de volta a Porto de Bondebico e entregue de uma vez as missões dos piratas e da carga."}, [41]={npc="Chefe de Segurança Silvadágua", tgt="Chefe de Segurança Silvadágua"}, [42]={npc="Sissi Ashando", tgt="Sissi Ashando"}, [43]={npc="Chefe de Segurança Silvadágua", tgt="Chefe de Segurança Silvadágua"}, [44]={npc="Esmirno", tgt="Esmirno"}, [45]={npc="Chefe de Segurança Silvadágua", tgt="Chefe de Segurança Silvadágua", tag="Opcional"}, [46]={npc="Esmirno", tgt="Esmirno", desc="Guarde por enquanto. Entregue na volta a Angra do Butim."}, [47]={text="Volte a Geringontzan para o segundo lote de Wastewander e as missões de procurado. Se a Pedra de Regresso já estiver vinculada a Geringontzan, use-a."}, [48]={npc="Engenheiro-chefe Silvadágua", tgt="Engenheiro-chefe Silvadágua"}, [49]={npc="Engenheiro-chefe Silvadágua", tgt="Engenheiro-chefe Silvadágua"}}},
    ["04-30"] = {name="Feralas", nameA="Feralas: {a:1099}", tips={{k="取捨", text="Siga a cadeia dos gnolls Woodpaw até Os planos de batalha para liberar as duas missões de Zukk'ash que podem ser feitas juntas, a sudeste de Bastilha Cortifúria."}, {k="取捨", text="Se pegou o Transmissor de Emergência OOX-22/FE, aceite a escolta no Vale dos Abomináveis. Depois de escoltar até a costa, faça os gigantes da costa e os elementais da água."}, {k="取捨", text="A missão secundária da costa fica no lado oeste; se o transmissor de emergência não cair, não vá atrás dele; percorra a costa se tiver tempo."}, {k="提醒", text="Ainda não chegou ao 47? Mate yetis no Vale dos Abomináveis (55.29,53.76) ou ogros Gordunni ao norte da Aldeia Mojache (75.13,34.86). Depois volte ao acampamento para entregar as missões.", s={{"Ainda não chegou ao 47?"}, {"Mate yetis no Vale dos Abomináveis (55.29,53.76) ou ogros Gordunni ao norte da Aldeia Mojache (75.13,34.86)"}, {"Depois volte ao acampamento para entregar as missões"}}}}, danger={[1]="O acampamento Gordunni ao norte de Aldeia Mojache tem magos e brutamontes. Limpe a rota de fuga antes de minerar cobalto e não se embrenhe no fundo do acampamento.", [2]="Use Ultra-encolhedor de Zorbin nos gigantes da Costa Esquecida antes de enfrentá-los. Espere os elementais da água se afastarem e puxe um de cada vez."}, grind={[1]={mob="Yeti Abominável", note="Yetis comuns concentrados nas encostas externas do Vale dos Abomináveis; dá para matar em sequência e pegar as peles. Se houver jogadores em missão na entrada da caverna, alterne pela encosta."}, [2]={mob="Parrudo Abominável", note="Yetis normais de nível ligeiramente superior a sudoeste de Vale dos Abomináveis. Puxe mobs corpo a corpo de fora e evite a boca lotada da caverna."}}, supply={[1]={npc="Shyn"}, [2]={npc="Estalajadeiro Greul"}, [3]={npc="Cavento Mira Certa"}, [4]={npc="Estalajadeiro Greul"}, [5]={npc="Cavento Mira Certa"}, [6]={npc="Tarhus"}}, steps={[1]={text="Se já tiver o ponto de voo da Aldeia Mojache, voe direto de Geringontzan. Na primeira visita, voe de Geringontzan para a Aldeia Vento Livre, em Mil Agulhas, desça pelo elevador até o fundo do vale e siga pela estrada do vale para o oeste até entrar em Feralas. Se a Aldeia Vento Livre também não estiver desbloqueada, vá de Geringontzan para o norte, suba até a Chapada Cintilante e siga para o oeste pelo fundo do vale de Mil Agulhas.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [2]={nodeA="{a:1099}", node="Camp Mojache", desc="Desbloquear o ponto de voo com Shyn."}, [3]={text="Vincule sua Pedra de Regresso com Estalajadeiro Greul na estalagem da Aldeia Mojache (74.80, 45.18).", bindA="{a:1099}"}, [4]={npc="Krueg Rachacrânio", tgt="Krueg Rachacrânio"}, [5]={npc="Orwin Sheiduztruc", tgt="Orwin Sheiduztruc"}, [6]={npc="Hadoken Passo Veloz", tgt="Hadoken Passo Veloz"}, [7]={npc="Jangdor Passo Veloz", tgt="Jangdor Passo Veloz"}, [8]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i"}, [9]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i", desc="Só está disponível depois de pegar em Rog'mar, em Sendas do Rio."}, [10]={npc="Rok Orhan", tgt="Rok Orhan"}, [11]={text="Ao redor do acampamento e das primeiras missões Gordunni ao norte"}, [12]={hint="Leve 10 Jubas de Gnoll Patábua para Hadoken Passo Veloz na Aldeia Mojache."}, [13]={hint="Rok Orhan, da Aldeia Mojache, quer que você mate 10 Ogros Gordunni, 10 Ogros-magos e 5 Brutamontes Gordunni."}, [14]={hint="Orwin Sheiduztruc, na Aldeia Mojache, quer 12 amostras de Cobalto Gordunni.", desc="Use a pá da missão ao lado do monte azul no acampamento Gordunni."}, [15]={npc="Pergaminho Gordunni", npcObj=true, desc="Clique no Pergaminho Gordunni no chão na extremidade norte."}, [16]={npc="Hadoken Passo Veloz", tgt="Hadoken Passo Veloz"}, [17]={npc="Rok Orhan", tgt="Rok Orhan"}, [18]={npc="Orwin Sheiduztruc", tgt="Orwin Sheiduztruc"}, [19]={npc="Rok Orhan", tgt="Rok Orhan"}, [20]={npc="Hadoken Passo Veloz", tgt="Hadoken Passo Veloz"}, [21]={npc="Rok Orhan", tgt="Rok Orhan"}, [22]={npc="Rok Orhan", tgt="Rok Orhan"}, [23]={hint="Mate 5 Machos Alfa Patábua e fale novamente com Hadoken Passo Veloz em uma hora.", desc="Temporizador de uma hora. Mate cinco em Serra dos Patábua ao sul e retorne imediatamente."}, [24]={npc="Hadoken Passo Veloz", tgt="Hadoken Passo Veloz"}, [25]={npc="Hadoken Passo Veloz", tgt="Hadoken Passo Veloz"}, [26]={hint="Encontre os Planos de Batalha Gnoll no acampamento dos Gnolls ao sul da Aldeia Mojache."}, [27]={npc="Mapa de Batalha de Patábua", npcObj=true}, [28]={npc="Mapa de Batalha de Patábua", npcObj=true}, [29]={npc="Hadoken Passo Veloz", tgt="Hadoken Passo Veloz"}, [30]={npc="Hadoken Passo Veloz", tgt="Hadoken Passo Veloz"}, [31]={npc="Hadoken Passo Veloz", tgt="Hadoken Passo Veloz"}, [32]={text="Dragões de fadas no meio, depois para oeste até Vale dos Abomináveis"}, [33]={hint="Traga 10 Asas Iridescentes de Dardejantes para Krueg Rachacrânio na Aldeia Mojache."}, [34]={hint="Capture os espíritos de 3 guinchadores em Feralas, e depois fale novamente com Yeh'kinya no Porto de Bondebico.", desc="Entregue em Porto de Bondebico após a perna Geringontzan / Complexo Dunamalho."}, [35]={hint="Leve 10 peças de Pelego Grosso de Yeti para Jangdor Passo Veloz na Aldeia Mojache.", desc="Mate Rage Scar Yetis dentro e ao redor da caverna por Pelego Grosso de Yeti."}, [36]={text="Só vá à Costa Esquecida se quiser as missões secundárias da costa. Se tiver o localizador de Feralas, pegue antes a escolta na caverna do Vale dos Abomináveis e siga depois pela costa.", tag="Opcional"}, [37]={npc="Transmissor de Emergência OOX-22/FE", npcObj=true, tag="Opcional", desc="O localizador é dropado por mobs; só aceite se tiver conseguido um."}, [38]={hint="Pegue o transmissor de emergência para o robô teleguiado de Olhatorto na caverna próxima ao Vale dos Abomináveis.", tag="Opcional", desc="O localizador é dropado por mobs; só aceite se tiver conseguido um."}, [39]={npc="Robô Teleguiado OOX-22/FE", tgt="Robô Teleguiado OOX-22/FE", tag="Opcional", desc="O localizador é dropado por mobs; só aceite se tiver conseguido um."}, [40]={npc="Robô Teleguiado OOX-22/FE", tgt="Robô Teleguiado OOX-22/FE", tag="Opcional", desc="Há emboscadas no caminho. Depois da escolta, entregue em Angra do Butim."}, [41]={hint="Escolte o OOX-22/FE até a doca ao longo da Costa Esquecida, depois apresente-se a Olhatorto Obnótico na Angra do Butim.", tag="Opcional", desc="Há emboscadas no caminho. Depois da escolta, entregue em Angra do Butim."}, [42]={npc="Zorbin Cegasvista", tgt="Zorbin Cegasvista"}, [43]={npc="Zorbin Cegasvista", tgt="Zorbin Cegasvista"}, [44]={hint="Use o Ultra-encolhedor de Zorbin para deixar qualquer tipo de gigante de Feralas com um tamanho mais compacto e manejável. Colete 15 Resíduos de Miniaturização encontrados nos gigantes encolhidos e leve para Zorbin Cegasvista, que fica nas docas da Costa Esquecida, em Feralas.", desc="Encolha os gigantes antes de matá-los; os que não forem encolhidos não dropam o item necessário."}, [45]={npc="Zorbin Cegasvista", tgt="Zorbin Cegasvista"}, [46]={hint="Colete 10 Âmagos dos Elementais de Água dos Elementais do Mar e dos Borrifos do Mar ao longo da Costa Esquecida de Feralas, e leve-os para Zorbin Cegasvista, próximo às docas."}, [47]={npc="Zorbin Cegasvista", tgt="Zorbin Cegasvista"}, [48]={text="Depois do Vale dos Abomináveis ou da costa, use a Pedra de Regresso para voltar à Aldeia Mojache e entregar tudo."}, [49]={npc="Krueg Rachacrânio", tgt="Krueg Rachacrânio"}, [50]={npc="Jangdor Passo Veloz", tgt="Jangdor Passo Veloz"}, [51]={npc="Krueg Rachacrânio", tgt="Krueg Rachacrânio"}, [52]={npc="Jangdor Passo Veloz", tgt="Jangdor Passo Veloz"}, [53]={hint="Traga 20 Chifres de Temível Totem para Krueg Rachacrânio na Aldeia Mojache.", desc="Pegue os chifres no acampamento Grimtotem a noroeste de Aldeia Mojache e depois retorne."}, [54]={npc="Krueg Rachacrânio", tgt="Krueg Rachacrânio"}, [55]={npc="Krueg Rachacrânio", tgt="Krueg Rachacrânio"}, [56]={text="Volte a Orgrimmar para liberar a continuação de Feralas."}, [57]={text="Voe da Aldeia Mojache para Orgrimmar (normalmente via Encruzilhada ou Penhasco do Trovão). Mantenha a Pedra de Regresso na Aldeia Mojache; depois de entregar em Orgrimmar, use-a para voltar a Feralas."}, [58]={npc="Neeru Cortafogo", tgt="Neeru Cortafogo"}, [59]={npc="Belgrom Pedramalho", tgt="Belgrom Pedramalho"}, [60]={npc="Neeru Cortafogo", tgt="Neeru Cortafogo", desc="Guarde para as etapas de Aldeia Mojache e Bastilha Cortifúria, em Feralas; entregue em Aldeia Mojache."}, [61]={npc="Uthel'nay", tgt="Uthel'nay", tag="Grupo recomendado, Opcional"}, [62]={text="Depois das entregas em Orgrimmar, use a Pedra de Regresso para voltar à Aldeia Mojache. Se estiver em recarga, voe de Orgrimmar para Mojache."}}},
    ["04-32"] = {name="Feralas: Gládio Cruel", nameA="Feralas: {a:1099} & Gládio Cruel", shortA="Feralas: {a:1099} +", tips={{k="取捨", text="Os yetis Cortifúria e os do Vale dos Abomináveis são dois lotes diferentes. Entregue primeiro Marca de qualidade na Aldeia Mojache, em Feralas, e depois limpe este Melhoria de qualidade. O Pelego imaculado de Yeti só se entrega quando cair."}, {k="取捨", text="Voltar com a Pedra de Regresso depois da cadeia dos murlocs poupa uma travessia do mar. A essência de coruscante de O teste do recipiente você pega quando chegar às Terras Agrestes; as continuações Muisec de hipogrifo-Armas de espírito ficam para a Aldeia Mojache, em Feralas."}, {k="提醒", text="Se precisar de EXP, faça um circuito pelos yetis Cortifúria no perímetro externo da Bastilha Cortifúria, de 55.73,33.05 a 54.39,33.10, priorizando puxar um por vez.", s={{"Se precisar de EXP, faça um circuito pelos yetis Cortifúria no perímetro externo da Bastilha Cortifúria, de 55.73,33.05 a 54.39,33.10, priorizando puxar um por vez"}}}}, danger={[1]="A entrada da caverna dos yetis é estreita. Os Anciões Rage Scar entram na luta junto com os mobs da entrada. Limpe primeiro o lado de fora e só depois entre na caverna."}, grind={[1]={mob="Yeti Cortifúria", note="Yetis comuns nas encostas externas de Bastilha Cortifúria. Dê uma volta pela encosta e pegue as peles de yeti; se a caverna estiver ocupada, fique na parte externa."}, [2]={mob="Ancião de Cortifúria", note="Yetis comuns de nível mais alto no mesmo acampamento; dá para alternar entre eles até o nível 49. A caverna estreita facilita puxar dois ao mesmo tempo, então limpe primeiro a entrada."}}, supply={[1]={npc="Shyn"}, [2]={npc="Estalajadeiro Greul"}, [3]={npc="Cavento Mira Certa"}, [4]={npc="Estalajadeiro Greul"}, [5]={npc="Cavento Mira Certa"}, [6]={npc="Tarhus"}}, steps={[1]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i"}, [2]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i", desc="Deixe para as Terras Agrestes. Mate bestas-coruja e use o recipiente da missão nos cadáveres; entregue em Aldeia Mojache."}, [3]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i", desc="Guarde os materiais naturais pelo caminho; a coleta completa e a entrega ficam para Aldeia Mojache."}, [4]={hint="Traga 20 Carapaças de Zukk'ash para Hadoken Passo Veloz na Aldeia Mojache, que fica em Feralas."}, [5]={hint="Derrote Cravaçoite na Profundeza Atormentada, leve as glândulas para Hadoken Passo Veloz na Aldeia Mojache, que fica em Feralas."}, [6]={hint="Rok Orhan, da Aldeia Mojache, quer que você mate 10 Xamãs Gordunni, 10 Bruxos Gordunni e 5 Espancadores Gordunni."}, [7]={hint="Rok Orhan, da Aldeia Mojache, quer que você encontre um Orbe Gordunni."}, [8]={text="Siga a estrada principal de volta a Aldeia Mojache para entregar Os ogros de Feralas e Infestação Zukk'ash. Deixe os yetis do norte para a próxima viagem."}, [9]={npc="Hadoken Passo Veloz", tgt="Hadoken Passo Veloz"}, [10]={npc="Hadoken Passo Veloz", tgt="Hadoken Passo Veloz"}, [11]={npc="Rok Orhan", tgt="Rok Orhan"}, [12]={npc="Rok Orhan", tgt="Rok Orhan"}, [13]={npc="Hadoken Passo Veloz", tgt="Hadoken Passo Veloz", desc="Entregue com as outras missões quando passar por Orgrimmar na etapa de Tanaris."}, [14]={npc="Rok Orhan", tgt="Rok Orhan", desc="Guarde para entregar em Orgrimmar na etapa de Tanaris."}, [15]={text="Rage Scar Yetis e a viagem de volta"}, [16]={hint="Leve 10 Pelegos de Yeti Cortifúria para Jangdor Passo Veloz na Aldeia Mojache, em Feralas.", desc="Siga a estrada para oeste até Bastilha Cortifúria (55.73, 33.05). Colete dez peles."}, [17]={npc="Pelego Perfeito de Yeti", npcObj=true, tag="Opcional", desc="Aceite apenas se um Yeti Cortifúria descartar o Pelego imaculado de Yeti."}, [18]={text="Terminados os yetis, use a Pedra de Regresso para voltar a Aldeia Mojache; se ela ainda estiver em recarga, volte a pé pela estrada principal. Depois de entregar, voe para Geringontzan."}, [19]={npc="Jangdor Passo Veloz", tgt="Jangdor Passo Veloz"}, [20]={npc="Jangdor Passo Veloz", tgt="Jangdor Passo Veloz", tag="Opcional"}}},
    ["05-d20"] = {name="Maraudon", entrance="Desolação 29.10, 62.50", pickup="Antes de ir a Aldeia Pescassombra, em Desolação, dá para pegar Fragmentos de lascanegra com Uthel'nay em Orgrimmar, mas só a partir do nível 39. Ao sair da Aldeia Mojache para Aldeia Pescassombra, fale primeiro com Warug e Selendra, depois passe por Faia e pelos Centauros Párias. Para a cadeia dos frascos de água da versão Eternal, vá primeiro ao sudeste de Shen'dralas e faça as torres de cristal e a introdução do Magister; depois pegue Word of the Woods → Rot and Regret no Jardim Esquecido. As missões de Shen'dralas exigem nível 35. Pegue Cavindra antes da porta laranja de Maraudon.", pickupS={{"Antes de ir a Aldeia Pescassombra, em Desolação, dá para pegar Fragmentos de lascanegra com Uthel'nay em Orgrimmar, mas só a partir do nível 39"}, {"Ao sair da Aldeia Mojache para Aldeia Pescassombra, fale primeiro com Warug e Selendra, depois passe por Faia e pelos Centauros Párias"}, {"Para a cadeia dos frascos de água da versão Eternal, vá primeiro ao sudeste de Shen'dralas e faça as torres de cristal e a introdução do Magister; depois pegue Word of the Woods → Rot and Regret no Jardim Esquecido"}, {"As missões de Shen'dralas exigem nível 35"}, {"Pegue Cavindra antes da porta laranja de Maraudon"}}, tips={{k="動線", text="Linha laranja: Tóxxico e Azorrague. Linha roxa: Lorde Torpelíngua. Colete estátuas, joias de khan e outros itens de missão pelo caminho → com os drops das duas linhas completos, vá ao ponto de encontro e fale com Celebras; acompanhe o ritual do cetro → Cachoeiras do Canção Telúrica → a Princesa → piscina de Putrigarra (opcional)."}, {k="取捨", text="Para pegar o cetro na primeira corrida, faça as duas linhas, laranja e roxa. Se quiser só a princesa e o crocodilo, quem do grupo tiver o cetro pode entrar direto na ala interna. Se a missão exigir criaturas sombrias fora da masmorra ou outro ramo, não pule pelo atalho."}, {k="說明", text="29.10, 62.50 é a entrada da caverna, ao ar livre; para achar os dois portais da masmorra, o laranja e o roxo, siga o túnel da cor correspondente. O caminho roxo e o laranja se encontram perto da cachoeira de água envenenada.", s={{"29.10, 62.50 é a entrada da caverna, ao ar livre; para achar os dois portais da masmorra, o laranja e o roxo, siga o túnel da cor correspondente"}, {"O caminho roxo e o laranja se encontram perto da cachoeira de água envenenada"}}}}, steps={[1]={npc="Uthel'nay", tgt="Uthel'nay"}, [2]={npc="Vark Chaga de Guerra", tgt="Vark Chaga de Guerra"}, [3]={npc="Selendra", tgt="Selendra"}, [4]={npc="Faia", tgt="Faia"}, [5]={npc="Centauro Pária", tgt="Centauro Pária", desc="O Centauro Pária patrulha o sul de Desolação."}, [6]={npc="Pilar de Shen'dralar", npcObj=true, tag="Opcional"}, [7]={hint="Explore Shen'dralas para tentar encontrar outros pilares como o primeiro.", tag="Opcional"}, [8]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional"}, [9]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional", preText="Pilares estranhos"}, [10]={hint="Recupere estilhaços e fragmentos dos pilares, que estão protegidos nas aldeias dos Magram e dos Gelkis. Leve-os de volta a Morden Sombracerta.", tag="Opcional", desc="As coordenadas são, em ordem, os dois itens nas aldeias de centauros Magram e Gelkis."}, [11]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional"}, [12]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional", desc="Verifique no registro de missões a quantidade de mana necessária.", preText="Fragmentos dos pilares"}, [13]={hint="Acquire the Mana Sieve from within the temple in Shen'dralas and use it to collect Ancient Mana Crystals. Once you have acquired enough mana, empower the pylons and return to Mordent Evenshade.", tag="Opcional", desc="A quantidade de mana depende do seu diário de missões. Pegue a peneira no andar mais alto do templo e reúna 8 de mana no total, 4 por torre. As torres oeste e leste podem ser usadas em furtividade."}, [14]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional", desc="Verifique no registro de missões a quantidade de mana necessária."}, [15]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional", preText="Powering the Pylons"}, [16]={hint="Speak with Mordent Evenshade in Shen'dralas for information about the crystals you repaired.", tag="Opcional"}, [17]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional"}, [18]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional", preText="A Brief History Lesson"}, [19]={hint="Locate Magister Kirandis inside the temple of Shen'dralas.", tag="Opcional"}, [20]={npc="Magister Kirandis", tgt="Magister Kirandis", tag="Opcional"}, [21]={npc="Mithera", tgt="Mithera", tag="Opcional", preText="Meeting the Magister"}, [22]={hint="Investigate the Forlorn Gardens near Shen'dralas and then return to Mithera at the nearby temple.", tag="Opcional"}, [23]={npc="Mithera", tgt="Mithera", tag="Opcional"}, [24]={npc="Mithera", tgt="Mithera", tag="Opcional", preText="Forlorn Gardens"}, [25]={npc="Woodwyrd", tgt="Woodwyrd", tag="Opcional"}, [26]={npc="Woodwyrd", tgt="Woodwyrd", tag="Opcional", desc="Entregue Word of the Woods primeiro. Traga isso para o Maraudon interno.", preText="Word of the Woods"}, [27]={npc="Cavindra", tgt="Cavindra", desc="Cavindra está fora do portal laranja. Saqueie um item do chefe de cada lado."}, [28]={hint="Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para Uthel'nay, em Orgrimmar."}, [29]={text="Entrada: Maraudon"}, [30]={text="Lado laranja: Caverna Esporelama (45-53). Procure por cristais laranja e pela piscina no fundo da caverna. Preencha o frasco antes de entrar no portal."}, [31]={hint="Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon.", desc="Local: Encha o frasco na piscina fora do portal laranja. Encontre vinhas dentro.", spot="Encha o frasco na piscina fora do portal laranja. Encontre vinhas dentro."}, [32]={text="Lado roxo: Wicked Grotto (45-53). Pegue a passagem de cristal roxo na bifurcação de três vias. Saqueie o diamante de Lorde Torpelíngua."}, [33]={hint="Colete 25 Entalhes de Cristal Terádrico para Faia, na Desolação.", desc="Guie-se pela quantidade do seu diário de missões. Local: Mate primeiro os centauros nas cavernas externas laranja e roxa e, depois de entrar, saqueie as estátuas por todo o caminho.", spot="Mate centauros fora de ambos os portais e saqueie estátuas conforme avança."}, [34]={hint="Leia as Instruções do Pária. Depois, obtenha em Maraudon o Amuleto da União e devolva-o ao Centauro Pária, na parte sul de Desolação.", desc="O primeiro fica entre as linhas laranja e roxa. O segundo e o terceiro ficam nas passagens fora das portas. O quarto e o quinto ficam atrás das portas laranja e roxa, cada um em patrulha. Local: Encontre os três primeiros na bifurcação laranja e roxa e nas duas cavernas externas, e um atrás de cada porta.", spot="Encontre os três primeiros khans na bifurcação laranja/roxa e nas duas cavernas externas, depois um dentro de cada portal."}, [35]={hint="Recupere as duas partes do Cetro de Celebras: o Bastão de Celebras e o Diamante de Celebras.", desc="Local: Pegue a varinha na linha laranja e o diamante na roxa e lute com Celebras no ponto de encontro. Ordem: É preciso passar pelas linhas laranja e roxa. Só entregue quando tiver todos os materiais.", spot="Pegue a varinha na linha laranja e o diamante na roxa. Mate Celebras no ponto de encontro."}, [36]={npc="Celebras, o Redimido", tgt="Celebras, o Redimido", desc="Depois de derrotar o chefe, fale com Celebras, o Redimido. Depois da derrota, entregue ao Redimido na sala.", spot="Na sala do chefe Celebras: Celebras, o Redimido"}, [37]={npc="Celebras, o Redimido", tgt="Celebras, o Redimido", desc="O Redimido está na sala do chefe; siga-o durante o ritual.", preText="Lendas de Maraudon"}, [38]={hint="Ajude Celebras, o Redimido, a criar o Cetro de Celebras.", desc="O Redimido está na sala do chefe. Siga-o durante o ritual. Local: Sala do chefe de Celebras: siga o Redimido durante todo o ritual.", spot="Siga Celebras, o Redimido através do ritual na sala do chefe."}, [39]={npc="Celebras, o Redimido", tgt="Celebras, o Redimido", desc="O Redimido está na sala do chefe; siga-o durante o ritual.", spot="Na sala do chefe Celebras: Celebras, o Redimido"}, [40]={text="Rota interna: Cachoeiras do Canção Telúrica (48-57). Desça da junção laranja/roxa ou faça com que um jogador com o cetro abra o atalho."}, [41]={hint="Matar: Woodwyrd", tag="Opcional", desc="Rotgrip patrulha a poça. A pequena fonte fica na superfície da mesma poça. Local: Pule na poça de Rotgrip abaixo da caverna da Princesa e procure a fonte na superfície da água. Ordem: Você pode fazer primeiro a etapa \"Corrupção da terra e dos grãos\" e depois entrar na água.", spot="Pule na piscina de Putrigarra, abaixo da caverna da Princesa. Encontre a fonte na superfície da água."}, [42]={hint="Mate a Princesa Theradras e fale novamente com Selendra perto da Aldeia Pescassombra, na Desolação.", desc="Local: Siga pelas Cachoeiras do Canção Telúrica até a caverna de Zaetar e chegue à plataforma da Princesa.", spot="Siga pelas Cachoeiras do Canção Telúrica até a caverna de Zaetar e chegue à plataforma da Princesa."}, [43]={npc="Espírito de Zaetar", tgt="Espírito de Zaetar", desc="O espírito de Zaetar aparece depois que a princesa Theradras morre. Pegue a missão agora e entregue fora da masmorra."}, [44]={npc="Selendra", tgt="Selendra"}, [45]={npc="Vark Chaga de Guerra", tgt="Vark Chaga de Guerra"}, [46]={npc="Faia", tgt="Faia"}, [47]={npc="Centauro Pária", tgt="Centauro Pária"}, [48]={npc="Uthel'nay", tgt="Uthel'nay"}, [49]={hint="Matar: Woodwyrd", tag="Opcional"}, [50]={npc="Woodwyrd", tgt="Woodwyrd", tag="Opcional"}, [51]={hint="Procure Remulos, na Clareira da Lua, e entregue a ele a Semente da Vida.", desc="Guarde para quando passar pela Clareira da Lua."}, [52]={npc="Guardião Remulos", tgt="Guardião Remulos", desc="Pode esperar até a Clareira da Lua."}}},
    ["04-33"] = {name="Tanaris: acampamento Fúria-da-areia", nameA="Tanaris: {a:976} & acampamento Fúria-da-areia", shortA="Tanaris: {a:976} +", tips={{k="取捨", text="Depois de entregar no poço ao norte, desbloqueie o Covil Nóxio. Entregue o Covil Nóxio para desbloquear A redenção de Anilhacido; depois faça juntos Complexo Dunamalho, Vale Moitagulhas e a colmeia de silitídeos ao sul."}, {k="取捨", text="Se tiver grupo, faça Zul'Farrak e as quatro missões de masmorra de uma vez. Sem grupo, pule as quatro e também O ovo velho."}, {k="取捨", text="Entregue primeiro A ameaça dos silitídeos e O relatório dos Zukk'ash. A marcha dos silitídeos exige nível 50. Se já tiver atingido, confira no Bazar; deixe a continuação completa para Geringontzan, em Tanaris, e Pilar Partido."}, {k="提醒", text="Antes do nível 50, há muitos ogros normais em Complexo Dunamalho (40.75,50.67) e eles soltam tecido. Se quiser upar na Garganta Abrasadora, deixe um pouco de XP para ganhar lá.", s={{"Antes do nível 50, há muitos ogros normais em Complexo Dunamalho (40.75,50.67) e eles soltam tecido"}, {"Se quiser upar na Garganta Abrasadora, deixe um pouco de XP para ganhar lá"}}}}, danger={[1]="A entrada da colmeia Centipaar facilita puxar vários de uma vez. Lute só no espaço aberto fora da colmeia e não persiga um mob para dentro do túnel estreito."}, grind={[1]={mob="Brutamontes Dunamalho", note="Mobs corpo a corpo comuns e numerosos fora de Complexo Dunamalho; dropam tecido e coincidem com as missões dos ogros. Se o acampamento estiver ocupado, continue andando pela borda."}, [2]={mob="Enxameador Centiparte", note="Mobs comuns densos e de nível mais alto fora da colmeia de silitídeos a oeste. Puxe um de cada vez perto da entrada. Evite grupos nos túneis estreitos."}}, supply={[1]={npc="Bulkrek Iracarpos"}, [2]={npc="Estalajadeiro Gabor Bulho"}, [3]={npc="Dobrov A. Massoaço"}, [4]={npc="Estalajadeiro Gabor Bulho"}, [5]={npc="Blizricco Sciumbigno"}}, steps={[1]={text="Voe da Aldeia Mojache para Geringontzan."}, [2]={text="Vincule temporariamente a Pedra de Regresso na estalagem de Geringontzan (52.51, 27.91).", bindA="{a:976}"}, [3]={text="Pegue tudo em Geringontzan e depois vá ao oeste para terminar a amostra de água e Investigação no Covil Nóxio"}, [4]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}, [5]={npc="Marin Nublacuca", tgt="Marin Nublacuca"}, [6]={npc="Andi Lynn", tgt="Andi Lynn"}, [7]={npc="Tran'rek", tgt="Tran'rek"}, [8]={npc="Quim", tgt="Quim", tag="Opcional", desc="Saqueie restos do deserto se você passar por eles."}, [9]={hint="Use o treco de coleta vazio junto à poça d'água perto do Posto Silitriste. Depois que você coletar a amostra, leve o treco de coleta cheio para o Topógrafo Sênior Secamolha em Geringontzan.", desc="Use o Treco de Coleta Vazio na poça do Posto Silitriste. Volte para a cidade assim que tiver a amostra."}, [10]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}, [11]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}, [12]={hint="Leve cinco Pedaços de Inseto Centiparte do Covil Nóxio para o Alquimista Almofarrista em Geringontzan."}, [13]={npc="Alquimista Almofarrista", tgt="Alquimista Almofarrista"}, [14]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}, [15]={text="Sul: Complexo Dunamalho e Vale Moitagulhas, depois siga pelo sopé até a colmeia de silitídeos"}, [16]={hint="Andi Lynn em Geringontzan quer que você destrua o Complexo Dunamalho. Para isso, deve matar 10 Brutamontes Dunamalho, 10 Impositores Dunamalho e Gor'marok, o Assolador."}, [17]={hint="O Chefe de Segurança Silvadágua do Porto de Bondebico, em Tanaris, quer que você um recupere bracelete particularmente brilhante que foi perdido próximo ao complexo ôgrico de Dunamalho.", desc="Faça apenas se tiver pegado em Porto de Bondebico ou Geringontzan."}, [18]={hint="Colete uma Glândula de Orvalho Cheia e leve para Marin Nublacuca em Geringontzan.", desc="Mate coletores de orvalho no Vale Moitagulhas e pegue 1 glândula de orvalho cheia."}, [19]={hint="Tran'rek, em Geringontzan, quer que você mate 8 Moitagulhas Rotos e 8 Fazraízes Moitagulhas."}, [20]={npc="Tuga", tgt="Tuga", tag="Escolta", desc="Escolta de nível 50: enquanto Tuga estiver seguindo você, não dá para usar montaria nem a Pedra de Regresso, e é preciso ir andando até Porto de Bondebico; se estiver com pressa, pule."}, [21]={hint="Descubra qual foi a sina do Topógrafo Júnior Caranduru, e leve ele ou seus equipamentos de topografia para o Topógrafo Sênior Secamolha, em Geringontzan.", desc="Vá para o subsolo na fenda sul para encontrar Aparelho de Inspeção do Anilhacido."}, [22]={hint="Quinn wants you to recover 7 pieces of Desert Debris and return to her in Gadgetzan.", tag="Opcional", desc="A sucata pode vir das missões da Aliança; se não aparecer, procure ao redor de Geringontzan."}, [23]={text="Volte a Geringontzan para entregar as missões. Use a Pedra de Regresso se estiver disponível; de passagem, pegue Gosto não se discute e Análise de pedaços de inseto."}, [24]={npc="Andi Lynn", tgt="Andi Lynn"}, [25]={npc="Tran'rek", tgt="Tran'rek"}, [26]={npc="Marin Nublacuca", tgt="Marin Nublacuca"}, [27]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}, [28]={npc="Quim", tgt="Quim", tag="Opcional"}, [29]={npc="Marin Nublacuca", tgt="Marin Nublacuca"}, [30]={hint="Marin Nublacuca quer que você fale com Sguisha em Geringontzan."}, [31]={npc="Sguisha", tgt="Sguisha"}, [32]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}, [33]={hint="Veja se o Alquimista Almofarrista em Geringontzan já terminou a análise dos pedaços de inseto."}, [34]={npc="Alquimista Almofarrista", tgt="Alquimista Almofarrista"}, [35]={npc="Alquimista Almofarrista", tgt="Alquimista Almofarrista"}, [36]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}, [37]={npc="Sguisha", tgt="Sguisha", desc="Colha Tragão Violeta no Lago Valovento, nas Terras Agrestes, e depois volte a Geringontzan para entregar."}, [38]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha", desc="Entregue ao passar pelo Bazar, em Orgrimmar; conclua os pré-requisitos junto com O relatório dos Zukk'ash."}, [39]={text="Porto de Bondebico e Zul'Farrak opcionais"}, [40]={npc="Yeh'kinya", tgt="Yeh'kinya", desc="Requer os três Espíritos guinchadores da perna Aldeia Mojache."}, [41]={npc="Chefe de Segurança Silvadágua", tgt="Chefe de Segurança Silvadágua"}, [42]={npc="Tarta", tgt="Tarta"}, [43]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Grupo recomendado, Opcional", desc="Com Espíritos guinchadores já entregue, aceite só se tiver um grupo para Zul'Farrak."}, [44]={hint="Leve a Primeira e a Segunda Tabuleta Mosh'Aru para Yeh'kinya, em Tanaris.", tag="Grupo recomendado, Opcional"}, [45]={hint="Leve 5 Couraças de Escaravelho Fechadas para Tran'rek em Geringontzan.", tag="Opcional", desc="Limpe os escaravelhos no cemitério Zul'Farrak."}, [46]={hint="Leve o Bastão Divinomático ao Engenheiro-chefe Silvadágua em Geringontzan.", tag="Grupo recomendado, Opcional", desc="Conclua o evento da escada. Pegue o bastão do Sargento Bly."}, [47]={hint="Leve 20 Frascos de Têmpera de Troll para Trenton Lumartelo em Geringontzan.", tag="Opcional"}, [48]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Grupo recomendado, Opcional"}, [49]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Opcional", desc="Só aceite se já tiver entregado A profecia de Mosh'aru. O Ovo Velho pode ser pego nas Terras Agrestes; depois volte ao porto para entregar."}, [50]={npc="Tran'rek", tgt="Tran'rek", tag="Opcional"}, [51]={npc="Engenheiro-chefe Silvadágua", tgt="Engenheiro-chefe Silvadágua", tag="Grupo recomendado, Opcional", star={"Anel da Confraria Maçom", {"ROGUE", "HUNTER", "DRUID"}}}, [52]={npc="Trenton Lumartelo", tgt="Trenton Lumartelo", tag="Opcional"}, [53]={text="Se tiver Charada do Cortello, voe primeiro de Geringontzan para Aldeia Muralha Verde, vá ao sul até a Toca de Sangrebrejo, no Pântano Vadeoso, para entregar e depois voe de Aldeia Muralha Verde para Orgrimmar.", tag="Opcional"}, [54]={hint="Resolva a charada.", tag="Opcional", desc="O Pergaminho Mofado está em cima de uma pedra dentro da caverna dos raptores."}, [55]={npc="Pergaminho Mofado", npcObj=true, tag="Opcional"}, [56]={npc="Pergaminho Mofado", npcObj=true, tag="Opcional"}, [57]={text="Quem fez a missão secundária da Aldeia Muralha Verde já está em Orgrimmar; faça direto as entregas da cidade. Os demais voam de Geringontzan para Orgrimmar. Vá primeiro ao Bazar procurar Zilzibin Tamborleiro e depois à cabana de Bosque Negro para entregar o Orbe Gordunni."}, [58]={npc="Zilzibin Tamborleiro", tgt="Zilzibin Tamborleiro"}, [59]={npc="Zilzibin Tamborleiro", tgt="Zilzibin Tamborleiro"}, [60]={npc="Uthel'nay", tgt="Uthel'nay"}}},
    ["05-d22"] = {name="Alcaz Prison", entrance="Pântano Vadeoso 75.30, 14.10", pickup="Na Tanaris: acampamento Fúria-da-areia, depois de entregar em Orgrimmar e antes de voar a Vila Catraca para atravessar o mar até a Garganta Abrasadora, vá ao salão de Thrall, no Vale da Sabedoria, em Orgrimmar, e aceite The Missing Kor'kron de Eitrigg (34.28, 39.35). Depois voe para a Aldeia Muralha Verde e procure Nazeer Lançasangrenta. Nade pela costa nordeste até a Ilha de Alcaz e procure o sargento do lado da ilha para entregar The Elite of the Elite e Right Place, Wrong Time em ordem; depois de aceitar No Orc Left Behind, entre no subsolo da torre da ilha. Deixe Thrall Needs to Know para entregar na próxima vez que voltar a Orgrimmar.", pickupS={{"Na Tanaris: acampamento Fúria-da-areia, depois de entregar em Orgrimmar e antes de voar a Vila Catraca para atravessar o mar até a Garganta Abrasadora, vá ao salão de Thrall, no Vale da Sabedoria, em Orgrimmar, e aceite The Missing Kor'kron de Eitrigg (34.28, 39.35)"}, {"Depois voe para a Aldeia Muralha Verde e procure Nazeer Lançasangrenta"}, {"Nade pela costa nordeste até a Ilha de Alcaz e procure o sargento do lado da ilha para entregar The Elite of the Elite e Right Place, Wrong Time em ordem; depois de aceitar No Orc Left Behind, entre no subsolo da torre da ilha"}, {"Deixe Thrall Needs to Know para entregar na próxima vez que voltar a Orgrimmar"}}, tips={{k="動線", text="Encontre Comandante Folkar nas células superiores → mate Feitor Wrex para obter a chave → limpe O Questionador e Senhora das Marés Ca'zass, saqueando bandanas → abra as células inferiores para Katerina, a Faxineira e Rugequeima → leia a nota na sala escondida e volte para Folkar no andar de cima."}, {k="取捨", text="Priorize a cadeia de resgate dos Kor'kron, de The Missing Kor'kron a Thrall Needs to Know. Se não juntou todos os turbantes em uma volta, adie a entrega. Ao sair da masmorra, voe da Aldeia Muralha Verde para Orgrimmar, entregue a Thrall e Eitrigg na mesma ida e então voe para Vila Catraca para cruzar o mar até a Garganta Abrasadora."}, {k="說明", text="Evite Theramore. Vá de Aldeia Muralha Verde até a costa nordeste e nade. O sargento está perto da ilha e o portal da masmorra fica no corredor sob a torre.", s={{"Evite Theramore"}, {"Vá de Aldeia Muralha Verde até a costa nordeste e nade"}, {"O sargento está perto da ilha e o portal da masmorra fica no corredor sob a torre"}}}}, steps={[1]={npc="Eitrigg", tgt="Eitrigg", desc="Aos 48, encontre Eitrigg no corredor de Thrall no Vale da Sabedoria."}, [2]={hint="Speak with Nazeer Bloodspike in Brackenwall Village."}, [3]={npc="Nazir Piquessangue", tgt="Nazir Piquessangue"}, [4]={npc="Nazir Piquessangue", tgt="Nazir Piquessangue", preText="The Missing Kor'kron"}, [5]={hint="Find the missing Kor'kron Elites."}, [6]={npc="Sergeant Ulka", tgt="Sergeant Ulka"}, [7]={npc="Sergeant Ulka", tgt="Sergeant Ulka", preText="The Elite of the Elite"}, [8]={npc="Sergeant Ulka", tgt="Sergeant Ulka"}, [9]={npc="Sergeant Ulka", tgt="Sergeant Ulka", preText="Right Place, Wrong Time"}, [10]={npc="Sergeant Ulka", tgt="Sergeant Ulka", tag="Opcional", desc="De passagem, conclua primeiro The Missing Kor'kron-Right Place, Wrong Time, de Orgrimmar até o lado da ilha, e depois confira a lista de missões do sargento."}, [11]={npc="Sergeant Ulka", tgt="Sergeant Ulka", tag="Opcional", desc="Só aceite se conseguir ver a missão; faça primeiro The Missing Kor'kron-Right Place, Wrong Time."}, [12]={text="Entrada: Alcaz Prison"}, [13]={hint="Enter the Alcaz Prison and find Commander Folkar.", desc="Local: Vá para o corredor superior e encontre Comandante Folkar em uma cela.", spot="Vá para o corredor superior e encontre Comandante Folkar em uma cela."}, [14]={npc="Commander Folkar", spot="Cela no corredor superior: Comandante Folkar"}, [15]={npc="Commander Folkar", preText="No Orc Left Behind"}, [16]={hint="Enter the Alcaz Prison and slay 15 Strashasz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sergeant Ulka.", tag="Opcional", desc="Local: Encontre Senhora das Marés Ca'zass pelas células superiores. Limpe as nagas ao longo do corredor.", spot="Encontre Senhora das Marés Ca'zass pelas células superiores. Limpe as nagas ao longo do corredor."}, [17]={hint="Enter Alcaz Prison and collect 8 Blood Red Bandanas from the human guards there.", tag="Opcional", desc="Pode ser preciso mais uma volta. Confira a quantidade antes de sair da masmorra. Local: Mate primeiro os guardas humanos do corredor superior da prisão e complete pelo caminho.", spot="Mate primeiro os guardas humanos no corredor da prisão superior e complete os itens pelo caminho."}, [18]={hint="Look for King Varian Wrynn in Alcaz Prison.", desc="Local: Abra a porta inferior e mate o último chefe; depois entre na câmara dos fundos e procure o bilhete no chão. Ordem: Pegue primeiro a chave com o carcereiro.", spot="Abra a porta inferior e mate o último chefe. Encontre a nota na sala escondida."}, [19]={npc="Objeto de missão", npcObj=true, spot="Bilhete no chão da sala secreta atrás de Blazeroar"}, [20]={npc="Objeto de missão", npcObj=true, preText="The Honor of the Kor'kron"}, [21]={hint="Report back to Commander Folkar.", desc="Local: Volte da câmara do último chefe ao nível superior e retorne à cela original para entregar ao comandante. Ordem: Leia primeiro o bilhete da etapa \"The Honor of the Kor'kron\".", spot="Retorne da sala escondida do último chefe para o comandante em sua cela superior."}, [22]={npc="Commander Folkar", spot="Cela no corredor superior: Comandante Folkar"}, [23]={npc="Commander Folkar", preText="Bad News for Folkar"}, [24]={npc="Sergeant Ulka", tgt="Sergeant Ulka", tag="Opcional"}, [25]={npc="Thrall", tgt="Thrall"}, [26]={npc="Eitrigg", tgt="Eitrigg", tag="Opcional"}}},
    ["05-d21"] = {name="Zul'Farrak", entrance="Tanaris 38.70, 20.00", pickup="Faça as três missões locais em Geringontzan e depois pegue Espíritos guinchadores com Yeh'kinya em Porto de Bondebico. Colete os espíritos em Feralas. De volta a Tanaris, passe primeiro em Porto de Bondebico para entregar Espíritos guinchadores e pegar A profecia de Mosh'aru, e depois encontre o grupo em Geringontzan. Pegue Gahz'rilla ao passar por Chapada Cintilante, em Mil Agulhas. Antes de ir ao Pântano das Mágoas, magos podem dar um desvio pelo Pântano Vadeoso para a missão paralela de Tabetha (só magos).", pickupS={{"Faça as três missões locais em Geringontzan e depois pegue Espíritos guinchadores com Yeh'kinya em Porto de Bondebico"}, {"Colete os espíritos em Feralas"}, {"De volta a Tanaris, passe primeiro em Porto de Bondebico para entregar Espíritos guinchadores e pegar A profecia de Mosh'aru, e depois encontre o grupo em Geringontzan"}, {"Pegue Gahz'rilla ao passar por Chapada Cintilante, em Mil Agulhas"}, {"Antes de ir ao Pântano das Mágoas, magos podem dar um desvio pelo Pântano Vadeoso para a missão paralela de Tabetha (só magos)"}}, tips={{k="動線", text="Desvio do Antu'sul → primeira tabuleta de Mosh'aru na sala de escaravelhos do Theka → cemitério do Zum'rah → evento da escadaria da pirâmide → segunda tabuleta e Bastão divinomático com Velratha (Gahz'rilla opcional na piscina) → Ukorz. Recolha conchas de escaravelho e Têmpera de troll pelo caminho."}, {k="取捨", text="Priorize as três missões de Geringontzan e as tabuletas de Mosh'aru. Enfrente Gahz'rilla se já tiver a marreta. Deixe a de Tabetha para quem passar pelo Pântano Vadeoso."}, {k="說明", text="Dá para fazer uma vez entre Porto de Bondebico e Geringontzan. Se for fazer a cadeia completa de Yeh'kinya, espere até passar por Geringontzan e pelo Complexo Dunamalho. As tabuletas de Mosh'aru também são pré-requisito da cadeia de Hakkar.", s={{"Dá para fazer uma vez entre Porto de Bondebico e Geringontzan"}, {"Se for fazer a cadeia completa de Yeh'kinya, espere até passar por Geringontzan e pelo Complexo Dunamalho"}, {"As tabuletas de Mosh'aru também são pré-requisito da cadeia de Hakkar"}}}}, steps={[1]={npc="Engenheiro-chefe Silvadágua", tgt="Engenheiro-chefe Silvadágua"}, [2]={npc="Tran'rek", tgt="Tran'rek"}, [3]={npc="Trenton Lumartelo", tgt="Trenton Lumartelo"}, [4]={npc="Yeh'kinya", tgt="Yeh'kinya", desc="Pegue em Porto de Bondebico e depois faça Feralas. Pegue A profecia de Mosh'aru depois de entregá-lo."}, [5]={hint="Capture os espíritos de 3 guinchadores em Feralas, e depois fale novamente com Yeh'kinya no Porto de Bondebico."}, [6]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [7]={npc="Yeh'kinya", tgt="Yeh'kinya", preText="Espíritos guinchadores"}, [8]={npc="Capu Latafuso", tgt="Capu Latafuso", tag="Opcional", desc="Pelo menos uma pessoa do grupo deve levar o Martelo de Gahz'rilla para garantir que dê para tocar o gongo. Se for passar antes por Terras Agrestes, pegue o Martelo Sagrado no altar de Zul e transforme-o no altar de Jintha'Alor."}, [9]={npc="Tabetha", tgt="Tabetha", tag="Opcional", desc="Tabetha oferece a missão diretamente. A missão A tarefa de Tabetha de Cidade Baixa, nível 40, é uma indicação opcional que pode ser ignorada."}, [10]={text="Entrada: Zul'Farrak"}, [11]={hint="Leve 5 Couraças de Escaravelho Fechadas para Tran'rek em Geringontzan.", desc="Local: Vá à sala de Theka, o Mártir, e limpe os escaravelhos próximos. Ordem: ao limpar os escaravelhos, mate também Theka e pegue a primeira tabuleta.", spot="Mate escaravelhos ao redor da sala de Theka, o Mártir."}, [12]={hint="Leve 20 Frascos de Têmpera de Troll para Trenton Lumartelo em Geringontzan.", desc="Combine antes a divisão com o grupo; uma única volta pode não bastar para o saque. Local: Desde a entrada, limpe os trolls Zangareia de cada área pela estrada principal.", spot="Elimine os trolls Sandfury ao longo da rota principal desde a entrada."}, [13]={hint="Leve a Tiara das Profundezas para Tabetha no Pântano Vadeoso.", tag="Opcional", desc="Local: Passe pela área do evento da pirâmide e siga até a piscina para encontrar Velratha. Ordem: ao matar Velratha, pegue também a Coroa do Abismo e a segunda tabuleta.", spot="Passe pela pirâmide e encontre Velratha na piscina."}, [14]={hint="Leve a Escama Eletrificada de Gahz'rilla para Capu Latafuso no Salar Cintilante.", tag="Opcional", desc="Local: Bata o gongo na margem da poça ao lado de Velratha e espere Gahz'rilla aparecer. Ordem: Limpe primeiro Velratha na mesma área e depois bata o gongo.", spot="Toque o gongo perto da piscina de Velratha para invocar Gahz'rilla."}, [15]={hint="Leve o Bastão Divinomático ao Engenheiro-chefe Silvadágua em Geringontzan.", desc="Abra primeiro a jaula para concluir o evento da escada, limpe as ondas de baixo e depois vire contra eles. Local: Siga a estrada principal até o topo da pirâmide, abra a jaula e segure as ondas na escada. Ordem: Só desafie o Sargento Bly depois de segurar todas as ondas.", spot="Abra as gaiolas no topo da pirâmide. Desça as escadas e segure as ondas."}, [16]={hint="Leve a Primeira e a Segunda Tabuleta Mosh'Aru para Yeh'kinya, em Tanaris.", desc="Local: Theka fica na sala dos escaravelhos e Velratha junto à piscina; cada um solta uma tabuleta.", spot="Theka fica na sala dos escaravelhos e Velratha junto à piscina; cada um solta uma tabuleta."}, [17]={npc="Tran'rek", tgt="Tran'rek"}, [18]={npc="Trenton Lumartelo", tgt="Trenton Lumartelo"}, [19]={npc="Engenheiro-chefe Silvadágua", tgt="Engenheiro-chefe Silvadágua"}, [20]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [21]={npc="Yeh'kinya", tgt="Yeh'kinya", desc="Só pegue e guarde por enquanto. Pegue o ovo em Jintha'Alor antes de entrar no Templo de Atal'Hakkar.", preText="A profecia de Mosh'aru"}, [22]={npc="Capu Latafuso", tgt="Capu Latafuso", tag="Opcional"}, [23]={npc="Tabetha", tgt="Tabetha", tag="Opcional"}}},
    ["04-34"] = {name="Garganta Abrasadora", nameA="Garganta Abrasadora: {a:1446}", tips={{k="交通", text="Desbloqueie primeiro o ponto de voo da Horda no Posto de Tório, voe depois para a Serraria Tarren e então aceite Terras Agrestes."}, {k="取捨", text="Conclua os quatro objetivos de morte em um loop. Se você estiver com poucos drops para OBJETOS ROUBADOS: Alcaraviz de Ferraria e Luneta do Espia, entregue os outros primeiro. Faça PROCURA-SE: Feitor Maltorius e Segue o fluxo na mesma caverna se você tiver um grupo."}, {k="取捨", text="Se já estiver no nível 50 depois das entregas no Posto de Tório, pode ir embora. A segunda metade da cadeia da tocha e o Banheiro de Madeira do sudeste exigem, cada um, uma volta extra; faça só se faltar EXP."}, {k="提醒", text="Falta pouco de EXP? Mate Golens de Guerra Pesados a leste do Caldeirão (44.76, 38.72) ou Feitores Dark Iron comuns na encosta norte (41.21, 23.33).", s={{"Falta pouco de EXP?"}, {"Mate Golens de Guerra Pesados a leste do Caldeirão (44.76, 38.72) ou Feitores Dark Iron comuns na encosta norte (41.21, 23.33)"}}}}, danger={[1]="O Feitor Martorius fica no fundo da mina Dark Iron, perto do Fosso de Lava. Limpe os túneis em grupo, etapa por etapa. Se estiver sozinho, pule a recompensa."}, grind={[1]={mob="Golem de Guerra Pesado", note="Golens normais na borda leste do Caldeirão. Fique no alto ao longo da borda e conte as mortes para a missão. Evite o chão se outros jogadores estiverem lá."}, [2]={mob="Capataz Ferro Negro", note="Mobs normais de Dark Iron ao sul de Posto de Tório. Pegue mortes e missões antes de retornar ao ponto de voo. Fique atento aos acréscimos dentro do acampamento."}}, supply={[1]={npc="Grisha"}, [2]={npc="Mestre Ferreiro Queimatar"}, [3]={npc="Mestre Ferreiro Queimatar"}, [4]={npc="Mestre Ferreiro Queimatar"}}, steps={[1]={text="Voe de Orgrimmar para Vila Catraca e vá ao cais para pegar o barco.", tag="Antes de ir para a Garganta Abrasadora, você pode comprar na casa de leilões (ou pedir para um alt enviar) 15 × Seda (para Calça arriada!)."}, [2]={npc="Cáliper Porcatraca", tgt="Cáliper Porcatraca", tag="Opcional"}, [3]={text="Pegue o barco até Angra do Butim e depois voe para Karrath, nos Ermos."}, [4]={text="Pegue a estrada sudoeste de Karrath para Garganta Abrasadora e siga a estrada norte para Posto de Tório."}, [5]={nodeA="{a:1446}", node="Thorium Point", desc="Desbloqueie o ponto de voo da Horda com Grisha."}, [6]={text="Pegue em Posto de Tório e passe pelo Caldeirão e pelo Fosso de Lava"}, [7]={npc="Procurados/Desaparecidos/Achados e Perdidos", npcObj=true}, [8]={npc="Hansel Mão-pesada", tgt="Hansel Mão-pesada"}, [9]={npc="Hansel Mão-pesada", tgt="Hansel Mão-pesada"}, [10]={npc="Hansel Mão-pesada", tgt="Hansel Mão-pesada"}, [11]={npc="Procurados/Desaparecidos/Achados e Perdidos", npcObj=true, tag="Opcional", desc="Pegue os dois itens dropados de passagem, enquanto mata os mobs."}, [12]={npc="Procurados/Desaparecidos/Achados e Perdidos", npcObj=true, tag="Grupo recomendado, Opcional", desc="Martorius é elite. Aceite apenas com um grupo."}, [13]={npc="Mestre Ferreiro Queimatar", tgt="Mestre Ferreiro Queimatar", tag="Opcional", desc="Dá para pegar na mesma passada do grupo de Martorius."}, [14]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [15]={hint="Ouça Kalaran Finalâmina contar a história dele."}, [16]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [17]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [18]={hint="Hansel Mão-pesada quer que você mate 20 Grandes Aranhas de Lava na Garganta Abrasadora. Você pode encontrá-las nos platôs e poços de lava do local."}, [19]={hint="Mate 15 Capatazes Ferro Negro e 15 Feitores Ferro Negro. Depois, fale novamente com Capataz Scrange, na Garganta Abrasadora."}, [20]={hint="Hansel Mão-pesada quer que você mate 20 Golens de Guerra Pesados."}, [21]={hint="Colete 4 Corações das Chamas e 4 globos de Óleo de Golem, e leve-os para Kalaran Finalâmina.", desc="Mate também os golens e os elementais de fogo ao redor do Caldeirão."}, [22]={hint="Encontre e devolva o Alcaraviz de Ferraria e a Luneta do Espia ao Capataz Scrange na Garganta Abrasadora.", tag="Opcional"}, [23]={hint="Hansel Mão-pesada quer que você mate 20 Incendossauros.", desc="Entre na mina do Fosso de Lava e mate Incendossauros; limpe junto com os mobs Dark Iron lá dentro."}, [24]={hint="Em algum lugar do Fosso de Lava do Caldeirão você encontra as Instruções Secretas: Fluxo Ígneo que o Feitor Maltorius roubou. Encontre as instruções e devolva-as ao Mestre Ferreiro Queimatar na Garganta Abrasadora.", tag="Opcional", desc="Procure as plantas perto de Martorius, nas profundezas do Fosso de Lava. Saqueie quando estiver seguro."}, [25]={hint="Nas profundezas do Fosso de Lava do Caldeirão, na Garganta Abrasadora, você encontrará o anão traidor dos Ferro Negro chamado Feitor Maltorius.", tag="Grupo recomendado, Opcional"}, [26]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [27]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina", desc="Aceite se precisar de EXP e estiver disposto a fazer outra viagem ao Caldeirão."}, [28]={hint="Leve 8 Punhais de Placas de Tório para Kalaran Finalâmina.", desc="Dropa dos Feitores e Traficantes de Escravos Dark Iron do Fosso de Lava."}, [29]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [30]={text="Volte para Posto de Tório e entregue todas as missões do Caldeirão juntos."}, [31]={npc="Hansel Mão-pesada", tgt="Hansel Mão-pesada"}, [32]={npc="Capataz Scrange", tgt="Capataz Scrange"}, [33]={npc="Hansel Mão-pesada", tgt="Hansel Mão-pesada"}, [34]={npc="Hansel Mão-pesada", tgt="Hansel Mão-pesada"}, [35]={npc="Capataz Scrange", tgt="Capataz Scrange", tag="Opcional"}, [36]={npc="Mestre Ferreiro Queimatar", tgt="Mestre Ferreiro Queimatar", tag="Opcional"}, [37]={npc="Capitão-vigia Lolo Longalcance", tgt="Capitão-vigia Lolo Longalcance", tag="Grupo recomendado, Opcional"}, [38]={text="EXP extra ou a tocha se você ainda precisar"}, [39]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina", tag="Grupo recomendado, Opcional", desc="Complete Forjando o bastão. Mate mobs Crepúsculo na caverna oeste para o Símbolo de Ragnaros."}, [40]={hint="Encontre e leve um Símbolo de Ragnaros para Kalaran Finalâmina.", tag="Grupo recomendado, Opcional", desc="Complete Forjando o bastão. Mate mobs Crepúsculo na caverna oeste para o Símbolo de Ragnaros."}, [41]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina", tag="Grupo recomendado, Opcional", desc="Complete Forjando o bastão. Mate mobs Crepúsculo na caverna oeste para o Símbolo de Ragnaros."}, [42]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina", tag="Grupo recomendado, Opcional"}, [43]={hint="Espere enquanto Kalaran Finalâmina termina de preparar a Tocha da Retribuição.", tag="Grupo recomendado, Opcional"}, [44]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina", tag="Grupo recomendado, Opcional"}, [45]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [46]={hint="Pegue a Tocha da Retribuição."}, [47]={npc="Tocha da Retribuição", npcObj=true}, [48]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [49]={npc="Escudeiro Maltraque", tgt="Escudeiro Maltraque"}, [50]={npc="Escudeiro Maltraque", tgt="Escudeiro Maltraque", tag="Opcional", desc="Afaste os guardas antes de acender todas as quatro torres."}, [51]={hint="Incendeie as Torres de Sentinela Norte, Sul, Leste e Oeste usando a Tocha da Retribuição dentro de cada prédio.", tag="Opcional", desc="Afaste os guardas antes de acender todas as quatro torres."}, [52]={npc="Escudeiro Maltraque", tgt="Escudeiro Maltraque", tag="Opcional", desc="Afaste os guardas antes de acender todas as quatro torres."}, [53]={npc="Tesouro da Revoada Negra", npcObj=true, tag="Opcional"}, [54]={hint="Abra o baú.", tag="Opcional"}, [55]={npc="Tesouro da Revoada Negra", npcObj=true, tag="Opcional"}, [56]={npc="Banheiro de Madeira", npcObj=true, tag="Opcional", desc="Desvie até o Banheiro de Madeira apenas se for ao sudeste ou se faltar bastante EXP. Prepare antes 15 Seda."}, [57]={hint="Mate 8 Geólogos Ferro Negro e leve 15 pedaços de Seda para a pessoa que está trancada na casinha na Garganta Abrasadora.", tag="Opcional", desc="Desvie até o Banheiro de Madeira apenas se for ao sudeste ou se faltar bastante EXP. Prepare antes 15 Seda."}, [58]={npc="Banheiro de Madeira", npcObj=true, tag="Opcional", desc="Desvie até o Banheiro de Madeira apenas se for ao sudeste ou se faltar bastante EXP. Prepare antes 15 Seda."}}},
    ["04-35"] = {name="Terras Agrestes", nameA="Terras Agrestes: {a:3317} & {a:354}", shortA="Terras Agrestes: {a:3317} +", tips={{k="取捨", text="Faça O grogue perdido do Aldo Isque na mesma praia das missões de tartaruga. Mate as bestas-coruja de Caça às bestas e O teste do recipiente juntas."}, {k="取捨", text="Temos vagas: Capitão da Guarda da Aldeia Revatusco exige matar 80 elites; sem um grupo pronto, pule. Se Jintha'Alor estiver difícil de fazer sozinho, faça primeiro as missões da costa e do interior."}, {k="取捨", text="Entregue O grogue perdido do Aldo Isque em Angra do Butim e O teste do recipiente na Aldeia Mojache; guarde O Ingrediente Secreto de Sguisha e O ovo velho para a parada de Geringontzan e Pilar Partido, em Tanaris."}, {k="提醒", text="Abaixo do nível 52? Dá para ganhar EXP nas Terras Agrestes com as tartarugas e bestas-coruja da costa, ou limpar Jintha'Alor em grupo.", s={{"Abaixo do nível 52?"}, {"Dá para ganhar EXP nas Terras Agrestes com as tartarugas e bestas-coruja da costa, ou limpar Jintha'Alor em grupo"}}}}, danger={[1]="Os andares de cima de Jintha'Alor têm grupos de trolls Vilebranch de elite e curandeiros. Em grupo, limpe a escada um andar de cada vez; sem grupo, fique na costa.", [2]="Gammerita é uma tartaruga de elite que patrulha a costa. Fique de olho nela enquanto mata tartarugas comuns e, se estiver sem grupo, mantenha distância."}, grind={[1]={mob="Mordelisca de Água Salgada", note="Tartarugas normais na praia ao norte de Aldeia Revatusco. Siga a costa, esfole-os e compartilhe a praia com os caçadores de carne de tartaruga. Ignore as elites Jintha'Alor."}}, supply={[1]={npc="Gorkas"}, [2]={npc="Banha"}, [3]={npc="Ferreiro Escoriárvore"}, [4]={npc="Banha"}, [5]={npc="Renn'az"}, [6]={npc="Mística Yayo'jin"}}, steps={[1]={text="Se a Aldeia Revatusco estiver desbloqueada, escolha Aldeia Revatusco no mapa de voo a partir do Posto de Tório e faça baldeação por pontos desbloqueados como Karrath e a Cidade Baixa. Se não, voe primeiro para a Serraria Tarren, entre nas Terras Agrestes pela passagem ao norte do Forte Durnholde, siga a estrada principal a leste e desça pela costa ao sul até a Aldeia Revatusco.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [2]={nodeA="{a:3317}", node="Revantusk Village", desc="Desbloquear o ponto de voo com Gorkas."}, [3]={text="Durante esta etapa, dá para vincular a Pedra de Regresso em Aldeia Revatusco."}, [4]={text="Pegar missões em Aldeia Revatusco → costa"}, [5]={npc="Katum, o Pesqueiro", tgt="Katum, o Pesqueiro"}, [6]={npc="Katum, o Pesqueiro", tgt="Katum, o Pesqueiro", tag="Grupo recomendado, Opcional", desc="Gammerita é uma tartaruga elite de nível 48; se for instável sozinho, não aceite."}, [7]={npc="Guarda-caça Markhor", tgt="Guarda-caça Markhor"}, [8]={npc="Guarda-caça Markhor", tgt="Guarda-caça Markhor"}, [9]={npc="Banha", tgt="Banha"}, [10]={npc="Guarda-caça Markhor", tgt="Guarda-caça Markhor"}, [11]={npc="Primeva Presa-arrancada", tgt="Primeva Presa-arrancada"}, [12]={npc="Primeva Presa-arrancada", tgt="Primeva Presa-arrancada", tag="Grupo recomendado, Opcional", desc="A continuação para recuperar a chave exige matar o Guardião Hitaya, uma elite de nível 51; se for instável sozinho, não aceite a cadeia toda."}, [13]={npc="Guarda-caça Markhor", tgt="Guarda-caça Markhor", tag="Opcional", desc="Faça isso apenas se encontrar um raro grifo Bico Navalha."}, [14]={npc="Ferreiro Escoriárvore", tgt="Ferreiro Escoriárvore", tag="Opcional", desc="Desvio para o templo a nordeste."}, [15]={npc="Chamado às armas!", npcObj=true, tag="Grupo recomendado, Opcional", desc="Elites nos terraços superiores de Jintha'Alor. Aceite quando já tiver um grupo."}, [16]={npc="Chamado às armas!", npcObj=true, tag="Grupo recomendado, Opcional", desc="Pegue apenas se você planeja matar 80 elites em Jintha'Alor.", star={"Runa do Capitão da Guarda", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}}, [17]={hint="Katum, o Pesqueiro, quer que você mate 15 tartarugas Mordeliscas de Água Salgada. Fale novamente com ele na Aldeia Revatusco, que fica nas Terras Agrestes, quando concluir a tarefa."}, [18]={hint="Katum, o Pesqueiro, na Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate Gammerita e apanhe a Melhor Isca de Katum da carcaça.", tag="Grupo recomendado, Opcional", desc="Faça com Mordeliscas, cara! e O grogue perdido do Aldo Isque. Mate o alvo se você avistá-lo."}, [19]={hint="Aldo Isque, na Angra do Butim, quer que você leve para ele as garrafas de Xerez de Pupellyverbos que ele perdeu.", desc="Pegue primeiro em Angra do Butim. Procure a garrafa na praia ao norte da vila."}, [20]={hint="Banha na Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre o Almoço do Banha. Fale novamente com ele quando a tarefa for concluída."}, [21]={hint="Resolva a charada.", tag="Opcional", desc="Só se você já entregou a etapa anterior, O enigma de Cortello, e já aceitou esta. Entregue a etapa anterior no Pergaminho Mofado sobre uma pedra dentro da Toca de Sangrebrejo, no Pântano Vadeoso."}, [22]={npc="Tesouro de Cortello", npcObj=true, tag="Opcional", desc="Pule se você não tiver Charada do Cortello em seu registro de missões."}, [23]={text="Bestas-coruja do interior e lobos Silvermane → altar de Jintha'Alor"}, [24]={hint="O Guarda-caça Markhor da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate 15 Espreitadores Jubaprata e 15 Uivadores Jubaprata. Ao terminar a tarefa, fale novamente com ele."}, [25]={hint="O Guarda-caça Markhor da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate 20 Ferujas Selvagens. Ao terminar a tarefa, fale novamente com ele."}, [26]={hint="Viaje até as Terras Agrestes e localize os Coruscantes. Mate 10 e use o Recipiente de Muisec para encolher e capturar os Coruscantes abatidos.", desc="Pegue na etapa de Aldeia Mojache e Bastilha Cortifúria e entregue em Feralas mais tarde."}, [27]={hint="O Guarda-caça Markhor da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate um Senhor Celeste Bicavalha e tire dele a Pluma de Senhor Celeste. Ao terminar a tarefa, fale novamente com Markhor.", tag="Opcional", desc="Mate-o se você ver."}, [28]={hint="O Ferreiro Escoriárvore, da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre as Ferramentas Perdidas de Escoriárvore. Quando terminar, fale novamente com ele.", tag="Opcional"}, [29]={hint="Sguisha, em Geringontzan, quer que você colete um Tragão Violeta e fale novamente com ela.", desc="Aceite na primeira visita a Geringontzan e Complexo Dunamalho; entregue em Geringontzan."}, [30]={hint="Primeva Presa-arrancada da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre 10 Recipientes com Sangue Maculado em Jintha'Alor. Quando terminar, fale novamente com Primeva Presa-arrancada.", desc="Faça junto com a missão de Ancião Presa-arrancada. Fique atento às patrulhas nas escadas."}, [31]={hint="O Guarda-caça Markhor da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre os restos mortais do irmão gêmeo dele. Encontre o Crânio do Guarda-caça Malkhor e os Ossos do Guarda-caça Malkhor e leve-os para o Guarda-caça Markhor.", desc="Saqueie ambos os itens. Eles estão em locais separados."}, [32]={npc="Ancião Presa-arrancada", tgt="Ancião Presa-arrancada", tag="Grupo recomendado, Opcional"}, [33]={npc="Ancião Presa-arrancada", tgt="Ancião Presa-arrancada", tag="Grupo recomendado, Opcional"}, [34]={hint="O Ancião Presa-arrancada, em Jintha'Alor, quer que você mate Hitah'ya, a Guardiã e pegue a Chave dos Grilhões para soltá-lo. Quando tiver a chave, fale novamente com o Ancião Presa-arrancada.", tag="Grupo recomendado, Opcional", desc="O Guardião Hitaya é uma elite de nível 51."}, [35]={npc="Ancião Presa-arrancada", tgt="Ancião Presa-arrancada", tag="Grupo recomendado, Opcional"}, [36]={npc="Ancião Presa-arrancada", tgt="Ancião Presa-arrancada"}, [37]={hint="Leve o Ovo Velho para Yeh'kinya, em Tanaris.", tag="Opcional", desc="Faça só se a aceitou na parada de Geringontzan e Complexo Dunamalho, em Tanaris; entregue em Porto de Bondebico na próxima vez que estiver em Tanaris."}, [38]={hint="Você recebeu ordens de matar a Sacerdotisa Torpe Bagata e 20 Guardas Aman'zasi Ramatorpe. Quando terminar, procure Primeva Presa-arrancada, na Aldeia Revatusco, que fica nas Terras Agrestes.", tag="Grupo recomendado, Opcional"}, [39]={hint="Você recebeu a missão de dizimar 20 Berserkers Ramatorpe, 20 Caçadores Sombrios Ramatorpe, 20 Bebe-sangue Ramatorpe e 20 Devoradores de Almas Ramatorpe.", tag="Grupo recomendado, Opcional"}, [40]={text="Se a Pedra de Regresso estiver vinculada a Aldeia Revatusco, use-a para voltar e entregar tudo de uma vez."}, [41]={npc="Primeva Presa-arrancada", tgt="Primeva Presa-arrancada"}, [42]={npc="Guarda-caça Markhor", tgt="Guarda-caça Markhor"}, [43]={npc="Primeva Presa-arrancada", tgt="Primeva Presa-arrancada"}, [44]={npc="Katum, o Pesqueiro", tgt="Katum, o Pesqueiro"}, [45]={npc="Katum, o Pesqueiro", tgt="Katum, o Pesqueiro", tag="Grupo recomendado, Opcional"}, [46]={npc="Guarda-caça Markhor", tgt="Guarda-caça Markhor"}, [47]={npc="Guarda-caça Markhor", tgt="Guarda-caça Markhor"}, [48]={npc="Banha", tgt="Banha"}, [49]={npc="Guarda-caça Markhor", tgt="Guarda-caça Markhor", tag="Opcional"}, [50]={npc="Ferreiro Escoriárvore", tgt="Ferreiro Escoriárvore", tag="Opcional"}, [51]={npc="Primeva Presa-arrancada", tgt="Primeva Presa-arrancada", tag="Grupo recomendado, Opcional"}, [52]={npc="Primeva Presa-arrancada", tgt="Primeva Presa-arrancada", tag="Grupo recomendado, Opcional", star={"Runa do Capitão da Guarda", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}}, [53]={npc="Cristovão Ribeiro", tgt="Cristovão Ribeiro", tag="Opcional", desc="Cristovão Ribeiro, treinador de guerreiros na Cidade Baixa; entregue quando for à Barreira do Inferno. Dá para aceitar antes de ir para as Terras Agrestes."}, [54]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Da Serraria Tarren, siga o rio ao norte até Bath'rah. Você pode comprar os quatro materiais na Casa de Leilões. Se aceitou Mestre dos elementos com o instrutor, use os mesmos materiais para entregar Mestre dos elementos."}, [55]={hint="Leve os elementos terra, ar, fogo e água para Bath'rah, o Vigia dos Ventos.", tag="Opcional", desc="Da Serraria Tarren, siga o rio ao norte até Bath'rah. Você pode comprar os quatro materiais na Casa de Leilões. Se aceitou Mestre dos elementos com o instrutor, use os mesmos materiais para entregar Mestre dos elementos."}, [56]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Da Serraria Tarren, siga o rio ao norte até Bath'rah. Você pode comprar os quatro materiais na Casa de Leilões. Se aceitou Mestre dos elementos com o instrutor, use os mesmos materiais para entregar Mestre dos elementos."}, [57]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Faça Mestre dos elementos ou Dominando os elementos. Reúna os materiais em Terras Pestilentas Ocidentais."}, [58]={npc="Ezequiel Escobar", tgt="Ezequiel Escobar", tag="Opcional", desc="Aceite primeiro no Distrito dos Ladinos, na Cidade Baixa; fica no caminho na sua primeira ida às Terras Agrestes."}, [59]={hint="Fale com Lorde Jorach Corvoforte na Mansão de Corvoforte.", tag="Opcional", desc="Aceite primeiro no Distrito dos Ladinos, na Cidade Baixa; fica no caminho na sua primeira ida às Terras Agrestes."}, [60]={npc="Lorde Jorach Corvoforte", tgt="Lorde Jorach Corvoforte", tag="Opcional", desc="Aceite primeiro no Distrito dos Ladinos, na Cidade Baixa; fica no caminho na sua primeira ida às Terras Agrestes."}, [61]={npc="Lorde Jorach Corvoforte", tgt="Lorde Jorach Corvoforte", tag="Opcional", desc="Aceite na mansão Corvoforte e deixe para Azshara."}}},
    ["04-36"] = {name="Barreira do Inferno", tips={{k="取捨", text="Mate os cinco itens de coleta juntos. Para entregar tudo, são necessários 5 mandíbulas, 6 pulmões de javali, 6 pinças de escorpião, 11 cérebros de lagarto e 14 moelas de abutre. Cada entrega consome materiais."}, {k="取捨", text="Entregue primeiro as missões cujos itens caem mais rápido. Se houver muita disputa pelos urubus ou pelos basiliscos, deixe A mordida do basilisco ou O vigor do abutre inacabada e siga para Angra do Butim, na Selva do Espinhaço."}, {k="提醒", text="Quer EXP? Mate feras nas encostas do norte (46-53, 15-27). Há inimigos de nível mais alto ao sul.", s={{"Quer EXP?"}, {"Mate feras nas encostas do norte (46-53, 15-27)"}, {"Há inimigos de nível mais alto ao sul"}}}}, danger={[1]="Os mobs ao sul do acampamento Bloodmage são de nível mais alto do que aqueles nas encostas ao norte. Atenha-se às encostas externas para as missões de coleta do norte."}, grind={[1]={mob="Aguilhante Escorpóde", note="Escorpiões normais a leste do acampamento Bloodmage. Colete pinças e esfole-as. Afaste-se da estrada quando estiver lotado e fique atento às patrulhas de elite."}}, supply={[1]={npc="Khebra"}, [2]={npc="Estalajadeiro Karakal"}, [3]={npc="Gharash"}, [4]={npc="Thultash"}, [5]={npc="Thultazor"}}, steps={[1]={text="Se Pedregal estiver desbloqueado, escolha Pedregal a partir da Aldeia Revatusco (baldeação por pontos desbloqueados como Karrath) Se não, voe para Rog'mar, siga a estrada do sul passando por Mirante de Terral para o sul até o Pântano das Mágoas e desbloqueie Pedregal. Siga a estrada do sul até a Barreira do Inferno e vá aos dois magos de sangue ao norte (50.64, 14.30)."}, [2]={npc="Mago Sangrento Drazial", tgt="Mago Sangrento Drazial"}, [3]={npc="Mago Sangrento Drazial", tgt="Mago Sangrento Drazial"}, [4]={npc="Mago Sangrento Drazial", tgt="Mago Sangrento Drazial"}, [5]={npc="Maga Sangrenta Lynnore", tgt="Maga Sangrenta Lynnore"}, [6]={npc="Maga Sangrenta Lynnore", tgt="Maga Sangrenta Lynnore"}, [7]={hint="Traga três Mandíbulas de Rasgarrindo, dois Pulmões de Javali Destroçados e uma Tenaz de Escórpode para o Mago Sangrento Drazial."}, [8]={hint="Leve 3 Pulmões de Javali Destroçado, 2 Tenazes de Escórpode e 1 Cérebro de Basilisco para o Mago Sangrento Drazial."}, [9]={hint="Leve 3 Tenazes de Escórpode, 2 Moelas de Abutre e 1 Pulmão de Javali Destroçado para o Mago Sangrento Drazial."}, [10]={hint="Leve 10 Cérebros de Basilisco e 2 Moelas de Abutre para a Maga Sangrenta Lynnore."}, [11]={hint="Leve 10 Moelas de Abutre e 2 Mandíbulas de Rasgarrindo para a Maga Sangrenta Lynnore."}, [12]={npc="Mago Sangrento Drazial", tgt="Mago Sangrento Drazial"}, [13]={npc="Mago Sangrento Drazial", tgt="Mago Sangrento Drazial"}, [14]={npc="Mago Sangrento Drazial", tgt="Mago Sangrento Drazial"}, [15]={npc="Maga Sangrenta Lynnore", tgt="Maga Sangrenta Lynnore"}, [16]={npc="Maga Sangrenta Lynnore", tgt="Maga Sangrenta Lynnore"}, [17]={npc="Kum'isha, o Colecionador", tgt="Kum'isha, o Colecionador", tag="Opcional", desc="Pule se o item não cair."}, [18]={hint="Em suas jornadas pela Barreira do Inferno, caso encontre uma esfera de draenetista impecável, leve-a de volta para Kum'isha, o Colecionador.", tag="Opcional", desc="Pule se o item não cair."}, [19]={npc="Kum'isha, o Colecionador", tgt="Kum'isha, o Colecionador", tag="Opcional", desc="Pule se o item não cair."}, [20]={npc="Kum'isha, o Colecionador", tgt="Kum'isha, o Colecionador", tag="Opcional", desc="Pule se o item não cair."}, [21]={hint="Leve Fragmentos Imperfeitos de Draenetista para Kum'isha e ganhe uma recompensa por cada fragmento entregue.", tag="Opcional", desc="Pule se o item não cair."}, [22]={npc="Kum'isha, o Colecionador", tgt="Kum'isha, o Colecionador", tag="Opcional", desc="Pule se o item não cair."}, [23]={hint="Fale com o Herói Caído da Horda na entrada da Barreira do Inferno.", tag="Opcional"}, [24]={npc="Herói Caído da Horda", tgt="Herói Caído da Horda", tag="Opcional"}, [25]={npc="Herói Caído da Horda", tgt="Herói Caído da Horda", tag="Opcional", desc="Combine com a missão do pulmão de javali dos Bloodmages; dá para fazer antes, juntas, no norte."}, [26]={hint="Mate 7 Javiltuscos na Barreira do Inferno e fale novamente com o Herói Caído da Horda.", tag="Opcional", desc="Combine com a missão do pulmão de javali dos Bloodmages; dá para fazer antes, juntas, no norte."}, [27]={npc="Herói Caído da Horda", tgt="Herói Caído da Horda", tag="Opcional", desc="Combine com a missão do pulmão de javali dos Bloodmages; dá para fazer antes, juntas, no norte."}, [28]={npc="Herói Caído da Horda", tgt="Herói Caído da Horda", tag="Opcional", desc="Puxe os mobs, um de cada vez, da borda do acampamento."}, [29]={hint="Mate os Devotos da Sombra na Barreira do Inferno e fale novamente com o Herói Caído da Horda.", tag="Opcional", desc="Puxe os mobs, um de cada vez, da borda do acampamento."}, [30]={npc="Herói Caído da Horda", tgt="Herói Caído da Horda", tag="Opcional", desc="Puxe os mobs, um de cada vez, da borda do acampamento."}, [31]={npc="Herói Caído da Horda", tgt="Herói Caído da Horda", tag="Opcional", desc="Se já conseguir formar grupo, dá para terminar na mesma viagem; também pode ficar para quando você voltar aos Reinos do Leste, na parada da Capela Esperança da Luz, nas Terras Pestilentas Orientais.", star={"Frasco de Diamante", {"WARRIOR"}}}, [32]={text="Refaça sua rota até Pedregal e voe para Angra do Butim."}}},
    ["04-37"] = {name="Selva do Espinhaço (retorno)", nameA="Selva do Espinhaço: {a:35} (retorno)", tips={{k="取捨", text="Nesta ida, priorize entregar O grogue perdido do Aldo Isque, de nível 50. As missões de baixo nível de Grom'gol e de Angra do Butim, na Selva do Espinhaço, já foram feitas em idas anteriores. As que ainda estão no diário e já foram concluídas também podem ser entregues na mesma ida ao porto."}, {k="取捨", text="Se não tiver o grogue das Terras Agrestes nem missões para entregar, esta parada é só para pegar o barco. O baú do capitão e Febre da Selva do Espinhaço exigem sair da cidade e voltar; faça só se faltar EXP ou se tiver grupo."}, {k="提醒", text="Angra do Butim é um porto neutro. Embarque no barco de passageiros para Vila Catraca e confira para não pegar outra balsa.", s={{"Angra do Butim é um porto neutro"}, {"Embarque no barco de passageiros para Vila Catraca e confira para não pegar outra balsa"}}}}, grind={[1]={mob="Recuperador Sanguinélfico", note="Esta parada em Angra do Butim serve para entregas e para pegar o barco. Se estiver abaixo do nível 53, mate elfos sangrentos comuns na próxima parada, em Azshara; os pontos de missão costumam estar disputados, então pegue na borda do acampamento."}}, supply={[1]={npc="Gringer"}, [2]={npc="Estalajadeiro Skindle"}, [3]={npc="Jutak"}, [4]={npc="Nixxrax Enchecopo"}, [5]={npc="Haren Kanmae"}}, steps={[1]={npc="MacKinley Lobo do Mar", tgt="MacKinley Lobo do Mar"}, [2]={npc="Olhatorto Obnótico", tgt="Olhatorto Obnótico", tag="Opcional"}, [3]={npc="Krazek", tgt="Krazek", tag="Opcional", desc="Entregue em Pedregal, no Pântano das Mágoas, só quando tiver todo o Pó onírico."}, [4]={npc="Aldo Isque", tgt="Aldo Isque", desc="Aceite primeiro em Angra do Butim, na Selva do Espinhaço; pegue o grogue nas Terras Agrestes."}, [5]={npc="Capitão Hecklebury Smotts", tgt="Capitão Hecklebury Smotts", tag="Grupo recomendado, Opcional", desc="Missão opcional de nível 47. Aceite se precisar de EXP e ainda não o fez."}, [6]={npc="Fino Algazarro", tgt="Fino Algazarro", tag="Opcional", desc="Várias ondas de gorilas atacam em sequência; aceite só com um grupo."}, [7]={hint="Leve o Baú do Smotts para Hacklebury Smotts na Angra do Butim.", tag="Grupo recomendado, Opcional"}, [8]={npc="Mandingueiro Unbagwa", tgt="Mandingueiro Unbagwa", tag="Opcional", desc="Aceite Febre da Selva do Espinhaço antes de entregar as presas para acionar o evento."}, [9]={hint="Saque de: Gorila do Vale da Névoa, Trovejador da Selva, Gorila Costalva Enfurecido", tag="Opcional", desc="Aceite Febre da Selva do Espinhaço antes de entregar as presas para acionar o evento."}, [10]={npc="Mandingueiro Unbagwa", tgt="Mandingueiro Unbagwa", tag="Opcional", desc="Aceite Febre da Selva do Espinhaço antes de entregar as presas para acionar o evento."}, [11]={hint="Procure o Mandingueiro Unbagwa e faça-o evocar Mokk, o Selvagem. Leve o Coração de Mokk para Fino Algazarro.", tag="Opcional", desc="Surge durante o evento de entrega de presas para Febre da Selva do Espinhaço."}, [12]={npc="Capitão Hecklebury Smotts", tgt="Capitão Hecklebury Smotts", tag="Grupo recomendado, Opcional"}, [13]={npc="Fino Algazarro", tgt="Fino Algazarro", tag="Opcional"}, [14]={text="Pegue o barco de Angra do Butim para Vila Catraca."}, [15]={npc="Fanny Quito", tgt="Fanny Quito", desc="Fica ao lado do cais, logo ao descer do barco; conclua no Pico Penacho de Fogo, em Un'Goro, e volte a Vila Catraca para entregar."}, [16]={text="Voe de Vila Catraca para Orgrimmar. Antes de ir para Valormok, em Azshara, você pode aceitar Traição com Belgrom em Orgrimmar."}}},
    ["04-38"] = {name="Azshara: Templo de Arkkoroc", nameA="Azshara: {a:1237} & Templo de Arkkoroc", shortA="Azshara: {a:1237} +", tips={{k="取捨", text="Faça juntos a Base Darnassiana, as três marcas e Remtori. Nas Ruínas de Eldarath, pegue de passagem as quatro tabuletas e a runa naga."}, {k="取捨", text="Ley of the Land e Deadliest Catch podem exigir grupo para enfrentar elites; pule as duas nesta parada."}, {k="取捨", text="Entrega para Andron Gante é entregue a Andron Gante, na Cidade Baixa (54.81, 76.33); dá para guardá-la até a parada da Capela Esperança da Luz, nas Terras Pestilentas Orientais. A missão que ele manda de volta da cidade exige retornar a Azshara; esta rota pode dispensá-la."}, {k="提醒", text="Abaixo do nível 53? Mate nagas nas Ruínas de Eldarath ou elfos sangrentos na Base Darnassiana e aproveite para procurar os itens de missão.", s={{"Abaixo do nível 53?"}, {"Mate nagas nas Ruínas de Eldarath ou elfos sangrentos na Base Darnassiana e aproveite para procurar os itens de missão"}}}}, danger={[1]="Dentro das Ruínas de Eldarath há muitos nagas conjuradores. Ao pegar as tabuletas, entre e saia pela parede externa; interrompa os conjuradores e puxe os mobs para fora das salas."}, grind={[1]={mob="Recuperador Sanguinélfico", note="Os elfos sangrentos comuns da Base Darnassiana estão em um nível ideal para EXP e para as missões. Puxe pela borda para evitar pegar os conjuradores do interior."}, [2]={mob="Mirmidão Iralisca", note="Nagas comuns nas Ruínas de Eldarath; dá para pegar as missões das nagas de passagem. Puxe um de cada vez pela parede externa e evite os grupos densos de conjuradores lá dentro."}}, supply={[1]={npc="Kroum"}, [2]={npc="Gruul Laminegra"}, [3]={npc="Korll"}, [4]={npc="Estalajadeira Gryshka"}, [5]={npc="Jaka"}, [6]={npc="Horthus"}}, steps={[1]={npc="Belgrom Pedramalho", tgt="Belgrom Pedramalho", desc="Aceite no Vale da Honra de Orgrimmar. Inicia a cadeia Traição atualizada."}, [2]={npc="Sona'rima", tgt="Sona'rima", tag="Opcional", desc="Opcional. Pegue agora e mate Ravasaurs em Un'Goro."}, [3]={text="Se já tiver o ponto de voo de Azshara, voe de Orgrimmar para Valormok. Na primeira visita, voe de Orgrimmar para o Posto Machadada, siga para o leste primeiro até Loh'atu e depois continue até Valormok; se o Posto Machadada não estiver desbloqueado, voe primeiro para a Encruzilhada e pegue a estrada do norte, passando pela Paliçada Mor'shan, até a estrada do lado leste do Vale Gris.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [4]={text="Loh'atu no oeste → pegar tudo em Valormok"}, [5]={npc="Loh'atu", tgt="Loh'atu"}, [6]={npc="Loh'atu", tgt="Loh'atu"}, [7]={hint="Destrua 6 Aparições Altaneiras e 6 Subliches Altaneiros. Depois, fale com Loh'atu em Azshara."}, [8]={hint="Mate 6 Sátiros Haldarr, 2 Trapaceiros Haldarr e 2 Devotos Vil Haldarr. Depois, fale novamente com Loh'atu na fronteira do Vale Gris."}, [9]={npc="Loh'atu", tgt="Loh'atu"}, [10]={npc="Loh'atu", tgt="Loh'atu"}, [11]={nodeA="{a:1237}", node="Valormok", desc="Desbloquear o ponto de voo com Kroum."}, [12]={npc="Ag'tor Punho de Sangue", tgt="Ag'tor Punho de Sangue"}, [13]={npc="Ag'tor Punho de Sangue", tgt="Ag'tor Punho de Sangue"}, [14]={npc="Jediga", tgt="Jediga"}, [15]={text="Base Darnassiana → templo e Ruínas de Eldarath → Valormok"}, [16]={npc="Kam'arawn", tgt="Kam'arawn"}, [17]={hint="Vasculhe o Acampamento Talassiano e encontre os seguintes itens de Kam'arawn: A Bússola, o Telescópio, o Frango Recheado e a Chinforímpola. Depois, devolva os itens para Kam'arawn em Azsahra."}, [18]={npc="Kam'arawn", tgt="Kam'arawn"}, [19]={npc="Kam'arawn", tgt="Kam'arawn"}, [20]={hint="Mate 10 Recuperadores Sanguinélficos e 10 Topógrafos Sanguinélficos antes de procurar o acampamento da Maga Rimtori. Quando localizá-lo, procure algo que possa ser importante para ela e possa ser usado para forçá-la a lutar.", desc="Siga o diário de missões para as quantidades exatas."}, [21]={npc="Tomo Kaldorei da Evocação", npcObj=true}, [22]={npc="Sin'dorei Tome of Summoning", tgt="Sin'dorei Tome of Summoning", desc="Cadeia Traição da versão Forever. Conclua primeiro; colete um de cada um dos três tipos."}, [23]={hint="Saque de: Lieutenant Suncrest, Magíster Falcoelmo, Ranger Lydrea", tag="Alvo: Tenente Suncrest / Magíster Falcoelmo / Patrulheiro Lydrea / Skyborne Test", desc="Cadeia Traição da versão Forever. Conclua primeiro; colete um de cada um dos três tipos."}, [24]={npc="Sin'dorei Tome of Summoning", tgt="Sin'dorei Tome of Summoning", desc="Cadeia Traição da versão Forever. Conclua primeiro; colete um de cada um dos três tipos."}, [25]={npc="Sin'dorei Tome of Summoning", tgt="Sin'dorei Tome of Summoning"}, [26]={hint="Saque de: Maga Rimtori"}, [27]={hint="Encontre Essa Tal Runa que está com as nagas nas Ruínas de Eldarath e traga-a para Kam'arawn, em Azshara."}, [28]={hint="Encontre a Tabuleta de Beth'Amara, a Tabuleta de Jin'yael, a Tabuleta de Markri e a Tabuleta de Sael'hai. Depois volte a falar com Jediga, em Azshara."}, [29]={npc="Kam'arawn", tgt="Kam'arawn"}, [30]={npc="Jediga", tgt="Jediga"}, [31]={npc="Ag'tor Punho de Sangue", tgt="Ag'tor Punho de Sangue"}, [32]={npc="Ag'tor Punho de Sangue", tgt="Ag'tor Punho de Sangue"}, [33]={npc="Jediga", tgt="Jediga", tag="Opcional", desc="Entregue se passar por Penhasco do Trovão antes da próxima parada."}, [34]={npc="Jediga", tgt="Jediga", tag="Opcional", desc="Entregue quando voltar a Orgrimmar nesta viagem."}, [35]={npc="Jediga", tgt="Jediga", tag="Opcional", desc="Entregue a missão quando voltar a passar pela Cidade Baixa."}, [36]={text="De Valormok, voe de volta a Orgrimmar e entregue a cabeça e a tábua que você pegou no caminho. Você pode seguir para Penhasco do Trovão para entregar a tábua, mas isso acrescenta um trecho; se o ponto de voo de Penhasco do Trovão não estiver aberto, voe para Acampamento Taurajo, entre a oeste em Mulgore e suba pelo elevador até Penhasco do Trovão (47.00, 49.83) para abri-lo. Se não quiser o desvio, pule Entrega para Magatha."}, [37]={npc="Belgrom Pedramalho", tgt="Belgrom Pedramalho"}, [38]={npc="Sona'rima", tgt="Sona'rima", tag="Opcional"}, [39]={npc="Zilzibin Tamborleiro", tgt="Zilzibin Tamborleiro", tag="Opcional", desc="Aceite com Zilzibin Tamborleiro em Orgrimmar e depois voe para Feralas. Aceite só se já tiver entregue A ameaça dos silitídeos ou O relatório dos Zukk'ash em Geringontzan, Tanaris, e no Complexo Dunamalho; deixe para Geringontzan e Pilar Partido. Se for passar pelo Penhasco do Trovão para entregar Entrega para Magatha, aceite esta missão antes de sair de Orgrimmar."}, [40]={npc="Magatha Temível Totem", tgt="Magatha Temível Totem", tag="Opcional"}, [41]={npc="Ormak Tiroatroz", tgt="Ormak Tiroatroz", tag="Opcional", desc="Ao passar por Orgrimmar, procure primeiro o treinador de caçadores; entre em Azshara pelo ponto de voo do oeste."}, [42]={hint="Encontre Ogtinc em Azshara.", tag="Opcional", desc="Ao passar por Orgrimmar, procure primeiro o treinador de caçadores; entre em Azshara pelo ponto de voo do oeste."}, [43]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional", desc="Ao passar por Orgrimmar, procure primeiro o treinador de caçadores; entre em Azshara pelo ponto de voo do oeste."}, [44]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional"}, [45]={hint="Leve um par de Galhadas Perfeitas de Ginete para Ogtinc em Azshara. Ogtinc vive no alto dos penhascos a nordeste das Ruínas de Eldarath.", tag="Opcional"}, [46]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional"}, [47]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional"}, [48]={hint="Leve 6 Escamas de Fura-ondas para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath.", tag="Opcional"}, [49]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional"}, [50]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional", desc="Dá para fazer o Templo Submerso na volta da Capela Esperança da Luz aos Reinos do Leste.", star={"Olho de Demossauro", {"HUNTER"}}}, [51]={npc="Uthel'nay", tgt="Uthel'nay", tag="Opcional", desc="Veja primeiro o treinador no Vale dos Espíritos de Orgrimmar."}, [52]={hint="Procure Sanath Lim-yo e consiga o transporte para ver o Arquimago Tauriel.", tag="Opcional", desc="Veja primeiro o treinador no Vale dos Espíritos de Orgrimmar."}, [53]={npc="Sanath Lim-yo", tgt="Sanath Lim-yo", tag="Opcional", desc="Veja primeiro o treinador no Vale dos Espíritos de Orgrimmar."}, [54]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel", tag="Opcional", desc="Dá para fazer junto com as missões dos elfos sangrentos do norte de Valormok, em Azshara; antes, aceite esta com o Arquimago Tauriel."}, [55]={hint="Leve 10 Poeiras Reluzentes para o Arquimago Tauriel.", tag="Opcional", desc="Dá para fazer junto com as missões dos elfos sangrentos do norte de Valormok, em Azshara; antes, aceite esta com o Arquimago Tauriel."}, [56]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel", tag="Opcional", desc="Dá para fazer junto com as missões dos elfos sangrentos do norte de Valormok, em Azshara; antes, aceite esta com o Arquimago Tauriel."}, [57]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel", tag="Opcional"}, [58]={hint="Obtenha 6 Corais Encantados e entregue-os ao Arquimago Tauriel.", tag="Opcional"}, [59]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel", tag="Opcional"}, [60]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel", tag="Opcional", desc="Dá para fazer o Templo Submerso na volta da Capela Esperança da Luz aos Reinos do Leste.", star={"Rubi de Fogo", {"MAGE"}}}, [61]={hint="Recupere o Saco Lazúli Lacrado com o Xamã Presamatos, em Azshara. Então o leve para o Arquimago Tauriel, também em Azshara.", tag="Opcional, Alvo: Xamã Presamatos / Blackmaw Xamã", desc="Os xamãs Timbermaw e Blackmaw dropam o item; mate primeiro os Blackmaw para não perder reputação com os Timbermaw."}, [62]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel", tag="Opcional", desc="Fale com Sanath Lim-yo no sopé da montanha (28.11, 50.09) para chegar à torre de Xylem."}, [63]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel", tag="Opcional"}, [64]={hint="Leve 10 Fragmentos Codificados para o Arquimago Tauriel em Azshara.", tag="Opcional"}, [65]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel", tag="Opcional"}, [66]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel", tag="Opcional", desc="Dá para fazer o Templo quando você voltar aos Reinos do Leste, na parada da Capela Esperança da Luz, nas Terras Pestilentas Orientais.", star={"Clâmide Quiropúsculo", {"ROGUE"}}}, [67]={npc="Ur'kyo", tgt="Ur'kyo", tag="Opcional", desc="Ao passar por Orgrimmar, procure o treinador de sacerdotes e aproveite para comprar 1 Undeath's Ichor."}, [68]={hint="Encontre Ogtinc em Azshara.", tag="Opcional", desc="Ao passar por Orgrimmar, procure o treinador de sacerdotes e aproveite para comprar 1 Undeath's Ichor."}, [69]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional", desc="Ao passar por Orgrimmar, procure o treinador de sacerdotes e aproveite para comprar 1 Undeath's Ichor."}, [70]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional"}, [71]={hint="Obtenha 4 Glândulas de Ginete Saudável leve-as para Ogtinc em Azshara. Ogtinc vive no alto dos penhascos a nordeste das Ruínas de Eldarath.", tag="Opcional"}, [72]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional"}, [73]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional", desc="Dá para comprar de jogadores ou na casa de leilões, evitando uma viagem às Terras Pestilentas."}, [74]={hint="Obtenha uma Linfa de Morte-viva para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath.", tag="Opcional", desc="Dá para comprar de jogadores ou na casa de leilões, evitando uma viagem às Terras Pestilentas."}, [75]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional", desc="Dá para comprar de jogadores ou na casa de leilões, evitando uma viagem às Terras Pestilentas."}, [76]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional", desc="Dá para fazer o Templo Submerso na volta da Capela Esperança da Luz aos Reinos do Leste.", star={"Contas de Oração Abençoadas", {"PRIEST"}}}}},
    ["04-39"] = {name="Feralas (retorno)", nameA="Feralas: {a:1099} (retorno)", tips={{k="取捨", text="Entregue O teste do recipiente na Aldeia Mojache e aceite a continuação Muisec de hipogrifo-Muisec de Arvoroso. Entregue cada etapa primeiro; só assim o próximo recipiente fica disponível."}, {k="取捨", text="Se faltar muito material para Caçadores de matérias-primas perdidas, pule; as missões secundárias de Northspring ficam na mesma viagem dos gigantes mais distantes, a oeste; faça se tiver tempo."}, {k="提醒", text="Precisa de um pouco de EXP? Mate Sprite Darters em 69.45, 44.95 ou vá para o acampamento das harpias a noroeste.", s={{"Precisa de um pouco de EXP?"}, {"Mate Sprite Darters em 69.45, 44.95 ou vá para o acampamento das harpias a noroeste"}}}}, grind={[1]={mob="Matadora da Nascente Norte", note="Mobs comuns na borda do acampamento das harpias de Northspring; se estiver nas missões de Northspring, colete os itens de passagem. Só por EXP, não volte ao acampamento e deixe para a próxima parada."}, [2]={mob="Trovejante Groddoc", note="Se o ponto das harpias estiver ocupado, mate os gorilas comuns a sudeste. O terreno aberto facilita recuar; puxe pela parte externa para evitar vários de uma vez."}}, supply={[1]={npc="Shyn"}, [2]={npc="Estalajadeiro Greul"}, [3]={npc="Cavento Mira Certa"}, [4]={npc="Estalajadeiro Greul"}, [5]={npc="Cavento Mira Certa"}, [6]={npc="Tarhus"}}, steps={[1]={text="De Orgrimmar, ou do Penhasco do Trovão depois de entregar Entrega para Magatha, escolha Aldeia Mojache no mapa de voo e faça baldeação por pontos desbloqueados como a Encruzilhada. Se começar por esta parada sem tê-lo desbloqueado, voe primeiro para a Aldeia Vento Livre, em Mil Agulhas, siga a estrada do vale a oeste até Feralas e procure Shyn para desbloqueá-lo."}, [2]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i", desc="Aceite na etapa de Aldeia Mojache e Bastilha Cortifúria. Nas Terras Agrestes, capture com o recipiente as almas de bestas-coruja."}, [3]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i", desc="Volte ao feiticeiro para a próxima missão."}, [4]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i", desc="Na próxima parada, entregue a Marlon Catarrebite no Pilar Partido, em Tanaris."}, [5]={npc="Talo Casco de Espinhos", tgt="Talo Casco de Espinhos", desc="Guarde por enquanto: mate os ursos-cinzentos e os assoladores em Selva Maleva e depois volte à Aldeia Mojache para entregar."}, [6]={hint="Mate 10 Hipogrifos Esfiapluma de qualquer tipo e use o Recipiente de Muisec para encolhê-los e capturá-los.", desc="Volte ao feiticeiro para a próxima missão."}, [7]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i", desc="Volte ao feiticeiro para a próxima missão."}, [8]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i"}, [9]={hint="Mate 8 Dardejantes ou Dragões-íris. Use o Recipiente de Muisec para encolher e capturar as Dragoletas abatidas."}, [10]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i"}, [11]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i"}, [12]={hint="Mate 3 Andarilhos Errantes da Floresta. Use o Recipiente de Muisec para encolher e capturar os Arvorosos abatidos."}, [13]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i"}, [14]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i", tag="Opcional"}, [15]={npc="Talo Casco de Espinhos", tgt="Talo Casco de Espinhos", tag="Grupo recomendado, Opcional", desc="Aceite quando for à área das harpias de Northspring e tiver condições de enfrentar elites."}, [16]={npc="Talo Casco de Espinhos", tgt="Talo Casco de Espinhos", tag="Opcional"}, [17]={hint="Mate 7 Terrâmbulos ou Gigantes do Penhasco. Use o Recipiente de Muisec para encolher e capturar os Gigantes da Montanha abatidos.", tag="Opcional"}, [18]={hint="Talo Casco de Espinhos quer que você mate 4 Harpias da Nascente Norte, 4 Plumerrantes da Nascente Norte, 4 Arautos do Vento da Nascente Norte e 4 Matadoras da Nascente Norte.", tag="Opcional"}, [19]={hint="Talo Casco de Espinhos, da Aldeia Mojache, quer o Coração Sombrio de Edana Iragarra.", tag="Grupo recomendado, Opcional", desc="Evoque no Altar de Northspring."}, [20]={hint="Leve 2 Pedaços de Lenha, 6 Minerais Incrustados, 20 pedaços de Tendão Resiliente e 40 Fragmentos Metálicos para Mandingueiro Uzer'i na Aldeia Mojache.", desc="Aceite na etapa de Aldeia Mojache e Bastilha Cortifúria. Colete nas três primeiras rodadas conforme avança; se faltar muito, não volte só para isso."}, [21]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i", tag="Opcional"}, [22]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i"}, [23]={npc="Talo Casco de Espinhos", tgt="Talo Casco de Espinhos", tag="Grupo recomendado, Opcional"}, [24]={npc="Talo Casco de Espinhos", tgt="Talo Casco de Espinhos", tag="Opcional"}, [25]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i", tag="Opcional", desc="Aceite após completar Muisec de Gigante da Montanha e Caçadores de matérias-primas perdidas."}, [26]={hint="O Mandingueiro Uzer'i deseja que você aguarde por um instante enquanto ele prepara as armas.", tag="Opcional", desc="Aceite após completar Muisec de Gigante da Montanha e Caçadores de matérias-primas perdidas."}, [27]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i", tag="Opcional", desc="Aceite após completar Muisec de Gigante da Montanha e Caçadores de matérias-primas perdidas."}, [28]={text="Voe de Aldeia Mojache para Geringontzan em Tanaris."}}},
    ["04-40"] = {name="Tanaris", nameA="Tanaris: {a:976} & {a:1938}", shortA="Tanaris: {a:976} +", tips={{k="取捨", text="Em Geringontzan, entregue primeiro as três etapas de O Ingrediente Secreto de Sguisha→O Elixir Nublacuca; depois de aceitar a missão de Un'Goro, siga para Pilar Partido."}, {k="取捨", text="O círculo de pedra exige voltar a Vila Catraca; nesta parada, basta fazer O Templo Submerso e Gahz'ridian. Se aceitar O círculo de pedra por causa da cadeia da masmorra, pegue o Círculo de Pedra em Vila Catraca, nos Sertões, e volte em outra viagem para entregar."}, {k="取捨", text="Supergrudento e Sururu na selva, que tem pré-requisito, são feitas na parada do Refúgio do Marshal, na Cratera Un'Goro. Entregue Yuka Parafuseta em Monte Candente, nas Estepes Ardentes."}, {k="提醒", text="Precisa de EXP? Faça Gahz'ridian pelo Pilar Partido e mate os ogros Dunemaul, ou encontre um grupo Zul'Farrak em Tanaris.", s={{"Precisa de EXP?"}, {"Faça Gahz'ridian pelo Pilar Partido e mate os ogros Dunemaul, ou encontre um grupo Zul'Farrak em Tanaris"}}}}, grind={[1]={mob="Enxameador Hazzali", note="Escorpídeos comuns, densos e de nível mais próximo ao desta etapa, fora da Fenda Hazzali. Fique na superfície; perto da entrada é fácil puxar vários."}, [2]={mob="Petrificador Silicouro", note="Mate lagartos comuns pela estrada sul antes de ir ao Pilar Partido ou a Un'Goro. Os mobs reaparecem espalhados e são menos disputados que as missões de Complexo Dunamalho."}}, supply={[1]={npc="Bulkrek Iracarpos"}, [2]={npc="Estalajadeiro Gabor Bulho"}, [3]={npc="Dobrov A. Massoaço"}, [4]={npc="Estalajadeiro Gabor Bulho"}, [5]={npc="Blizricco Sciumbigno"}}, steps={[1]={npc="Sguisha", tgt="Sguisha", desc="Aceite na parada de Geringontzan e Complexo Dunamalho, em Tanaris, e colha os cogumelos nas Terras Agrestes. Ao voltar a Geringontzan, entregue esta primeiro."}, [2]={npc="Sguisha", tgt="Sguisha", desc="Entregue O Ingrediente Secreto de Sguisha primeiro."}, [3]={hint="Sguisha quer que você leve o Pó Violeta para Marin Nublacuca em Geringontzan.", desc="Entregue O Ingrediente Secreto de Sguisha primeiro."}, [4]={npc="Marin Nublacuca", tgt="Marin Nublacuca", desc="Entregue O Ingrediente Secreto de Sguisha primeiro."}, [5]={npc="Marin Nublacuca", tgt="Marin Nublacuca"}, [6]={hint="Marin Nublacuca quer que você volte a falar com ele depois que ele criar o elixir."}, [7]={npc="Marin Nublacuca", tgt="Marin Nublacuca"}, [8]={hint="Fale com o Alquimista Almofarrista em Geringontzan.", tag="Opcional", desc="Antes de sair de Orgrimmar para Valormok, em Azshara, se já tiver concluído 32 ou O relatório dos Zukk'ash, aceite com Zilzibin."}, [9]={npc="Alquimista Almofarrista", tgt="Alquimista Almofarrista", tag="Opcional"}, [10]={npc="Alquimista Almofarrista", tgt="Alquimista Almofarrista", tag="Opcional", desc="Só aceite depois de entregar A marcha dos silitídeos da Horda. Deixe para Un'Goro."}, [11]={npc="Tran'rek", tgt="Tran'rek", desc="Mate os monstros de alcatrão na etapa de Refúgio do Marshal, em Un'Goro."}, [12]={text="Se tiver o ovo velho, vá primeiro ao leste, a Porto de Bondebico, para entregar. Os demais podem ir direto ao sul, até o Pilar Partido."}, [13]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Opcional", desc="Aceite em Tanaris (Geringontzan e Complexo Dunamalho). Pegue o ovo em Jintha'Alor. Yeh'kinya fica em Porto de Bondebico."}, [14]={npc="Yorba Parafuseta", tgt="Yorba Parafuseta", tag="Opcional", desc="Pegue a missão no Porto de Bondebico e entregue no Monte Candente. Vale a pena se você for ao Abismo Rocha Negra."}, [15]={hint="Encontre Marlon Catarrebite em Tanaris.", desc="Aceite primeiro em Aldeia Mojache, na etapa de Aldeia Mojache e Bastilha Cortifúria."}, [16]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite"}, [17]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite"}, [18]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite", tag="Opcional", desc="Entregue O Templo Submerso primeiro. O círculo de pedra fica em Vila Catraca; só aceite se for fazer o Templo Submerso ou quiser a missão."}, [19]={hint="Marlon Catarrebite, em Tanaris, quer que você colete 30 Ornamentos de Gahz'ridian.", desc="Pesquise primeiro ao redor do Pilar Partido e depois varra o perímetro."}, [20]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite"}, [21]={hint="Busque o Círculo de Pedra na oficina de Marlon Catarrebite em Vila Catraca.", tag="Opcional", desc="Haverá outras passagens por Vila Catraca; também dá para esperar e pegar de passagem nos Sertões."}, [22]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite", tag="Opcional"}, [23]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite", tag="Opcional", desc="Aceite apenas se estiver executando Templo Submerso."}, [24]={npc="Torwa Mateiro", tgt="Torwa Mateiro", tag="Opcional", desc="Ao entrar pela entrada sudeste de Un'Goro, encontre Torwa Mateiro; na próxima etapa, colete pelo caminho."}, [25]={text="Siga a estrada Tanaris para o sul a partir de Pilar Partido e depois siga para oeste até Cratera Un'Goro."}}},
    ["05-d23"] = {name="Templo de Atal'Hakkar", entrance="Pântano das Mágoas (1435), 69.50, 52.50. Marca a parte externa do templo.", pickup="Em Pedregal, no Pântano das Mágoas, conclua Poço de Lágrimas e guarde O exilado Atal'ai. Do ponto de voo da Aldeia Revantusk, nas Terras Agrestes, vá ao sul das Terras Agrestes, entregue O exilado Atal'ai ao exilado e aceite Retorno a Vil'zerul e Jammal'an, o Profeta. Se concluir a cadeia das tabuletas de Zul'Farrak, vá também a Jintha'Alor buscar o ovo. Em Feralas, aceite primeiro O Templo Submerso. Ao chegar a Geringontzan, em Tanaris, procure Marvon para a missão do círculo de pedras, voe a Vila Catraca para buscar o item e volte a Marvon para aceitar as duas missões do templo. Depois de entregar o ovo em Porto de Bondebico, dá para voar de Geringontzan a Vila Catraca e pegar o barco para Angra do Butim. Por fim, voe para Pedregal, entregue Retorno a Vil'zerul, aceite O templo de Atal'Hakkar e siga para o templo.", pickupS={{"Em Pedregal, no Pântano das Mágoas, conclua Poço de Lágrimas e guarde O exilado Atal'ai"}, {"Do ponto de voo da Aldeia Revantusk, nas Terras Agrestes, vá ao sul das Terras Agrestes, entregue O exilado Atal'ai ao exilado e aceite Retorno a Vil'zerul e Jammal'an, o Profeta"}, {"Se concluir a cadeia das tabuletas de Zul'Farrak, vá também a Jintha'Alor buscar o ovo"}, {"Em Feralas, aceite primeiro O Templo Submerso"}, {"Ao chegar a Geringontzan, em Tanaris, procure Marvon para a missão do círculo de pedras, voe a Vila Catraca para buscar o item e volte a Marvon para aceitar as duas missões do templo"}, {"Depois de entregar o ovo em Porto de Bondebico, dá para voar de Geringontzan a Vila Catraca e pegar o barco para Angra do Butim"}, {"Por fim, voe para Pedregal, entregue Retorno a Vil'zerul, aceite O templo de Atal'Hakkar e siga para o templo"}}, tips={{k="動線", text="Caminho plano à direita da entrada → altar e estátuas da galeria inferior → Atal'alarion → guardas das seis sacadas superiores → Jammal'an no corredor leste do Poço de Sacrifício → evocação opcional de Hakkar a oeste → quatro dragonianos → Eranikus e a Fonte de Essência. Mate trolls Atal'ai pelo caminho para recolher ídolos."}, {k="取捨", text="Priorize as cadeias locais de Pedregal e Terras Agrestes. A cadeia de Mosh'aru serve a quem já fez Zul'Farrak e visitou Jintha'Alor. Para o Círculo de Pedra, planeje uma viagem a Vila Catraca durante a etapa de Geringontzan e Complexo Dunamalho."}, {k="說明", text="As coordenadas marcam o prédio fora do Poço de Lágrimas. Desça as escadas sul para o templo, passe pelo Salão das Máscaras e pelo Salão do Ritual, até o portal no nível intermediário do Salão dos Ossos.", s={{"As coordenadas marcam o prédio fora do Poço de Lágrimas"}, {"Desça as escadas sul para o templo, passe pelo Salão das Máscaras e pelo Salão do Ritual, até o portal no nível intermediário do Salão dos Ossos"}}}}, steps={[1]={npc="Vil'zerul", tgt="Vil'zerul", desc="Comece em O exilado Atal'ai se você já fez isso na rota principal."}, [2]={hint="Vil'zerul, no Pedregal, quer que você colete 10 Artefatos Atal'ai."}, [3]={npc="Vil'zerul", tgt="Vil'zerul"}, [4]={npc="Vil'zerul", tgt="Vil'zerul", preText="Poço de Lágrimas"}, [5]={npc="Exilado Atal'ai", tgt="Exilado Atal'ai"}, [6]={npc="Exilado Atal'ai", tgt="Exilado Atal'ai", preText="O exilado Atal'ai"}, [7]={npc="Exilado Atal'ai", tgt="Exilado Atal'ai"}, [8]={hint="Fale novamente com Vil'Zerul em Pedregal."}, [9]={npc="Vil'zerul", tgt="Vil'zerul"}, [10]={npc="Vil'zerul", tgt="Vil'zerul", preText="Retorno a Vil'zerul"}, [11]={npc="Mandingueiro Uzer'i", tgt="Mandingueiro Uzer'i"}, [12]={hint="Encontre Marlon Catarrebite em Tanaris."}, [13]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite"}, [14]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite", preText="O Templo Submerso"}, [15]={hint="Busque o Círculo de Pedra na oficina de Marlon Catarrebite em Vila Catraca."}, [16]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite"}, [17]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite", preText="O círculo de pedra"}, [18]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite", preText="O círculo de pedra"}, [19]={npc="Yeh'kinya", tgt="Yeh'kinya", desc="Pegue em Porto de Bondebico e depois faça Feralas. Pegue A profecia de Mosh'aru depois de entregá-lo."}, [20]={hint="Capture os espíritos de 3 guinchadores em Feralas, e depois fale novamente com Yeh'kinya no Porto de Bondebico."}, [21]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [22]={npc="Yeh'kinya", tgt="Yeh'kinya", preText="Espíritos guinchadores"}, [23]={hint="Leve a Primeira e a Segunda Tabuleta Mosh'Aru para Yeh'kinya, em Tanaris.", desc="Salve o acompanhamento O ovo velho para a missão Templo Submerso O deus Hakkar."}, [24]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [25]={npc="Yeh'kinya", tgt="Yeh'kinya", desc="Jintha'Alor tem grupos de elites; faça em paralelo com a rota principal enquanto estiver nas Terras Agrestes.", preText="A profecia de Mosh'aru"}, [26]={hint="Leve o Ovo Velho para Yeh'kinya, em Tanaris."}, [27]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [28]={npc="Yeh'kinya", tgt="Yeh'kinya", preText="O ovo velho"}, [29]={text="Entrada: Templo de Atal'Hakkar"}, [30]={hint="Encontre o Altar de Hakkar no Templo Submerso, que fica no Pântano das Mágoas.", desc="Local: Entre pela porta, siga o caminho plano à direita até o nível inferior e procure o Altar de Hakkar no corredor circular. Ordem: Entregue primeiro o altar e depois aceite a etapa \"Segredo do círculo\".", spot="Ao entrar, pegue o caminho plano da direita até o nível inferior e procure o Altar de Hakkar no corredor circular."}, [31]={npc="Altar de Hakkar", npcObj=true, spot="Altar de Hakkar no corredor circular inferior"}, [32]={hint="Entre no Templo Submerso e descubra o segredo escondido no círculo de estátuas.", desc="Uma ordem errada aciona uma armadilha. Local: Clique nas seis estátuas em ordem pelo corredor circular inferior e depois vá ao centro matar o chefe. Ordem: Sul → norte → sudoeste → sudeste → noroeste → nordeste.", spot="Ative as seis estátuas em ordem no corredor circular inferior e depois mate o chefe no centro."}, [33]={npc="Ídolo de Hakkar", npcObj=true, spot="Centro do nível inferior: a estátua Hakkari"}, [34]={hint="Obtenha 20 Fetiches de Hakkar e leve-os para Vil'Zerul em Pedregal.", desc="Local: Mate os trolls Atal'ai ao longo do anel inferior e das varandas superiores.", spot="Mate os trolls Atal'ai ao longo do anel inferior e das varandas superiores."}, [35]={hint="O Exilado Atal'ai nas Terras Agrestes quer a Cabeça de Jammal'an.", desc="Local: Limpe as seis sacadas superiores, volte ao Fosso do Sacrifício e siga o corredor leste para encontrar Jammal'an. Ordem: Mate primeiro os seis guardas das sacadas para remover a barreira.", spot="Limpe as seis varandas superiores e volte ao Poço de Sacrifício pelo corredor leste até Jammal'an."}, [36]={hint="Leve o Ovo de Hakkar Cheio para Yeh'kinya, em Tanaris.", desc="Entre primeiro com todo o grupo na sala e depois inicie o evento. Siga pela passagem oeste até a sala de Hakkar. Local: Do Fosso do Sacrifício, siga pelo corredor oeste até a sala de Hakkar, reúna o grupo e use o ovo. Ordem: O corredor oeste leva a Hakkar e o corredor leste a Jammal'an.", spot="Pegue o corredor oeste do Poço de Sacrifício até a sala de Hakkar. Reúna o grupo antes de usar o ovo."}, [37]={npc="Essência de Erânicos", npcObj=true, desc="Mate o Vulto de Eranikus e clique com o botão direito no item que ele solta para aceitar a missão."}, [38]={hint="Coloque a Essência de Erânicos na Fonte de Essência encontrada neste covil do Templo Submerso.", desc="Local: Derrote os quatro chefes dragonídeos e clique na fonte ao lado do último chefe na sala do Sonhador. Ordem: O último chefe solta a essência; depois de aceitar, entregue na mesma sala.", spot="Mate os quatro chefes dragonkin. Use a fonte na sala do Sonhador, ao lado do chefe final."}, [39]={npc="Fonte de Essência", npcObj=true, spot="Câmara de Eranikus: a Fonte de Essência ao lado do chefe final"}, [40]={npc="Vil'zerul", tgt="Vil'zerul"}, [41]={npc="Exilado Atal'ai", tgt="Exilado Atal'ai"}, [42]={npc="Yeh'kinya", tgt="Yeh'kinya"}}},
    ["04-41"] = {name="Cratera Un'Goro", nameA="Cratera Un'Goro: {a:541}", tips={{k="取捨", text="Cristais de energia, materiais de dinossauro, alcatrão e Pétala Sangrenta andam juntos. Antes de chegar ao centro, cuidado com o demonossauro patrulheiro."}, {k="取捨", text="É segredo para todo mundo fica para Hibérnia; entregue Atividade vulcânica e Oficina do Marlon em Vila Catraca antes de embarcar. A isca para Lar'korwi, as três torres de cristal, as peles de gorila, o resgate do Pico Penacho de Fogo e Morno... morno... quente! ficam para a parada do Refúgio do Marshal, na Cratera Un'Goro."}, {k="取捨", text="Se já juntou as garras de Armas de gume de osso, entregue-a na próxima passagem por Orgrimmar a Jes'rimon (55.52, 34.08). O peão captura a rainha exige chocar ao sul e matar o chefe; pode ser pulada."}, {k="提醒", text="Falta pouco para o nível 54? Mate monstros de alcatrão no norte (51.77, 25.14) ou Diemetradons a leste do Refúgio do Marshal (50.78, 19.90) para ganhar EXP.", s={{"Falta pouco para o nível 54?"}, {"Mate monstros de alcatrão no norte (51.77, 25.14) ou Diemetradons a leste do Refúgio do Marshal (50.78, 19.90) para ganhar EXP"}}}}, danger={[1]="Há devilsaurs de elite, níveis 54-55, patrulhando Un'Goro. Ao subir para o acampamento, siga pela borda leste e, se vir um, dê passagem."}, grind={[1]={mob="Tocaieiro de Piche", note="Monstros de alcatrão comuns ao sul do acampamento; dá para pegar de passagem o Piche Supergrudento. Eles reaparecem à beira da água: puxe um de cada vez pela margem e fique de olho nas patrulhas de devilsaurs."}, [2]={mob="Trovejador de Un'Goro", note="Gorilas comuns na entrada da caverna a nordeste. Coincidem com as missões dos gorilas; dentro da caverna é fácil puxar vários, então fique de fora. Se o lado de fora estiver ocupado, volte aos poços de alcatrão."}}, supply={[1]={npc="Gryfe"}, [2]={npc="Goberto"}, [3]={npc="Nergal"}, [4]={npc="Nergal"}}, steps={[1]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [2]={hint="Encontre a carcaça mais recente de uma presa morta por Lar'korwi e roube um Pedaço de Carcaça de Manguadonte. Depois disso, fale novamente com Torwa Mateiro na Cratera Un'Goro."}, [3]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [4]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [5]={hint="Leve 2 Glândulas de Feromônio de Ravassauro para Torwa Mateiro, que está perto da entrada da Cratera Un'Goro."}, [6]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [7]={npc="Torwa Mateiro", tgt="Torwa Mateiro", desc="Guarde para a volta ao Refúgio do Marshal, em Un'Goro."}, [8]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [9]={hint="Leve 8 Garras Brancas de Ravassauro para Sona'rima em Orgrimmar.", tag="Opcional", desc="Aceite primeiro em Orgrimmar e só então faça."}, [10]={npc="Bote Naufragado", npcObj=true}, [11]={hint="Olhe em volta da lagoa para descobrir uma pista sobre quem pode ser o dono do bote destruído."}, [12]={npc="Um Pacote Pequeno", npcObj=true}, [13]={npc="Um Pacote Pequeno", npcObj=true}, [14]={hint="Examine os itens dentro da bolsa e leve até o dono.", desc="Mantenha o item na mochila."}, [15]={text="Vá para o norte pela borda leste até o Refúgio do Marshal. Evite os devilsaurs do meio."}, [16]={nodeA="{a:541}", node="Marshal's Refuge", desc="Desbloquear o ponto de voo com Gryfe."}, [17]={npc="Linken", tgt="Linken"}, [18]={npc="Linken", tgt="Linken", desc="Salve para entregar em Donova em Hibérnia."}, [19]={npc="Williden Marshal", tgt="Williden Marshal"}, [20]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [21]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal", tag="Opcional", desc="Leve ao Pico da Eternidade no Monte Hyjal e entregue a Tiala Whitemane."}, [22]={npc="Chispa Minanilo", tgt="Chispa Minanilo"}, [23]={npc="Cuidado com o Pterrordax", npcObj=true, tag="Opcional", desc="Missão de nível 55, na placa de avisos do acampamento; os pterrordaxes e as escamas vêm dos mesmos mobs, e os Pterrordaxes Frenéticos ficam no lado oeste da cratera."}, [24]={npc="Chislo", tgt="Chislo"}, [25]={npc="Lário", tgt="Lário"}, [26]={npc="Karna Trilheiro", tgt="Karna Trilheiro", desc="Entregue assim que encontrar A-Me 01 na caverna dos gorilas; a continuação pede itens de engenharia: não aceite."}, [27]={npc="J.D. Neri", tgt="J.D. Neri"}, [28]={text="Monstros de alcatrão ao norte → volta pela borda externa do acampamento → voltar ao acampamento"}, [29]={hint="Colete 12 amostras de Piche Supergrudento para Tran'rek em Geringontzan.", desc="Aceite na sua segunda visita a Tanaris."}, [30]={hint="Leve 8 Ossos de Dinossauro para Chispa Minanilo na Cratera Un'Goro."}, [31]={hint="Colete 8 Escamas de Dimetrodonte Palmado e 8 Escamas de Pterrordax Palmado para Chislo no Refúgio do Marshal."}, [32]={hint="Mate 10 Pterrordaxes e 15 Pterrordaxes Frenéticos, então fale com Espraga Froque no Refúgio do Marshal.", tag="Opcional"}, [33]={hint="Cace 5 Açoitadeiras Pétala Sangrenta, 5 Látegas Pétala Sangrenta, 5 Esfoladoras Pétala Sangrenta e 5 Laçadoras Pétala Sangrenta para Lário, do Refúgio do Marshal."}, [34]={hint="Leve 2 Pelagens de Gorila de Un'Goro, 2 Pelagens de Pisoteador de Un'Goro, 2 Pelagens de Trovejador de Un'Goro para Torwa Mateiro na entrada da Cratera Un'Goro.", tag="Alvo: Gorila de Un'Goro / Pisoteador de Un'Goro / Trovejador de Un'Goro"}, [35]={npc="A-Me 01", tgt="A-Me 01"}, [36]={hint="Leve um Caixote de Comestíveis e o Equipamento de Pesquisa para Williden Marshal in Cratera Un'Goro."}, [37]={hint="Colete 9 amostras das Cinzas de Un'Goro dos elementais de fogo ao redor do vulcão da Cratera Un'Goro, e leve-as para Fanny Quito, em Vila Catraca.", desc="Só faça se já tiver aceitado em Vila Catraca. Entregue em Vila Catraca."}, [38]={npc="Um Diário Destroçado", npcObj=true, tag="Opcional", desc="Começa com um item de saque. Se não cair, não fique farmando."}, [39]={hint="Devolva o diário a Williden Marshal na Cratera Un'Goro.", tag="Opcional", desc="Começa com um item de saque. Se não cair, não fique farmando."}, [40]={npc="Williden Marshal", tgt="Williden Marshal", tag="Opcional", desc="Começa com um item de saque. Se não cair, não fique farmando."}, [41]={hint="Leve uma Glândula Odorífera Gorishi e 5 Amostras de Solo de Un'Goro ao Alquimista Almofarrista em Geringontzan.", tag="Opcional", desc="Faça só se a aceitou em Tanaris; antes de sair da zona, percorra uma vez a rota do sul."}, [42]={hint="Use a Ampola de Amostra para coletar uma Amostra de Parede de Colmeia de uma das incubadoras Gorishi na Cratera Un'Goro. Procure as câmaras com larvas."}, [43]={hint="Colete 7 Cristais de Poder de cada uma das seguintes cores: vermelho, azul, amarelo e verde. Leve-os para J.D. Neri no Refúgio do Marshal."}, [44]={npc="Williden Marshal", tgt="Williden Marshal"}, [45]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [46]={npc="Chispa Minanilo", tgt="Chispa Minanilo"}, [47]={npc="Chislo", tgt="Chislo"}, [48]={npc="Espraga Froque", tgt="Espraga Froque", tag="Opcional"}, [49]={npc="Lário", tgt="Lário"}, [50]={npc="J.D. Neri", tgt="J.D. Neri"}, [51]={npc="J.D. Neri", tgt="J.D. Neri"}, [52]={npc="J.D. Neri", tgt="J.D. Neri"}, [53]={npc="J.D. Neri", tgt="J.D. Neri"}, [54]={npc="Lário", tgt="Lário", desc="Entregue em Vila Catraca."}, [55]={text="Voe de Refúgio do Marshal para Geringontzan e entregue qualquer missão de coleta lá."}, [56]={npc="Tran'rek", tgt="Tran'rek"}, [57]={npc="Alquimista Almofarrista", tgt="Alquimista Almofarrista", tag="Opcional"}, [58]={text="Voe de Geringontzan para Vila Catraca e entregue a Liv antes de pegar o barco."}, [59]={npc="Fanny Quito", tgt="Fanny Quito", tag="Se você coletou todas as cinzas na perna Refúgio do Marshal"}, [60]={hint="Vá até a oficina de Marlon Catarrebite na Vila Catraca.", tag="Se aceito na perna Refúgio do Marshal"}, [61]={npc="Fanny Quito", tgt="Fanny Quito", tag="Se aceito na perna Refúgio do Marshal"}, [62]={hint="Colete 8 Cogumelos Vermelhos e 8 Ferrões de Gorishi e fale novamente com Torwa Mateiro na Cratera Un'Goro.", tag="Opcional", desc="Faça junto com a colmeia do sul e as missões de flores."}, [63]={npc="Torwa Mateiro", tgt="Torwa Mateiro", tag="Opcional"}, [64]={npc="Torwa Mateiro", tgt="Torwa Mateiro", tag="Opcional", desc="Use o item de missão e saia. Você pode pular a elite."}, [65]={hint="Espete um Demossauro com uma Farpa para Demossauro. Fale novamente com Torwa Mateiro na Cratera Un'goro depois que tiver terminado a tarefa.", tag="Opcional", desc="Use o item de missão e saia. Você pode pular a elite."}, [66]={npc="Torwa Mateiro", tgt="Torwa Mateiro", tag="Opcional", desc="Use o item de missão e saia. Você pode pular a elite."}, [67]={npc="Torwa Mateiro", tgt="Torwa Mateiro", tag="Opcional", desc="Forme um grupo para o Templo Submerso na próxima volta aos Reinos do Leste, depois da Capela Esperança da Luz.", star={"Pelagem Cinzenta", {"DRUID"}}}, [68]={text="Em Vila Catraca, pegue o barco para Angra do Butim e depois voe para Karrath, nos Ermos. Guarde as garras de Ravasaur para o caminho da Cidade Baixa de volta a Orgrimmar."}}},
    ["04-42"] = {name="Estepes Ardentes: Montanha Rocha Negra", nameA="Estepes Ardentes: {a:251} & Montanha Rocha Negra", shortA="Estepes Ardentes: {a:251} +", tips={{k="取捨", text="Em Karrath, aceite primeiro e O levante das máquinas; depois de desbloquear o Monte Candente, concentre-se em Rochedo Malhorrendo e Ruínas de Thaurissan."}, {k="取捨", text="Aceite Felnok Molaço primeiro e guarde-a para entregar em Visteterna, em Hibérnia."}, {k="取捨", text="Desarmonia das chamas e O levante das máquinas exigem ir à Montanha Rocha Negra ou fazer mais uma viagem aos Ermos; se estiver subindo de nível sozinho e com pouco tempo, pode pular. Se quiser fazer o Abismo Rocha Negra, aceite as continuações à parte."}, {k="提醒", text="Precisa de EXP? Mate anões e golens Dark Iron ao redor das Ruínas de Thaurissan. Se for ao Abismo Rocha Negra em grupo, pegue antes as missões de masmorra em Karrath e Monte Candente.", s={{"Precisa de EXP?"}, {"Mate anões e golens Dark Iron ao redor das Ruínas de Thaurissan"}, {"Se for ao Abismo Rocha Negra em grupo, pegue antes as missões de masmorra em Karrath e Monte Candente"}}}}, danger={[1]="A passagem da mina para o Abismo Rocha Negra é estreita, e o Mestre Supremo Piro patrulha por ali. Limpe os mobs comuns da entrada antes de atacar.", [2]="Conjuradores e patrulhas das Ruínas de Thaurissan entram na luta juntos. Puxe de fora das paredes quebradas e não fique no cruzamento de duas rotas de patrulha."}, grind={[1]={mob="Aniquilador de Guerra", note="Golens comuns fora das Ruínas de Thaurissan. Siga pela parede externa para ir matando em sequência e contando as mortes da missão das ruínas. Cuidado com os conjuradores misturados entre os escombros."}, [2]={mob="Andachama de Thaurissan", note="Anões comuns nas mesmas ruínas; dá para pegar tecido e contar mortes de passagem. Conjuradores e patrulhas podem entrar na luta juntos, então puxe de fora das paredes quebradas."}}, supply={[1]={npc="Vahgruk"}, [2]={npc="Yuka Parafuseta"}, [3]={npc="Gruna"}, [4]={npc="Estalajadeiro Shul'kar"}, [5]={npc="Sranda"}, [6]={npc="Rosnado"}}, steps={[1]={npc="Thal'trak Altapresa", tgt="Thal'trak Altapresa", desc="Aceite em Karrath; entregue no Rochedo Malhorrendo, a leste."}, [2]={npc="Hierofante Theodora Malvadania", tgt="Hierofante Theodora Malvadania", desc="Aceite em Karrath. Mate golens e elementais nas Estepes Ardentes."}, [3]={npc="Coração Trovejante", tgt="Coração Trovejante", tag="Grupo recomendado, Opcional", desc="Aceite em Karrath somente se você estiver indo para Montanha Rocha Negra."}, [4]={text="Se já abriu o ponto de voo de Monte Candente e não vai fazer Desarmonia das Chamas, voe de Karrath direto para Monte Candente. Caso contrário, voe de Karrath para Posto de Tório, vá ao sul para a Montanha Rocha Negra e desça pelas correntes até a Pedreira de Moagem, no nível mais baixo."}, [5]={hint="Vá até a pedreira da Montanha Rocha Negra e mate o Mestre Supremo Piro. Fale novamente com Coração Trovejante quando tiver cumprido essa tarefa.", tag="Grupo recomendado, Opcional", desc="Pyron é uma elite de nível 52 que patrulha a Pedreira de Moagem, fora da entrada do Abismo Rocha Negra."}, [6]={text="Da Montanha Rocha Negra siga para a saída das Estepes Ardentes e depois acompanhe o lado norte para leste até Monte Candente.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [7]={nodeA="{a:251}", node="Flame Crest", desc="Desbloquear o ponto de voo com Vahgruk."}, [8]={hint="Fale com Yuka Parafuseta nas Estepes Ardentes.", tag="Opcional", desc="Só entregue se a aceitou em Porto de Bondebico, em Tanaris."}, [9]={npc="Yuka Parafuseta", tgt="Yuka Parafuseta", tag="Opcional"}, [10]={npc="Maxwort Uberraio", tgt="Maxwort Uberraio"}, [11]={npc="Vera Brequim", tgt="Vera Brequim"}, [12]={text="Rochedo Malhorrendo no leste → Ruínas de Thaurissan → Karrath"}, [13]={hint="Explore as Estepes Ardentes e descubra o que aconteceu com Sha'ni Altapresa."}, [14]={npc="Sha'ni Altapresa", tgt="Sha'ni Altapresa"}, [15]={npc="Sha'ni Altapresa", tgt="Sha'ni Altapresa"}, [16]={hint="Recupere a Argola Nasal de Sha'ni de Krom'Grul e leve-a para Thal'trak em Karrath. Procure nas várias cavernas e minas do Rochedo Malhorrendo."}, [17]={hint="Leve 8 Essências da Reprodução e o Draco-incarcinatrix 900 a Vera Brequim no Monte Candente, que fica nas Estepes Ardentes.", desc="Use o item de missão primeiro. Mate o alvo e saqueie a essência que ele deixa para trás."}, [18]={hint="Leve a Transcrição de Tabuleta para Maxwort Uberraio nas Estepes Ardentes."}, [19]={hint="Vá para as Estepes Ardentes e recupere 10 Estilhaços Elementais Fraturados para a Hierofante Theodora Malvadania.", desc="Mate os alvos na mesma viagem dos tablets."}, [20]={npc="Maxwort Uberraio", tgt="Maxwort Uberraio"}, [21]={npc="Vera Brequim", tgt="Vera Brequim"}, [22]={npc="Vera Brequim", tgt="Vera Brequim", desc="Guarde para entregar a Felnok Molaço em Visteterna, em Hibérnia."}, [23]={text="Voe de Monte Candente para Karrath. Entregue Argola Nasal de Sha'ni e os fragmentos. Entregue a missão Mestre Supremo Piro se você a tiver concluído."}, [24]={npc="Thal'trak Altapresa", tgt="Thal'trak Altapresa"}, [25]={npc="Hierofante Theodora Malvadania", tgt="Hierofante Theodora Malvadania"}, [26]={npc="Hierofante Theodora Malvadania", tgt="Hierofante Theodora Malvadania", tag="Opcional", desc="Só vá ao leste se quiser pegar a sequência secundária do Abismo Rocha Negra."}, [27]={hint="Leve a Amostra de Estilhaço Elemental para Lotwil Viriato.", tag="Opcional", desc="Só vá ao leste se quiser pegar a sequência secundária do Abismo Rocha Negra."}, [28]={npc="Lotwil Viriato", tgt="Lotwil Viriato", tag="Opcional", desc="Só vá ao leste se quiser pegar a sequência secundária do Abismo Rocha Negra."}, [29]={npc="Coração Trovejante", tgt="Coração Trovejante", tag="Grupo recomendado, Opcional"}, [30]={text="Voe de Karrath para a Cidade Baixa e prepare-se para as Terras Pestilentas Ocidentais."}}},
    ["05-d24"] = {name="Abismo Rocha Negra", entrance="Garganta Abrasadora (1427), 34.80, 85.30. Marca o acesso externo a Montanha Rocha Negra.", pickup="Abra o ponto de voo de Posto de Tório. Ao passar por Monte Candente, procure primeiro Yuka e Maxwort. Voe para Karrath e fale com Coração Trovejante, o quadro de procurados e Vivian. Entre em Montanha Rocha Negra, mate o Mestre Supremo Piro do lado de fora e volte a Karrath para entregar Desarmonia das chamas e pegar Desarmonia do fogo e O último elemento. Depois entre na montanha de novo, por Posto de Tório ou Monte Candente.", pickupS={{"Abra o ponto de voo de Posto de Tório"}, {"Ao passar por Monte Candente, procure primeiro Yuka e Maxwort"}, {"Voe para Karrath e fale com Coração Trovejante, o quadro de procurados e Vivian"}, {"Entre em Montanha Rocha Negra, mate o Mestre Supremo Piro do lado de fora e volte a Karrath para entregar Desarmonia das chamas e pegar Desarmonia do fogo e O último elemento"}, {"Depois entre na montanha de novo, por Posto de Tório ou Monte Candente"}}, tips={{k="動線", text="Dá para derrotar antes o Mestre Supremo Piro do lado de fora → corredores do bloco de detenção e da arena: elimine os anões Ironfury → Bigorna Negra: Incendius → Salão da Criação: Fineous; no monumento, troque pela chave de Umbraforja → cofre: pegue O Coração da Montanha; no Grim Guzzler, Ribbles e a receita, em qualquer ordem → passe pelos Sete e pela ponte de lava até o Fragmento de Núcleo ao lado da porta de Núcleo Derretido. Elimine elementais e golens pelo caminho."}, {k="取捨", text="Priorize as missões Karrath e Monte Candente na primeira execução. Faça o cofre ou a entrada Núcleo Derretido se tiver tempo."}, {k="說明", text="A entrada norte leva a Montanha Rocha Negra. Lá dentro, desça pela corrente central, atravesse a Pedreira de Moagem e passe pelo Mestre Supremo Piro para chegar ao portal. Também dá para entrar pelas Estepes Ardentes (29.40, 38.30).", s={{"A entrada norte leva a Montanha Rocha Negra"}, {"Lá dentro, desça pela corrente central, atravesse a Pedreira de Moagem e passe pelo Mestre Supremo Piro para chegar ao portal"}, {"Também dá para entrar pelas Estepes Ardentes (29.40, 38.30)"}}}}, steps={[1]={npc="Yuka Parafuseta", tgt="Yuka Parafuseta"}, [2]={npc="Maxwort Uberraio", tgt="Maxwort Uberraio", tag="Opcional", desc="Colete 12 chaves Arca de Relíquia. Retire apenas se o seu grupo planeja fazer o cofre."}, [3]={npc="PROCURA-SE", npcObj=true}, [4]={npc="Umbramante Vivian Latumba", tgt="Umbramante Vivian Latumba"}, [5]={npc="Coração Trovejante", tgt="Coração Trovejante", desc="Entre na montanha pela entrada norte da Montanha Rocha Negra; Piro fica dentro da Pedreira de Moagem, diante do portal."}, [6]={hint="Vá até a pedreira da Montanha Rocha Negra e mate o Mestre Supremo Piro. Fale novamente com Coração Trovejante quando tiver cumprido essa tarefa."}, [7]={npc="Coração Trovejante", tgt="Coração Trovejante"}, [8]={npc="Coração Trovejante", tgt="Coração Trovejante", preText="Desarmonia das chamas"}, [9]={npc="Umbramante Vivian Latumba", tgt="Umbramante Vivian Latumba", preText="Desarmonia das chamas"}, [10]={npc="Franclorn Forjífice", tgt="Franclorn Forjífice", desc="Vá como fantasma até a tumba suspensa no centro de Montanha Rocha Negra para encontrar Forgewright. As coordenadas externas de Montanha Rocha Negra servem só para navegação."}, [11]={hint="Fale com Franclorn Forjífice se tiver interesse em obter uma chave para a parte principal da cidade.", desc="As coordenadas são do túmulo de Franclorn em Montanha Rocha Negra. Só é visível como fantasma."}, [12]={npc="Franclorn Forjífice", tgt="Franclorn Forjífice"}, [13]={npc="Franclorn Forjífice", tgt="Franclorn Forjífice", preText="Legado dos Ferro Negro"}, [14]={npc="Lothos Fendespéril", tgt="Lothos Fendespéril", tag="Opcional", desc="Só pegue com o nível 55 completo. Faça junto com a rota pelos Sete e pela porta de Núcleo Derretido."}, [15]={text="Entrada: Abismo Rocha Negra"}, [16]={hint="Desbrave o Abismo Rocha Negra e destrua aqueles invasores degenerados!", desc="Local: Entre no Bloco de Detenção e siga pelas celas até o Círculo da Lei, eliminando os guardas.", spot="Entre no Bloco de Detenção e siga pelas celas até o Círculo da Lei, eliminando os guardas."}, [17]={hint="Entre no Abismo Rocha Negra e encontre o Lorde Incendius. Mate-o e leve todas as informações que puder para o Coração Trovejante.", desc="Local: Siga a Estrada do Ferro Negro, descendo até a Bigorna Negra. Mate Incendius.", spot="Siga a Estrada do Ferro Negro, descendo até a Bigorna Negra. Mate Incendius."}, [18]={hint="Mate Fineous Forçanegra e recupere o grande martelo Ferrovil. Leve-o para o Santuário de Thaurissan e coloque-o na estátua de Franclorn Forjífice.", desc="Local: Pegue o martelo no Salão dos Artesãos e depois vá ao monumento do Templo de Thaurissan. Ordem: Mate primeiro Fineous e depois clique no monumento.", spot="Pegue o martelo no Salão da Criação e leve-o ao monumento no Santuário de Thaurissan."}, [19]={npc="Monumento de Franclorn Forjífice", npcObj=true, spot="Monumento de Franclorn Forjaverdade no Santuário de Thaurissan"}, [20]={hint="Vá até o Abismo Rocha Negra e obtenha 10 Essências dos Elementos. Seu primeiro impulso é procurar nos golens e criadores de golens. Você lembra que Vivian Latumba também mencionou elementais.", desc="Local: Mate elementais e golens ao longo da Estrada do Ferro Negro, desde a entrada. O Mestre Supremo Piro pode ser morto do lado de fora.", spot="Mate elementais e golens ao longo da Estrada do Ferro Negro, desde a entrada. O Mestre Supremo Piro pode ser morto do lado de fora."}, [21]={hint="Leve a Cabeça do Ribas para Yuka Parafuseta nas Estepes Ardentes.", desc="Fale com Ribas Parafuseta ao lado da mesa do bar para começar a luta. Local: Atravesse a Cidade Forjassombra até o Grim Guzzler e procure Ribas ao lado da mesa do bar.", spot="Atravesse a Cidade de Umbraforja até o Grim Guzzler e procure Ribbly ao lado das mesas."}, [22]={hint="Leve a Receita Perdida de Cervaforte para Vivian Latumba em Karrath.", desc="Limpe com os colegas os inimigos perto do bar antes de agir. As duas facções obtêm a receita do mesmo inimigo. Local: Vá à sala atrás do bar, quebre os três barris e espere Hurley Bafonegro aparecer.", spot="Quebre três barris na sala dos fundos do Grim Guzzler e espere por Hurley."}, [23]={hint="Leve o Coração da Montanha para Maxwort Uberraio nas Estepes Ardentes.", tag="Opcional", desc="Local: No Cofre Ferro Negro, abra os 12 cofres de relíquias e depois pegue O Coração da Montanha na sala escondida.", spot="No Cofre Ferro Negro, abra os 12 cofres de relíquias e depois pegue O Coração da Montanha na sala escondida."}, [24]={hint="Vá ao portal da entrada do Núcleo Derretido no Abismo Rocha Negra e recupere um Fragmento de Núcleo. Fale novamente com Lothos Fendespéril na Montanha Rocha Negra após recuperar o Fragmento de Núcleo.", tag="Opcional", desc="Local: Passe pelos Sete e atravesse a ponte de lava. O fragmento fica ao lado da porta de Núcleo Derretido.", spot="Passe pelos Sete e atravesse a ponte de lava. O fragmento fica ao lado da porta de Núcleo Derretido."}, [25]={npc="Lothos Fendespéril", tgt="Lothos Fendespéril", tag="Opcional"}, [26]={npc="Yuka Parafuseta", tgt="Yuka Parafuseta"}, [27]={npc="Maxwort Uberraio", tgt="Maxwort Uberraio", tag="Opcional"}, [28]={npc="Coração Trovejante", tgt="Coração Trovejante"}, [29]={npc="Senhor da Guerra Trincador", tgt="Senhor da Guerra Trincador"}, [30]={npc="Umbramante Vivian Latumba", tgt="Umbramante Vivian Latumba"}, [31]={npc="Umbramante Vivian Latumba", tgt="Umbramante Vivian Latumba"}, [32]={text="Depois de entregar, voe direto de Karrath para Cidade Baixa e siga para a próxima parada."}}},
    ["04-44"] = {name="Terras Pestilentas Ocidentais", nameA="Terras Pestilentas Ocidentais: {a:813}", tips={{k="交通", text="Para ir ao Baluarte, só a pé. Do lado oeste, siga para as Clareiras de Tirisfal ou a Cidade Baixa e pegue o zepelim fora da cidade de volta a Orgrimmar."}, {k="取捨", text="O caldeirão da peste e o pacote da Fazenda Felstone ficam no mesmo local; ao voltar à cidade, entregue Antes tarde do que nunca e O fado de Jeremias juntos."}, {k="取捨", text="Nesta ida, conclua o primeiro caldeirão; deixe Alvo: Lágrimas de Dalson, de Lágrimas de Dalson, e a missão de Scolomântia de Andorhal para a próxima rodada. O Amuleto da Sorte de Jeremiah (Pingente da Sorte/Um só coração) só é feito depois, na volta às Terras Pestilentas Ocidentais."}, {k="提醒", text="Abaixo do nível 55? Mate esqueletos e carniçais comuns ao redor de Campo Pedravil (cerca de 38, 56) e evite as elites de nível alto dentro de Andorhal.", s={{"Abaixo do nível 55?"}, {"Mate esqueletos e carniçais comuns ao redor de Campo Pedravil (cerca de 38, 56) e evite as elites de nível alto dentro de Andorhal"}}}}, danger={[1]="Araj, o Evocador é uma elite de nível 61 no centro de Andorhal. Fique na periferia da cidade ao marcar as torres e fique fora da praça."}, grind={[1]={mob="Esfolador Descarnado", note="Mortos-vivos comuns em Campo Pedravil, de passagem no circuito do caldeirão. É mais fácil puxar nos campos do que perto das casas. Se houver muitos jogadores em missão, mova-se pela borda."}, [2]={mob="Carniçal Salivante", note="Carniçais normais na mesma fazenda. Mate-os entre o reaparecimento do esqueleto. Não persiga mobs em Andorhal."}}, supply={[1]={npc="Intendente Argêntea Hasana"}, [2]={npc="Miguel Garreta"}, [3]={npc="Estalajadeiro Ronan"}, [4]={npc="Estalajadeiro Ronan"}, [5]={npc="Eleanor Rusga"}, [6]={npc="Thomas Mordan"}, [7]={npc="Ezequiel Potio"}}, steps={[1]={hint="Leve a Tabuleta de Markri para Andron Gante na Cidade Baixa.", tag="Opcional"}, [2]={npc="Andron Gante", tgt="Andron Gante", tag="Opcional"}, [3]={text="Saia de Cidade Baixa e siga pela estrada leste através de Clareiras de Tirisfal até o Baluarte (83.13, 68.94). Mantenha o Cidade Baixa ponto de voo à mão para entregas de missões na cidade no final desta etapa."}, [4]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz", desc="Depois de aceitar, pegue a Chama Engarrafada no baú ao lado de Derington e leve também o Estandarte do Flagelo dado pela missão."}, [5]={hint="Vá até a base de operações da Cruzada Escarlate, que fica entre o Campo Pedravil e as Lágrimas de Dalson, e destrua a Tenda de Comando.", desc="Queime primeiro a barraca com a Chama Engarrafada e depois use o estandarte."}, [6]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz", desc="Queime primeiro a barraca com a Chama Engarrafada e depois use o estandarte."}, [7]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz"}, [8]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz"}, [9]={hint="Fale com a Sacerdotisa Sombria Vandis, em Baluarte, que fica nas Terras Pestilentas Ocidentais."}, [10]={npc="Sacerdotisa Sombria Vandis", tgt="Sacerdotisa Sombria Vandis"}, [11]={npc="Sacerdotisa Sombria Vandis", tgt="Sacerdotisa Sombria Vandis"}, [12]={text="Siga para o leste do Baluarte até Campo Pedravil. Pegue primeiro a amostra do Caldeirão do Flagelo e depois verifique a casa de Janice e os estábulos."}, [13]={hint="Vá ao Campo Pedravil nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá. Ele pode ter uma chave que dê acesso ao caldeirão. Você precisa estar com a Garrafa do Campo Pedravil Vazia para guardar uma amostra dos venenos usados no caldeirão.", desc="Verifique se você tem o frasco vazio do entregador da missão."}, [14]={npc="Caldeirão do Flagelo", npcObj=true}, [15]={npc="Caldeirão do Flagelo", npcObj=true, desc="Colete a amostra e aceite a missão de retorno no mesmo caldeirão."}, [16]={npc="Janice Pedravil", tgt="Janice Pedravil"}, [17]={hint="As divagações da mulher fantasmagórica indicavam que ela precisava que um pacote fosse entregue. Ela afirmou que ele estava no mesmo lugar que seu cavalo. Quanto ao local onde o cavalo está ou onde o pacote deve ser entregue, continua sendo impossível entender o fantasma.", desc="Interaja com o pacote dentro do estábulo."}, [18]={npc="Embrulho da Janice", npcObj=true}, [19]={npc="Embrulho da Janice", npcObj=true, desc="Escolha a versão da Horda, Antes tarde do que nunca, e leve de volta à Cidade Baixa para entregar; aqui você só pega o pacote."}, [20]={text="Siga de Campo Pedravil para o leste até Lágrimas de Dalson. Aqui resolva primeiro o diário da casa e a chave; deixe o Caldeirão do Flagelo para a próxima vez."}, [21]={npc="Diário da Sra. Dalson", npcObj=true}, [22]={hint="Complete os objetivos da missão."}, [23]={npc="Diário da Sra. Dalson", npcObj=true}, [24]={npc="Casinha", npcObj=true, desc="Depois de ler o diário, procure o Esqueleto Errante. O fazendeiro aparece ao abrir a latrina."}, [25]={hint="Saque de: Esqueleto Errante", desc="Depois de ler o diário, procure o Esqueleto Errante. O fazendeiro aparece ao abrir a latrina."}, [26]={npc="Casinha", npcObj=true, desc="Depois de ler o diário, procure o Esqueleto Errante. O fazendeiro aparece ao abrir a latrina."}, [27]={npc="Armário Trancado", npcObj=true, desc="Limpe ao redor da latrina. Abra o baú e entregue imediatamente."}, [28]={hint="Saque de: Fazendeiro Dalson", desc="Limpe ao redor da latrina. Abra o baú e entregue imediatamente."}, [29]={npc="Armário Trancado", npcObj=true, desc="Limpe ao redor da latrina. Abra o baú e entregue imediatamente."}, [30]={text="Dê a volta pela borda de Andorhal, passando por cada torre, e depois volte ao Baluarte. Se houver guardas de nível alto na porta de uma torre, espere a patrulha se afastar."}, [31]={hint="Usando a Tocha Sinalizadora, marque cada torre em Andorhal. Você tem que ficar na entrada da torre para conseguir marcá-la.", desc="Dá para usar a tocha na porta, sem precisar entrar na torre para matar os guardas."}, [32]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz"}, [33]={npc="Sacerdotisa Sombria Vandis", tgt="Sacerdotisa Sombria Vandis"}, [34]={text="Volte para Cidade Baixa e entregue o pacote próximo ao registrador da guilda."}, [35]={hint="Fale com os Feitores Reais da Cidade Baixa para saber o paradeiro da Jeremias Pedravil. Geralmente tem um agente do censo perto do registro de guilda e tabardo."}, [36]={npc="Feitor Real Mesquita", tgt="Feitor Real Mesquita"}, [37]={npc="Feitor Real Mesquita", tgt="Feitor Real Mesquita"}, [38]={npc="Jeremias Mascotte", tgt="Jeremias Mascotte"}, [39]={npc="Jeremias Mascotte", tgt="Jeremias Mascotte", desc="Guarde por ora a metade do amuleto; entregue em Campo Pedravil, nas Terras Pestilentas Ocidentais, quando passar pelo Baluarte."}, [40]={npc="Cavaleiro do Luto", tag="Opcional", desc="Depois de entregar as missões da Cidade Baixa e antes de embarcar no zepelim, vá ao sudoeste para encontrá-lo. O cavaleiro tem vários pontos de aparecimento."}, [41]={hint="Speak with the Knight of Mourning to learn more about his unfinished quest.", tag="Opcional", desc="Depois de entregar as missões da Cidade Baixa e antes de embarcar no zepelim, vá ao sudoeste para encontrá-lo. O cavaleiro tem vários pontos de aparecimento."}, [42]={npc="Cavaleiro do Luto", tag="Opcional", desc="Depois de entregar as missões da Cidade Baixa e antes de embarcar no zepelim, vá ao sudoeste para encontrá-lo. O cavaleiro tem vários pontos de aparecimento."}, [43]={npc="Cavaleiro do Luto", tag="Opcional", desc="Ouça primeiro The Knight of Mourning até o fim; o relicário fica dentro da masmorra Gruta Bocanera: faça só se decidir entrar na Gruta Bocanera; depois de sair da masmorra, volte às Clareiras de Tirisfal para entregar.", star={"Sword of Mourning", {"PALADIN"}}}, [44]={hint="Leve as Penas Vodu dos trolls do Templo Submerso para o Herói Caído da Horda.", tag="Opcional, Alvo: Gashar / Zul'rol / Hooku / Mishan / Zul'ro / Lo'rol", desc="Leve para o Templo Submerso junto com as outras missões do Pântano das Mágoas."}, [45]={npc="Herói Caído da Horda", tgt="Herói Caído da Horda", tag="Opcional", desc="Entregue na entrada norte de Barreira do Inferno. Dá para escolher o Frasco de Diamante, entre outras recompensas.", star={"Frasco de Diamante", {"WARRIOR"}}}, [46]={hint="Leve o Dente de Morphaz para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath.", tag="Opcional", desc="Forme grupo em Pedregal para o Templo Submerso e procure Morphaz, o dragão verde."}, [47]={hint="Leve as partes para Bath'rah, o Vigia dos Ventos, fazer o totem de espírito.", tag="Opcional", desc="Mate aranhas, ursos e abutres enquanto realiza as missões da fazenda das Terras Pestilentas."}, [48]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Antes de sair da Cidade Baixa, voe a Serraria Tarren e entregue a Bath'rah."}, [49]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Aceite se tiver grupo para o Templo Submerso; termine na próxima volta aos Reinos do Leste.", star={"Espírito de Água Enamorado", {"SHAMAN"}}}, [50]={hint="Recupere o Estilhaço Arcano de posse de Morphaz e fale novamente com o Arquimago Tauriel.", tag="Opcional", desc="Forme grupo em Pedregal para o Templo Submerso e procure Morphaz, o dragão verde."}, [51]={hint="Leve a Chave Lazúli para o Lorde Jorach Corvoforte.", tag="Opcional", desc="Forme grupo em Pedregal para o Templo Submerso e procure Morphaz, o dragão verde."}, [52]={npc="Lorde Jorach Corvoforte", tgt="Lorde Jorach Corvoforte", tag="Opcional", desc="Voe de Pedregal a Serraria Tarren e entregue na mansão. Dá para escolher a Máscara de Ébano, entre outras recompensas.", star={"Clâmide Quiropúsculo", {"ROGUE"}}}, [53]={hint="Consiga uma Trepadeira Pútrida do guardião no fundo do Templo Submerso e fale novamente com Torwa Mateiro.", tag="Opcional", desc="Precisa de grupo; se o grupo só vai limpar a área dos dragões, avise antes que você precisa descer até o andar de baixo para as estátuas de serpente."}, [54]={hint="Mate Morphaz no templo submerso de Atal'Hakkar e leve o sangue dele para Greta Musgo no Casco na Selva Maleva. A entrada do templo submerso fica no Pântano das Mágoas.", tag="Opcional", desc="Forme grupo em Pedregal para o Templo Submerso e procure Morphaz, o dragão verde."}, [55]={text="Pegue o zepelim para Orgrimmar na torre fora da Cidade Baixa."}}},
    ["04-45"] = {name="Selva Maleva: sul", nameA="Selva Maleva: sul & {a:1997}", short="Selva Maleva: sul +", tips={{k="交通", text="Desbloqueie agora o ponto de voo de Posto Peçonha; a próxima etapa também parte daqui. Se passar por Posto Machadada, siga pela estrada principal contornando os guardas da cidade da Aliança."}, {k="取捨", text="Os ursos Madeira Morta do sul dão direto reputação com os Presamatos. Jaedenar, Rell do sul e o poço lunar dos sátiros Fogoverde podem ser feitos em sequência."}, {k="取捨", text="Aceite primeiro Purificar Selva Maleva e junte o âmbar sanguíneo no norte. Depois de coletar, volte ao sul mais tarde para entregar, o que poupa uma volta imediata."}, {k="提醒", text="Abaixo do nível 55? Dê prioridade a matar elementais comuns na borda do Vale das Escaras Pungentes (cerca de 41, 42) ou fúrbolgs Lenha Morta para a reputação dos Presamatos.", s={{"Abaixo do nível 55?"}, {"Dê prioridade a matar elementais comuns na borda do Vale das Escaras Pungentes (cerca de 41, 42) ou fúrbolgs Lenha Morta para a reputação dos Presamatos"}}}}, danger={[1]="Os elementais de calor do Vale das Escaras Pungentes reaparecem em pares na beira do poço. Puxe do topo da rampa, um de cada vez, e não atravesse o fundo do poço até o próximo grupo."}, grind={[1]={mob="Fera Entrópica", note="Elementais comuns na borda do Vale das Escaras Pungentes; coincidem com a missão de matar elementais de calor. Se a entrada estiver cheia de jogadores em missão, trabalhe de fora para dentro."}, [2]={mob="Horror Entrópico", note="Mesmo grupo de elementais comuns, com variantes de nível mais alto misturadas com as feras de calor. O terreno é estreito; fique atento aos que reaparecem em pares."}}, supply={[1]={npc="Brakkar"}, [2]={npc="Altsoba Totem da Fúria"}, [3]={npc="Fardo"}, [4]={npc="Fardo"}, [5]={npc="Estalajadeira Kailisk"}, [6]={npc="Estalajadeira Kailisk"}}, steps={[1]={npc="Sona'rima", tgt="Sona'rima", tag="Opcional", desc="Aceite em Valormok e junte as garras brancas de Ravasaur em Un'Goro."}, [2]={text="Voe de Orgrimmar a Posto Machadada, no Vale Gris, siga a estrada principal a oeste e depois entre em Selva Maleva pela estrada norte do Vale Gris. Pare primeiro em Santuário Esmeralda, no extremo sul."}, [3]={npc="Grazle", tgt="Grazle"}, [4]={npc="Maibess Brisa do Rio", tgt="Maibess Brisa do Rio", desc="O Âmbar de Sangue está no norte de Selva Maleva. Na próxima parada, mate de passagem os Ferrárbol (entes) e volte ao sul mais tarde para entregar."}, [5]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco"}, [6]={npc="Taronn Pena Vermelha", tgt="Taronn Pena Vermelha"}, [7]={hint="Grazle quer que você prove seu valor matando 6 Guerreiros de Lenha Morta, 6 Desbravadores de Lenha Morta e 6 Jardineiros de Lenha Morta. Quando você terminar, fale novamente com ele na parte sul da Selva Maleva, perto do Santuário Esmeralda.", desc="Ao concluir, sua reputação com o Domínio dos Presamatos sobe. Se ainda estiver hostil, complete no acampamento do norte mais tarde."}, [8]={npc="Grazle", tgt="Grazle"}, [9]={npc="Grazle", tgt="Grazle", desc="Aceite agora e entregue na próxima etapa, no extremo norte de Selva Maleva."}, [10]={text="Siga a estrada principal para o norte através de Jaedenar até Posto Peçonha."}, [11]={nodeA="{a:1997}", node="Bloodvenom Post", desc="Desbloquear o ponto de voo com Brakkar."}, [12]={hint="Entre em Jaedenar e mate 4 Cães de Jaedenar, 4 Guardas de Jaedenar, 6 Adeptos de Jaedenar e 6 Sectários de Jaedenar. Depois, fale novamente com Greta Musgo no Casco, na Selva Maleva."}, [13]={npc="Winna Perícon", tgt="Winna Perícon"}, [14]={npc="Dreka'Sur", tgt="Dreka'Sur"}, [15]={text="Siga a estrada principal para o norte por um trecho até o Vale das Escaras Pungentes e conclua a pesquisa da corrupção. Depois volte a Santuário Esmeralda pelo poço lunar dos sátiros a oeste e pelo acampamento orc ao sul."}, [16]={hint="Procure e destrua 2 Feras Entrópicas e 2 Horrores Entrópicos enquanto explora o Vale das Escaras Pungentes. Depois de ver se as crateras ainda estão cheias de água contaminada com vileza, fale novamente com Taronn Pena Vermelha, na Selva Maleva.", desc="Visite também a área de pesquisa. Matar elementais por si só não irá completá-lo."}, [17]={hint="Colete uma amostra de água corrompida do poço lunar dos Sátiros Flamejade e leve-a para Winna Perícon no Posto Peçonha.", desc="Este poço lunar e o outro, no centro de Jaedenar, são dois objetivos diferentes."}, [18]={hint="Mate o Suserano Ror e leve a garra dele para Dreka'Sur no Posto Peçonha, na Selva Maleva.", desc="O alvo está no acampamento sul. Limpe ao longo da rampa antes de puxar."}, [19]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco"}, [20]={npc="Taronn Pena Vermelha", tgt="Taronn Pena Vermelha"}, [21]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco", desc="Na próxima visita, encha o cantil vazio no poço lunar do centro de Jaedenar."}, [22]={text="Retorne ao Posto Peçonha para entregar a amostra de água e a garra de Rell. Reabasteça se necessário."}, [23]={npc="Winna Perícon", tgt="Winna Perícon"}, [24]={npc="Dreka'Sur", tgt="Dreka'Sur"}, [25]={npc="Ogtinc", tgt="Ogtinc", tag="Opcional", desc="No caminho de Orgrimmar para Selva Maleva, dá para voar antes a Azshara e entregar a Ogtinc. Dá para escolher equipamentos como o Olho de Demossauro.", star={"Olho de Demossauro", {"HUNTER"}}}, [26]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel", tag="Opcional", desc="Antes de ir a Selva Maleva, dá para passar por Azshara e entregar a Xylem. Dá para escolher o Rubi de Fogo, entre outras recompensas.", star={"Rubi de Fogo", {"MAGE"}}}, [27]={npc="Niby, o Todo-poderoso", tgt="Niby, o Todo-poderoso", tag="Opcional"}, [28]={hint="Fale com Diabretim na Selva Maleva.", tag="Opcional"}, [29]={npc="Diabretim", tgt="Diabretim", tag="Opcional"}, [30]={npc="Diabretim", tgt="Diabretim", tag="Opcional", desc="Colete primeiro a essência de Jaedenar. Ao ir de Orgrimmar a Azshara, pegue mais uma. Depois de voltar aos Reinos do Leste, vá de Pedregal às Terras Devastadas."}, [31]={npc="Diabretim", tgt="Diabretim", tag="Opcional", desc="Se já aceitou Pedido de diabrete com o instrutor, entregue Pedido de diabrete direto e aceite O enchimento errado. Tecido Vil ×1: dá para comprar na casa de leilões."}, [32]={hint="Leve um pedaço de Tecido Vil para Diabretim, em Selva Maleva.", tag="Opcional", desc="Se já aceitou Pedido de diabrete com o instrutor, entregue Pedido de diabrete direto e aceite O enchimento errado."}, [33]={npc="Diabretim", tgt="Diabretim", tag="Opcional", desc="Se já aceitou Pedido de diabrete com o instrutor, entregue Pedido de diabrete direto e aceite O enchimento errado."}, [34]={npc="Diabretim", tgt="Diabretim", tag="Opcional"}, [35]={hint="Leve 10 pedaços de Madeira Podre e 4 Essências de Peçonha para Diabretim em Selva Maleva.", tag="Opcional"}, [36]={npc="Diabretim", tgt="Diabretim", tag="Opcional"}, [37]={npc="Diabretim", tgt="Diabretim", tag="Opcional", desc="Aceite se pretende fazer o Templo Submerso; dá para fazer ao chegar aos Reinos do Leste, depois do Baluarte, nas Terras Pestilentas Ocidentais.", star={"Ceifalmas", {"WARLOCK"}}}, [38]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco", tag="Opcional", desc="Entregue a Greta, em Santuário Esmeralda. Dá para escolher as Contas de Oração Abençoadas, entre outras recompensas.", star={"Contas de Oração Abençoadas", {"PRIEST"}}}}},
    ["04-46"] = {name="Selva Maleva: Domínio dos Presamatos", nameA="Selva Maleva: {a:1997} - Domínio dos Presamatos", shortA="Selva Maleva: {a:1997} +", tips={{k="交通", text="Reabasteça no Posto Peçonha e siga a estrada principal para o norte. Na bifurcação dentro do túnel, pegue a saída Hibérnia."}, {k="取捨", text="No norte da Floresta Ferrárbol, resolva juntos o âmbar sanguíneo e A força da corrupção, e só por último farme a reputação com os ursos Madeira Morta."}, {k="取捨", text="Se já concluiu Purificar Selva Maleva, guarde o item e entregue depois, na volta ao Santuário Esmeralda. Deixe À procura de auxílio espiritual em Vila Catraca."}, {k="提醒", text="Alcance Inamistoso com o Domínio dos Presamatos para passar com segurança pelo túnel. Se ainda estiver hostil ou abaixo do nível 56, mate fúrbolgs no norte de Vila da Lenha Morta (cerca de 62, 8).", s={{"Alcance Inamistoso com o Domínio dos Presamatos para passar com segurança pelo túnel"}, {"Se ainda estiver hostil ou abaixo do nível 56, mate fúrbolgs no norte de Vila da Lenha Morta (cerca de 62, 8)"}}}}, danger={[1]="Se você ainda estiver hostil com o Domínio dos Presamatos, os guardas do túnel podem atacar em grupo. Mate os fúrbolgs Lenha Morta do lado de fora até chegar a Inamistoso antes de passar."}, grind={[1]={mob="Vingador de Lenha Morta", note="Fúrbolgs comuns no norte de Vila da Lenha Morta. Mate-os antes de ir ao Domínio dos Presamatos para ganhar reputação e coletar penas. É fácil puxar vários nas tendas; limpe primeiro a parte externa."}, [2]={mob="Vigia do Covil de Lenha Morta", note="Fúrbolgs comuns perto da estrada principal da mesma aldeia. Se houver um grupo farmando reputação, pegue os isolados à beira da estrada. Não ataque os guardas Timbermaw."}}, supply={[1]={npc="Brakkar"}, [2]={npc="Altsoba Totem da Fúria"}, [3]={npc="Fardo"}, [4]={npc="Fardo"}}, steps={[1]={npc="Winna Perícon", tgt="Winna Perícon"}, [2]={npc="Trull Ruinazar", tgt="Trull Ruinazar", desc="Mate as bestas-coruja em Hibérnia, na próxima parada, e depois volte ao Posto Peçonha para entregar."}, [3]={text="Vá para o sul até o poço lunar central de Jaedenar, colete água e entregue-a em Santuário Esmeralda. Solte o gatinho no poço lunar Flamejade depois."}, [4]={hint="Leve o Cantil Vazio para o Poço Lunar no meio de Jaedenar e encha-o. Depois, fale novamente com Greta Musgo no Casco na Selva Maleva."}, [5]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco"}, [6]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco", desc="Salve a entrega para Islen Vidente da Água ao sul de Vila Catraca."}, [7]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco", desc="Leve à Caverna do Eremita, na entrada do Monte Hyjal, e entregue a Ketharas."}, [8]={hint="Leve o gatinho de Winna para o poço lunar corrompido, solte-o e depois o leve de volta para Winna.", desc="Depois de soltar o gatinho, não ande depressa demais nem voe; perto de Winna, clique primeiro no gatinho para devolvê-lo e só então entregue a missão."}, [9]={npc="Winna Perícon", tgt="Winna Perícon"}, [10]={text="Saia de Posto Peçonha e siga a estrada principal para o norte pela Floresta Ferrárbol e Vila da Lenha Morta. No extremo norte, procure Nafien na entrada da caverna Timbermaw."}, [11]={hint="Leve 15 Âmbares de Sangue para Maibess Brisa do Rio em Selva Maleva.", desc="Guarde o que juntar para entregar a Maybess na próxima visita ao sul de Selva Maleva."}, [12]={hint="Talo Casco de Espinhos da Aldeia Mojache em Feralas quer que você mate 12 Ursos-cinzentos Garraivoso e 12 Assoladores Patavil em Selva Maleva.", tag="Só faça se já tiver aceitado A força da corrupção.", desc="Precisa ter sido aceita em Aldeia Mojache; entregue no próprio acampamento, em Feralas."}, [13]={npc="Nafien", tgt="Nafien"}, [14]={npc="Nafien", tgt="Nafien"}, [15]={hint="Nafien quer que você mate 6 Vigias do Covil de Lenha Morta, 6 Vingadores de Lenha Morta e 6 Xamãs de Lenha Morta. Fale novamente com ele na parte norte da Selva Maleva, perto da entrada do Domínio dos Presamatos.", desc="Depois de limpar o acampamento do norte, confira a reputação com o Domínio dos Presamatos. Se ainda estiver hostil, mate mais fúrbolgs Lenha Morta até chegar a Inamistoso."}, [16]={npc="Nafien", tgt="Nafien"}, [17]={npc="Nafien", tgt="Nafien", desc="De dentro da caverna, siga até a saída para Hibérnia; ao sair, procure Salfa."}, [18]={text="Com o Domínio dos Presamatos em Inamistoso, entre no túnel e siga pela saída de Hibérnia. Não ataque os fúrbolgs Timbermaw dentro da caverna."}}},
    ["04-47"] = {name="Hibérnia", nameA="Hibérnia: {a:2255}", tips={{k="交通", text="Na primeira visita a Visteterna, desbloqueie o ponto de voo e vincule a Pedra de Regresso. A próxima parada é Aldeia Mojache, em Feralas. Se não tiver o ponto de voo, voe até Aldeia Vento Livre, em Mil Agulhas, e siga a estrada principal para oeste até Feralas para desbloquear."}, {k="取捨", text="Entregue primeiro todas as missões de Donova nas Fontes Termais de Fogofrio e mate as bestas-coruja pelo caminho. Os yetis e as quimeras de Visteterna podem ser feitos na mesma ida."}, {k="取捨", text="Úrsius é elite, e Atividade Invernosa exige voltar para o oeste até a entrada da caverna. Faça se tiver grupo ou se ainda precisar de progresso."}, {k="取捨", text="Deixe no diário o relatório de Visteterna e o livro do Duque Nicholas; entregue-os juntos na próxima rodada pelos Reinos do Leste."}, {k="提醒", text="Abaixo do nível 56? Mate Yetis normais a leste de Visteterna (cerca de 64, 40) ou furbolgs fora de Aldeia dos Invernosos. Evite a patrulha de elite.", s={{"Abaixo do nível 56?"}, {"Mate Yetis normais a leste de Visteterna (cerca de 64, 40) ou furbolgs fora de Aldeia dos Invernosos"}, {"Evite a patrulha de elite"}}}}, danger={[1]="Úrsius, o Dentilhaço, um urso de elite, patrulha ao norte de Visteterna. Mantenha distância enquanto mata ursos comuns sozinho e só faça a missão dele com um grupo.", [2]="Xamãs e patrulhas furbolg podem se unir em Aldeia dos Invernosos. Se você precisar de EXP, mate os guardas solitários do lado de fora."}, grind={[1]={mob="Yeti Cardo de Gelo", note="Yetis comuns a leste de Visteterna, perto do ponto de suprimentos; dá para coletar peles de passagem. Se houver jogadores em missão na entrada da caverna, comece pelo sopé da montanha."}, [2]={mob="Vigia do Covil dos Invernosos", note="Fúrbolgs comuns na borda de Aldeia dos Invernosos, para reputação com Timbermaw e itens relacionados. Dentro da aldeia é fácil puxar conjuradores junto; evite as patrulhas de elite."}}, supply={[1]={npc="Yugrek"}, [2]={npc="Estalajadeira Vizzi"}, [3]={npc="Nixxrak"}, [4]={npc="Estalajadeira Vizzi"}, [5]={npc="Wixxrak"}}, steps={[1]={hint="Viaje pelo Domínio dos Presamatos até chegar a Hibérnia. Fale com Salfa, que está de guarda em frente à entrada do Domínio dos Presamatos.", tag="Se já aceita em Posto Peçonha / Domínio dos Presamatos"}, [2]={npc="Salfa", tgt="Salfa", tag="Se já aceita em Posto Peçonha / Domínio dos Presamatos"}, [3]={npc="Salfa", tgt="Salfa", tag="Opcional", desc="Dá para resolver em Aldeia dos Invernosos, a leste de Visteterna. Como depois você volta a oeste, também pode esperar e entregar na próxima passagem pela entrada da caverna."}, [4]={text="Vá para o sul do túnel até Fontes Termais de Fogofrio e pegue as missões furbolg de Donova antes de ir para o acampamento Winterfall no oeste."}, [5]={npc="Bruna Covaneve", tgt="Bruna Covaneve", tag="Se aceito na perna Refúgio do Marshal"}, [6]={npc="Bruna Covaneve", tgt="Bruna Covaneve", desc="Pegue a poção no norte de Feralas. Entregue na próxima ida às Fontes Termais de Fogofrio."}, [7]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [8]={hint="Bruna Covaneve, de Hibérnia, quer que você mate 8 Desbravadores Invernosos, 8 Vigias do Covil dos Invernosos e 8 Totêmicos Invernosos."}, [9]={npc="Frasco Vazio de Aguardente", npcObj=true, tag="Aceite se cair", desc="Os ursos soltam Garrafas Vazias de Aguardente; clique nelas depois de pegar. Este é o pré-requisito da cadeia de missões dos ursos de Hibérnia. Se ainda não caiu, continue matando ursos normais fora da Aldeia dos Invernosos."}, [10]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [11]={npc="Bruna Covaneve", tgt="Bruna Covaneve", tag="Faça se cair"}, [12]={npc="Bruna Covaneve", tgt="Bruna Covaneve", desc="Guarde para a próxima visita ao norte de Selva Maleva. O caldeirão fica dentro de uma tenda Lenha Morta."}, [13]={text="Siga para o leste, rumo a Visteterna, e mate pelo caminho os dois tipos de bestas-coruja."}, [14]={nodeA="{a:2255}", node="Everlook", desc="Desbloquear o ponto de voo com Yugrek."}, [15]={text="Vincule sua Pedra de Regresso com Estalajadeira Vizzi na estalagem de Visteterna (61.36, 38.83).", bindA="{a:2255}"}, [16]={hint="Trull Ruinazar em Selva Maleva quer que você mate 15 Ferujas Furiosas e 15 Ferujas Maltrapilhas.", tag="Se já aceita em Posto Peçonha / Domínio dos Presamatos", desc="Guarde para entregar na próxima visita a Posto Peçonha, em Selva Maleva."}, [17]={hint="Leve a Carta de Vera para Felnok Molaço.", tag="Se a aceitou nas Estepes Ardentes"}, [18]={npc="Felnok Molaço", tgt="Felnok Molaço", tag="Se a aceitou nas Estepes Ardentes"}, [19]={npc="Felnok Molaço", tgt="Felnok Molaço", tag="Conclua antes a missão Felnok Molaço"}, [20]={npc="Umi Zombarruga", tgt="Umi Zombarruga"}, [21]={npc="Gregor Pedragris", tgt="Gregor Pedragris", desc="Na próxima vez, entregue ao Oficial Argênteo Garush no Baluarte."}, [22]={npc="Gregor Pedragris", tgt="Gregor Pedragris", desc="Guarde para entregar na Capela Esperança da Luz, nas Terras Pestilentas Orientais."}, [23]={npc="Jéssica Trilharrubra", tgt="Jéssica Trilharrubra", desc="Leve junto com o relatório de Visteterna para as Terras Pestilentas Orientais. Esta entrega é em Vila das Flechas."}, [24]={npc="Ventania Casco Escuro", tgt="Ventania Casco Escuro", tag="Elite, Grupo recomendado, Opcional"}, [25]={text="Limpe a caverna do Yeti e a área circundante a leste de Visteterna e, em seguida, faça uma volta para o norte e para o leste, se necessário."}, [26]={hint="Colete 10 Peles Grossas de Yeti para Umi Zombarruga em Visteterna.", desc="Traga um chifre de Yeti para a próxima missão. Pegue Eu yeti falar uma coisa... em uma viagem posterior."}, [27]={npc="Umi Zombarruga", tgt="Umi Zombarruga"}, [28]={hint="Leve 8 Chifres Inteiriços de Quimera Ventogelante para Felnok Molaço.", tag="Conclua antes a missão Felnok Molaço"}, [29]={npc="Felnok Molaço", tgt="Felnok Molaço", tag="Conclua antes a missão Felnok Molaço"}, [30]={hint="Ventania Casco Escuro, de Visteterna, Hibérnia, quer que você mate Úrsius.", tag="Elite, Grupo recomendado, Opcional", desc="Elite de nível 56; só enfrente em grupo."}, [31]={npc="Ventania Casco Escuro", tgt="Ventania Casco Escuro", tag="Elite, Grupo recomendado, Opcional"}, [32]={hint="Salfa quer que você mate 8 Xamãs Invernosos, 8 Vigias do Covil dos Invernosos e 8 Ursinos Invernosos. Salfa está perto da entrada do Domínio dos Presamatos, em Hibérnia.", tag="Exige voltar à entrada da caverna, Opcional"}, [33]={npc="Salfa", tgt="Salfa", tag="Exige voltar à entrada da caverna, Opcional"}}},
    ["05-d25"] = {name="Pico da Rocha Negra Inferior", entrance="Garganta Abrasadora (1427), 34.80, 85.30. Marca o acesso externo a Montanha Rocha Negra.", pickup="Desbloqueie primeiro o ponto de voo de Monte Candente, nas Estepes Ardentes; depois do nível 55, volte a Monte Candente e aceite as duas missões com Kibler. Vá a Visteterna, em Hibérnia, falar com Kilram, voe direto de Visteterna para Orgrimmar, pegue o zepelim das Clareiras de Tirisfal na torre fora da cidade, entre na Cidade Baixa, voe para Karrath e aceite as missões com o Senhor da Guerra Trincador, com Galamav, o Atirador Perito, e com Lexlort. Vá pela Garganta Abrasadora ou por Monte Candente até a varanda superior do lado leste da Montanha Rocha Negra e entre pelo portal comum; volte a Karrath para entregar O comando do Senhor da Guerra, aceite A sabedoria de Eitrigg e guarde-a.", pickupS={{"Desbloqueie primeiro o ponto de voo de Monte Candente, nas Estepes Ardentes; depois do nível 55, volte a Monte Candente e aceite as duas missões com Kibler"}, {"Vá a Visteterna, em Hibérnia, falar com Kilram, voe direto de Visteterna para Orgrimmar, pegue o zepelim das Clareiras de Tirisfal na torre fora da cidade, entre na Cidade Baixa, voe para Karrath e aceite as missões com o Senhor da Guerra Trincador, com Galamav, o Atirador Perito, e com Lexlort"}, {"Vá pela Garganta Abrasadora ou por Monte Candente até a varanda superior do lado leste da Montanha Rocha Negra e entre pelo portal comum; volte a Karrath para entregar O comando do Senhor da Guerra, aceite A sabedoria de Eitrigg e guarde-a"}}, tips={{k="動線", text="Entrada inferior → Omokk → Vosh'gajin → Biju e seus pertences descendo a rampa → Voone → ovos e Mãe Queimateia → Halycon e Gizrul → Wyrmthalak. Saqueie as joias de Omokk, Voone e Wyrmthalak."}, {k="取捨", text="Priorize os documentos dos três chefes, os worgs, os ovos e Biju. Se alguém do grupo já puder abrir a parte superior, pode pular a cadeia do selo."}, {k="說明", text="O Pico da Rocha Negra inferior está disponível no lançamento. Para a entrada de superfície, utilize Estepes Ardentes (29.40, 38.30). Siga a rota ascendente para dentro da borda leste. Depois de entrar, desça à direita.", s={{"O Pico da Rocha Negra inferior está disponível no lançamento"}, {"Para a entrada de superfície, utilize Estepes Ardentes (29.40, 38.30)"}, {"Siga a rota ascendente para dentro da borda leste"}, {"Depois de entrar, desça à direita"}}}}, steps={[1]={npc="Kilram", tgt="Kilram"}, [2]={npc="Kibler", tgt="Kibler"}, [3]={npc="Kibler", tgt="Kibler"}, [4]={npc="Senhor da Guerra Trincador", tgt="Senhor da Guerra Trincador", desc="Se o NPC não abrir a janela de missão direto, fale com ele para receber O comando do Senhor da Guerra e depois clique com o botão direito no item."}, [5]={npc="Galamav, o Atirador Perito", tgt="Galamav, o Atirador Perito"}, [6]={npc="Lexlort", tgt="Lexlort"}, [7]={text="Entrada: Pico da Rocha Negra Inferior"}, [8]={npc="Infiltrador Escudo Marcado", tgt="Infiltrador Escudo Marcado", tag="Opcional", desc="Nível 57+. Fale com o Infiltrador Escudo Marcado na varanda superior: é Vaelan."}, [9]={hint="Vá ao Pico da Rocha Negra e descubra o que aconteceu com Biju.", desc="Local: Desça a rampa do quarto de Vosh'gajin. Procure Biju na plataforma lateral.", spot="Desça a rampa do quarto de Vosh'gajin. Procure Biju na plataforma lateral."}, [10]={npc="Biju", tgt="Biju", spot="Pela rampa grande fora da sala de Vosh'gajin: Biju na plataforma lateral"}, [11]={npc="Biju", tgt="Biju", preText="Agente Biju"}, [12]={hint="Encontre os Pertences de Biju e devolva-os a ela. Ela mencionou tê-los guardado no nível mais profundo da cidade.", desc="Local: Da plataforma do Biju, retorne ao centro e procure o nível inferior.", spot="Da plataforma do Biju, retorne ao centro e procure o nível inferior."}, [13]={npc="Biju", tgt="Biju", spot="A plataforma lateral de Biju"}, [14]={npc="Biju", tgt="Biju", preText="Pertences da Biju"}, [15]={hint="Vá para o Pico da Rocha Negra e colete 15 Ovos de Aranha do Pináculo para Kibler.", desc="Local: Pegue os ovos ao longo dos túneis de teia. Limpe primeiro as aranhas ao redor de cada ninho de ovos.", spot="Pegue os ovos ao longo dos túneis de teia. Limpe primeiro as aranhas ao redor de cada ninho de ovos."}, [16]={hint="Vá para o Pico da Rocha Negra e mate a Caçadora Sombria Vosh'gajin. Recolha a Litofídia de Vosh'gajin e fale novamente com Kilram.", desc="Local: Passe por Omokk, siga pela passagem e procure a Caçadora Sombria Vosh'gajin. Ordem: Mate primeiro Vosh'gajin e depois siga a rampa da sala dela para encontrar Biju.", spot="Passe Omokk e siga o túnel até Caçadora Sombria Vosh'gajin."}, [17]={hint="Vá para o Pico da Rocha Negra e encontre Filhotes de Worg Machado Sangrento. Use a jaula para carregar essas pequenas feras. Leve um Filhote de Worg Enjaulado para Kibler.", desc="Avise primeiro o grupo para deixar um filhote vivo, para que não seja morto por ataques em área. Local: Passe pela área das aranhas e pela bifurcação dos trolls, entre na sala dos lobos e capture um filhote.", spot="Passe pelas aranhas e pelo desvio dos trolls. Capture um lobo jovem na sala dos lobos."}, [18]={hint="Mate Halycon, senhora da matilha dos Worgs Machado Sangrento.", desc="Local: Na bifurcação depois da área das aranhas, vá para a direita e siga até a toca de worgs à esquerda.", spot="Na bifurcação depois da área das aranhas, vá para a direita e siga até a toca de worgs à esquerda."}, [19]={hint="Mate o Grão-lorde Omokk, o Senhor da Guerra Voone e o Lorde Supremo Wyrmthalak. Recupere Documentos Importantes dos Rocha Negra. Fale novamente com o Senhor da Guerra Trincador, em Karrath, quanto a missão tiver sido cumprida.", desc="O local do documento muda; procure primeiro nas três primeiras salas. O documento pode aparecer em qualquer sala de chefe; confira uma por uma. Local: Procure o documento sala por sala ao longo da linha dos três chefes e confira também a pilha de tributo de Ulokgan. Ordem: Omokk → Voone → Wyrmthalak.", spot="Verifique cada uma das salas dos três chefes e a pilha de tributos de Urok em busca dos documentos."}, [20]={hint="Encontre as três gemas da autoridade: a Gema de Espinho Fúmeo, a Gema de Agulhapétrea e a Gema de Machado Sangrento. Entregue-as, junto com o Selo da Ascensão sem Adorno, a Vaelan.", tag="Opcional", desc="A chance de drop de gemas e selos é limitada; combine antes com o grupo a divisão. Se só for fazer a parte superior, basta uma pessoa do grupo ter o item finalizado. Local: pegue uma gema de cada um dos três reis e procure o Selo Primordial nos lacaios pelo caminho. Ordem: Omokk → Voone → Wyrmthalak.", spot="Pegue uma gema de cada um dos três chefes e procure o Selo Sem Adorno nos monstros comuns do caminho."}, [21]={npc="Infiltrador Escudo Marcado", tgt="Infiltrador Escudo Marcado", tag="Opcional"}, [22]={npc="Infiltrador Escudo Marcado", tgt="Infiltrador Escudo Marcado", tag="Opcional", preText="Selo da Ascensão"}, [23]={hint="Leve o Relatório de Reconhecimento de Biju para o Grão-mestre Lexlort em Karrath."}, [24]={npc="Senhor da Guerra Trincador", tgt="Senhor da Guerra Trincador"}, [25]={npc="Galamav, o Atirador Perito", tgt="Galamav, o Atirador Perito"}, [26]={npc="Lexlort", tgt="Lexlort"}, [27]={npc="Kibler", tgt="Kibler"}, [28]={npc="Kibler", tgt="Kibler"}, [29]={npc="Kilram", tgt="Kilram"}, [30]={npc="Senhor da Guerra Trincador", tgt="Senhor da Guerra Trincador", desc="Guarde por enquanto; quando voltar a Orgrimmar de barco ou de zepelim, entre no Vale da Sabedoria e procure Eitrigg.", preText="O comando do Senhor da Guerra"}, [31]={hint="Vá para o Pântano da Serpe, que fica no Pântano Vadeoso. Encontre o draco ancião Ardeluta e ataque-o sem misericórdia até que sua vontade seja quebrada.", tag="Opcional", desc="Elites: melhor ir em grupo. Pare de atacar antes do controle do dragão e mantenha a vida alta."}, [32]={npc="Infiltrador Escudo Marcado", tgt="Infiltrador Escudo Marcado", tag="Opcional", desc="Encontre Vaelan dentro da entrada inferior Pico da Rocha Negra."}, [33]={text="De volta a Aldeia Mojache na próxima parada: se a Pedra de Regresso estiver vinculada em Visteterna e fora do tempo de recarga, volte com ela, voe para Posto Peçonha e a Encruzilhada e faça escala para Mojache. Se estiver em recarga, voe de Karrath para Cidade Baixa, pegue o zepelim ao sul de Montalvo para Orgrimmar, depois voe para a Encruzilhada e faça escala para Mojache."}}},
    ["04-48"] = {name="Feralas (visita curta)", nameA="Feralas: {a:1099} (visita curta)", tips={{k="交通", text="A rota de voo principal é de Visteterna para a Aldeia Mojache e da Aldeia Mojache para Vila Catraca."}, {k="取捨", text="A força da corrupção, aceita na nova visita à Aldeia Mojache, em Feralas, e feita em Selva Maleva, pode ser entregue assim que você voltar à aldeia."}, {k="提醒", text="Esta parada não exige um nível mínimo próprio. Se estiver abaixo do 56, entregue primeiro na parada seguinte e deixe a diferença de EXP para os mobs do seu nível mais adiante.", s={{"Esta parada não exige um nível mínimo próprio"}, {"Se estiver abaixo do 56, entregue primeiro na parada seguinte e deixe a diferença de EXP para os mobs do seu nível mais adiante"}}}}, grind={[1]={mob="Arauto do Vento da Nascente Norte", note="Se já entregou em Northspring, mate as harpias comuns na borda do acampamento e pegue de passagem os itens das missões de Northspring. Os mobs são de nível baixo; se faltar muito para o próximo nível, vá para Hibérnia."}, [2]={mob="Yeti Cardo de Gelo", note="Se estiver abaixo do 56, ganhe EXP aqui antes de sair de Visteterna, na parada anterior. Os yetis comuns ficam concentrados, e as encostas externas são mais fáceis de puxar que a entrada da caverna."}}, supply={[1]={npc="Shyn"}, [2]={npc="Estalajadeiro Greul"}, [3]={npc="Cavento Mira Certa"}, [4]={npc="Estalajadeiro Greul"}, [5]={npc="Cavento Mira Certa"}, [6]={npc="Tarhus"}}, steps={[1]={text="Voe de Visteterna para a Aldeia Mojache. Nesta ida, volte primeiro ao acampamento para entregar as missões paralelas de Selva Maleva aceitas antes; vá ao norte depois de aceitar o Elixir Videre."}, [2]={npc="Talo Casco de Espinhos", tgt="Talo Casco de Espinhos", tag="Entregue depois de concluir A força da corrupção."}, [3]={text="Se tiver O elixir Videre, siga a estrada de Feralas para oeste até a bifurcação e depois em direção a Colossos Gêmeos e às ruínas de Ravenwind, ao norte."}, [4]={text="Isca", npc="Gregan Cospechope", tag="Compre só depois de aceitar o Elixir Videre."}, [5]={hint="Procure Gregan Cospechope ao norte de Feralas. Descubra com ele como obter o elixir Videre, depois fale novamente com Bruna Covaneve em Hibérnia.", tag="Faça só depois de aceitar o Elixir Videre.", desc="A troca da poção de Gregan faz parte do diálogo de O elixir Videre. Desta vez, só pegue a poção e não beba; guarde para entregar a Donova em Hibérnia."}, [6]={text="Volte à Aldeia Mojache e voe para Vila Catraca."}}},
    ["04-49"] = {name="Sertões (visita curta)", nameA="Sertões: {a:392} (visita curta)", tips={{k="交通", text="Depois de voar de Vila Catraca a Orgrimmar, pegue o zepelim para a Cidade Baixa fora da cidade. Ao chegar às Clareiras de Tirisfal, siga pela estrada leste até o Baluarte."}, {k="取捨", text="Vá à costa e aceite a carta de Islen para Selva Maleva."}, {k="取捨", text="Se não tiver nada para entregar em Vila Catraca, você pode voar direto de Feralas para Orgrimmar e pegar o zepelim lá."}, {k="提醒", text="Os monstros de Vila Catraca têm nível baixo. Se estiver abaixo do nível 56, antes de pegar o zepelim, volte de voo a Visteterna e mate yetis normais ao leste (cerca de 64, 40), ou vá à Fazenda Felstone, nas Terras Pestilentas Ocidentais (cerca de 38, 56), matar mortos-vivos normais.", s={{"Os monstros de Vila Catraca têm nível baixo"}, {"Se estiver abaixo do nível 56, antes de pegar o zepelim, volte de voo a Visteterna e mate yetis normais ao leste (cerca de 64, 40), ou vá à Fazenda Felstone, nas Terras Pestilentas Ocidentais (cerca de 38, 56), matar mortos-vivos normais"}}}}, grind={[1]={mob="Feiticeiro Descarnado", note="Em Vila Catraca só se fazem entregas e trânsito. Se faltar EXP para o nível 56, pegue o zepelim como de costume e mate esqueletos comuns em Campo Pedravil, na próxima parada. Puxe da borda do campo e evite as patrulhas Escarlates."}}, supply={[1]={npc="Bragok"}, [2]={npc="Estalajadeiro Wiley"}, [3]={npc="Xaveco"}, [4]={npc="Estalajadeiro Wiley"}, [5]={npc="Bossanovik"}, [6]={npc="Horthus"}}, steps={[1]={text="Em Vila Catraca, siga a costa para o sul até Islen Vidente da Água."}, [2]={npc="Islen Vidente da Água", tgt="Islen Vidente da Água", tag="Se já aceita em Posto Peçonha / Domínio dos Presamatos"}, [3]={npc="Islen Vidente da Água", tgt="Islen Vidente da Água", tag="Conclua antes a missão À procura de auxílio espiritual", desc="Mantenha a água purificada para Greta em Santuário Esmeralda mais tarde."}, [4]={text="Volte a Vila Catraca."}}},
    ["04-50"] = {name="Terras Pestilentas Ocidentais", tips={{k="交通", text="Vá a pé da torre de zepelins até o Baluarte. Depois de Aridez de Garrão, siga pela estrada principal para o leste até as Terras Pestilentas Orientais."}, {k="取捨", text="Faça os caldeirões da praga na ordem de continuação; no Antro Repelente, faça de passagem as duas missões de feras selvagens."}, {k="取捨", text="Guarde Retorno a Baluarte para o Baluarte, nas Terras Pestilentas Ocidentais; Praga de cupins! é concluída na parada da Capela Esperança da Luz, nas Terras Pestilentas Orientais, e entregue de volta no Baluarte, nas Terras Pestilentas Ocidentais."}, {k="提醒", text="Mesma faixa de nível 56-57; em seguida, vá para a parada da Capela Esperança da Luz, nas Terras Pestilentas Orientais. Scolomântia, Fragmentos de Ossos e A Cousin Abroad exigem nível 55; aceite-as na terceira volta ao Baluarte, nas Terras Pestilentas Ocidentais. Se pretende fazer a sua própria chave de Scolomântia, aceite Um molde que vale ouro logo depois de entregar.", s={{"Mesma faixa de nível 56-57; em seguida, vá para a parada da Capela Esperança da Luz, nas Terras Pestilentas Orientais"}, {"Scolomântia, Fragmentos de Ossos e A Cousin Abroad exigem nível 55; aceite-as na terceira volta ao Baluarte, nas Terras Pestilentas Ocidentais"}, {"Se pretende fazer a sua própria chave de Scolomântia, aceite Um molde que vale ouro logo depois de entregar"}}}}, danger={[1]="Patrulhas Escarlates vagam ao norte de Lágrimas de Dalson. Puxe esqueletos da borda do campo enquanto coleta materiais para caldeirões. Não siga para o norte através do acampamento."}, grind={[1]={mob="Terror Descarnado", note="Mate esqueletos normais em Lágrimas de Dalson para Fragmentos de Ossos no caldeirão. Fique do lado de fora e observe as patrulhas Scarlet ao norte."}, [2]={mob="Carniçal Friento", note="Carniçais comuns perto do Antro Repelente, de nível adequado e no caminho do próximo caldeirão. Há muitos na porta da casa; comece pela borda do campo."}}, supply={[1]={npc="Intendente Argêntea Hasana"}}, steps={[1]={text="Se ainda estiver em Vila Catraca, voe para Orgrimmar e procure Frezza na torre de zepelins fora da cidade (50.82, 13.54) para pegar a linha das Clareiras de Tirisfal; se já estiver na torre, embarque direto. Depois de descer em Montalvo, siga a estrada fora da Cidade Baixa a leste até o Baluarte."}, [2]={npc="Oficial Argênteo Garush", tgt="Oficial Argênteo Garush"}, [3]={npc="Guel Levine", tgt="Guel Levine"}, [4]={npc="Sacerdotisa Sombria Vandis", tgt="Sacerdotisa Sombria Vandis"}, [5]={hint="Vá a Lágrimas de Dalson nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa das Lágrimas de Dalson Vazia para guardar uma amostra dos venenos usados no caldeirão.", desc="Limpe os mortos-vivos normais ao redor do caldeirão. Aproxime-se para gerar o guardião."}, [6]={npc="Caldeirão do Flagelo", npcObj=true}, [7]={npc="Caldeirão do Flagelo", npcObj=true}, [8]={hint="Leve a Garrafa das Lágrimas de Dalson Cheia à Sacerdotisa Sombria Vandis em Baluarte, que fica nas Terras Pestilentas Ocidentais."}, [9]={npc="Sacerdotisa Sombria Vandis", tgt="Sacerdotisa Sombria Vandis"}, [10]={npc="Sacerdotisa Sombria Vandis", tgt="Sacerdotisa Sombria Vandis"}, [11]={hint="Vá ao Antro Repelente nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa do Antro Repelente Vazia para guardar uma amostra dos venenos usados no caldeirão.", desc="Limpe os mortos-vivos normais ao redor do caldeirão. Aproxime-se para gerar o guardião."}, [12]={npc="Caldeirão do Flagelo", npcObj=true}, [13]={npc="Caldeirão do Flagelo", npcObj=true}, [14]={npc="Mulgris Riofundo", tgt="Mulgris Riofundo"}, [15]={hint="Destrua 8 Lobos Doentes e fale novamente com Mulgris Riofundo no Antro Repelente, que fica nas Terras Pestilentas Ocidentais."}, [16]={npc="Mulgris Riofundo", tgt="Mulgris Riofundo"}, [17]={npc="Mulgris Riofundo", tgt="Mulgris Riofundo"}, [18]={hint="Destrua 8 Ursos-cinzentos Doentes e fale novamente com Mulgris Riofundo no Antro Repelente, que fica nas Terras Pestilentas Ocidentais."}, [19]={npc="Mulgris Riofundo", tgt="Mulgris Riofundo"}, [20]={hint="Leve a Garrafa do Antro Repelente Cheia à Sacerdotisa Sombria Vandis em Baluarte, que fica nas Terras Pestilentas Ocidentais."}, [21]={npc="Sacerdotisa Sombria Vandis", tgt="Sacerdotisa Sombria Vandis"}, [22]={npc="Sacerdotisa Sombria Vandis", tgt="Sacerdotisa Sombria Vandis"}, [23]={hint="Vá a Aridez de Garrão nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa da Aridez de Garrão Vazia para guardar uma amostra dos venenos usados no caldeirão.", desc="Limpe os mortos-vivos normais ao redor do caldeirão. Aproxime-se para gerar o guardião."}, [24]={npc="Caldeirão do Flagelo", npcObj=true}, [25]={npc="Caldeirão do Flagelo", npcObj=true}, [26]={hint="Leve as Penas Vodu para Bath'rah, o Vigia dos Ventos.", tag="Opcional, Alvo: Gashar / Zul'rol / Hooku / Mishan / Zul'ro / Lo'rol", desc="Voe da Cidade Baixa a Pedregal para formar seu grupo."}, [27]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional", desc="Entregue a Bath'rah, em Alterac. Dá para escolher o Espírito de Água Enamorado, entre outras recompensas.", star={"Espírito de Água Enamorado", {"SHAMAN"}}}, [28]={hint="Leve um total de 6 Penas Vodu dos trolls do templo submerso.", tag="Opcional, Alvo: Gashar / Zul'rol / Hooku / Mishan / Zul'ro / Lo'rol", desc="Dá para voar da Cidade Baixa a Pedregal. Guarde a entrega ao Diabretim para a Floresta Ferrárbol."}}},
    ["04-51"] = {name="Terras Pestilentas Orientais", tips={{k="交通", text="Depois de entregar as missões na Capela, desbloqueie o ponto de voo; por fim, voe para a Cidade Baixa, entregue o livro e vá a pé até o Baluarte."}, {k="取捨", text="Entregue Praga de cupins! e Tia Marlene de volta no Baluarte, nas Terras Pestilentas Ocidentais."}, {k="取捨", text="Quiroscuro (Ah, Quiroscuro, como vos odeio...) fica nas Terras Pestilentas Orientais e é um alvo elite que patrulha; sem grupo, pode pular."}, {k="取捨", text="A súplica de Hameya exige ir e voltar entre a cripta e Zul'Mashar, e em Elixir de memórias esquecidas clicar na terra da sepultura atrai um grupo de mercenários; com pressa, pode pular as duas."}, {k="提醒", text="Atrasado em EXP? Mate morcegos, cães e carniçais comuns ao redor do Bosque Pestilento (cerca de 29, 28). Para chegar ao 57, dá para esperar até antes da etapa de Planalto Esfiapluma, em Feralas.", s={{"Atrasado em EXP?"}, {"Mate morcegos, cães e carniçais comuns ao redor do Bosque Pestilento (cerca de 29, 28)"}, {"Para chegar ao 57, dá para esperar até antes da etapa de Planalto Esfiapluma, em Feralas"}}}}, danger={[1]="Abominações Costuradas e patrulhas de nível mais alto vagam pelo lado do Bosque Pestilento perto de Stratholme. Fique pela borda ao coletar cupins ou matar carniçais.", [2]="Os mortos-vivos dentro da casa e nas escadas podem se unir enquanto você procura o livro-razão. Limpe o andar de baixo primeiro."}, grind={[1]={mob="Carniçal Canibal", note="Mortos-vivos comuns na borda do Bosque Pestilento. Dá para fazer junto as missões das almas dos moradores; evite as Abominações Costuradas de nível mais alto e as patrulhas."}, [2]={mob="Cão Pestilento Frenético", note="Cães da peste comuns fora da estrada na mesma área, de nível próximo ao desta etapa e fáceis de puxar em espaço aberto. Se houver gente matando mortos-vivos, procure os cães pela borda externa."}}, supply={[1]={npc="Georgia"}, [2]={npc="Jessica Dávila"}, [3]={npc="Artesão Wilhelm"}, [4]={npc="Jessica Dávila"}, [5]={npc="Zelador Alen"}}, steps={[1]={text="Depois de cruzar a fronteira oeste, procure Tirion ao longo da margem do Rio Thondroril. Pegue todas as missões e siga para o sul até a estrada principal."}, [2]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [3]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [4]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [5]={npc="Augustus, o Pirado", tgt="Augustus, o Pirado", tag="Opcional", desc="Longe da rota principal. Pule se estiver com pressa."}, [6]={hint="Leve o Livro-caixa do Augustus para Augustus, o Pirado, na Várzea do Medo.", tag="Opcional", desc="Longe da rota principal. Pule se estiver com pressa."}, [7]={npc="Augustus, o Pirado", tgt="Augustus, o Pirado", tag="Opcional", desc="Longe da rota principal. Pule se estiver com pressa."}, [8]={npc="Nathanos Arauto da Praga", tgt="Nathanos Arauto da Praga"}, [9]={npc="Nathanos Arauto da Praga", tgt="Nathanos Arauto da Praga"}, [10]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [11]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [12]={hint="Encontre a boneca de Pâmela.", desc="Limpe a entrada primeiro. Fantasmas podem aparecer quando você saqueia as peças."}, [13]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [14]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [15]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [16]={hint="Vá ao Cruzamento de Corin, a leste, e mate membros do Flagelo que habitam a cidade. Colete 7 pedaços de Putrefação Viva em menos de 10 minutos. Use o Almofariz e Pilão para moer a Putrefação Viva, de maneira a transformá-la em Putrefação Coagulada.", desc="A podridão dura cerca de 10 minutos. Moa no local quando tiver o suficiente."}, [17]={hint="Encontre Carlin Trilharrubra."}, [18]={npc="Carlin Trilharrubra", tgt="Carlin Trilharrubra"}, [19]={hint="Entregue o livro \"Estudos sobre Comunicação com Espíritos\" ao Duque Nicolau Zverenhoff na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais."}, [20]={npc="Duque Nicolau Zverenhoff", tgt="Duque Nicolau Zverenhoff"}, [21]={npc="Duque Nicolau Zverenhoff", tgt="Duque Nicolau Zverenhoff", desc="Uma entre três missões de mesmo nome (as outras ficam no Baluarte e no Acampamento Ventogelante): depois de aceitar uma, as outras deixam de estar disponíveis; só com a Ordem da Aurora Argêntea em mãos você consegue saquear Pedras do Flagelo."}, [22]={npc="Duque Nicolau Zverenhoff", tgt="Duque Nicolau Zverenhoff"}, [23]={npc="Carlin Trilharrubra", tgt="Carlin Trilharrubra"}, [24]={npc="Zelador Alen", tgt="Zelador Alen"}, [25]={npc="Livro", tgt="Jana Catão", npcObj=true, desc="Livro da versão Forever. Fica nos fundos, no lado esquerdo da capela; depois de pegar, entregue na Cidade Baixa."}, [26]={hint="Usar/coletar: Livro"}, [27]={node="Capela Esperança da Luz", desc="Na primeira visita, desbloqueie o ponto de voo da Horda com Georgia."}, [28]={text="Em seguida, suba pela estrada para o norte e dê uma volta pelo Bosque Pestilento."}, [29]={hint="Use a Jarra de Cupins Vazia nos Cupinzeiros que há nas Terras Pestilentas Orientais. Após conseguir 100 Cupins das Terras Pestilentas, fale novamente com Guel Levine no Baluarte, nas Clareiras de Tirisfal.", desc="Verifique os cupinzeiros ao longo da borda do Bosque Pestilento. Evite elites por Stratholme."}, [30]={hint="Mate 20 Cães Pestilentos Miúdos, 5 Cães Pestilentos e 5 Cães Pestilentos Frenéticos. Fale novamente com Tirion Fordring quando a tarefa estiver concluída."}, [31]={hint="Mate 30 Quirópragos e fale novamente com Tirion Fordring."}, [32]={hint="Procure os Vermes Carniceiros e os Devoradores de Carniça da região. Mate-os e tire a carne. Fale novamente com Tirion Fordring depois que tiver juntado 15 Nacos de Carne de Verme Carniceiro."}, [33]={hint="Mate 20 Quirópragos Nóxios e 10 Quirópragos Monstruosos. Fale novamente com Nathanos Arauto da Praga quando você tiver terminado."}, [34]={hint="Liberte 15 Espíritos da Vila das Flechas e fale novamente com Carlin Trilharrubra.", desc="Clique em cada alma gerada após matar. As mortes por si só não contam."}, [35]={npc="Nathanos Arauto da Praga", tgt="Nathanos Arauto da Praga"}, [36]={npc="Nathanos Arauto da Praga", tgt="Nathanos Arauto da Praga"}, [37]={hint="Leve a Cabeça de Zaeldarr ao Zelador Alen na Capela Esperança da Luz.", desc="A cripta fica ao sul do Sítio dos Marris; lá dentro há mais alguns guardas."}, [38]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [39]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [40]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [41]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Complete as três missões de caça de Tirion para desbloquear esta."}, [42]={hint="Escute o que Tirion Fordring tem a dizer.", desc="Complete as três missões de caça de Tirion para desbloquear esta."}, [43]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Complete as três missões de caça de Tirion para desbloquear esta."}, [44]={npc="Carlin Trilharrubra", tgt="Carlin Trilharrubra"}, [45]={npc="Zelador Alen", tgt="Zelador Alen"}, [46]={text="Ao terminar, voe da Capela para a Cidade Baixa."}, [47]={npc="Urraca Convulserpe", tgt="Urraca Convulserpe", desc="Oran e Adélio Tadeu (73.40, 33.00) estão no Distrito da Magia de Cidade Baixa; siga primeiro o aviso de entrega do jogo."}}},
    ["05-d27"] = {name="Stratholme: Mortos-vivos", entrance="Terras Pestilentas Orientais (Os suprimentos perdidos), entrada lateral Morto-vivo, cerca de 43.50, 19.40.", pickup="Visite Betina, Leonid e Zelador Alen em Capela Esperança da Luz. Vá para oeste para ver Egan em Várzea do Medo antes de entrar pelo portão lateral. Se o seu grupo tiver saído do portão frontal, salve o acompanhamento O agente ativo para esta corrida.", pickupS={{"Visite Betina, Leonid e Zelador Alen em Capela Esperança da Luz"}, {"Vá para oeste para ver Egan em Várzea do Medo antes de entrar pelo portão lateral"}, {"Se o seu grupo tiver saído do portão frontal, salve o acompanhamento O agente ativo para esta corrida"}}, tips={{k="動線", text="Entrada lateral e Aurius na capela pequena → derrote a Baronesa Anastari, Nerub'enkan e Maleki nos três zigurates e confira os dados → Ramstein no matadouro → derrote o Barão Rivendare e fale com Aurius. Recolha carne, abra caixas para pegar água benta e liberte os moradores espectrais."}, {k="取捨", text="Colete a carne, a água benta e as almas de Egan na mesma corrida. Se for fazer só uma ala, pode pular a cadeia de Aurius, que exige antes o Medalhão da Fé."}, {k="說明", text="Masmorra para cinco jogadores. Use a Chave da cidade para a Entrada de Serviço. Na primeira corrida, passe pela rota interna da cidade a partir do portão da frente e pegue a chave da Entrada de Serviço com Barthilas.", s={{"Masmorra para cinco jogadores"}, {"Use a Chave da cidade para a Entrada de Serviço"}, {"Na primeira corrida, passe pela rota interna da cidade a partir do portão da frente e pegue a chave da Entrada de Serviço com Barthilas"}}}, {k="提醒", text="Masmorra para cinco jogadores. Use a Chave da cidade para a Entrada de Serviço. Na primeira corrida, passe pela rota interna da cidade a partir do portão da frente e pegue a chave da Entrada de Serviço com Barthilas.", s={{"Masmorra para cinco jogadores"}, {"Use a Chave da cidade para a Entrada de Serviço"}, {"Na primeira corrida, passe pela rota interna da cidade a partir do portão da frente e pegue a chave da Entrada de Serviço com Barthilas"}}}}, steps={[1]={npc="Betina Bigozinco", tgt="Betina Bigozinco", desc="Se você entregou isso, aceite O agente ativo nesta execução."}, [2]={npc="Betina Bigozinco", tgt="Betina Bigozinco", desc="Entregue A carne não mente primeiro. Salve isto para a próxima execução se ainda não estiver desbloqueado.", preText="A carne não mente"}, [3]={npc="Leonid Bartolomeu, o Venerado", tgt="Leonid Bartolomeu, o Venerado"}, [4]={npc="Zelador Alen", tgt="Zelador Alen"}, [5]={hint="Encontre Egan. Ele foi visto pela última vez nos arredores de Stratholme."}, [6]={npc="Egan", tgt="Egan"}, [7]={npc="Egan", tgt="Egan", desc="Obtenha o Blaster de Egan.", preText="As almas inquietas"}, [8]={text="Entrada: Stratholme: Mortos-vivos"}, [9]={hint="Recupere 20 Amostras de Carne Infectada de Stratholme e leve-as para Betina Bigozinco. Você desconfia que qualquer criatura em Stratholme poderia ter essa amostra de carne.", desc="Local: Entre no portão de serviço e saqueie carne dos mortos-vivos pelas ruas.", spot="Entre no portão de serviço e saqueie carne dos mortos-vivos pelas ruas."}, [10]={hint="Vá para Stratholme e vasculhe os zigurates. Encontre novos Dados do Flagelo e leve-os para Betina Bigozinco.", desc="Local: Vasculhe as três torres necromantes uma a uma; os dados estão em um baú pequeno de uma delas. Ordem: Confira a torre toda vez que derrotar um chefe de portão de torre.", spot="Procure nos três zigurates. Os dados estão em uma pequena caixa em um deles."}, [11]={hint="Viaje para Stratholme, ao norte. Procure os caixotes de suprimentos que cobrem a cidade e recupere 5 Águas Bentas de Stratholme. Fale novamente com Leonid Bartolomeu, o Venerado, quando coletar fluido abençoado suficiente.", desc="Local: Verifique as caixas de madeira ao longo das ruas. Limpe os mobs próximos primeiro.", spot="Verifique as caixas de madeira ao longo das ruas. Limpe os mobs próximos primeiro."}, [12]={hint="Use o Canhão de Ectoplasma do Egan nos moradores fantasmagóricos e espectrais de Stratholme. Depois de livrá-los da forma de fantasma, use o canhão de novo e BLAU: liberdade!", desc="Local: Procure os cidadãos espectrais pelas ruas e use o Blaster duas vezes em cada alvo.", spot="Procure os cidadãos espectrais pelas ruas e use o Blaster duas vezes em cada alvo."}, [13]={npc="Aurius", tgt="Aurius", desc="Pegue o Medalhão da Fé no cofre de Malor, no setor Escarlate, e depois vá à capela ao lado da entrada da ala dos mortos-vivos."}, [14]={hint="Usar/coletar: Cofre de Malor", desc="Local: Entre no portão de serviço. Procure a capela em chamas na entrada.", spot="Entre no portão de serviço. Procure a capela em chamas na entrada."}, [15]={npc="Aurius", tgt="Aurius", spot="Capela em chamas ao lado da entrada dos mortos-vivos"}, [16]={npc="Aurius", tgt="Aurius", desc="Dê a ele o medalhão e aceite a missão antes de lutar contra Barão Rivendare.", preText="O Medalhão da Fé"}, [17]={hint="Complete os objetivos da missão.", desc="Depois de limpar a torre necromântica, passe pelo matadouro, derrote o Barão Rivendare e fale com Aurius na mesma sala."}, [18]={npc="Aurius", tgt="Aurius", desc="Ao concluir, Aurius vai para a sala do chefe final; a missão ainda é aceita na pequena capela ao lado da entrada da área dos mortos-vivos.", spot="Sala do Barão Rivendare: Aurius se muda para lá"}, [19]={npc="Betina Bigozinco", tgt="Betina Bigozinco"}, [20]={npc="Betina Bigozinco", tgt="Betina Bigozinco"}, [21]={npc="Leonid Bartolomeu, o Venerado", tgt="Leonid Bartolomeu, o Venerado"}, [22]={npc="Egan", tgt="Egan"}}},
    ["05-d26"] = {name="Stratholme: Vivos", entrance="Terras Pestilentas Orientais Os suprimentos perdidos por volta de 27.10, 10.70 (portal da entrada principal)", pickup="Visite o Duque e Fumaça na Capela Esperança da Luz e siga a estrada principal para noroeste até o portão da frente. Para a pintura de Tirion, conclua antes as missões de caça na Capela Esperança da Luz, nas Terras Pestilentas Orientais. Continue pelas criptas ao sul e pelo vale ao norte, procure o pintor em Castro das Flechas, nas Terras Pestilentas Ocidentais, e depois volte às Terras Pestilentas Orientais.", pickupS={{"Visite o Duque e Fumaça na Capela Esperança da Luz e siga a estrada principal para noroeste até o portão da frente"}, {"Para a pintura de Tirion, conclua antes as missões de caça na Capela Esperança da Luz, nas Terras Pestilentas Orientais"}, {"Continue pelas criptas ao sul e pelo vale ao norte, procure o pintor em Castro das Flechas, nas Terras Pestilentas Ocidentais, e depois volte às Terras Pestilentas Orientais"}}, tips={{k="動線", text="Portão principal → tabacaria do mercado → Bastião Escarlate (Willey opcional) → recolha os documentos e queime os arquivos na sala do arquivista Galford → mate Balnazzar se for limpar tudo."}, {k="取捨", text="As missões do tabaco e dos arquivos são fáceis de pegar. Some Do amor e da família se já tiver concluído a primeira metade da cadeia de Tirion. Para fazer tudo em uma só corrida, pegue antes todos os pré-requisitos."}, {k="說明", text="Masmorra para cinco jogadores. Leve a Chave Escarlate para o portão da fortaleza Escarlate. Se estiver abaixo do nível 58, pegue as missões agora e forme o grupo depois. Dá para entrar na ala dos mortos-vivos pela Entrada de Serviço subterrânea.", s={{"Masmorra para cinco jogadores"}, {"Leve a Chave Escarlate para o portão da fortaleza Escarlate"}, {"Se estiver abaixo do nível 58, pegue as missões agora e forme o grupo depois"}, {"Dá para entrar na ala dos mortos-vivos pela Entrada de Serviço subterrânea"}}}, {k="提醒", text="Masmorra para cinco jogadores. Leve a Chave Escarlate para o portão da fortaleza Escarlate. Se estiver abaixo do nível 58, pegue as missões agora e forme o grupo depois. Dá para entrar na ala dos mortos-vivos pela Entrada de Serviço subterrânea.", s={{"Masmorra para cinco jogadores"}, {"Leve a Chave Escarlate para o portão da fortaleza Escarlate"}, {"Se estiver abaixo do nível 58, pegue as missões agora e forme o grupo depois"}, {"Dá para entrar na ala dos mortos-vivos pela Entrada de Serviço subterrânea"}}}}, steps={[1]={npc="Leandro Leonardo", tgt="Leandro Leonardo"}, [2]={npc="Duque Nicolau Zverenhoff", tgt="Duque Nicolau Zverenhoff", desc="Mate o Arquivista e queime os registros na mesma corrida."}, [3]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="A sequência longa de Tirion é opcional. Se já terminou na Capela Esperança da Luz, nas Terras Pestilentas Orientais, siga para o próximo passo. Lorde Tirion Fordring (53.95, 24.45) também oferece a missão."}, [4]={hint="Mate 20 Cães Pestilentos Miúdos, 5 Cães Pestilentos e 5 Cães Pestilentos Frenéticos. Fale novamente com Tirion Fordring quando a tarefa estiver concluída."}, [5]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [6]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="A sequência longa de Tirion é opcional. Se já terminou na Capela Esperança da Luz, nas Terras Pestilentas Orientais, siga para o próximo passo. Lorde Tirion Fordring (53.95, 24.45) também oferece a missão."}, [7]={hint="Mate 30 Quirópragos e fale novamente com Tirion Fordring."}, [8]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [9]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="A sequência longa de Tirion é opcional. Se já terminou na Capela Esperança da Luz, nas Terras Pestilentas Orientais, siga para o próximo passo. Lorde Tirion Fordring (53.95, 24.45) também oferece a missão."}, [10]={hint="Procure os Vermes Carniceiros e os Devoradores de Carniça da região. Mate-os e tire a carne. Fale novamente com Tirion Fordring depois que tiver juntado 15 Nacos de Carne de Verme Carniceiro."}, [11]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [12]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Cadeia opcional de Tirion. Pule se já fez no trecho da Capela Esperança da Luz.", preText="Cães demoníacos, Céu tingido de sangue, Carne de verme carniceiro"}, [13]={hint="Escute o que Tirion Fordring tem a dizer."}, [14]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [15]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Cadeia opcional de Tirion. Pule se já fez no trecho da Capela Esperança da Luz.", preText="Redenção"}, [16]={hint="Viaje para a Chácara Secreta, no extremo sul das Terras Pestilentas Orientais, e recupere o Martelo de Taelan. Fale novamente com Tirion Fordring ao completar seu objetivo."}, [17]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [18]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Cadeia opcional de Tirion. Pule se já fez no trecho da Capela Esperança da Luz.", preText="Elixir de memórias esquecidas"}, [19]={hint="Viaje para o Vilarejo do Norte, na região nordeste das Terras Pestilentas Orientais, e recupere o Símbolo da Honra Perdida. Fale novamente com Tirion Fordring ao completar seu objetivo."}, [20]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [21]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Cadeia opcional de Tirion. Pule se já fez no trecho da Capela Esperança da Luz.", preText="Da honra perdida"}, [22]={npc="Artista Renée", tgt="Artista Renée"}, [23]={npc="Artista Renée", tgt="Artista Renée", preText="Do amor e da família"}, [24]={text="Entrada: Stratholme: Vivos"}, [25]={hint="Encontre a tabacaria de Ezra Carranca em Stratholme e recolha uma caixa do Tabaco da Lata do Carranca. Fale novamente com Leandro Leonardo depois que tiver terminado o serviço.", desc="Local: Entre pelo portão principal, vá ao mercado e abra a caixa da tabacaria de Siabi.", spot="Entre pelo portão principal, vá ao mercado e abra a caixa da tabacaria de Siabi."}, [26]={hint="Viaje até Stratholme e encontre o Arquivista Galford da Cruzada Escarlate. Destrua-o e queime o Arquivo Escarlate.", desc="O arquivo escarlate fica na sala de arquivos onde está o arquivista. Local: Entre na sala de arquivos do Bastião Escarlate e queime o arquivo depois de matar Galford.", spot="Mate Galford nos arquivos Bastião Escarlate e depois queime os registros."}, [27]={hint="Viaje para Stratholme, na parte norte das Terras Pestilentas. No Bastião Escarlate, você encontrará a pintura \"Do Amor e da Família\", escondida atrás de outro quadro que retrata as luas gêmeas do nosso mundo.", desc="O quadro das Duas Luas fica na mesma sala do chefe do arquivo. Local: Na mesma sala do arquivo escarlate, examine o quadro das Duas Luas na parede.", spot="Confira a pintura das duas luas na parede da mesma sala de arquivos Escarlate."}, [28]={npc="Leandro Leonardo", tgt="Leandro Leonardo"}, [29]={npc="Duque Nicolau Zverenhoff", tgt="Duque Nicolau Zverenhoff"}, [30]={npc="Tirion Fordring", tgt="Tirion Fordring"}}},
    ["04-57"] = {name="Terras Pestilentas Ocidentais", tips={{k="交通", text="Comece pelo Baluarte e, no fim, pegue o zepelim fora da Cidade Baixa."}, {k="取捨", text="Faça Felstone e Andorhal em sequência; os térmitas da última etapa são entregues juntos na volta."}, {k="取捨", text="O resto da cadeia de Crona exige voltar às Terras Pestilentas Orientais. Aceite se for voltar de propósito."}, {k="提醒", text="Se estiver atrasado no nível, mate mortos-vivos normais na borda leste de Andorhal (cerca de 46, 64) ou nas fazendas pestilentas antes de voltar a Kalimdor.", s={{"Se estiver atrasado no nível, mate mortos-vivos normais na borda leste de Andorhal (cerca de 46, 64) ou nas fazendas pestilentas antes de voltar a Kalimdor"}}}}, danger={[1]="A prefeitura de Andorhal fica perto de Araj, o Evocador, elite de nível 61. Ao procurar Os Anais da Vila das Flechas, entre e saia pelas paredes externas."}, grind={[1]={mob="Carniçal Ardente", note="Mortos-vivos normais na borda leste de Andorhal. Moa aqui antes de retornar para a fazenda. Evite elites e matilhas nos edifícios."}, [2]={mob="Visão Assombrosa", note="Aparições normais de nível superior em Aridez de Garrão. Use este local se você ainda estiver no leste. Faça um loop na borda para evitar puxar vários mobs dentro das casas."}}, supply={[1]={npc="Intendente Argêntea Hasana"}, [2]={npc="Miguel Garreta"}, [3]={npc="Estalajadeiro Ronan"}, [4]={npc="Estalajadeiro Ronan"}, [5]={npc="Eleanor Rusga"}, [6]={npc="Thomas Mordan"}, [7]={npc="Ezequiel Potio"}}, steps={[1]={text="Saia da Cidade Baixa e siga a estrada principal para o leste até o Baluarte; depois passe por Campo Pedravil, Andorhal e Madeireira Beiranorte."}, [2]={npc="Sacerdotisa Sombria Vandis", tgt="Sacerdotisa Sombria Vandis"}, [3]={npc="Guel Levine", tgt="Guel Levine"}, [4]={npc="Oficial Argênteo Garush", tgt="Oficial Argênteo Garush", desc="Leve à entrada do Monte Hyjal e entregue a Thark Gorax."}, [5]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz"}, [6]={hint="Fale com o Boticário Trépido no Baluarte das Terras Pestilentas Ocidentais."}, [7]={npc="Boticário Trépido", tgt="Boticário Trépido"}, [8]={npc="Boticário Trépido", tgt="Boticário Trépido", desc="Os Fragmentos de Ossos só começam a cair depois que você aceita a missão; colete-os de passagem ao matar esqueletos em Andorhal."}, [9]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz", star={"Espada Curta Valente", {"PALADIN", "MAGE", "WARLOCK"}}}, [10]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz", star={"Espada Curta Valente", {"PALADIN", "MAGE", "WARLOCK"}}}, [11]={npc="Guel Levine", tgt="Guel Levine"}, [12]={npc="Janice Pedravil", tgt="Janice Pedravil"}, [13]={npc="Janice Pedravil", tgt="Janice Pedravil"}, [14]={hint="Localize a outra metade do Pingente da Sorte em algum lugar da Fazenda Pedravil, nas Terras Pestilentas Ocidentais, e monte-o novamente.", desc="O carniçal se move pela fazenda; procure primeiro no lado sul."}, [15]={npc="Janice Pedravil", tgt="Janice Pedravil"}, [16]={hint="Fale com Marlene, ao sul das Ruínas de Andorhal."}, [17]={npc="Marlene Trilharrubra", tgt="Marlene Trilharrubra"}, [18]={npc="Marlene Trilharrubra", tgt="Marlene Trilharrubra"}, [19]={hint="Leve o Anel de Casamento do Josefo para Crona.", desc="Há um lich de elite no centro de Andorhal. Vá pela borda até a pousada."}, [20]={npc="Crona", tgt="Crona"}, [21]={npc="Crona", tgt="Crona"}, [22]={npc="Crona", tgt="Crona"}, [23]={hint="Leve os Anais da Vila das Flechas para Crona em Andorhal.", desc="Verifique a capa. Livros falsos podem gerar inimigos. Evite as elites no centro."}, [24]={hint="Use o Deslocador Temporal perto de um dos silos de Andorhal e desencave Parasitas Temporais."}, [25]={npc="Crona", tgt="Crona"}, [26]={npc="Crona", tgt="Crona"}, [27]={npc="Crona", tgt="Crona"}, [28]={hint="Encontre 5 Relógios de Andorhal, que estão em cofres em meio às ruínas da cidade. Regresse com eles até Crona, que está na Estalagem Andorhal, que fica nas Terras Pestilentas Ocidentais."}, [29]={hint="Leve 15 Fragmentos de Ossos para o Boticário Trépido no Baluarte, que fica nas Terras Pestilentas Ocidentais."}, [30]={npc="Crona", tgt="Crona"}, [31]={npc="Kirsta Sombrafunda", tgt="Kirsta Sombrafunda", desc="Ela fica a nordeste da Madeireira Beiranorte; os alvos da continuação ficam mais longe: não aceite."}, [32]={hint="Mate 2 Socorristas Escarlate, 2 Caçadores Escarlate, 2 Magos Escarlate e 2 Cavaleiros Escarlate antes de voltar a Kirsta Sombrafunda, nas Terras Pestilentas Ocidentais.", desc="Os cavaleiros ficam na Madeireira Beiranorte, os magos a leste, e os caçadores e médicos à beira da estrada, ao sul."}, [33]={hint="Encontre um lugar apropriado para pôr o Barril de Cupins das Terras Pestilentas no centro da Serraria de Beiranorte, que fica nas Terras Pestilentas Ocidentais."}, [34]={npc="Barril de Cupins", npcObj=true}, [35]={npc="Barril de Cupins", npcObj=true}, [36]={hint="Solte os Cupins das Terras Pestilentas na Serraria de Beiranorte, depois retorne com o Barril de Cupins das Terras Pestilentas até Guel Levine, no Baluarte, que fica nas Clareiras de Tirisfal.", desc="Abrir o barril atrai inimigos. Saia assim que abri-lo."}, [37]={npc="Kirsta Sombrafunda", tgt="Kirsta Sombrafunda"}, [38]={npc="Guel Levine", tgt="Guel Levine"}, [39]={npc="Boticário Trépido", tgt="Boticário Trépido"}, [40]={text="Volte à torre do zepelim da Cidade Baixa e pegue o zepelim de volta a Orgrimmar."}}},
    ["05-d32"] = {name="Scolomântia", entrance="Terras Pestilentas Ocidentais (Ameaça do mar), por volta de 68.90, 72.80. Entrada subterrânea de Castro das Flechas.", pickup="No Baluarte, pegue A fortuna da família Barov com Alexi e a parte inicial da missão da chave. Pegue Filhotes Pestilentos na Capela Esperança da Luz. Do Baluarte, siga a estrada sul até a ilha de Castro das Flechas e fale com Eva antes de entrar. Para fazer a chave você mesmo, entregue os Fragmentos de Ossos no Baluarte, pegue a missão do molde, vá a Geringontzan e ao Pico Penacho de Fogo e volte ao Baluarte para concluir.", pickupS={{"No Baluarte, pegue A fortuna da família Barov com Alexi e a parte inicial da missão da chave"}, {"Pegue Filhotes Pestilentos na Capela Esperança da Luz"}, {"Do Baluarte, siga a estrada sul até a ilha de Castro das Flechas e fale com Eva antes de entrar"}, {"Para fazer a chave você mesmo, entregue os Fragmentos de Ossos no Baluarte, pegue a missão do molde, vá a Geringontzan e ao Pico Penacho de Fogo e volte ao Baluarte para concluir"}}, tips={{k="動線", text="Ponte da entrada → escritura no primeiro salão → outra após a câmara de invocação → ossuário: Ossorrange e filhotes de praga → escritura no quarto de Ras Friomúrmuro → seis salas no andar de baixo: pegue a última escritura e limpe a sala de Krastinov → Umbromestre Gandling."}, {k="取捨", text="Vale a pena fazer as quatro escrituras, os filhotes de praga e o professor na mesma corrida. Se alguém do grupo puder abrir a porta, os outros podem pular toda a cadeia de materiais da chave."}, {k="說明", text="Masmorra para cinco jogadores. Quem tiver a chave abre a porta externa primeiro. As missões depois do professor, Saco de Horrores de Krastinov e Kirtonos, o Arauto, exigem corridas repetidas; guarde-as para uma viagem com o mesmo grupo.", s={{"Masmorra para cinco jogadores"}, {"Quem tiver a chave abre a porta externa primeiro"}, {"As missões depois do professor, Saco de Horrores de Krastinov e Kirtonos, o Arauto, exigem corridas repetidas; guarde-as para uma viagem com o mesmo grupo"}}}, {k="提醒", text="Masmorra para cinco jogadores. Quem tiver a chave abre a porta externa primeiro. As missões depois do professor, Saco de Horrores de Krastinov e Kirtonos, o Arauto, exigem corridas repetidas; guarde-as para uma viagem com o mesmo grupo.", s={{"Masmorra para cinco jogadores"}, {"Quem tiver a chave abre a porta externa primeiro"}, {"As missões depois do professor, Saco de Horrores de Krastinov e Kirtonos, o Arauto, exigem corridas repetidas; guarde-as para uma viagem com o mesmo grupo"}}}}, steps={[1]={npc="Alexei Barov", tgt="Alexei Barov", desc="Comece cedo no Baluarte quando atingir o nível 52."}, [2]={npc="Betina Bigozinco", tgt="Betina Bigozinco", desc="Encontre Betina na Capela Esperança da Luz."}, [3]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff", desc="Encontre Eva do lado de fora da porta em Castro das Flechas."}, [4]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz", desc="Só faça se precisar fazer a chave de Scolomântia você mesmo. Pule se já fez no Baluarte, nas Terras Pestilentas Ocidentais."}, [5]={hint="Vá até a base de operações da Cruzada Escarlate, que fica entre o Campo Pedravil e as Lágrimas de Dalson, e destrua a Tenda de Comando."}, [6]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz"}, [7]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz", desc="Já na rota principal no Baluarte em Terras Pestilentas Ocidentais.", preText="Distrações escarlate"}, [8]={hint="Usando a Tocha Sinalizadora, marque cada torre em Andorhal. Você tem que ficar na entrada da torre para conseguir marcá-la."}, [9]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz"}, [10]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz", desc="Você pode entregar isso mais cedo no Baluarte.", preText="Você não vê as torres?"}, [11]={hint="Fale com o Boticário Trépido no Baluarte das Terras Pestilentas Ocidentais."}, [12]={npc="Boticário Trépido", tgt="Boticário Trépido"}, [13]={npc="Boticário Trépido", tgt="Boticário Trépido", desc="Pule esses três se terminar no Baluarte. Pegue o molde se estiver fazendo sua própria chave.", preText="Scolomântia"}, [14]={hint="Leve 15 Fragmentos de Ossos para o Boticário Trépido no Baluarte, que fica nas Terras Pestilentas Ocidentais."}, [15]={npc="Boticário Trépido", tgt="Boticário Trépido"}, [16]={npc="Boticário Trépido", tgt="Boticário Trépido", desc="Antes de passar por Geringontzan vindo da Cratera Un'Goro, prepare duas barras de Tório.", preText="Fragmentos de Ossos"}, [17]={hint="Leve os Fragmentos de Ossos Imbuídos e 15 moedas de ouro para Rugov A. Massoaço em Geringontzan."}, [18]={npc="Rugov A. Massoaço", tgt="Rugov A. Massoaço"}, [19]={npc="Rugov A. Massoaço", tgt="Rugov A. Massoaço", desc="Dá para fazer junto com as missões de Pico Penacho de Fogo no trecho do Refúgio do Marshal.", preText="Um molde que vale ouro"}, [20]={hint="Leve o Molde de Chave-mestra e 2 Barras de Tório para o topo do Pico Penacho de Fogo, na Cratera Un'Goro. Use o Molde de Chave-mestra no lago de lava para forjar a Chave-mestra Inacabada."}, [21]={npc="Boticário Trépido", tgt="Boticário Trépido"}, [22]={npc="Boticário Trépido", tgt="Boticário Trépido", desc="Faça-o durante a etapa de Andorhal desde o Baluarte se tiver um grupo.", preText="A forja do Pico Penacho de Fogo"}, [23]={hint="Destrua Araj, o Evocador e leve o Escaravelho de Araj para o Boticário Trépido no Baluarte, que fica nas Terras Pestilentas Ocidentais."}, [24]={npc="Boticário Trépido", tgt="Boticário Trépido"}, [25]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz", preText="O escaravelho de Araj"}, [26]={hint="Complete os objetivos da missão."}, [27]={npc="Alto-executor Arcabuz", tgt="Alto-executor Arcabuz"}, [28]={text="Entrada: Scolomântia"}, [29]={hint="Desbrave Scolomântia e recupere a fortuna da família Barov. A fortuna é composta por quatro escrituras: A Escritura de Castro das Flechas, A Escritura de Montalvo, A Escritura da Serraria Tarren e A Escritura de Costa Sul. Fale novamente com Alexei Barov quando tiver terminado a tarefa.", desc="Costa Sul, Serraria Tarren, Montalvo e Castro das Flechas são nomes de escrituras; não é preciso sair da masmorra. Local: procure as quatro escrituras no salão de entrada, atrás do salão de invocação, na sala de Ras Friomúrmuro e na sala de Barov.", spot="Procure as quatro escrituras no salão de entrada, atrás do salão de invocação, na sala de Ras Friomúrmuro e na sala de Barov."}, [30]={hint="Mate 20 Filhotes Pestilentos, depois fale novamente com Betina Bigozinco, na Capela Esperança da Luz.", desc="Local: Passe pela sala de invocação e mate os filhotes no ossuário de Ossorrange.", spot="Passe pela sala de invocação e mate os filhotes no ossuário de Ossorrange."}, [31]={hint="Encontre o Doutor Theolen Krastinov em Scolomântia. Destrua-o, depois queime os Restos Mortais de Eva Sarkhoff e os Restos Mortais de Lucien Sarkhoff. Fale novamente com Eva Sarkhoff depois que tiver terminado a tarefa.", desc="Os restos de Eva e Lucien estão na sala do professor. Local: Vá às seis salas da seção final para encontrar Krastinov e queime os dois restos na mesma sala. Ordem: Os restos estão na mesma sala.", spot="Entre nas últimas seis salas e encontre Krastinov. Queime os dois conjuntos de restos mortais na mesma sala."}, [32]={npc="Eva Sarkhoff", tgt="Eva Sarkhoff", desc="Eva pode oferecer The Bag of Horrors para a próxima corrida. Na primeira corrida de nivelamento, basta entregar ao professor."}, [33]={npc="Alexei Barov", tgt="Alexei Barov"}, [34]={npc="Betina Bigozinco", tgt="Betina Bigozinco"}}},
    ["04-52"] = {name="Clareira da Lua", tips={{k="交通", text="Voe primeiro para o Penhasco do Trovão e depois para o Posto Peçonha, atravesse o Domínio dos Presamatos até a Clareira da Lua, desbloqueie o ponto de voo e depois siga a pé para Hibérnia."}, {k="取捨", text="Aceite primeiro Terras Devastadas e Relicário da Pureza; na Aldeia Vento Sul, em Silithus, dá para continuar com as missões da mesma zona."}, {k="取捨", text="Entregue Meleca misteriosa em Visteterna, em Hibérnia; Relicário da Pureza é pega no Forte Cenariano, em Silithus, e guardada para entregar em Refúgio Noturno, na Clareira da Lua."}, {k="提醒", text="Se os Presamatos ainda atacarem você, mate primeiro os ursos Madeira Morta fora do domínio ou faça antes as missões de reputação dos Presamatos em Selva Maleva. Depois de passar pelo Domínio dos Presamatos, dá para ir direto a Visteterna, em Hibérnia.", s={{"Se os Presamatos ainda atacarem você, mate primeiro os ursos Madeira Morta fora do domínio ou faça antes as missões de reputação dos Presamatos em Selva Maleva"}, {"Depois de passar pelo Domínio dos Presamatos, dá para ir direto a Visteterna, em Hibérnia"}}}}, danger={[1]="Se for da Clareira da Lua a Hibérnia pelo Domínio dos Presamatos, confirme antes a reputação com os Timbermaw. Se estiver hostil, dê a volta ou volte a Selva Maleva para subir a reputação."}, grind={[1]={mob="Vingador de Lenha Morta", note="Depois de entregar em Refúgio Noturno, dá para voltar pelo Domínio dos Presamatos até a entrada de Selva Maleva e farmar aqui. Fúrbolgs Lenha Morta comuns e densos também sobem a reputação com os Presamatos; evite os guardas Timbermaw e os que puxam junto dentro das tendas."}, [2]={mob="Vigia do Covil dos Invernosos", note="Se já atravessou o Domínio dos Presamatos, mate primeiro os fúrbolgs comuns ao longo da estrada do lado de Hibérnia. Perto de Donova dá para ganhar um pouco de EXP, mas os grupos principais ficam a leste de Visteterna."}}, supply={[1]={npc="Faustron"}, [2]={npc="Meliri"}, [3]={npc="Dargon"}, [4]={npc="Daeolyn Foliéstia"}}, steps={[1]={npc="Emissário Cenariano Casco Negro", tgt="Emissário Cenariano Casco Negro"}, [2]={text="Se o Penhasco do Trovão estiver desbloqueado, voe de Orgrimmar para o Penhasco do Trovão. Se não, voe para o Acampamento Taurajo, vá a oeste pela estrada de Mulgore até o Penhasco do Trovão, suba pelo elevador e desbloqueie com Tal. Siga a orientação do mensageiro abaixo da cidade e depois vá ao Platô dos Anciãos para encontrar o arquidruida."}, [3]={npc="Mensageiro do Penhasco Andaventos", tgt="Mensageiro do Penhasco Andaventos", desc="Este é o guia da Horda para Refúgio Noturno. Personagens que já fizeram Novas Fronteiras em outras versões podem falar direto com Hamuul."}, [4]={hint="Fale com o Arquidruida Hamuul Runa Totem no Platô dos Anciãos, no Penhasco do Trovão, sobre o chamado do Círculo Cenariano para explorar as fronteiras de Kalimdor.", desc="Este é o guia da Horda para Refúgio Noturno. Personagens que já fizeram Novas Fronteiras em outras versões podem falar direto com Hamuul."}, [5]={npc="Arquidruida Hamuul Runa Totem", tgt="Arquidruida Hamuul Runa Totem", desc="Este é o guia da Horda para Refúgio Noturno. Personagens que já fizeram Novas Fronteiras em outras versões podem falar direto com Hamuul."}, [6]={npc="Arquidruida Hamuul Runa Totem", tgt="Arquidruida Hamuul Runa Totem"}, [7]={text="Voe a Posto Peçonha. Siga ao norte pela Vila da Lenha Morta até o caldeirão (60.20, 5.84) e depois pegue o desvio do Domínio dos Presamatos rumo à Clareira da Lua."}, [8]={hint="Investigue o acampamento dos pelursos Lenha Morta na parte norte de Selva Maleva para encontrar alguma pista."}, [9]={npc="Caldeirão de Lenha Morta", npcObj=true}, [10]={npc="Caldeirão de Lenha Morta", npcObj=true}, [11]={npc="Ravine Saturna", tgt="Ravine Saturna"}, [12]={npc="Ravine Saturna", tgt="Ravine Saturna"}, [13]={npc="Ravine Saturna", tgt="Ravine Saturna", desc="Se estiver abaixo do nível 56 e não conseguir aceitar, pule por enquanto; pule também o passo de pegar o relicário em Silithus."}, [14]={node="Clareira da Lua", desc="Desbloqueie o ponto de voo da Horda com Faustron, no sudoeste da Clareira da Lua."}, [15]={text="Atravesse Domínio dos Presamatos novamente para chegar a Hibérnia."}}},
    ["04-53"] = {name="Hibérnia", tips={{k="交通", text="Ao sair do Domínio dos Presamatos, pare primeiro nas fontes termais; no fim, siga para o sul pela Garganta do Sussurro Sombrio até entrar no Monte Hyjal."}, {k="取捨", text="Encontro na sepultura se resolve em Geringontzan, em Tanaris. Para Horrores tóxicos, farme os itens na Floresta Ferrárbol, em Selva Maleva, e volte às Fontes Termais de Fogofrio, em Hibérnia, para entregar."}, {k="取捨", text="Eu yeti falar uma coisa... percorre três mapas pela mesma rota; ao aceitar, use uma vez em Visteterna."}, {k="提醒", text="Abaixo do nível 57? Mate Yetis normais em Serra Cardo de Gelo (cerca de 66, 43) ou hipogrifos em Planalto Esfiapluma.", s={{"Abaixo do nível 57?"}, {"Mate Yetis normais em Serra Cardo de Gelo (cerca de 66, 43) ou hipogrifos em Planalto Esfiapluma"}}}}, danger={[1]="A caverna Serra Cardo de Gelo é estreita, e yetis de nível 57-58 podem se juntar nas curvas. Se só precisa de EXP, fique do lado de fora da entrada."}, grind={[1]={mob="Matriarca Cardo de Gelo", note="Yetis normais fora da caverna Serra Cardo de Gelo soltam os chifres da missão. Use a encosta externa se estiver movimentada. Fique atento para puxões extras dentro."}, [2]={mob="Patriarca Cardo de Gelo", note="Yetis comuns de nível mais alto na mesma área, bons para chegar ao 57. Se tiver companhia, limpem primeiro as passagens estreitas para evitar que dois entrem na luta ao mesmo tempo."}}, supply={[1]={npc="Yugrek"}, [2]={npc="Estalajadeira Vizzi"}, [3]={npc="Nixxrak"}, [4]={npc="Estalajadeira Vizzi"}, [5]={npc="Wixxrak"}}, steps={[1]={text="Siga para o leste a partir de Domínio dos Presamatos. Visite Donova em Fontes Termais de Fogofrio antes de entrar em Visteterna."}, [2]={hint="Informe Bruna Covaneve sobre as suas descobertas."}, [3]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [4]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [5]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [6]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [7]={npc="Umi Zombarruga", tgt="Umi Zombarruga"}, [8]={hint="Colete 2 Chifres Impolutos de Yeti para Umi Zombarruga em Visteterna.", desc="Só a matriarca e o rei yeti adultos dentro da caverna dropam o item; deixe os yetis de nível baixo para as missões anteriores."}, [9]={npc="Umi Zombarruga", tgt="Umi Zombarruga"}, [10]={npc="Umi Zombarruga", tgt="Umi Zombarruga", desc="Depois de aceitar, use o Yeti Mecânico em Legacki, em Visteterna (61.54, 38.61); as outras duas pessoas usam de passagem na parada do Refúgio do Marshal, na Cratera Un'Goro."}, [11]={npc="Harlo Balançante", tgt="Harlo Balançante", tag="Opcional", desc="Missão só de conversa, dentro da vila; a continuação exige enfrentar gigantes elite: não aceite."}, [12]={npc="Mandingueira Mau'ari", tgt="Mandingueira Mau'ari", tag="Opcional"}, [13]={text="Saia de Visteterna pela estrada sul rumo à Garganta do Sussurro Sombrio e entre no Monte Hyjal."}}},
    ["04-61"] = {tips={{k="交通", text="De Visteterna, entre na montanha pela Garganta do Sussurro Sombrio, desbloqueie primeiro o ponto de voo de Contraforte Maculado e depois siga ao norte até a oficina de Kaylaena. Depois, voe de Visteterna à Clareira da Lua e volte; na volta, entregue primeiro as caixas na oficina. Por fim, siga a estrada grande para noroeste."}, {k="取捨", text="A cadeia principal do eremita Ketharas vai até o Cajado da Montanha, no Pico da Eternidade; a ida e volta à Clareira da Lua serve para engatar a parte posterior."}, {k="取捨", text="Celastrus the Bitter, Sunderbark e a Awakened Fel Ash Slime são todos elites; sozinho, pule essas três missões, e pule também A Revenge Now Bitter."}, {k="取捨", text="Guarde The Western Post e Farsight Guided para entregar em Velhamata; Taking to New Heights e Heading Up the Mountain ficam para a próxima parada; entregue Kindling, Kinda junto, quando levar a caixa."}, {k="取捨", text="A caixa de Crate Expectations expira em cerca de duas horas; por isso, só aceite ao voltar da Clareira da Lua e entregue-a direto ao descer no ponto de voo. A continuação Rubble Rummage exige vasculhar as ruínas do acampamento da Horda acima de Velhamata, e a localização dos itens é desconhecida; pule também Siegecraft e Drum Up Trouble; Drum Up Trouble ainda exige atrair Ghansurok, a quimera de nível 60."}, {k="提醒", text="Para sementes, ovos de coruja, tubérculos, solo, cristais e pinhas, procure por perto conforme a descrição da missão. Se não achar, faça primeiro as missões de matar próximas.", s={{"Para sementes, ovos de coruja, tubérculos, solo, cristais e pinhas, procure por perto conforme a descrição da missão"}, {"Se não achar, faça primeiro as missões de matar próximas"}}}}, danger={[1]="Na Garganta do Sussurro Sombrio há Matadores Hederine elite de nível 57-60, e um gigante Friomalho elite na entrada. Siga a estrada principal pelo fundo e não puxe monstros das encostas.", [2]="A leste do Contraforte Maculado rondam o ancião elite Sunderbark (nível 56) e Celastrus, o Amargo (elite, nível 57); fique atento ao matar hibiscos e coletar.", [3]="A gosma de cinzas desperta ao lado da pilha de ossos é uma elite de nível 58; não fique na poça de gosma ao jogar os ossos."}, grind={[1]={note="Bruxos comuns na Cicatriz Sangrevil; as duas missões precisam deles e há muitos. Há um bruxo nomeado de nível 58 no acampamento, então limpe primeiro a periferia."}, [2]={note="Cervos comuns fora da entrada da Caverna do Eremita; dá para pegar carne de cervo de passagem. Ficam espalhados, um a um, e servem para matar enquanto se anda."}}, supply={[1]={}, [2]={npc="Yugrek"}, [3]={npc="Estalajadeira Vizzi"}, [4]={npc="Nixxrak"}, [5]={npc="Meliri"}, [6]={npc="Dargon"}}, steps={[1]={text="Na primeira vez no Monte Hyjal: pegue a estrada sul de Visteterna até a entrada norte da Garganta do Sussurro Sombrio (59.82, 74.25), siga a estrada principal pelo fundo do desfiladeiro para o oeste até o fim e saia pela barreira druídica no canto sudeste do Monte Hyjal (cerca de 87, 74). Não precisa da missão do portão. Há um gigante Friomalho elite na entrada e demônios elite lá dentro; não saia da estrada."}, [2]={npc="Thark Gorax", tgt="Thark Gorax", desc="Trazida das Terras Pestilentas Ocidentais, Baluarte dos Mortos-vivos. Se não tiver, aceite só a próxima etapa."}, [3]={npc="Thark Gorax", tgt="Thark Gorax", desc="Entregue a Ortak Lomgok em Velhamata; a próxima parada passa por lá."}, [4]={npc="Loose Cog", npcObj=true, desc="Uma engrenagem solta à beira da estrada; clique nela para aceitar a missão."}, [5]={npc="Ketharas", tgt="Ketharas", desc="Trazida de Selva Maleva, Santuário Esmeralda. Se não tiver, pule."}, [6]={npc="Ketharas", tgt="Ketharas"}, [7]={npc="Ketharas", tgt="Ketharas", desc="Depois de abrir o ponto de voo do Contraforte Maculado, leve a caixa ao norte, para a oficina de Kaylaena."}, [8]={npc="Ketharas", tgt="Ketharas"}, [9]={npc="Ketharas", tgt="Ketharas"}, [10]={hint="Collect 10 Untainted Seeds for Ketharas."}, [11]={hint="Rescue 12 Hyjal Owl Eggs and bring them to Ketharas."}, [12]={npc="Ketharas", tgt="Ketharas"}, [13]={npc="Ketharas", tgt="Ketharas"}, [14]={npc="Ketharas", tgt="Ketharas"}, [15]={npc="Ketharas", tgt="Ketharas"}, [16]={hint="Saque de: Hyjal Stag, Predatory Hyjal Stag"}, [17]={hint="Plant the Enchanted Seeds near the Ruined Ballista, the Ruined Catapult, and the Ruined Flying Machine.", desc="Os destroços da balista, da catapulta e da máquina voadora contam como um objetivo cada, e é preciso plantar nos três."}, [18]={npc="Ketharas", tgt="Ketharas"}, [19]={npc="Ketharas", tgt="Ketharas"}, [20]={npc="Ketharas", tgt="Ketharas"}, [21]={hint="Bury the remains at Ketharas' shrine."}, [22]={npc="Ketharas", tgt="Ketharas"}, [23]={npc="Ketharas", tgt="Ketharas"}, [24]={nodeA="{a:16853}", node="Tainted Foothills", desc="Siga a estrada para o oeste e obtenha o ponto de voo de Bluebell. Compartilhado pelas duas facções."}, [25]={npc="Fraxinus", tgt="Fraxinus"}, [26]={npc="Hyacinth", tgt="Hyacinth"}, [27]={npc="Hyacinth", tgt="Hyacinth"}, [28]={npc="Thylaen", tgt="Thylaen", tag="Grupo recomendado, Opcional", desc="Celastrus é um ancião elite de nível 57 que ronda a encosta onde você coletará hibiscos mais tarde. Se for instável sozinho, não aceite."}, [29]={text="Cavalgue ao norte até a oficina de Kaylaena (60.1, 61.2); na volta, mate hibiscos pela encosta, colete terra e retorne a Hyacinth."}, [30]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [31]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Guarde os materiais por enquanto. Ao voltar da Clareira da Lua com as caixas, entregue-as também a Kaylaena."}, [32]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Ao passar por Visteterna a caminho da Clareira da Lua, entregue a Nami."}, [33]={hint="Matar: Tainted Shrubbery"}, [34]={hint="Saque de: Tainted Shrubbery"}, [35]={hint="Saque de: Celastrus the Bitter", tag="Grupo recomendado, Opcional"}, [36]={hint="Collect 6 samples of Untainted Soil from around the foothills of Mount Hyjal."}, [37]={npc="Hyacinth", tgt="Hyacinth"}, [38]={npc="Hyacinth", tgt="Hyacinth"}, [39]={npc="Thylaen", tgt="Thylaen", tag="Grupo recomendado, Opcional"}, [40]={npc="Hyacinth", tgt="Hyacinth"}, [41]={hint="Matar: Fraxinus", desc="Use em um ancião amistoso; não precisa lutar."}, [42]={npc="Fraxinus", tgt="Fraxinus"}, [43]={npc="Fraxinus", tgt="Fraxinus", tag="Grupo recomendado, Opcional", desc="Sunderbark é um ancião elite de nível 56. Se for instável sozinho, não aceite."}, [44]={hint="Hunt down and destroy the corrupted ancient Sunderbark, then plant a seed in his remains.", tag="Grupo recomendado, Opcional"}, [45]={npc="Fraxinus", tgt="Fraxinus", tag="Grupo recomendado, Opcional"}, [46]={npc="Fraxinus", tgt="Fraxinus"}, [47]={npc="Curious Crow", tgt="Curious Crow"}, [48]={npc="Curious Crow", tgt="Curious Crow"}, [49]={npc="Curious Crow", tgt="Curious Crow"}, [50]={npc="Felflick", tgt="Felflick", desc="Vá ao norte, até a Cicatriz Sangrevil, e procure o demônio aprisionado."}, [51]={npc="Felflick", tgt="Felflick"}, [52]={hint="Matar: Ashen Acolyte", desc="As anotações caem dos mesmos acólitos; enfrente-os para as duas missões."}, [53]={hint="Saque de: Ashen Acolyte"}, [54]={npc="Felflick", tgt="Felflick"}, [55]={npc="Felflick", tgt="Felflick"}, [56]={hint="Gather 8 Fel-Slime Crystals and 1 Pristine Fel-Slime Crystal."}, [57]={npc="Felflick", tgt="Felflick"}, [58]={npc="Felflick", tgt="Felflick"}, [59]={npc="Felflick", tgt="Felflick"}, [60]={hint="Saque de: Tyaeha Darkoath, Dazka Shadowsleep, Frezzlie Popwhiz", desc="Os três são monstros comuns de nível 58."}, [61]={hint="Matar: Brashann Grimdark"}, [62]={npc="Felflick", tgt="Felflick"}, [63]={npc="Felflick", tgt="Felflick"}, [64]={npc="Felflick", tgt="Felflick"}, [65]={npc="Curious Crow", tgt="Curious Crow"}, [66]={npc="Curious Crow", tgt="Curious Crow"}, [67]={npc="Curious Crow", tgt="Curious Crow"}, [68]={hint="Saque de: Visgo Nocivo"}, [69]={hint="Collect 10 Prickly Pinecones under healthy trees."}, [70]={hint="Throw the warlock bones onto the bone pile near the slime pools."}, [71]={npc="Bone Pile", npcObj=true}, [72]={npc="Bone Pile", npcObj=true, tag="Grupo recomendado, Opcional", desc="Invoca uma gosma elite de nível 58. Se for instável sozinho, não aceite."}, [73]={hint="Matar: Awakened Fel Ash Slime", tag="Grupo recomendado, Opcional"}, [74]={npc="Velician", tgt="Velician", desc="Encontre o espírito selvagem moribundo um pouco a oeste da pilha de ossos e leve o Cajado Cintilante de volta a Crow para entregar."}, [75]={npc="Curious Crow", tgt="Curious Crow"}, [76]={npc="Curious Crow", tgt="Curious Crow"}, [77]={npc="Curious Crow", tgt="Curious Crow"}, [78]={hint="Use the pinecones to destroy the Ashen Reign workstations."}, [79]={npc="Felflick", tgt="Felflick", tag="Grupo recomendado, Opcional", desc="Felflick está bem aqui, no acampamento da estação de trabalho; entregue de passagem."}, [80]={npc="Felflick", tgt="Felflick"}, [81]={npc="Curious Crow", tgt="Curious Crow"}, [82]={npc="Curious Crow", tgt="Curious Crow"}, [83]={npc="Curious Crow", tgt="Curious Crow"}, [84]={npc="Curious Crow", tgt="Curious Crow", desc="Entregue a Zet'gan em Velhamata; a próxima parada passa por lá."}, [85]={npc="Curious Crow", tgt="Curious Crow"}, [86]={npc="Ketharas", tgt="Ketharas", desc="Cavalgue de volta para o leste pela estrada até a Caverna do Eremita."}, [87]={npc="Ketharas", tgt="Ketharas"}, [88]={text="Voe do Contraforte Maculado (54.98, 82.82) para Visteterna."}, [89]={npc="Nami", tgt="Nami", desc="A caixa seguinte tem limite de tempo; aceite-a quando voltar de Clareira da Lua."}, [90]={text="Em Visteterna, troque para um voo a Clareira da Lua (32.09, 66.61) e siga a estrada para nordeste até Refúgio Noturno. O ponto de voo de Clareira da Lua foi aberto na Clareira da Lua; se não abriu, cavalgue a oeste de Visteterna até a entrada do Domínio dos Presamatos, saia pela bifurcação rumo a Clareira da Lua e abra primeiro o ponto de voo (32.09, 66.61); se sua reputação com os Presamatos estiver abaixo de neutra, os furbolgs lá embaixo atacarão você."}, [91]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [92]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [93]={npc="Orokai", tgt="Orokai"}, [94]={npc="Orokai", tgt="Orokai"}, [95]={hint="Speak with Orokai when you are ready to see what he learned from the Faintly Glowing Branch."}, [96]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [97]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [98]={text="No ponto de voo de Clareira da Lua, procure Faustron (32.09, 66.61) para voar a Visteterna."}, [99]={npc="Nami", tgt="Nami", desc="As baterias da caixa param de funcionar após cerca de duas horas. Cavalgue devagar e não caia; se quebrar, volte a Nami para repor."}, [100]={text="Voe para o Contraforte Maculado e cavalgue direto ao norte do ponto de voo até a oficina de Kaylaena."}, [101]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [102]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [103]={npc="Ketharas", tgt="Ketharas", desc="Cavalgue ao sudeste da oficina de volta à Caverna do Eremita."}, [104]={npc="Ketharas", tgt="Ketharas"}, [105]={npc="Ketharas", tgt="Ketharas", desc="Entregue a Skylord Omnuron no Santuário de Aviana; a próxima parada passa por lá."}, [106]={npc="Curious Crow", tgt="Curious Crow"}, [107]={npc="Curious Crow", tgt="Curious Crow", desc="Toque no retrato do corvo na ponte de Berço da Tranquilidade; faça isso na próxima parada."}, [108]={text="Siga a estrada para o oeste e vire ao norte depois de Refúgio de Malorne (cerca de 29, 71)."}}},
    ["04-62"] = {tips={{k="交通", text="Desbloqueie primeiro o ponto de voo do Pico da Eternidade. Depois, voe para Contraforte Maculado para entregar os três pré-requisitos do Cajado da Montanha; em seguida vá a Visteterna para entregar o pacote de correio e fazer a cadeia do correio, e então volte de voo à montanha. Ao sair da montanha, voe de Contraforte Maculado a Visteterna; por fim, escolha a rota conforme for passar ou não por Planalto Esfiapluma, em Feralas."}, {k="取捨", text="As missões de Velhamata, Repouso do Lamento e Berço da Tranquilidade ficam dos dois lados da estrada; dá para matar e coletar juntos."}, {k="取捨", text="Ao descer com o cajado, entregue também o pacote de correio e conclua a continuação do correio (Mending Communications→Unfrozen Deliveries→Top of the Post)."}, {k="取捨", text="As cinzas de Ashes of the Legion Ascent ficam no centro das ruínas de Dae'gun, ao lado de um demonarca elite; se não conseguir pegá-las sozinho, pule o Staff of the Mountain e as continuações (Ashes of the Legion Ascent, The Staff of the Mountain, Paying Back the Pact, Ve'han's Fall, Work Well Done); Stolen Life e A Bit of the Sky são entregues normalmente na Caverna do Eremita, e a cadeia do correio, assim como Summit Sentries, A Thorn in the Paw, A Thorny Solution, Cult Closure, Twisted Tools e Cleansing Winds, não precisa do cajado: faça-as normalmente."}, {k="取捨", text="Ve'han's Fall exige enfrentar Ve'han Talongrasp, elite de nível 60, e Work Well Done vem logo depois dela; sozinho, pule. Blackthorne Blackout exige matar um mensageiro Blackthorne elite de nível 60, e Bait the Beast, matar um guardião sabre-da-noite elite e depois atrair Ghansurok; a rota não aceita nenhuma das duas."}, {k="取捨", text="O esmaga-crânios de Head Scratcher é um elite de nível 60 (cerca de 35, 71); a insígnia de Flags of Our Forebears precisa ser obtida nas ruínas de Dae'gun e entregue de volta em Velhamata; Tribal Colors e Wrap Return exigem voltar a Velhamata e depois ir até a Aldeia Sen'jin; nenhuma delas fica no caminho."}, {k="取捨", text="Stemming the Demon Tide, Siphoned Ephemeral Essence e Blademaster's Bonfires, do acampamento no lado oeste das ruínas de Dae'gun, e Maerion's Misery, de Maerion Thaelemaches, no canto nordeste, exigem idas e vindas extras, e a rota não faz o desvio; aceite-as se tiver grupo para limpar as ruínas de Dae'gun."}, {k="取捨", text="As continuações do Veterano da Terceira Guerra, Lifted by Legacy, Wake Memories, Praise, Ends Meet e Soldier's Solace, mandam você para lugares distantes, como Mil Agulhas e Vila Plácida; pode pular."}, {k="取捨", text="Os gatinhos de Kits and Cats, de Shalla'kal (31.3, 50.3, ao lado de Maroshis), estão espalhados pela montanha, em locais desconhecidos; pode pular. Challenger of the Gods (o relatório de pesquisa na estante ao lado de Ve'han) e Return to Jereman (voltar para falar com Jereman) têm pré-requisitos desconhecidos; também pode pular."}, {k="提醒", text="Abaixo do nível 60, você pode matar cultistas Blackthorne no lado sul do acampamento dos cultistas no Pico da Eternidade (75.20, 42.20), ou voltar a Repouso do Lamento e matar Saqueadores Esfola-carne.", s={{"Abaixo do nível 60, você pode matar cultistas Blackthorne no lado sul do acampamento dos cultistas no Pico da Eternidade (75.20, 42.20), ou voltar a Repouso do Lamento e matar Saqueadores Esfola-carne"}}}}, danger={[1]="A floresta ao norte de Refúgio de Malorne tem um esmaga-crânios elite de nível 60; não entre fundo ao passar pelo acampamento Madeira Morta.", [2]="Repouso do Lamento tem um carpideiro morto-vivo elite de nível 61; olhe bem antes de puxar os Saqueadores Esfola-carne.", [3]="Dae'gun tem um demonarca elite; ao pegar as cinzas, entre e saia pelo sul.", [4]="O acampamento ao norte do Pico da Eternidade tem batedores e sacerdotes Blackthorne elite, e Ve'han Talongrasp também está por perto."}, grind={[1]={note="Flagelo comum em Repouso do Lamento, misturado com os Soldados Esquecidos; as missões também precisam deles. Evite o carpideiro morto-vivo elite."}, [2]={note="Os bandos densos de harpias a oeste do Santuário de Aviana; Zarrat Wormwing está na mesma área."}, [3]={note="Cultistas comuns ao sul do acampamento dos cultistas a leste do Pico da Eternidade, compartilhados por três missões. O acampamento norte tem batedores e sacerdotes elite de nível 60; não puxe para o norte."}}, supply={[1]={}, [2]={}, [3]={}, [4]={}, [5]={}, [6]={}, [7]={}, [8]={}}, steps={[1]={text="Da curva da estrada em Refúgio de Malorne, vá a oeste e procure Brerufa fora da caverna dos furbolgs casca-de-árvore."}, [2]={npc="Brerufa", tgt="Brerufa", desc="Aceite por ora e mate os guardiões na etapa \"Feathers in Flight\", quando voltar ao sul para caçar as corujas. A continuação dentro da caverna exige antes farmar reputação; a rota faz só esta."}, [3]={npc="Eluneth", tgt="Eluneth", desc="No caminho ao norte, rumo a Velhamata."}, [4]={npc="Veteran of the Third War", tgt="Veteran of the Third War"}, [5]={npc="Zet'gan", tgt="Zet'gan"}, [6]={npc="Ortak Lomgok", tgt="Ortak Lomgok"}, [7]={npc="Zet'gan", tgt="Zet'gan"}, [8]={npc="Zet'gan", tgt="Zet'gan"}, [9]={npc="Zet'gan", tgt="Zet'gan", desc="Abaixo do nível 57, faça primeiro as outras missões da aldeia e volte para aceitar quando chegar ao 57; leve com você a Survivor's Torch que a missão entrega."}, [10]={npc="Ortak Lomgok", tgt="Ortak Lomgok"}, [11]={npc="Embroidered Scabbard", npcObj=true, desc="O mirante a oeste de Velhamata."}, [12]={npc="Embroidered Scabbard", npcObj=true}, [13]={hint="Use the Embroidered Scabbard to speak with the war veteran and hear his story at the overlook in Elderwild."}, [14]={npc="Veteran of the Third War", tgt="Veteran of the Third War"}, [15]={text="Siga a estrada a leste por Repouso do Lamento e encontre primeiro o espírito selvagem na ponte de Berço da Tranquilidade; as missões de Repouso do Lamento são feitas juntas depois de aceitar as de Marrosis."}, [16]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre", desc="As antigas ruínas ao lado da estrada. Encha o recipiente de água a caminho de Berço da Tranquilidade e entregue na volta, na etapa \"Sacred Refreshment\"."}, [17]={hint="Fill Galvinquam Leafsyre's drinking gourd at the waterfall ahead.", desc="Use a cabaça vazia da missão para encher d'água na cachoeira à frente, não ao lado de Galvinquam. Procure a cachoeira ao longo da estrada rumo a Berço da Tranquilidade."}, [18]={hint="Touch the Crow Effigy on the bridge overlooking the Cradle of Tranquility to call the Wild God, Jereman."}, [19]={npc="Jereman", tgt="Jereman"}, [20]={npc="Jereman", tgt="Jereman"}, [21]={npc="Jereman", tgt="Jereman"}, [22]={npc="Jereman", tgt="Jereman", desc="Entregue a Renalard; fica no caminho quando for ao Pico da Eternidade mais tarde."}, [23]={npc="Kala'th", tgt="Kala'th"}, [24]={npc="Kala'th", tgt="Kala'th"}, [25]={hint="Matar: Predatory Hyjal Stag"}, [26]={npc="Kala'th", tgt="Kala'th"}, [27]={npc="Marrosis", tgt="Marrosis"}, [28]={npc="Marrosis", tgt="Marrosis", desc="Entregue a Ketharas; volte voando para entregar tudo junto depois de chegar ao Pico da Eternidade."}, [29]={npc="Marrosis", tgt="Marrosis"}, [30]={hint="Matar: Forgotten Soldier, Fleshflay Ravener"}, [31]={hint="Saque de: Eternal Sentry"}, [32]={hint="Saque de: Death Wailer, Fleshflay Ravener, Forgotten Soldier", desc="Saqueadores Esfola-carne e Soldados Esquecidos dropam; evite o carpideiro morto-vivo elite."}, [33]={hint="Saque de: Scourge Reanimator"}, [34]={hint="Collect 20 Sun-Bleached Bones."}, [35]={hint="Collect 12 Hyjal Silphium."}, [36]={npc="Marrosis", tgt="Marrosis"}, [37]={npc="Eluneth", tgt="Eluneth"}, [38]={hint="Saque de: Hyjal Owl, Tainted Hyjal Owl"}, [39]={hint="Matar: Deadwood Den Guardian"}, [40]={npc="Brerufa", tgt="Brerufa"}, [41]={npc="Zet'gan", tgt="Zet'gan"}, [42]={npc="Zet'gan", tgt="Zet'gan"}, [43]={npc="Zet'gan", tgt="Zet'gan"}, [44]={npc="Ortak Lomgok", tgt="Ortak Lomgok"}, [45]={npc="Ortak Lomgok", tgt="Ortak Lomgok"}, [46]={hint="Deliver the Hyjal Silphium Poultice to Enho and Maruke.", desc="Procure Anhe perto de Maruk."}, [47]={npc="Ortak Lomgok", tgt="Ortak Lomgok"}, [48]={npc="Zet'gan", tgt="Zet'gan"}, [49]={text="Siga a estrada para o leste e entregue primeiro a água a Galvinquam Leafsyre; depois passe por Berço da Tranquilidade e vá ao sudeste até o Santuário de Aviana."}, [50]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre"}, [51]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre", desc="Leve a bagagem a Marn Euhorn no Pico da Eternidade."}, [52]={npc="Lisbael Highfeather", tgt="Lisbael Highfeather"}, [53]={npc="Corrupted Growth", npcObj=true}, [54]={hint="Usar/coletar: Corrupted Growth"}, [55]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [56]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [57]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [58]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [59]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [60]={npc="Skylord Omnuron", tgt="Skylord Omnuron", desc="Entregue a Ketharas, na mesma viagem de Stolen Life."}, [61]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [62]={hint="Saque de: Wormwing Harpy, Wormwing Windwitch, Wormwing Ambusher"}, [63]={hint="Saque de: Zarrat Wormwing", desc="Monstros comuns de nível 59 entre as harpias."}, [64]={hint="Collect 8 Tarnished Highfeather Bangles from Wormwing Harpy nests."}, [65]={hint="Find the Jewel of the Horizon in the Wormwing harpy nests on Mount Hyjal and bring it to Ketharas."}, [66]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [67]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [68]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [69]={npc="Renalard", tgt="Renalard", desc="Vá a nordeste a partir do santuário."}, [70]={npc="Renalard", tgt="Renalard", tag="Opcional", desc="As cinzas ficam no meio de Dae'gun, com um demonarca elite por perto; no nível 58, tenha cuidado se estiver sozinho. Se não pegou as cinzas, pule o Cajado da Montanha e o que vem depois. As missões do topo da montanha que não precisam do cajado podem ser feitas normalmente."}, [71]={npc="Renalard", tgt="Renalard"}, [72]={hint="Collect 8 Abandoned Supplies.", desc="Use o chumaço de pelo de raposa (Tuft of Fox Fur) que a missão dá para afastar o demônio e depois pegue 8 suprimentos abandonados. Os suprimentos não ficam ao lado de Renalard."}, [73]={hint="Fetch a pinch of Azgalor's Ashes from the ruins of Dae'gun on Mount Hyjal.", tag="Opcional", desc="O demonarca elite está bem perto; assim que pegar, recue para o sul."}, [74]={npc="Renalard", tgt="Renalard"}, [75]={nodeA="{a:16849}", node="Summit of Eternity", desc="Suba a montanha para o leste e obtenha o ponto de voo de Fayran Elthas. Compartilhado pelas duas facções; só voa para o Contraforte Maculado."}, [76]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [77]={npc="Tiala Whitemane", tgt="Tiala Whitemane", tag="Opcional", desc="Trazida da Cratera Un'Goro, Refúgio do Marshal. Se não tiver, pule."}, [78]={npc="Sebelia", tgt="Sebelia", desc="Entregue o pacote de correio em Visteterna na sua próxima descida da montanha."}, [79]={text="Voe do Pico da Eternidade para o Contraforte Maculado e cavalgue ao leste até a Caverna do Eremita; entregue primeiro Vida Roubada (Stolen Life) e Fragmento do Céu (A Bit of the Sky); só entregue Ashes of the Legion Ascent e pegue o Cajado da Montanha se tiver as cinzas."}, [80]={npc="Ketharas", tgt="Ketharas"}, [81]={npc="Ketharas", tgt="Ketharas", tag="Opcional"}, [82]={npc="Ketharas", tgt="Ketharas"}, [83]={npc="Ketharas", tgt="Ketharas", tag="Opcional"}, [84]={text="Voe do Contraforte Maculado para Visteterna para entregar o pacote de correio; a cadeia do correio é entregue no alto da montanha, então depois voe direto de Visteterna de volta ao Pico da Eternidade (com conexão no Contraforte Maculado)."}, [85]={npc="Estalajadeira Vizzi", tgt="Estalajadeira Vizzi"}, [86]={npc="Estalajadeira Vizzi", tgt="Estalajadeira Vizzi", desc="Só aparece depois de entregar Restaurando as Comunicações. A continuação, Correio do Pico, volta para Sebelia no Pico da Eternidade."}, [87]={hint="Find 4 pieces of Missing Mail in the hills north of Everlook and bring it back to Innkeeper Vizzie.", desc="Primeiro veja no diário de missões onde o correio cai. Se não achar, pode pular."}, [88]={npc="Estalajadeira Vizzi", tgt="Estalajadeira Vizzi"}, [89]={npc="Estalajadeira Vizzi", tgt="Estalajadeira Vizzi"}, [90]={npc="Sebelia", tgt="Sebelia", desc="Volte voando para o Pico da Eternidade a partir de Visteterna."}, [91]={npc="Tiala Whitemane", tgt="Tiala Whitemane", tag="Opcional"}, [92]={npc="Tiala Whitemane", tgt="Tiala Whitemane", tag="Opcional", desc="Você precisa entregar primeiro o Cajado da Montanha."}, [93]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [94]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [95]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [96]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [97]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [98]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [99]={hint="Use the Staff of the Mountain on 10 members of the Blackthorne Pact on the Summit of Eternity to remove their wards and then kill them.", tag="Opcional", desc="Enfrente os mesmos cultistas das duas missões seguintes."}, [100]={hint="Matar: Blackthorne Cultist, Blackthorne Adept"}, [101]={hint="Saque de: Blackthorne Cultist, Blackthorne Outrunner, Blackthorne Adept", desc="Cultistas comuns também dropam; não precisa enfrentar os batedores ou sacerdotes elite."}, [102]={hint="Reactivate the sentinel stones north, west, and south around the Blackthorne cultists.", desc="As pedras norte, oeste e sul contam como um objetivo cada, e é preciso visitar as três."}, [103]={hint="Find thorn seeds in the forests at the summit of Mount Hyjal and bring them back to Tiala Whitemane."}, [104]={hint="Saque de: Mountain Squallclimber, Wildbreath Chimaerok"}, [105]={npc="Tiala Whitemane", tgt="Tiala Whitemane", tag="Opcional"}, [106]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [107]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [108]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [109]={hint="Plant thorn seeds near the inn, the storage tower, and the grouping of trees at the loyalist druid camp."}, [110]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [111]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [112]={npc="Thisalee Crow", tgt="Thisalee Crow", desc="Só aparece depois de entregar Acabar com o Frenesi."}, [113]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [114]={npc="Marn Euhorn", tgt="Marn Euhorn", desc="Só aparece depois de entregar Ventos da Purificação."}, [115]={npc="Marn Euhorn", tgt="Marn Euhorn", desc="Só aparece depois de entregar Ventos da Purificação."}, [116]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [117]={hint="Enter the Well of Eternity and examine the roots of Nordrassil."}, [118]={hint="Use the Enchanted Branch to release 5 wisps around Nordrassil.", desc="Liberte a luz tênue que já está sob as raízes de Nordrassil, em vez de invocá-la com um item na clareira. Procure perto das raízes."}, [119]={hint="Take Marn's incense and allow the smoke to ward the air around Archimonde's remains.", desc="Procure os restos perto de Nordrassil."}, [120]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [121]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [122]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [123]={npc="Tiala Whitemane", tgt="Tiala Whitemane", tag="Grupo recomendado, Opcional", desc="Ve'han Talongrasp é uma elite de nível 60."}, [124]={hint="Matar: Ve'han Talongrasp", tag="Grupo recomendado, Opcional"}, [125]={npc="Tiala Whitemane", tgt="Tiala Whitemane", tag="Grupo recomendado, Opcional"}, [126]={npc="Tiala Whitemane", tgt="Tiala Whitemane", desc="Ao partir, desça no Contraforte Maculado e cavalgue até a Caverna do Eremita para entregar."}, [127]={text="Voe do Pico da Eternidade para o Contraforte Maculado. Só vá montado até a Caverna do Eremita, a leste, para entregar se tiver a missão de continuação de Tiala."}, [128]={npc="Ketharas", tgt="Ketharas"}, [129]={text="Voe do Contraforte Maculado para Visteterna."}, [130]={text="Só voe para a Aldeia Mojache, em Feralas, se for fazer a missão opcional dos ovos ou já tiver um grupo de Gládio Cruel pronto. Se pular as duas, voe para Geringontzan."}}},
    ["04-54"] = {name="Feralas", tips={{k="交通", text="Primeiro vá ao sul pegar o ovo e depois voe para Geringontzan."}, {k="取捨", text="Entrega única no Super Ovomático; se já fez ou quer poupar a caminhada, pode voar direto para Geringontzan."}, {k="提醒", text="Decida o que fazer depois conforme o nível real; o ovo é opcional e serve só para uma entrega única.", s={{"Decida o que fazer depois conforme o nível real; o ovo é opcional e serve só para uma entrega única"}}}}, grind={[1]={mob="Matriarca Cardo de Gelo", note="A visita curta a Feralas só tem a missão secundária do ovo de hipogrifo. Se o nível estiver baixo, complete antes de sair de Visteterna; os yetis Cardo de Gelo têm nível mais alto, e a entrada da caverna pode estar disputada."}}, supply={[1]={npc="Shyn"}, [2]={npc="Estalajadeiro Greul"}, [3]={npc="Cavento Mira Certa"}, [4]={npc="Estalajadeiro Greul"}, [5]={npc="Cavento Mira Certa"}, [6]={npc="Tarhus"}}, steps={[1]={text="Do Aldeia Mojache, siga a estrada sul até o Planalto Esfiapluma; clique no ovo de hipogrifo (55.91, 76.03; se tiver sido levado, procure outro a leste) e volte ao ponto de voo depois de pegar 1.", tag="Opcional"}, [2]={text="Se você coletou um ovo, retorne para Aldeia Mojache e voe para Geringontzan. Se você ignorou Feralas, inicie o trecho Refúgio do Marshal a partir de Geringontzan."}}},
    ["05-d30"] = {name="Gládio Cruel: Norte", entrance="Feralas (1444), 62.50, 24.90. Portal da asa norte.", pickup="Reúna o grupo e os materiais em Aldeia Mojache e siga para oeste. A maioria das missões comuns da ala norte fica dentro da masmorra. Pegue a Chave do Crescente na ala leste ou vá com alguém que a tenha. Se precisar entregar um livro de classe, compre o livro correspondente na Casa de Leilões.", pickupS={{"Reúna o grupo e os materiais em Aldeia Mojache e siga para oeste"}, {"A maioria das missões comuns da ala norte fica dentro da masmorra"}, {"Pegue a Chave do Crescente na ala leste ou vá com alguém que a tenha"}, {"Se precisar entregar um livro de classe, compre o livro correspondente na Casa de Leilões"}}, tips={{k="動線", text="Para limpar tudo, siga por Mol'dar, Kreeg, Fengus, a armadilha ao lado de Knot, Kromcrush e o Rei Gordok. Para o tributo, poupe os guardas, encontre Knot, cuide da armadilha e volte ao Kreeg depois de matar o rei. Para os livros de classe, você pode entrar na biblioteca pela porta lateral do pátio de entrada."}, {k="取捨", text="Ao nivelar, favoreça um grupo que possa terminar em uma corrida. Se você está esperando materiais de tributo, continue fazendo missões."}, {k="說明", text="Na rota do Tributo, mantenha vivos os guardas e Kreeg. Fale com Kreeg depois de matar o Rei Gordok. Se quiser só a limpeza completa normal, avise o grupo antes.", s={{"Na rota do Tributo, mantenha vivos os guardas e Kreeg"}, {"Fale com Kreeg depois de matar o Rei Gordok"}, {"Se quiser só a limpeza completa normal, avise o grupo antes"}}}, {k="提醒", text="Na rota do Tributo, mantenha vivos os guardas e Kreeg. Fale com Kreeg depois de matar o Rei Gordok. Se quiser só a limpeza completa normal, avise o grupo antes.", s={{"Na rota do Tributo, mantenha vivos os guardas e Kreeg"}, {"Fale com Kreeg depois de matar o Rei Gordok"}, {"Se quiser só a limpeza completa normal, avise o grupo antes"}}}}, steps={[1]={text="Entrada: Gládio Cruel: Norte"}, [2]={npc="Fiapo Agulhacerta", tgt="Fiapo Agulhacerta", desc="Leve 4 peças de Runatrama, 8 Couro Rústico e 2 Fio Rúnico. Pegue 1 Tanino Ôgrico dentro da masmorra. Compre antes Peça de Runatrama, Couro Rústico e Fio Rúnico na casa de leilões. Tanino Ôgrico é obtido dentro da masmorra."}, [3]={hint="Leve 4 Peças de Runatrama, 8 Couros Rústicos, 2 Fios Rúnicos e Tanino Ôgrico para Fiapo Agulhacerta. Atualmente, ele está acorrentado dentro da ala Gordok do Gládio Cruel.", desc="Local: Saque o tanino lá em cima, passando por Fengus. Encontre Knot perto da armadilha.", spot="Saque o tanino lá em cima, passando por Fengus. Encontre Knot perto da armadilha."}, [4]={npc="Fiapo Agulhacerta", tgt="Fiapo Agulhacerta", spot="Depois de Fengus, junto à armadilha: Knot Dedalcampo"}, [5]={npc="Fiapo Agulhacerta", tgt="Fiapo Agulhacerta", desc="Só faça se tiver a Chave dos Grilhões Gordok. Na rota do tributo, os guardas são poupados, então há menos chance de drop."}, [6]={hint="Saque de: Brutamontes Gordok, Lorde-mago Gordok, Capitão Gordok", desc="Local: Passando pelo pátio de Fengus, use a chave em Knot próximo à armadilha quebrada.", spot="Passando pelo pátio de Fengus, use a chave em Knot próximo à armadilha quebrada."}, [7]={npc="Fiapo Agulhacerta", tgt="Fiapo Agulhacerta", spot="Pátio de Fengus, junto à armadilha quebrada: Knot Dedalcampo"}, [8]={npc="Pisoteador Kreeg", tgt="Pisoteador Kreeg", desc="Depois de concluir a rota do tributo e obter o status de rei, procure Kreeg. Pisoteador Kreeg fica na Praça dos Gordok. Só fale com ele depois de obter o status de rei."}, [9]={hint="Complete os objetivos da missão.", desc="Depois de derrotar o chefe e obter a condição de rei, volte pelo mesmo caminho a Praça Gordok e fale com Kreeg."}, [10]={npc="Pisoteador Kreeg", tgt="Pisoteador Kreeg", desc="Mesmo depois de concluir a rota do tributo, você ainda precisa ficar na masmorra e entregar a Kreeg. Pisoteador Kreeg fica na Praça dos Gordok. Só fale com ele depois de obter o status de rei.", spot="Praça Gordok: Pisoteador Kreeg"}, [11]={npc="Garona: Um Estudo sobre Furtividade e Traição", npcObj=true, desc="Pegue o livro de classe dos chefes ou das pilhas de livros, ou compre de outro jogador. Clique com o botão direito para ativá-lo e vá à Biblioteca."}, [12]={hint="Devolva o livro aos legítimos donos.", desc="Local: Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca.", spot="Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca."}, [13]={npc="Erudito Kildrath", tgt="Erudito Kildrath", spot="Biblioteca: Erudito Kildrath"}, [14]={npc="Códice de Defesa", npcObj=true, desc="Pegue o livro de classe dos chefes ou das pilhas de livros, ou compre de outro jogador. Clique com o botão direito para ativá-lo e vá à Biblioteca."}, [15]={hint="Devolva o livro aos legítimos donos.", desc="Local: Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca.", spot="Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca."}, [16]={npc="Erudito Kildrath", tgt="Erudito Kildrath", spot="Biblioteca: Erudito Kildrath"}, [17]={npc="Livro de Receitas do Arcanista", npcObj=true, desc="Pegue o livro de classe dos chefes ou das pilhas de livros, ou compre de outro jogador. Clique com o botão direito para ativá-lo e vá à Biblioteca."}, [18]={hint="Devolva o livro aos legítimos donos.", desc="Local: Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca.", spot="Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca."}, [19]={npc="Erudito Kildrath", tgt="Erudito Kildrath", spot="Biblioteca: Erudito Kildrath"}, [20]={npc="A Luz e Como Ativá-la", npcObj=true, desc="Pegue o livro de classe dos chefes ou das pilhas de livros, ou compre de outro jogador. Clique com o botão direito para ativá-lo e vá à Biblioteca."}, [21]={hint="Devolva o livro aos legítimos donos.", desc="Local: Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca.", spot="Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca."}, [22]={npc="Erudita Mykos", tgt="Erudita Mykos", spot="Biblioteca: Erudita Mykos"}, [23]={npc="Sombras Agrilhoantes", npcObj=true, desc="Pegue o livro de classe dos chefes ou das pilhas de livros, ou compre de outro jogador. Clique com o botão direito para ativá-lo e vá à Biblioteca."}, [24]={hint="Devolva o livro aos legítimos donos.", desc="Local: Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca.", spot="Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca."}, [25]={npc="Erudita Mykos", tgt="Erudita Mykos", spot="Biblioteca: Erudita Mykos"}, [26]={npc="A Grande Corrida dos Caçadores", npcObj=true, desc="Pegue o livro de classe dos chefes ou das pilhas de livros, ou compre de outro jogador. Clique com o botão direito para ativá-lo e vá à Biblioteca."}, [27]={hint="Devolva o livro aos legítimos donos.", desc="Local: Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca.", spot="Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca."}, [28]={npc="Erudita Mykos", tgt="Erudita Mykos", spot="Biblioteca: Erudita Mykos"}, [29]={npc="Caçarolas: O Que a Luz Não lhe Contará", npcObj=true, desc="Pegue o livro de classe dos chefes ou das pilhas de livros, ou compre de outro jogador. Clique com o botão direito para ativá-lo e vá à Biblioteca."}, [30]={hint="Devolva o livro aos legítimos donos.", desc="Local: Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca.", spot="Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca."}, [31]={npc="Erudito Javon", tgt="Erudito Javon", spot="Biblioteca: Erudito Javon"}, [32]={npc="O Choque Gélido e Você", npcObj=true, desc="Pegue o livro de classe dos chefes ou das pilhas de livros, ou compre de outro jogador. Clique com o botão direito para ativá-lo e vá à Biblioteca."}, [33]={hint="Devolva o livro aos legítimos donos.", desc="Local: Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca.", spot="Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca."}, [34]={npc="Erudito Javon", tgt="Erudito Javon", spot="Biblioteca: Erudito Javon"}, [35]={npc="Sonho Esmeralda", npcObj=true, desc="Pegue o livro de classe dos chefes ou das pilhas de livros, ou compre de outro jogador. Clique com o botão direito para ativá-lo e vá à Biblioteca."}, [36]={hint="Devolva o livro aos legítimos donos.", desc="Local: Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca.", spot="Entre pelo portão norte até o pátio, pegue a porta lateral trancada e siga o túnel longo até a Biblioteca."}, [37]={npc="Erudito Javon", tgt="Erudito Javon", spot="Biblioteca: Erudito Javon"}}},
    ["05-d29"] = {name="Gládio Cruel: Oeste", entrance="Feralas (1444), 60.30, 30.20. Portal no lado oeste do pátio.", pickup="Visite o Sábio Korolusk em Aldeia Mojache e pegue Lendas élficas no nível 54. Voe até lá e siga a estrada principal para oeste. Confirme com o grupo quem tem a Chave do Crescente; se ninguém tiver, faça primeiro a ala leste.", pickupS={{"Visite o Sábio Korolusk em Aldeia Mojache e pegue Lendas élficas no nível 54"}, {"Voe até lá e siga a estrada principal para oeste"}, {"Confirme com o grupo quem tem a Chave do Crescente; se ninguém tiver, faça primeiro a ala leste"}}, tips={{k="動線", text="Portão oeste → limpe os pilones do jardim → Tendris Lenhorto → pegue as missões dos anciãos no andar de cima e limpe os pilones (Kalendris e Illyanna são opcionais) → Immol'thar na jaula → príncipe Tortheldrin na biblioteca → volte aos anciãos e depois procure o tesouro e os restos na biblioteca."}, {k="取捨", text="Faça Lendas élficas, A loucura intrínseca e O tesouro de Shen'dralar em uma execução. Guarde os materiais de encantamento e as cadeias mais longas de várias masmorras para uma corrida de equipamentos."}, {k="說明", text="Masmorra para cinco jogadores. A Chave do Crescente vem de Pusillin, na ala leste. Limpe os cinco pilares antes de Immol'thar. Veja as notas da ala norte para os livros de classe da Biblioteca.", s={{"Masmorra para cinco jogadores"}, {"A Chave do Crescente vem de Pusillin, na ala leste"}, {"Limpe os cinco pilares antes de Immol'thar"}, {"Veja as notas da ala norte para os livros de classe da Biblioteca"}}}, {k="提醒", text="Masmorra para cinco jogadores. A Chave do Crescente vem de Pusillin, na ala leste. Limpe os cinco pilares antes de Immol'thar. Veja as notas da ala norte para os livros de classe da Biblioteca.", s={{"Masmorra para cinco jogadores"}, {"A Chave do Crescente vem de Pusillin, na ala leste"}, {"Limpe os cinco pilares antes de Immol'thar"}, {"Veja as notas da ala norte para os livros de classe da Biblioteca"}}}}, steps={[1]={npc="Sábio Korolusk", tgt="Sábio Korolusk", desc="Pegue em Aldeia Mojache. Chegue à Biblioteca pela ala oeste ou pela passagem ao lado da ala norte."}, [2]={text="Entrada: Gládio Cruel: Oeste"}, [3]={npc="Anciã Shen'dralar", tgt="Anciã Shen'dralar", desc="Fale primeiro com a Anciã Shen'dralar no andar de cima da ala oeste do Gládio Cruel."}, [4]={hint="Mate os guardiões que cercam os cinco pilares de força da Prisão de Immol'thar. Quando os pilares se desligarem, o campo de força que cerca Immol'thar se dissipará.", desc="Limpe primeiro as cinco torres de cristal. Local: Limpe as cinco torres do jardim e do andar superior, passe pela porta trancada e mate Immol'thar e o príncipe. Ordem: Cinco torres → Immol'thar → o príncipe da biblioteca.", spot="Limpe os cinco pilares no jardim e no andar de cima, passe pela porta trancada e enfrente Immol'thar e o Príncipe."}, [5]={npc="Anciã Shen'dralar", tgt="Anciã Shen'dralar", spot="Biblioteca: Anciã Shen'dralar"}, [6]={npc="Anciã Shen'dralar", tgt="Anciã Shen'dralar", desc="Pegue depois de entregar ao Ancião, na mesma corrida de A loucura intrínseca.", preText="A loucura intrínseca"}, [7]={hint="Volte ao Ateneu e encontre o Tesouro dos Shen'dralar. Resgate sua recompensa!", desc="Local: Saia da gaiola de Immol'thar pelo corredor e procure o baú embaixo da escada da Biblioteca.", spot="Saia da gaiola de Immol'thar pelo corredor e procure o baú embaixo da escada da Biblioteca."}, [8]={npc="Tesouro dos Shen'dralar", npcObj=true, spot="Baú Shen'dralar sob a escada da biblioteca"}, [9]={hint="Procure Telmius Romanesca no Gládio Cruel. Reporte-se, então, ao Sábio Korolusk na Aldeia Mojache com qualquer informação que você encontrar.", desc="Local: Siga o corredor da gaiola até a Biblioteca. Procure os restos mortais junto às estantes.", spot="Siga o corredor da gaiola até a Biblioteca. Procure os restos mortais junto às estantes."}, [10]={npc="Sábio Korolusk", tgt="Sábio Korolusk"}}},
    ["05-d28"] = {name="Gládio Cruel: Leste", entrance="Feralas (1444), 64.80, 30.20. Portal no nicho da parede leste da arena.", pickup="Se estiver no nível 54 passando de Azshara por Orgrimmar, dá para aceitar com o anunciador Gorak. Entregue Taro na Aldeia Mojache e aceite A teia de Letendris primeiro. Depois de voar à Aldeia Mojache, procure Estoldi no Pavilhão Lariss. Relicário da Pureza pode ser aceita na Clareira da Lua. Busque a caixa na Aldeia Vento Sul, em Silithus, e entregue-a em Refúgio Noturno, na Clareira da Lua; só então Pedaços de Vinhavil aparece, e pode ficar para uma ida posterior.", pickupS={{"Se estiver no nível 54 passando de Azshara por Orgrimmar, dá para aceitar com o anunciador Gorak"}, {"Entregue Taro na Aldeia Mojache e aceite A teia de Letendris primeiro"}, {"Depois de voar à Aldeia Mojache, procure Estoldi no Pavilhão Lariss"}, {"Relicário da Pureza pode ser aceita na Clareira da Lua"}, {"Busque a caixa na Aldeia Vento Sul, em Silithus, e entregue-a em Refúgio Noturno, na Clareira da Lua; só então Pedaços de Vinhavil aparece, e pode ficar para uma ida posterior"}}, tips={{k="動線", text="Persiga Pusillin desde a entrada e lute com ele só no final → Lethtendris e Hydrospawn, conforme os caminhos laterais → Zevrim Cascardo no altar do sátiro → o chefe final Alzzin, o Selvamorfo. A Biblioteca tem entrada separada, pelo oeste ou pelo norte."}, {k="取捨", text="Pegue a Chave do Crescente na ala leste do Gládio Cruel. As missões de Thalo e Pusillin são as que combinam melhor. Se Pedaços de Vinhavil ainda não estiver liberada, não atravesse dois mapas só para pegar o relicário."}, {k="說明", text="Masmorra para cinco jogadores. Use a entrada leste. Não vá só atrás dos chefes e deixe Pusillin de fora. Guarde a chave para as alas oeste e norte.", s={{"Masmorra para cinco jogadores"}, {"Use a entrada leste"}, {"Não vá só atrás dos chefes e deixe Pusillin de fora"}, {"Guarde a chave para as alas oeste e norte"}}}, {k="提醒", text="Masmorra para cinco jogadores. Use a entrada leste. Não vá só atrás dos chefes e deixe Pusillin de fora. Guarde a chave para as alas oeste e norte.", s={{"Masmorra para cinco jogadores"}, {"Use a entrada leste"}, {"Não vá só atrás dos chefes e deixe Pusillin de fora"}, {"Guarde a chave para as alas oeste e norte"}}}}, steps={[1]={npc="Belarauto Garganto", tgt="Belarauto Garganto", desc="Introdução da cidade; dá para pegar A teia de Letendris direto com Thalo."}, [2]={hint="Fale com Talo Casco de Espinhos na Aldeia Mojache, em Feralas."}, [3]={npc="Talo Casco de Espinhos", tgt="Talo Casco de Espinhos"}, [4]={npc="Talo Casco de Espinhos", tgt="Talo Casco de Espinhos", desc="Versão da Horda; Aldeia Mojache é uma introdução opcional que pode ser pega direto."}, [5]={npc="Azj'Tordin", tgt="Azj'Tordin", desc="Encontre Pavilhão Lariss ao norte de Aldeia Mojache."}, [6]={npc="Ravine Saturna", tgt="Ravine Saturna", tag="Opcional", desc="Rota principal: a Silithus pega a caixa e a Clareira da Lua entrega; se ainda não terminou a primeira passagem, pule e deixe os Pedaços de Vinhavil para a volta a Clareira da Lua na Clareira da Lua."}, [7]={hint="Viaje até Silithus e procure um Relicário da Pureza dentro das ruínas da Vila do Vento Sul. Se conseguir encontrá-lo, regresse com ele até Ravine Saturna, no Refúgio Noturno, que fica na Clareira da Lua.", tag="Opcional", desc="Rota principal: a Silithus pega a caixa e a Clareira da Lua entrega; se ainda não terminou a primeira passagem, pule e deixe os Pedaços de Vinhavil para a volta a Clareira da Lua na Clareira da Lua."}, [8]={npc="Ravine Saturna", tgt="Ravine Saturna", tag="Opcional", desc="Rota principal: a Silithus pega a caixa e a Clareira da Lua entrega; se ainda não terminou a primeira passagem, pule e deixe os Pedaços de Vinhavil para a volta a Clareira da Lua na Clareira da Lua."}, [9]={npc="Ravine Saturna", tgt="Ravine Saturna", tag="Opcional", desc="Rota principal: a Silithus pega a caixa e a Clareira da Lua entrega; se ainda não terminou a primeira passagem, pule e deixe os Pedaços de Vinhavil para a volta a Clareira da Lua na Clareira da Lua.", preText="Relicário da Pureza"}, [10]={text="Entrada: Gládio Cruel: Leste"}, [11]={hint="Vá ao Gládio Cruel e encontre o Diabrete Pusillin. Convença-o usando qualquer meio que for necessário a lhe dar o Livro de Encantamentos de Azj'Tordin.", desc="Fale com Pusillin pelo portão leste e siga-o pela passagem até o fim. Fale com ele de novo a cada parada."}, [12]={hint="Leve a Teia de Letendris para Talo Casco de Espinhos na Aldeia Mojache, em Feralas.", desc="Local: Pegue a passagem superior do jardim até a plataforma de Lethtendris.", spot="Pegue a passagem superior do jardim até a plataforma de Lethtendris."}, [13]={hint="Encontre a Vinhavil no Gládio Cruel e obtenha uma lasca dela. É bem provável que você só consiga encontrar uma depois da derrota de Azzin, o Selvamorfo. Use o Relicário da Pureza para selar a lasca com segurança e leve-a de volta para Ravine Saturna, no Refúgio Noturno, que fica na Clareira da Lua.", tag="Opcional", desc="Rota principal: a Silithus pega a caixa e a Clareira da Lua entrega; se ainda não terminou a primeira passagem, pule e deixe os Pedaços de Vinhavil para a volta a Clareira da Lua na Clareira da Lua. Local: siga o último corredor até a sala de Alzzin; depois da luta, encontre o fragmento e sele.", spot="Siga o último túnel até a sala de Alzzin. Depois de matá-lo, procure os pedaços e sele-os."}, [14]={npc="Erudito Lydros", tgt="Erudito Lydros", desc="Com nível 60, pegue com Lydros na Biblioteca, na rota oeste ou norte, e depois siga para leste."}, [15]={hint="Vá ao Distrito Lenhatorta, no Gládio Cruel, e mate o elemental da água, Rebentágua. Leve a Essência de Rebentágua para o Erudito Lydros, no Ateneu.", desc="Local: Siga o canal inferior da ala leste do Gládio Cruel e mate Rebentágua na piscina.", spot="Siga o canal inferior da ala leste do Gládio Cruel e mate Rebentágua na piscina."}, [16]={npc="Erudito Lydros", tgt="Erudito Lydros", desc="Ao sair da masmorra, volte primeiro à Biblioteca para entregar; depois aprenda o nível mais alto de Conjurar Água e volte para o leste, até Aldeia Mojache."}, [17]={npc="Azj'Tordin", tgt="Azj'Tordin"}, [18]={npc="Talo Casco de Espinhos", tgt="Talo Casco de Espinhos"}, [19]={npc="Ravine Saturna", tgt="Ravine Saturna", tag="Opcional", desc="Rota principal: a Silithus pega a caixa e a Clareira da Lua entrega; se ainda não terminou a primeira passagem, pule e deixe os Pedaços de Vinhavil para a volta a Clareira da Lua na Clareira da Lua."}}},
    ["04-55"] = {name="Cratera Un'Goro", tips={{k="交通", text="Você passa por Geringontzan na ida e na volta; use o Yeti Mecânico pelo caminho e, no fim, vá para Silithus pela encosta noroeste."}, {k="取捨", text="Entregue As novas fontes nas Fontes Termais de Fogofrio, em Hibérnia, e Eu yeti falar uma coisa... em Visteterna; guarde Memória de Linken para a Floresta Ferrárbol, em Selva Maleva."}, {k="取捨", text="Só vá ao Super Ovomático se tiver pegado um ovo e ainda puder entregá-lo; se não pegou, não precisa voltar."}, {k="提醒", text="Decida pelo nível real se precisa compensar com monstros. Para isso, mate elementais comuns nas montanhas Pluma de Fogo ou os macacos ao norte, e cuidado com o demossauro que patrulha a planície.", s={{"Decida pelo nível real se precisa compensar com monstros"}, {"Para isso, mate elementais comuns nas montanhas Pluma de Fogo ou os macacos ao norte, e cuidado com o demossauro que patrulha a planície"}}}}, danger={[1]="Devilsaurs de elite de nível 54-56 patrulham as planícies ao sul de Pico Penacho de Fogo. Explore a rota antes de escoltar Ringo e mantenha-se na encosta."}, grind={[1]={mob="Chama Viva", note="Elementais comuns de nível mais alto em Pico Penacho de Fogo; dá para fazer junto a missão do vulcão. Puxe pela encosta e não entre na planície, onde patrulham os devilsaurs."}, [2]={mob="Senhor do Piche", note="Mobs de alcatrão comuns perto do Refúgio do Marshal; se faltar pouco para subir de nível, dá para fazer algumas voltas saindo do acampamento. Puxe um de cada vez da beira dos poços."}}, supply={[1]={npc="Gryfe"}, [2]={npc="Goberto"}, [3]={npc="Nergal"}, [4]={npc="Nergal"}, [5]={npc="Estalajadeiro Gabor Bulho"}}, steps={[1]={text="Faça primeiro, em Geringontzan, as entregas ligadas ao cemitério. Se estiver na missão do Yeti Mecânico, fique na cidade e só pegue a estrada sul depois de usar o yeti."}, [2]={npc="Ovomático", npcObj=true, tag="Opcional", desc="Use 1 ovo pego em Planalto Esfiapluma, em Feralas; se já fez, pule."}, [3]={hint="Usar/coletar: Ovo de Hipogrifo", tag="Opcional"}, [4]={npc="Ovomático", npcObj=true, tag="Opcional"}, [5]={hint="Vá até o cemitério perto de Geringontzan e use o Elixir Videre. Siga as outras instruções de Bruna para achar Gaeriyan.", desc="Bebendo isso mata você. Fale enquanto estiver morto e depois ressuscite no cemitério."}, [6]={npc="Gaeriyan", tgt="Gaeriyan"}, [7]={npc="Gaeriyan", tgt="Gaeriyan"}, [8]={hint="Ressuscite, depois procure a lápida que Gaeriyan disse para você encontrar."}, [9]={npc="Lápide Evidente", npcObj=true}, [10]={npc="Lápide Evidente", npcObj=true}, [11]={text="Use o Yeti Mecânico em Sguisha em Geringontzan (51.06, 26.87) e, em seguida, pegue a estrada sul para Un'Goro."}, [12]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [13]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [14]={hint="Descubra a localização da Torre de Cristal Leste, que fica na Cratera Un'Goro."}, [15]={hint="Use o conteúdo do Bornal do Torwa para evocar Lar'korwi e derrotá-lo. Então, leve a Cabeça do Lar'korwi para Torwa Mateiro, que está perto da entrada da Cratera Un'Goro.", desc="Vá à pedra plana ao lado da torre de cristal, no lado leste, abra o Bornal do Torwa, coloque primeiro os pedaços de carne e depois use os feromônios para atrair Lar'korwi."}, [16]={hint="Leve Pelagem de U'cha para Torwa Mateiro na entrada da Cratera Un'Goro.", desc="Ao entrar na caverna, limpe primeiro os gorilas da parte externa. U'cha é um mob comum."}, [17]={hint="Descubra a localização da Torre de Cristal Norte, que fica na Cratera Un'Goro."}, [18]={npc="Linken", tgt="Linken"}, [19]={npc="Linken", tgt="Linken"}, [20]={hint="Encontre J.D. Neri na caverna do Refúgio do Marshal."}, [21]={npc="J.D. Neri", tgt="J.D. Neri"}, [22]={npc="J.D. Neri", tgt="J.D. Neri"}, [23]={npc="Espraga Froque", tgt="Espraga Froque"}, [24]={hint="Leve o Yeti Mecânico da Umi e assuste os amigos dela:", desc="Os dois primeiros são feitos pelo caminho, na parada de Visteterna, em Hibérnia, e neste trecho; depois de usá-lo em Quixxil aqui, guarde para entregar na parada da Garganta dos Sussurros Gelados, em Hibérnia."}, [25]={hint="Descubra a localização da Torre de Cristal Oeste, que fica na Cratera Un'Goro."}, [26]={npc="Gualter", tgt="Gualter"}, [27]={hint="Gualter, na Cratera Un'Goro, quer que você encontre a área mais quente do Pico Penacho de Fogo.", desc="Basta haver reação para contar; não precisa pular na lava."}, [28]={npc="Ringo", tgt="Ringo"}, [29]={npc="Ringo", tgt="Ringo", desc="Limpe a entrada da caverna antes da escolta. Quando Ringo cair, acorde-o com o Cantil da Espraga."}, [30]={hint="Leve Ringo até Espraga Froque, no Refúgio do Marshal."}, [31]={npc="Espraga Froque", tgt="Espraga Froque"}, [32]={npc="J.D. Neri", tgt="J.D. Neri"}, [33]={npc="J.D. Neri", tgt="J.D. Neri"}, [34]={npc="J.D. Neri", tgt="J.D. Neri"}, [35]={npc="J.D. Neri", tgt="J.D. Neri"}, [36]={hint="Fale com J.D. Neri em um instante."}, [37]={npc="J.D. Neri", tgt="J.D. Neri"}, [38]={npc="Gualter", tgt="Gualter"}, [39]={npc="Gualter", tgt="Gualter"}, [40]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [41]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [42]={npc="Torwa Mateiro", tgt="Torwa Mateiro", tag="Opcional", desc="Entregue a Torwa quando passar pela entrada sudeste; dá para escolher armadura de couro ou cajado.", star={"Pelagem Cinzenta", {"DRUID"}}}, [43]={text="Entre em Silithus pela encosta noroeste de Un'Goro e siga pela estrada direto até o Forte Cenariano."}}},
    ["05-d31"] = {name="O Terraço do Moldador", entrance="Cratera Un'Goro 48.10, 6.10 (marco externo da construção titã; procure a entrada dentro do edifício)", pickup="A caminho da Clareira da Lua, ao passar pelo Penhasco do Trovão, vá antes ao noroeste de Mulgore falar com Mayena Earthseeker. De volta ao Refúgio do Marshal, na Cratera Un'Goro, suba a escada de pedra ao norte e procure a construção titã. Essence of Seeping Slimes e The Dark Crystal são aceitas no distrito de alquimia da Cidade Baixa; aceite-as antes da terceira saída da Cidade Baixa, nas Terras Pestilentas Ocidentais.", pickupS={{"A caminho da Clareira da Lua, ao passar pelo Penhasco do Trovão, vá antes ao noroeste de Mulgore falar com Mayena Earthseeker"}, {"De volta ao Refúgio do Marshal, na Cratera Un'Goro, suba a escada de pedra ao norte e procure a construção titã"}, {"Essence of Seeping Slimes e The Dark Crystal são aceitas no distrito de alquimia da Cidade Baixa; aceite-as antes da terceira saída da Cidade Baixa, nas Terras Pestilentas Ocidentais"}}, tips={{k="動線", text="Entrada → siga pelas ruínas titânicas coletando os cristais de quatro cores → junto ao cristal incolor, resolva também os objetivos da poça."}, {k="取捨", text="Aceite primeiro Crystalline Elements. Se não houver outra missão no acampamento, entre direto na masmorra com o grupo."}, {k="說明", text="Masmorra de cinco jogadores nova da versão Forever. Suba a encosta ao norte do Refúgio do Marshal; diante do portão titã, dá para usar os cristais de energia coletados em Un'Goro. Em Un'Goro, cerca de 48.10, 6.10, há um marco externo da construção titã; procure a entrada dentro do edifício.", s={{"Masmorra de cinco jogadores nova da versão Forever"}, {"Suba a encosta ao norte do Refúgio do Marshal; diante do portão titã, dá para usar os cristais de energia coletados em Un'Goro"}, {"Em Un'Goro, cerca de 48.10, 6.10, há um marco externo da construção titã; procure a entrada dentro do edifício"}}}, {k="提醒", text="Masmorra de cinco jogadores nova da versão Forever. Suba a encosta ao norte do Refúgio do Marshal; diante do portão titã, dá para usar os cristais de energia coletados em Un'Goro. Em Un'Goro, cerca de 48.10, 6.10, há um marco externo da construção titã; procure a entrada dentro do edifício.", s={{"Masmorra de cinco jogadores nova da versão Forever"}, {"Suba a encosta ao norte do Refúgio do Marshal; diante do portão titã, dá para usar os cristais de energia coletados em Un'Goro"}, {"Em Un'Goro, cerca de 48.10, 6.10, há um marco externo da construção titã; procure a entrada dentro do edifício"}}}}, steps={[1]={npc="Mayena Buscaterra", tgt="Mayena Buscaterra", desc="Aceite no planalto a oeste do Penhasco do Trovão."}, [2]={npc="Químico Sérgio", tgt="Químico Sérgio", desc="Terras Pestilentas Ocidentais: pegue antes de sair da Cidade Baixa pela terceira vez."}, [3]={npc="Mestre-boticário Faranello", tgt="Mestre-boticário Faranello", desc="Terras Pestilentas Ocidentais: pegue antes de sair da Cidade Baixa pela terceira vez."}, [4]={text="Entrada: O Terraço do Moldador"}, [5]={hint="Bring Mayena Earthseeker a Moist Crystal, a Charged Crystal, a Noxious Crystal and a Fiery Crystal from Shaper's Terrace.", desc="Local: Siga as ruínas dos titãs e saqueie todas as quatro cores de cristal dos elementais.", spot="Siga as ruínas dos titãs e saqueie todas as quatro cores de cristal dos elementais."}, [6]={hint="Gather 8 Seeping Slime Essence in the Shaper's Terrace.", desc="Local: Encontre a Gosma Infiltrante dentro da masmorra.", spot="Encontre a Gosma Infiltrante dentro da masmorra."}, [7]={hint="Gather a colorless Drained Crystal Fragment near the Achromatic Crystal in the Shaper's Terrace.", desc="Local: Procure no chão ao redor do Cristal Incolor um fragmento esgotado.", spot="Procure no chão ao redor do Cristal Incolor um fragmento esgotado."}, [8]={npc="Mayena Buscaterra"}, [9]={npc="Químico Sérgio", tgt="Químico Sérgio"}, [10]={}}},
    ["04-56"] = {name="Silithus", tips={{k="交通", text="Primeiro desbloqueie o ponto de voo do Forte Cenariano; no fim, voe de volta para Orgrimmar."}, {k="取捨", text="Guarde Relicário da Pureza e Umbero, o arquivista para entregar na Clareira da Lua."}, {k="取捨", text="Algibeira perdida do Noggel exige mais uma corrida do forte até o extremo sul do mapa; Procura-se: Agarramata, o Terror das Areias exige matar um elite; numa rota de evolução, pode pular as duas."}, {k="取捨", text="Quiroscuro (Ah, Quiroscuro, como vos odeio...) fica nas Terras Pestilentas Orientais; nesta parada de Silithus, pule também os elites de grupo."}, {k="提醒", text="Abaixo do nível 60, fique a nordeste da fortaleza (cerca de 55, 29) e mate escorpídeos e aranhas comuns, ou os cultistas do Crepúsculo a sudoeste (cerca de 38, 44).", s={{"Abaixo do nível 60, fique a nordeste da fortaleza (cerca de 55, 29) e mate escorpídeos e aranhas comuns, ou os cultistas do Crepúsculo a sudoeste (cerca de 38, 44)"}}}}, danger={[1]="Chegar ao topo da torre Vila do Vento Sul desencadeia um enxame de silitídeos. Limpe a torre e as escadas primeiro para ter uma saída."}, grind={[1]={mob="Vingador do Crepúsculo", note="Cultistas comuns do Crepúsculo na borda do acampamento, de nível ideal, dropam equipamentos do Crepúsculo e dá para fazer as missões dos cultistas juntas. Há jogadores farmando equipamentos; limpe pela borda do acampamento."}, [2]={mob="Dragataca", note="Mobs comuns na clareira a nordeste do Forte Cenariano, de nível um pouco menor, mas densos, e no caminho da coleta de materiais de missão. Troque para cá se o acampamento Crepúsculo estiver cheio."}}, supply={[1]={npc="Runk Adestra Vento"}, [2]={npc="Calandrath"}, [3]={npc="Vargus"}, [4]={npc="Calandrath"}, [5]={npc="Calandrath"}, [6]={npc="Khiran Chifre Curto"}}, steps={[1]={nodeA="{a:3425}", node="Cenarion Hold", desc="Desbloqueie o ponto de voo da Horda com Runk Adestra Vento."}, [2]={text="Dá para vincular a Pedra de Regresso na pousada (51.89, 39.16) e usá-la depois de terminar o Repouso dos Valorosos."}, [3]={npc="Arauto do Vento Chifre Altivo", tgt="Arauto do Vento Chifre Altivo"}, [4]={npc="Belhatriz Corredente", tgt="Belhatriz Corredente"}, [5]={npc="Arauto do Vento Chifre Altivo", tgt="Arauto do Vento Chifre Altivo"}, [6]={npc="Geóloga Matarriso", tgt="Geóloga Matarriso"}, [7]={npc="Bor Juba Agreste", tgt="Bor Juba Agreste"}, [8]={hint="Belhatriz Corredente, no Forte Cenariano em Silithus, quer que você traga 8 Aguilhões de Escorpídeo Petraçoite e 8 Presas de Rastejante da Areia. Fale com ela quando tiver completado a tarefa."}, [9]={hint="O Arauto do Vento Chifre Altivo, no Forte Cenariano, quer que você mate 15 Dragatacas."}, [10]={hint="Mostre a Carta de Ravine para Layo Golpestela perto do Repouso dos Valorosos, o cemitério de Silithus."}, [11]={npc="Layo Golpestela", tgt="Layo Golpestela"}, [12]={npc="Layo Golpestela", tgt="Layo Golpestela"}, [13]={hint="A Geóloga Matarriso, no Forte Cenariano, quer que você recolha 8 Fragmentos de Tabuleta do Crepúsculo."}, [14]={hint="Traga 10 Textos Cifrados do Crepúsculo para Bor Juba Agreste no Forte Cenariano."}, [15]={npc="Belhatriz Corredente", tgt="Belhatriz Corredente"}, [16]={npc="Arauto do Vento Chifre Altivo", tgt="Arauto do Vento Chifre Altivo"}, [17]={npc="Geóloga Matarriso", tgt="Geóloga Matarriso"}, [18]={npc="Bor Juba Agreste", tgt="Bor Juba Agreste"}, [19]={npc="Comandante Mar'alith", tgt="Comandante Mar'alith", desc="Vá ao Acampamento Barbabronze, ao sul, e interrogue os dois anões; a continuação exige entrar na colmeia: não aceite."}, [20]={npc="Belhatriz Corredente", tgt="Belhatriz Corredente"}, [21]={npc="Arauto do Vento Chifre Altivo", tgt="Arauto do Vento Chifre Altivo"}, [22]={npc="Geóloga Matarriso", tgt="Geóloga Matarriso"}, [23]={hint="O Arauto do Vento Chifre Altivo, no Forte Cenariano, quer que você mate 20 Dragasmagas."}, [24]={hint="Belhatriz Corredente, no Forte Cenariano em Silithus, quer que você consiga 3 Aguilhões de Tenaz Petraçoite, 3 Aguilhões de Esfolador Petraçoite e 3 Presas de Espreitadora de Rocha."}, [25]={hint="O Comandante Mar'alith, no Forte Cenariano, em Silithus, quer que você interrogue os ocupantes do Acampamento Barbabronze. Ele fica diretamente ao sul do Forte Cenariano."}, [26]={npc="Eremita Ortell", tgt="Eremita Ortell"}, [27]={hint="Viaje até Silithus e procure um Relicário da Pureza dentro das ruínas da Vila do Vento Sul. Se conseguir encontrá-lo, regresse com ele até Ravine Saturna, no Refúgio Noturno, que fica na Clareira da Lua."}, [28]={hint="Liberte os espíritos de 8 Druidas Torturados e 8 Sentinelas Torturadas na Vila do Vento Sul, depois fale novamente com Layo Golpestela no Repouso dos Valorosos, o cemitério de Silithus.", desc="Mortos-vivos podem gerar um silitídeo ao morrer. Mate-o antes de puxar o próximo."}, [29]={npc="Layo Golpestela", tgt="Layo Golpestela"}, [30]={npc="Layo Golpestela", tgt="Layo Golpestela"}, [31]={hint="Escale a torre da Vila do Vento Sul e descubra um jeito de despertar a colmeia. Leve tudo de estranho que encontrar durante a missão para Layo Golpestela no Repouso dos Valorosos, o cemitério de Silithus.", desc="Limpe as escadas da torre antes de abrir o objeto. Observe sua linha de visão."}, [32]={npc="Layo Golpestela", tgt="Layo Golpestela"}, [33]={npc="Layo Golpestela", tgt="Layo Golpestela"}, [34]={text="Volte ao Forte Cenariano; se vinculou a Pedra de Regresso nesta parada, pode usá-la agora."}, [35]={npc="Belhatriz Corredente", tgt="Belhatriz Corredente"}, [36]={npc="Arauto do Vento Chifre Altivo", tgt="Arauto do Vento Chifre Altivo"}, [37]={npc="Comandante Mar'alith", tgt="Comandante Mar'alith"}, [38]={text="Voe de volta a Orgrimmar a partir do Forte Cenariano."}}},
    ["04-58"] = {name="Selva Maleva", tips={{k="交通", text="Siga para o norte a partir do Vale Gris; no fim, vá para a Clareira da Lua pelo Domínio dos Presamatos."}, {k="取捨", text="O golpe final exige percorrer de novo a Fortaleza do Concílio das Sombras por causa de três alvos no fundo; se estiver difícil sozinho, pule."}, {k="取捨", text="Leve Horrores tóxicos para entregar nas Fontes Termais de Fogofrio, em Hibérnia."}, {k="提醒", text="Abaixo do nível 60? Mate Horrores Tóxicos e entes Irontree na Floresta Ferrárbol (cerca de 49, 25) ou deixe a diferença de EXP para Hibérnia.", s={{"Abaixo do nível 60?"}, {"Mate Horrores Tóxicos e entes Irontree na Floresta Ferrárbol (cerca de 49, 25) ou deixe a diferença de EXP para Hibérnia"}}}}, danger={[1]="Os braseiros da Fortaleza do Concílio das Sombras ficam espalhados por túneis estreitos. Limpe um trecho de cada vez antes de apagar o fogo e volte pelo mesmo caminho ao sair."}, grind={[1]={mob="Horror Tóxico", note="Elementais comuns junto ao poço da Floresta Ferrárbol; dá para coletar de passagem as gotas de Horror Tóxico. São de nível baixo, bons só para uma pequena diferença de EXP. Se houver muitos jogadores em missão no poço, vá para Hibérnia."}, [2]={mob="Retalhador Lenhatorta", note="Entes comuns ao lado da estrada norte. Se o poço estiver ocupado, troque para cá; a estrada facilita seguir para o Domínio dos Presamatos. Cuidado com os conjuradores dentro do acampamento."}}, supply={[1]={npc="Estalajadeira Kailisk"}, [2]={npc="Estalajadeira Kailisk"}, [3]={npc="Brakkar"}, [4]={npc="Altsoba Totem da Fúria"}, [5]={npc="Fardo"}, [6]={npc="Fardo"}}, steps={[1]={text="De Orgrimmar voe para o Posto Machadada em Vale Gris, siga a estrada ao norte para Selva Maleva e vá primeiro ao Santuário Esmeralda e à beira da estrada próxima. Se já abriu o Posto Peçonha, voe direto de Orgrimmar e siga a estrada ao sul até o Santuário Esmeralda."}, [2]={npc="Maibess Brisa do Rio", tgt="Maibess Brisa do Rio"}, [3]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco"}, [4]={npc="Eridan Brisazul", tgt="Eridan Brisazul"}, [5]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco"}, [6]={npc="Eridan Brisazul", tgt="Eridan Brisazul"}, [7]={hint="Use a Água Purificada do Poço Lunar para extinguir os quatro braseiros de proteção no interior da Fortaleza do Concílio das Sombras, em Selva Maleva, depois fale novamente com Greta Musgo no Casco, no Santuário Esmeralda.", desc="Limpe primeiro a passagem e só depois avance. Dentro da caverna, as coordenadas podem se sobrepor."}, [8]={hint="Colete 11 Garras Prateadas e 1 Coração de Ferrárbol para Eridan Brisazul na Selva Maleva.", desc="Garras de Prata dropam de lobos e ursos; o coração Irontree vem dos entes Irontree."}, [9]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco"}, [10]={npc="Eridan Brisazul", tgt="Eridan Brisazul"}, [11]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco", desc="Volte para Fortaleza do Concílio das Sombras com um parceiro ou se você puder puxar mobs um de cada vez."}, [12]={hint="Mate Moora e Salia, e leve a Cabeça do Lorde das Sombras Fel'dan para Greta Musgo no Casco em Selva Maleva.", desc="Os guardas estão perto do senhor. Limpe a patrulha próxima primeiro."}, [13]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco"}, [14]={npc="Trull Ruinazar", tgt="Trull Ruinazar"}, [15]={hint="Colha 3 Gotinhas de Horror Tóxico para Bruna Covaneve em Hibérnia."}, [16]={npc="Diabretim", tgt="Diabretim", tag="Opcional", desc="Ceifalmas é uma das opções de recompensa.", star={"Ceifalmas", {"WARLOCK"}}}, [17]={hint="Leve três Essências Vis Impecáveis, originárias de três locais distintos, para Diabretim na Selva Maleva.", tag="Opcional", desc="Se já tiver as três essências, de Selva Maleva, de Azshara e da Barreira do Inferno, volte direto a Diabretim."}, [18]={npc="Diabretim", tgt="Diabretim", tag="Opcional"}, [19]={npc="Diabretim", tgt="Diabretim", tag="Opcional", desc="A luta contra o elite é melhor em grupo. Entregar a missão a Niby desbloqueia a invocação de Inferno."}, [20]={hint="Procure os restos mortais de Kroshius no Vale das Escaras Pungentes, que fica na Selva Maleva. Ao encontrá-los, use o Fogo Vil perto deles e aguarde o retorno de Kroshius. Quando o infernal acordar, mate-o e retire do corpo dele o Núcleo Infernal de Kroshius.", tag="Opcional", desc="A luta contra o elite é melhor em grupo. Entregar a missão a Niby desbloqueia a invocação de Inferno."}, [21]={npc="Niby, o Todo-poderoso", tgt="Niby, o Todo-poderoso", tag="Opcional", desc="A luta contra o elite é melhor em grupo. Entregar a missão a Niby desbloqueia a invocação de Inferno."}, [22]={text="Siga para o norte até o Domínio dos Presamatos, rumo à Clareira da Lua."}}},
    ["04-59"] = {name="Clareira da Lua", tips={{k="交通", text="Vá primeiro a pé até Refúgio Noturno; no fim, escolha as fontes termais ou Visteterna de acordo com as missões que tiver."}, {k="取捨", text="As entregas dos dois NPCs de Refúgio Noturno ficam na mesma aldeia."}, {k="取捨", text="Pedaços de Vinhavil exige entrar na ala leste de Gládio Cruel; deixe para o itinerário da masmorra."}, {k="提醒", text="Esta etapa ainda é para os níveis 59-60. Vá direto para Garganta dos Sussurros Gelados quando terminar.", s={{"Esta etapa ainda é para os níveis 59-60"}, {"Vá direto para Garganta dos Sussurros Gelados quando terminar"}}}}, danger={[1]="Verifique a reputação do Timbermaw antes de passar de Clareira da Lua para Hibérnia. Se ainda for hostil, aumente sua reputação no lado Selva Maleva antes de entrar no túnel."}, grind={[1]={mob="Dentilhaço Raivoso", note="Depois de entregar na Clareira da Lua, atravesse o Domínio dos Presamatos até Hibérnia e mate ursos comuns perto da entrada norte da Garganta dos Sussurros Gelados. Eles têm nível próximo de 60; evite as elites mais abaixo, no fundo do desfiladeiro."}}, supply={[1]={npc="Meliri"}, [2]={npc="Dargon"}, [3]={npc="Daeolyn Foliéstia"}, [4]={npc="Faustron"}}, steps={[1]={text="Saia de Domínio dos Presamatos e siga pela estrada principal até Refúgio Noturno. Entregue ambos os itens de Silithus."}, [2]={npc="Ravine Saturna", tgt="Ravine Saturna"}, [3]={npc="Umbero", tgt="Umbero"}, [4]={npc="Umbero", tgt="Umbero"}, [5]={npc="Ravine Saturna", tgt="Ravine Saturna"}, [6]={npc="Umbero", tgt="Umbero"}, [7]={hint="Complete os objetivos da missão."}, [8]={npc="Umbero", tgt="Umbero"}, [9]={text="Se tiver As novas fontes ou Horrores tóxicos, volte da Clareira da Lua pelo mesmo caminho, atravessando o Domínio dos Presamatos até Hibérnia, e vá primeiro às fontes termais. Só se não tiver nenhuma das duas e pular as missões secundárias de Donova, voe de Faustron (32.09, 66.61) a Visteterna."}}},
    ["04-60"] = {name="Hibérnia", tips={{k="交通", text="Vá primeiro às fontes termais; depois de entregar a missão dos yetis em Visteterna, siga para o sul e, no fim, mate mobs do lado de fora da entrada norte da garganta."}, {k="取捨", text="Para Mensageiros Invernosos, priorize mensageiros isolados. Fontes estranhas é de exploração, na mesma rota do ponto de monstros ao norte da Garganta dos Sussurros Gelados."}, {k="取捨", text="Chefe Supremo Invernoso é elite; sozinho, ganhe os níveis matando pelursos normais."}, {k="提醒", text="Se estiver abaixo do nível 60, mate ursos no norte da Garganta dos Sussurros Gelados: os ursos Dentesfendidos enlouquecidos normais (cerca de 57.63, 70.83 / 66.68, 70.57), evitando os elites do fundo do vale.", s={{"Se estiver abaixo do nível 60, mate ursos no norte da Garganta dos Sussurros Gelados: os ursos Dentesfendidos enlouquecidos normais (cerca de 57.63, 70.83 / 66.68, 70.57), evitando os elites do fundo do vale"}}}}, danger={[1]="Gigantes de elite Frostmaul de nível 59-60 vagam por Garganta dos Sussurros Gelados. Puxe os ursos, um de cada vez, ao longo da encosta na entrada norte e não os arraste para o desfiladeiro.", [2]="Há Hederine Slayers de elite, níveis 57-60, na Garganta do Sussurro Sombrio. Ative Fontes estranhas na entrada norte e volte à estrada."}, grind={[1]={mob="Dentilhaço Raivoso", note="Ursos comuns corpo a corpo a oeste da entrada norte da Garganta dos Sussurros Gelados; dá para puxar um de cada vez e esfolar. Depois de limpar, alterne para o leste. Não entre na área das elites no fundo."}, [2]={mob="Dentilhaço Raivoso", note="Ursos comuns a leste da entrada norte do desfiladeiro. Venha para cá se o lado oeste estiver ocupado ou ainda não tiver reaparecido. Puxe pela encosta de volta à estrada, longe das elites do fundo."}}, supply={[1]={npc="Yugrek"}, [2]={npc="Estalajadeira Vizzi"}, [3]={npc="Nixxrak"}, [4]={npc="Estalajadeira Vizzi"}, [5]={npc="Wixxrak"}}, steps={[1]={text="Ao sair do Domínio dos Presamatos, vá primeiro às fontes termais ver Donova e entregue as missões de Un'Goro e da Floresta Ferrárbol; depois siga para Visteterna e o vale ao sul. Quem voou direto para Visteterna e pulou as missões das fontes termais começa com Umi Zombarruga."}, [2]={hint="Vá a Hibérnia e fale com Bruna Covaneve."}, [3]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [4]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [5]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [6]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [7]={hint="Encontre os Mensageiros Invernosos e impeça-os de entregar o carregamento à Aldeia dos Invernosos.", desc="Os mensageiros da estrada principal andam em grupo; sozinho, procure um mensageiro isolado perto da entrada Timbermaw ou do caldeirão Lenha Morta."}, [8]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [9]={npc="Bruna Covaneve", tgt="Bruna Covaneve", tag="Grupo recomendado, Opcional", desc="Agrupe-se para a elite de nível 59 e furbolgs próximos."}, [10]={hint="Bruna Covaneve em Hibérnia quer que você derrote o Chefe Supremo Invernoso.", tag="Grupo recomendado, Opcional", desc="Limpe primeiro os mobs de fora. Se, depois da luta, cair uma carta, dá para continuar a cadeia se precisar."}, [11]={npc="Registro Escrito Grosseiramente", npcObj=true, tag="Opcional", desc="Clique com o botão direito no diário que o Chefe Supremo Invernoso dropar para aceitar a missão."}, [12]={npc="Bruna Covaneve", tgt="Bruna Covaneve", tag="Grupo recomendado, Opcional"}, [13]={npc="Bruna Covaneve", tgt="Bruna Covaneve", tag="Opcional"}, [14]={npc="Umi Zombarruga", tgt="Umi Zombarruga"}, [15]={hint="Siga as instruções de Bruna Covaneve, depois fale novamente com ela.", desc="Pare na entrada do desfiladeiro. Evite as elites mais profundas."}, [16]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [17]={text="Abaixo do nível 60? Fique fora da entrada norte do desfiladeiro e mate Ursos Shardtooth Enlouquecidos comuns."}}},
    ["05-d34"] = {name="Pico da Rocha Negra Superior", entrance="Garganta Abrasadora (1427), 34.80, 85.30. Marca o acesso externo a Montanha Rocha Negra.", pickup="Depois do nível 55, voe de Visteterna, em Hibérnia, para Orgrimmar e pegue o zepelim para os Reinos do Leste; faça primeiro a parte inferior, 4903, e volte a Karrath para aceitar A sabedoria de Eitrigg com Gortus. Depois de Vila Catraca, nos Sertões, volte ao Vale da Sabedoria, em Orgrimmar, para entregar a Eitrigg e Thrall e guarde Pela Horda!. Depois do nível 57, volte ao distrito de alquimia da Cidade Baixa para aceitar Vivian Latumba e a Tabuleta de Pedranegra, voe a Karrath para entregar a Vivian e aceite A tabuleta de Pedranegra. Na parte inferior, pelo menos uma pessoa deve concluir as duas etapas do Selo da Ascensão e abrir a porta com o selo. Quem já tem o selo no grupo pode ir direto à parte superior.", pickupS={{"Depois do nível 55, voe de Visteterna, em Hibérnia, para Orgrimmar e pegue o zepelim para os Reinos do Leste; faça primeiro a parte inferior, 4903, e volte a Karrath para aceitar A sabedoria de Eitrigg com Gortus"}, {"Depois de Vila Catraca, nos Sertões, volte ao Vale da Sabedoria, em Orgrimmar, para entregar a Eitrigg e Thrall e guarde Pela Horda!"}, {"Depois do nível 57, volte ao distrito de alquimia da Cidade Baixa para aceitar Vivian Latumba e a Tabuleta de Pedranegra, voe a Karrath para entregar a Vivian e aceite A tabuleta de Pedranegra"}, {"Na parte inferior, pelo menos uma pessoa deve concluir as duas etapas do Selo da Ascensão e abrir a porta com o selo"}, {"Quem já tem o selo no grupo pode ir direto à parte superior"}}, tips={{k="動線", text="Salão da Torre do Dragão: sete runas → Piroguarda Mirabrasa → tabuleta no viveiro → Blackhand Hall → Rend e Gyth na arena → forja (A Fera é opcional) → General Drakkisath no trono, no topo da torre, e examine o orbe atrás dele."}, {k="取捨", text="Aceite tudo em Karrath e Orgrimmar primeiro. O Comando do Mão Negra é o pré-requisito do teletransporte para a raide; faça só se precisar."}, {k="說明", text="Compartilha a porta externa com a parte inferior; depois de entrar, vire à esquerda e suba para achar a fechadura da parte superior. Em grupo, procure primeiro um colega que possa usar o Selo da Ascensão. Se um terreno de plataformas bloquear o caminho, siga pela passarela externa do andar superior.", s={{"Compartilha a porta externa com a parte inferior; depois de entrar, vire à esquerda e suba para achar a fechadura da parte superior"}, {"Em grupo, procure primeiro um colega que possa usar o Selo da Ascensão"}, {"Se um terreno de plataformas bloquear o caminho, siga pela passarela externa do andar superior"}}}}, steps={[1]={npc="Senhor da Guerra Trincador", tgt="Senhor da Guerra Trincador", desc="Se o NPC não abrir a janela de missão direto, fale com ele para receber O comando do Senhor da Guerra e depois clique com o botão direito no item."}, [2]={hint="Mate o Grão-lorde Omokk, o Senhor da Guerra Voone e o Lorde Supremo Wyrmthalak. Recupere Documentos Importantes dos Rocha Negra. Fale novamente com o Senhor da Guerra Trincador, em Karrath, quanto a missão tiver sido cumprida.", desc="O local do documento muda; procure primeiro nas três primeiras salas. O documento pode aparecer em qualquer sala de chefe; confira uma por uma."}, [3]={npc="Senhor da Guerra Trincador", tgt="Senhor da Guerra Trincador"}, [4]={npc="Senhor da Guerra Trincador", tgt="Senhor da Guerra Trincador", preText="O comando do Senhor da Guerra"}, [5]={hint="Fale com Eitrigg em Orgrimmar. Quando tiver discutido o assunto com Eitrigg, busque o conselho de Thrall."}, [6]={npc="Thrall", tgt="Thrall"}, [7]={npc="Thrall", tgt="Thrall", preText="A sabedoria de Eitrigg"}, [8]={npc="Boticária Zilda", tgt="Boticária Zilda", tag="Opcional", desc="Aceite no nível 57 no Boticário de Cidade Baixa. Pule se você já tiver a A tabuleta de Pedranegra."}, [9]={npc="Umbramante Vivian Latumba", tgt="Umbramante Vivian Latumba", tag="Opcional"}, [10]={npc="Umbramante Vivian Latumba", tgt="Umbramante Vivian Latumba", desc="Retire com Vivian, se oferecido. Caso contrário, comece com Vivian Latumba e a Tabuleta de Pedranegra em Cidade Baixa."}, [11]={npc="Comando do Mão Negra", npcObj=true, tag="Opcional", desc="Pegue a carta com o Intendente Splintershield fora de Pico da Rocha Negra e clique com o botão direito para aceitar. Só se quiser entrar no Covil Asa Negra."}, [12]={text="Entrada: Pico da Rocha Negra Superior"}, [13]={hint="Viaje para o Pico da Rocha Negra e mate o Chefe Guerreiro Laceral Mão Negra. Pegue sua cabeça e volte para Orgrimmar.", desc="Local: Passe pela incubadora, suba ao salão da Mão Negra e entre pelo portão norte da arena para acionar Rend. Ordem: Pegue primeiro a tabuleta da incubadora e depois lute na arena.", spot="Passe pelo incubatório e suba até o Salão do Mão Negra. Entre pelo portão norte da arena para acionar Rend Blackhand."}, [14]={hint="Leve a Tabuleta de Pedranegra à Umbramante Vivian Latumba, em Karrath.", desc="Fique no caminho para evitar os ovos de dragão; pisar em um atrai filhotes. Local: Depois de matar os guardas Flamejantes, entre na incubadora e procure a tabuleta no chão junto às paredes. Ordem: Conclua antes da arena na etapa \"Pela Horda!\".", spot="Depois de matar Piroguarda Mirabrasa, entre no incubatório. Procure a tábua no chão, junto da parede."}, [15]={hint="Sem dúvida, um orc excepcionalmente burro. Parece que para acessar o Orbe de Comando é necessário ter a Marca de Drakkisath.", tag="Opcional", desc="A marca está atrás de Drakkisath. Local: Saia pelo portão sul da arena, passe pela fornalha até o trono; a marca está atrás do rei. Ordem: Clique na marca atrás dele depois de matar Drakkisath.", spot="Saia pelo portão sul da arena, passe pela forja e siga até o trono. A marca fica atrás do chefe."}, [16]={npc="Marca de Drakkisath", npcObj=true, tag="Opcional", spot="Marca de Drakkisath atrás do trono"}, [17]={npc="Umbramante Vivian Latumba", tgt="Umbramante Vivian Latumba"}, [18]={text="De Karrath, voe para Cidade Baixa, pegue o zepelim na torre ao sul de Montalvo para Orgrimmar e entregue a Thrall."}, [19]={npc="Thrall", tgt="Thrall"}}},
    ["05-d33"] = {name="Blackmaw Hold", entrance="Azshara 38.70, 33.40 (saída externa do túnel; entre na montanha por Valormok; a entrada da masmorra fica em Hibérnia 66.60, 84.40)", pickup="Em Valormok, procure Jediga para Beneath Nordrassil. Na mesma parada, vá a Ogtinc para Claws That Rend, Tusks that Gore. No nível 55, volte a Azshara e procure Ekkal. Ao voltar a Kalimdor via Vila Catraca, voe primeiro ao Penhasco do Trovão e entregue a carta de Jediga no Platô dos Anciãos, aceite Get to the Roots of It e depois vá a Mulgore procurar Muln Terrafúria. Por fim, voe a Valormok e siga pelo túnel de Azshara até a masmorra. Deixe Get to the Roots of It e Blackmaw Magic para entregar na próxima passagem de volta pelo Penhasco do Trovão e por Mulgore.", pickupS={{"Em Valormok, procure Jediga para Beneath Nordrassil"}, {"Na mesma parada, vá a Ogtinc para Claws That Rend, Tusks that Gore"}, {"No nível 55, volte a Azshara e procure Ekkal"}, {"Ao voltar a Kalimdor via Vila Catraca, voe primeiro ao Penhasco do Trovão e entregue a carta de Jediga no Platô dos Anciãos, aceite Get to the Roots of It e depois vá a Mulgore procurar Muln Terrafúria"}, {"Por fim, voe a Valormok e siga pelo túnel de Azshara até a masmorra"}, {"Deixe Get to the Roots of It e Blackmaw Magic para entregar na próxima passagem de volta pelo Penhasco do Trovão e por Mulgore"}}, tips={{k="動線", text="Túnel dos ursos na entrada: pegue as bolsas de Gargantanegra ao longo do caminho → colete o Capuz de raiz de Nordrassil na zona de raízes subterrâneas → bifurcação de Putrigórjeo e Focinhosso → pegue o totem ritual com o Xamã Ancião Jubassangue."}, {k="取捨", text="Prepare de passagem as missões de Ogtinc e das Ruínas de Eldarath. Conclua a cadeia dos Rootcaps da Horda em uma única visita a Penhasco do Trovão."}, {k="說明", text="As coordenadas do portal ficam no mapa de Hibérnia. Entre pelo túnel dos furbolgs em Azshara (38.70, 33.40) e siga até o portal; não procure na superfície de Hibérnia.", s={{"As coordenadas do portal ficam no mapa de Hibérnia"}, {"Entre pelo túnel dos furbolgs em Azshara (38.70, 33.40) e siga até o portal; não procure na superfície de Hibérnia"}}}}, steps={[1]={npc="Jediga", tgt="Jediga"}, [2]={hint="Speak to Nara Wildmane at Elder Rise in Thunder Bluff."}, [3]={npc="Nara Juba Agreste", tgt="Nara Juba Agreste"}, [4]={npc="Nara Juba Agreste", tgt="Nara Juba Agreste", preText="Beneath Nordrassil"}, [5]={npc="Ogtinc", tgt="Ogtinc"}, [6]={npc="Alaana Tempesvaga", tgt="Muln Earthfury", desc="Use o pino do mapa Mulgore no caminho para Penhasco do Trovão."}, [7]={npc="Ekkal", tgt="Ekkal"}, [8]={text="Entrada: Blackmaw Hold"}, [9]={hint="Gather 10 Nordrassil Root Caps inside Blackmaw Hold for Nara Wildmane in Thunder Bluff.", desc="Local: Siga as passagens da cidade até a região das raízes subterrâneas e colete os Rootcaps nas raízes.", spot="Siga as passagens da cidade até a região das raízes subterrâneas e colete os Rootcaps nas raízes."}, [10]={hint="Bring the Claws of the Great Bear and the Tusks of the Unbroken to Ogtinc, in Azshara.", tag="Alvo: Gigante Urso Putrigórjeo / Focinhosso, o Inquebrável", desc="Local: Siga o túnel dos ursos até Putrigórjeo e Focinhosso, o Inquebrável; ficam em ramais diferentes.", spot="Siga o túnel dos ursos até Putrigórjeo e Focinhosso, o Inquebrável; ficam em ramais diferentes."}, [11]={hint="Recover a Blackmaw Ritual Totem from Blackmaw Hold.", desc="Local: Siga a rota do chefe até Xamã Ancião Jubassangue e saqueie seu totem ritual.", spot="Siga a rota do chefe até Xamã Ancião Jubassangue e saqueie seu totem ritual."}, [12]={hint="Saque de: Blackmaw Berserker, Blackmaw Thrall, Blackmaw Headhunter", desc="Local: Entre e limpe os furbolgs Blackmaw corrompidos pela área onde vivem, atento às bolsas.", spot="Entre e limpe os furbolgs Blackmaw corrompidos pela área onde vivem, atento às bolsas."}, [13]={hint="Travel to Blackmaw Hold in Kalimdor, and recover the Reliquary of Tyr.", tag="Opcional"}, [14]={npc="Ogtinc", tgt="Ogtinc"}, [15]={npc="Ekkal", tgt="Ekkal"}, [16]={npc="Nara Juba Agreste"}, [17]={npc="Alaana Tempesvaga", tgt="Muln Earthfury"}, [18]={npc="Cavaleiro do Luto", tag="Opcional", desc="Pegue o zepelim de Orgrimmar de volta às Clareiras de Tirisfal e entregue ao Cavaleiro do Luto, no sudoeste; dá para escolher a Sword of Mourning.", star={"Sword of Mourning", {"PALADIN"}}}}},
  },
  quests = {
    [2] = {n="Garra de Garraguda", d="Leve a Garra de Garraguda para Senani Coração Trovejante no Posto Machadada, Vale Gris."},
    [10] = {n="Um sonho de voltar vivo pra cidade", d="Descubra qual foi a sina do Topógrafo Júnior Caranduru, e leve ele ou seus equipamentos de topografia para o Topógrafo Sênior Secamolha, em Geringontzan.", objs={"Aparelho de Inspeção do Anilhacido"}},
    [23] = {n="Pata de Ursangous", d="Leve a Pata de Ursangous para Senani Coração Trovejante no Posto Machadada, Vale Gris."},
    [24] = {n="Cabeça de Shadumbra", d="Leve a Cabeça de Shadumbra para Senani Coração Trovejante no Posto Machadada, Vale Gris."},
    [25] = {n="Paralisação nas Torres de Pedra", d="Liquide 12 Elementais da Água Contaminados no Lago Mistral, a leste do Túnel Garracava e a sudoeste de Posto Machadada.\nFaça o reconhecimento do gazebo do Lago Mistral, que fica de frente para o Entreposto da Aliança mais próximo.\nFale novamente com Mastok Wrilehiss em Posto Machadada, no Vale Gris.", tgo={{"Elemental da Água Contaminado"}}},
    [27] = {n="Uma lição a aprender", d="Fale com Dendrite Stellardor no vilarejo de Refúgio Noturno, na Clareira da Lua."},
    [28] = {n="A prova do lago", d="Encontre um Adorno de Altar no Lago Eluna'ara e leve-o para o Santuário de Remulos, na parte noroeste da Clareira da Lua. Use o Adorno de Altar lá dentro.\nVocê terá que falar com Tajarri, lá no santuário mesmo, para concluir a prova.", objs={"Santuário de Remulos"}},
    [30] = {n="Missão do leão marinho", d="Encontre o Meio-pingente da Agilidade Aquática e o Meio-pingente da Resistência Aquática. Fale com os residentes da Clareira da Lua para obter pistas de onde esse itens podem estar.\nForme o Pingente do Leão Marinho a partir das duas metades. Você precisa estar perto do Santuário de Remulos para fazer isso.\nLeve o pingente reunido ao Dendrite Stellardor na vila de Refúgio Noturno, que fica na Clareira da Lua.", objs={"Santuário de Remulos"}},
    [31] = {n="Forma aquática", d="Volte ao Penhasco do Trovão e mostre a Turak Runa Totem o Pingente do Leão Marinho."},
    [32] = {n="A ascensão dos silitídeos", d="Leve o relatório para Zilzibin Tamborleiro em Orgrimmar."},
    [63] = {n="Clamor da água", d="Derrote a Manifestação da Água Corrompida e deposite as Braçadeiras da Manifestação Corrompida junto com as Gotas Restantes da Mais Pura Água no Braseiro da Fonteterna, que fica na Floresta de Pinhaprata.", tgo={{"Manifestação Menor Corrompida da Água"}}},
    [82] = {n="Investigação no Covil Nóxio", d="Leve cinco Pedaços de Inseto Centiparte do Covil Nóxio para o Alquimista Almofarrista em Geringontzan.", tgo={{"Vespa Centiparte", "Aguilhante Centiparte", "Enxameador Centiparte", "Trabalhador Centiparte", "Escavador Centiparte", "Arrasareias Centiparte"}}},
