    [3122] = {n="Fale novamente com Mandingueiro Uzer'i.", d="Entregue a Bolsa de Herborismo de Neeru para Mandingueiro Uzer'i em Feralas."},
    [3123] = {n="O teste do recipiente", d="Viaje até as Terras Agrestes e localize os Coruscantes. Mate 10 e use o Recipiente de Muisec para encolher e capturar os Coruscantes abatidos.\nLeve 10 Muisecs de Coruscante e o Recipiente de Muisec para Mandingueiro Uzer'i em Feralas.", tgo={{"Feruja Feroz", "Feruja Primitiva", "Feruja Selvagem"}}},
