    [8284] = {n="O mistério do crepúsculo", d="A Geóloga Matarriso, no Forte Cenariano, quer que você recolha 8 Fragmentos de Tabuleta do Crepúsculo.", objs={"Fragmento de Tabuleta do Crepúsculo"}},
    [8285] = {n="O desertor", d="Leve a tabuleta restaurada para o Eremita Ortell em Silithus."},
    [8304] = {n="Querida Natália", d="O Comandante Mar'alith, no Forte Cenariano, em Silithus, quer que você interrogue os ocupantes do Acampamento Barbabronze. Ele fica diretamente ao sul do Forte Cenariano.\nUma vez obtidas as informações solicitadas, fale novamente com o Comandante Mar'alith.", tgo={{"Frankal Pontepedra"}, {"Rutgar Formaglifo"}}},
    [8318] = {n="Comunicação secreta", d="Traga 10 Textos Cifrados do Crepúsculo para Bor Juba Agreste no Forte Cenariano.", tgo={{"Guardião do Crepúsculo Havunth", "Vingador do Crepúsculo", "Geolorde do Crepúsculo", "Petraz do Crepúsculo", "Mestre do Crepúsculo", "Senhor do Crepúsculo Everun", "Latroflamas do Crepúsculo", "Suserano do Crepúsculo"}}},
    [8365] = {n="Chapéus de pirata, io-hô!", d="Sissi Ashando quer que você colete 20 Chapéus de Pirata dos Mares do Sul e leve-os para ela no Porto de Bondebico, em Tanaris.", tgo={{"Pirata dos Mares do Sul", "Flibusteiro dos Mares do Sul", "Estivador dos Mares do Sul", "Espadachim dos Mares do Sul", "André Barbarruiva", "Kregg Khaldus"}}},
    [8366] = {n="Recadinho dos Mares do Sul", d="O Chefe de Segurança Silvadágua do Porto de Bondebico, em Tanaris, quer que você mate 10 Piratas dos Mares do Sul, 10 Flibusteiros dos Mares do Sul, 10 Estivadores dos Mares do Sul e 10 Espadachins dos Mares do Sul.", tgo={{"Pirata dos Mares do Sul"}, {"Flibusteiro dos Mares do Sul"}, {"Estivador dos Mares do Sul"}, {"Espadachim dos Mares do Sul"}}},
    [8411] = {n="Dominando os elementos", d="Leve os elementos terra, ar, fogo e água para Bath'rah, o Vigia dos Ventos.", tgo={{"Redemoinho de Poeira", "Exilado Trovejante", "Ciclonium", "Vórtice Soprador", "Vórtice Giratório", "Tempestade Viva", "Redemoinho Estripador", "Redemoinho Andarilho"}, {"Elemental da Rocha", "Fúria Pétrea", "Escravo Elemental", "Exilado Tonitruante", "Elemental Inferior da Rocha", "Elemental Maior da Rocha", "Estrondor", "Myzrael"}, {"Embaixador Infernus", "Exilado em Chamas", "Espírito Errante das Chamas", "Assolador Ardente", "Destruidor Ardente", "Elemental Fulgurante", "Elemental do Inferno", "Elemental de Magma"}, {"Elemental Inferior da Água", "Exilado Vagalhante", "Guardião Evocado", "Elemental da Água Contaminado", "Serviçal Aku'mai", "Elemental do Mar", "Borrifo do Mar", "Horror Irradiado"}}},
    [8412] = {n="Totem de espírito", d="Leve as partes para Bath'rah, o Vigia dos Ventos, fazer o totem de espírito.", tgo={{"Abutre Carniceiro", "Tocaieira Carniceira", "Tocaieira Rasterruça", "Tocaieira Pestilenta", "Rotting Condor", "Plaguewing Vulture"}, {"Abutre Carniceiro", "Urso Preto Doente", "Urso-cinzento Doente", "Rotting Condor", "Plaguewing Vulture"}}},
